// Historical receiving exceptions are not proof of another required delivery,
// outstanding adjustment, payment, or currently reusable credit.
@visibleForTesting
String workPurchaseNextStep({required ({int totalItems, int matchedItems,
    bool hasMatches, bool damaged, bool shortage, bool returnedOnMatchedDelivery})? progress,
    required int? remainingMinor}) {
  if (progress == null) return 'Next: recover saved goods status before matching again.';
  if (remainingMinor == null) return 'Next: verify this bill’s balance in the supplier account.';
  final hasAdjustments = progress.damaged || progress.shortage || progress.returnedOnMatchedDelivery;
  if (hasAdjustments && progress.matchedItems < progress.totalItems) {
    final balance = remainingMinor == 0 ? 'No amount due on this bill.'
      : remainingMinor > 0 ? 'Bill amount remains due.' : 'Bill credit recorded.';
    return '$balance Check recorded goods adjustments; match existing receipts where applicable. '
      'Record another delivery only when goods arrive.';
  }
  if (!hasAdjustments && progress.matchedItems < progress.totalItems) {
    return 'Next: match saved goods below, or record a delivery.';
  }
  if (remainingMinor > 0) return 'Next: record payment or link available payment / credit.';
  if (remainingMinor < 0) {
    return hasAdjustments
      ? 'Bill credit recorded. Check eligible credit/refund options below; goods adjustments remain in history.'
      : 'Bill credit recorded. Check eligible credit/refund options below.';
  }
  return hasAdjustments ? 'No amount due on this bill. Goods adjustments remain in history.'
    : 'Bill, goods matching and balance are up to date.';
}

List<(int, WorkspaceSupplierGoodsReceipt, WorkspaceSupplierGoodsReceiptLine)>
    _supplierShortageOptions(WorkspacePurchaseSavedCopy copy, WorkspaceSupplierLedger account) {
  final result = <(int, WorkspaceSupplierGoodsReceipt, WorkspaceSupplierGoodsReceiptLine)>[];
  final seen = <(int, String, String)>{};
  final now = DateTime.now().toUtc();
  for (var index = 0; index < copy.draft.goods.length; index++) {
    for (final receipt in account.goodsReceipts.values) {
      for (final line in receipt.lines) {
        if (!seen.add((index, receipt.expectedDeliveryId, line.sourceLineId))) continue;
        final probe = account.reviewShortageIntent(operationId: 'shortage-option-probe',
          billId: copy.draft.id, billLineIndex: index, deliveryId: receipt.expectedDeliveryId,
          lineId: line.sourceLineId, quantityMilli: 1, attributionReviewed: true, requestedAt: now);
        if (probe != null) result.add((index, receipt, line));
      }
    }
  }
  return result;
}

String _formatStoreAmount(int value) {
  final negative = value < 0;
  final digits = value.abs().toString();
  if (digits.length <= 3) return '${negative ? '-' : ''}$digits';
  final tail = digits.substring(digits.length - 3);
  var lead = digits.substring(0, digits.length - 3);
  final groups = <String>[];
  while (lead.length > 2) {
    groups.insert(0, lead.substring(lead.length - 2));
    lead = lead.substring(0, lead.length - 2);
  }
  if (lead.isNotEmpty) groups.insert(0, lead);
  return '${negative ? '-' : ''}${groups.join(',')},$tail';
}

String _formatStoreMinorAmount(int value) {
  final absolute = value.abs();
  final decimals = absolute % 100;
  return '${value < 0 ? '-' : ''}${_formatStoreAmount(absolute ~/ 100)}'
      '${decimals == 0 ? '' : '.${decimals.toString().padLeft(2, '0')}'}';
}

@visibleForTesting
String storeCounterSettlementHint(WorkspacePaymentRecord? payment,
    Iterable<WorkspaceCustomerLedgerEntry> entries) {
  const pending = 'Confirm payment before handing over goods.';
  const handover = 'Hand over goods at the counter.';
  if (payment == null || !payment.valid || payment.dueMinor != 0 ||
      payment.refundedMinor != 0) { return pending; }
  if (payment.state != WorkspacePaymentState.creditApplied) {
    return payment.paidMinor > 0 && payment.paidMinor >= payment.amountMinor
        ? 'Hand over goods at the counter' : pending;
  }
  var credit = 0;
  final receipts = <WorkspacePaymentChannel, int>{};
  for (final entry in entries) {
    if (!entry.valid || entry.invoiceId != payment.invoiceId ||
        entry.orderId != payment.orderId ||
        entry.state != WorkspaceLedgerPostingState.posted) { continue; }
    if (entry.kind == WorkspaceLedgerEntryKind.creditReceived) {
      credit += entry.amountMinor;
    } else if (entry.kind == WorkspaceLedgerEntryKind.collection) {
      receipts.update(entry.channel, (value) => value + entry.amountMinor,
          ifAbsent: () => entry.amountMinor);
    }
  }
  final collected = receipts.values.fold<int>(0, (sum, value) => sum + value);
  if (credit <= 0 || credit + payment.paidMinor != payment.amountMinor ||
      collected != payment.paidMinor) {
    return payment.paidMinor > 0
        ? 'Settled with customer credit and recorded payments. $handover'
        : 'Settled using customer credit. $handover';
  }
  final parts = ['${_purchaseAmount(credit)} customer credit'];
  for (final entry in receipts.entries) {
    final label = switch (entry.key) {
      WorkspacePaymentChannel.cash => 'cash',
      WorkspacePaymentChannel.directUpi => 'UPI',
      WorkspacePaymentChannel.bankTransfer => 'bank transfer',
      WorkspacePaymentChannel.platform => 'through MoolSocial',
      _ => 'recorded payment',
    };
    parts.add('${_purchaseAmount(entry.value)} $label');
  }
  return 'Settled with ${parts.join(' + ')}. $handover';
}

@visibleForTesting
String storeInvoicePaymentMethod(String selectedMethod,
    WorkspacePaymentRecord? payment,
    Iterable<WorkspaceCustomerLedgerEntry> entries, {
    bool preferRecordedMethods = false,
  }) {
  final original = 'Payment method: $selectedMethod';
  if (payment == null || !payment.valid) return original;
  var credit = 0;
  var collected = 0;
  final channels = <WorkspacePaymentChannel>{};
  for (final entry in entries) {
    if (!entry.valid || entry.invoiceId != payment.invoiceId ||
        entry.orderId != payment.orderId ||
        entry.state != WorkspaceLedgerPostingState.posted) { continue; }
    if (entry.kind == WorkspaceLedgerEntryKind.creditReceived) {
      credit += entry.amountMinor;
    } else if (entry.kind == WorkspaceLedgerEntryKind.collection) {
      collected += entry.amountMinor;
      channels.add(entry.channel);
    }
  }
  if (credit == 0 && payment.state != WorkspacePaymentState.creditApplied) {
    if (preferRecordedMethods && payment.paidMinor > 0) {
      if (collected != payment.paidMinor || channels.isEmpty) {
        return 'Payment method: Recorded payments · details unavailable';
      }
      return 'Payment method: ${channels.map((channel) => switch (channel) {
        WorkspacePaymentChannel.cash => 'Cash',
        WorkspacePaymentChannel.directUpi => 'UPI',
        WorkspacePaymentChannel.bankTransfer => 'Bank transfer',
        WorkspacePaymentChannel.platform => 'MoolSocial',
        _ => 'Recorded payment',
      }).join(' + ')}';
    }
    return original;
  }
  final methods = <String>['Customer credit'];
  if (payment.paidMinor > 0) {
    if (collected == payment.paidMinor && channels.isNotEmpty) {
      for (final channel in channels) {
        methods.add(switch (channel) {
          WorkspacePaymentChannel.cash => 'Cash',
          WorkspacePaymentChannel.directUpi => 'UPI',
          WorkspacePaymentChannel.bankTransfer => 'Bank transfer',
          WorkspacePaymentChannel.platform => 'MoolSocial',
          _ => 'Recorded payment',
        });
      }
    } else {
      methods.add('Recorded payments');
    }
  }
  return 'Payment method: ${methods.join(' + ')}';
}

String _storeSummaryAmount(String exact) {
  final parts = RegExp(r'^(-?)(\d+)(?:\.(\d{1,2}))?$').firstMatch(
    exact.replaceAll('₹', '').replaceAll(',', '').replaceAll('−', '-'),
  );
  if (parts == null) return exact;
  final rupees = int.tryParse(parts[2]!);
  if (rupees == null) return exact;
  final minor = rupees * 100 + int.parse((parts[3] ?? '').padRight(2, '0'));
  final amount = parts[1] == '-' ? -minor : minor;
  if (amount.abs() < 10000000) return exact;
  final magnitude = amount.abs();
  final divisor = magnitude >= 1000000000 ? 1000000000 : 10000000;
  final unit = magnitude >= 1000000000 ? 'cr' : 'lakh';
  final whole = magnitude ~/ divisor;
  final fraction = (magnitude % divisor) ~/ (divisor ~/ 100);
  final approximate = magnitude % (divisor ~/ 100) != 0;
  final decimals = fraction == 0
      ? ''
      : '.${fraction.toString().padLeft(2, '0')}';
  return '${approximate ? '≈' : ''}₹${amount < 0 ? '-' : ''}${_formatStoreAmount(whole)}$decimals $unit';
}

String _storeAdjustmentAmount(int value) =>
    '${value < 0 ? '+' : '−'} ₹${_formatStoreAmount(value.abs())}';

// Animate only the current, confirmed presentation. Never interpolate money,
// retain an outgoing actionable surface, or move an action's hit target.
class _StoreValueMotion extends StatefulWidget {
  const _StoreValueMotion({
    required this.value,
    required this.child,
    this.motionKey,
  });
  final Object value;
  final Widget child;
  final Key? motionKey;

  @override
  State<_StoreValueMotion> createState() => _StoreValueMotionState();
}

class _StoreValueMotionState extends State<_StoreValueMotion>
    with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  late final AnimationController _controller = AnimationController(
    vsync: this,
    duration: MoolMotion.standard,
    value: 1,
  );
  bool _enabled = false;
  bool _foreground = true;
  bool _resumeCatchUp = false;

  @override
  void initState() {
    super.initState();
    _foreground =
        WidgetsBinding.instance.lifecycleState == null ||
        WidgetsBinding.instance.lifecycleState == AppLifecycleState.resumed;
    WidgetsBinding.instance.addObserver(this);
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    _enabled =
        !MoolMotion.isReduced(context) && TickerMode.valuesOf(context).enabled;
    if (!_enabled) _controller.value = 1;
  }

  @override
  void didUpdateWidget(covariant _StoreValueMotion oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.value != widget.value) {
      if (_enabled && _foreground && !_resumeCatchUp) {
        _controller.forward(from: 0);
      } else {
        _controller.value = 1;
      }
    }
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    _foreground = state == AppLifecycleState.resumed;
    if (!_foreground) {
      _resumeCatchUp = true;
      _controller.value = 1;
    } else {
      // Flutter may defer the background data rebuild until this first frame.
      // Display it settled; only subsequent foreground changes should move.
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) _resumeCatchUp = false;
      });
    }
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => AnimatedBuilder(
    animation: _controller,
    child: widget.child,
    builder: (context, child) => Transform.translate(
      key: widget.motionKey,
      offset: Offset(
        0,
        3 * (1 - MoolMotion.enter.transform(_controller.value)),
      ),
      transformHitTests: false,
      child: child,
    ),
  );
}

class _StoreMoneyText extends StatefulWidget {
  const _StoreMoneyText(
    this.value, {
    super.key,
    this.style,
    this.textAlign = TextAlign.start,
    this.summary = false,
  });
  final String value;
  final TextStyle? style;
  final TextAlign textAlign;
  final bool summary;

  @override
  State<_StoreMoneyText> createState() => _StoreMoneyTextState();
}

class _StoreMoneyTextState extends State<_StoreMoneyText> {
  final _scroll = ScrollController();

  @override
  void dispose() {
    _scroll.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final display = widget.summary
        ? _storeSummaryAmount(widget.value)
        : widget.value;
    final style = DefaultTextStyle.of(context).style
        .merge(widget.style)
        .copyWith(fontFeatures: const [FontFeature.tabularFigures()]);
    return LayoutBuilder(
      builder: (context, constraints) {
        final painter = TextPainter(
          text: TextSpan(text: display, style: style),
          textDirection: Directionality.of(context),
          textScaler: MediaQuery.textScalerOf(context),
        )..layout();
        var effectiveStyle = style;
        if (constraints.hasBoundedWidth &&
            constraints.maxWidth > 0 &&
            painter.width > constraints.maxWidth) {
          final originalSize = style.fontSize ?? 14;
          final minimumSize = originalSize < 14 ? originalSize : 14.0;
          final fittedSize =
              (originalSize * constraints.maxWidth / painter.width * .98)
                  .clamp(minimumSize, originalSize)
                  .toDouble();
          effectiveStyle = style.copyWith(fontSize: fittedSize);
          painter.text = TextSpan(text: display, style: effectiveStyle);
          painter.layout();
        }
        final needsScroll =
            constraints.hasBoundedWidth && painter.width > constraints.maxWidth;
        painter.dispose();
        final text = Text(
          display,
          style: effectiveStyle,
          softWrap: false,
          maxLines: 1,
          textAlign: widget.textAlign,
        );
        return Tooltip(
          message: widget.value,
          excludeFromSemantics: true,
          child: Semantics(
            label: widget.value,
            excludeSemantics: true,
            child: needsScroll
                ? Padding(
                    padding: const EdgeInsets.only(bottom: 6),
                    child: Scrollbar(
                      controller: _scroll,
                      thumbVisibility: true,
                      child: SingleChildScrollView(
                        controller: _scroll,
                        scrollDirection: Axis.horizontal,
                        child: text,
                      ),
                    ),
                  )
                : _StoreValueMotion(value: widget.value, child: text),
          ),
        );
      },
    );
  }
}

class _StoreMoneyLine extends StatelessWidget {
  const _StoreMoneyLine({
    super.key,
    required this.leading,
    required this.value,
    this.style,
    this.orderReference,
    this.alignAmountToEnd = false,
  });
  final Widget leading;
  final String value;
  final TextStyle? style;
  final String? orderReference;
  final bool alignAmountToEnd;

  @override
  Widget build(BuildContext context) => LayoutBuilder(
    builder: (context, constraints) {
      final painter = TextPainter(
        text: TextSpan(
          text: value,
          style: DefaultTextStyle.of(context).style.merge(style),
        ),
        textDirection: Directionality.of(context),
        textScaler: MediaQuery.textScalerOf(context),
      )..layout();
      final stacked =
          painter.width + 12 > constraints.maxWidth * .5 ||
          (!alignAmountToEnd &&
              MediaQuery.textScalerOf(context).scale(11) > 16);
      painter.dispose();
      final amount = orderReference == null
          ? _StoreMoneyText(value, style: style, textAlign: TextAlign.end)
          : _StoreOrderAmount(
              value,
              orderReference: orderReference!,
              style: style,
              textAlign: TextAlign.end,
            );
      return stacked
          ? Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [leading, const SizedBox(height: 6), amount],
            )
          : Row(
              mainAxisAlignment: alignAmountToEnd
                  ? MainAxisAlignment.spaceBetween
                  : MainAxisAlignment.start,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Expanded(child: leading),
                const SizedBox(width: 12),
                if (alignAmountToEnd) amount else Flexible(child: amount),
              ],
            );
    },
  );
}

class _StoreOrderAmount extends StatelessWidget {
  const _StoreOrderAmount(
    this.value, {
    required this.orderReference,
    this.style,
    this.textAlign = TextAlign.start,
    this.amountMinor,
    this.amountLabel = 'Order total',
  });

  final String value;
  final String orderReference;
  final TextStyle? style;
  final TextAlign textAlign;
  final int? amountMinor;
  final String amountLabel;

  @override
  Widget build(BuildContext context) => LayoutBuilder(
    builder: (context, constraints) {
      final textStyle = DefaultTextStyle.of(context).style.merge(style);
      final size = textStyle.fontSize ?? 14;
      final painter = TextPainter(
        text: TextSpan(
          text: value,
          style: textStyle.copyWith(
            fontSize: size < 14 ? size : 14,
            fontFeatures: const [FontFeature.tabularFigures()],
          ),
        ),
        textDirection: Directionality.of(context),
        textScaler: MediaQuery.textScalerOf(context),
      )..layout();
      final compact = painter.width > constraints.maxWidth;
      painter.dispose();
      if (!compact) {
        return _StoreMoneyText(value, style: style, textAlign: textAlign);
      }
      var summaryValue = _storeSummaryAmount(
        amountMinor == null ? value : '₹${amountMinor! ~/ 100}',
      );
      if (amountMinor != null &&
          amountMinor! % 100 != 0 &&
          !summaryValue.startsWith('≈')) {
        summaryValue = '≈$summaryValue';
      }
      final summary = summaryValue.split(' ');
      return Semantics(
        container: true,
        button: true,
        label:
            '$orderReference, ${amountLabel.toLowerCase()} $value. Show exact amount',
        child: InkWell(
          key: const Key('work-order-exact-amount-open'),
          onTap: () => showDialog<void>(
            context: context,
            builder: (context) => Dialog(
              key: const Key('work-order-exact-amount-dialog'),
              insetPadding: const EdgeInsets.symmetric(
                horizontal: 12,
                vertical: 24,
              ),
              child: ConstrainedBox(
                constraints: const BoxConstraints(maxWidth: 400),
                child: Padding(
                  padding: const EdgeInsets.fromLTRB(8, 4, 8, 16),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      Row(
                        children: [
                          Expanded(child: Text(orderReference)),
                          IconButton(
                            tooltip: 'Close amount',
                            onPressed: () => Navigator.of(context).pop(),
                            icon: const Icon(Icons.close_rounded),
                          ),
                        ],
                      ),
                      Text(amountLabel),
                      const SizedBox(height: 8),
                      _StoreMoneyText(
                        value,
                        style: const TextStyle(
                          fontSize: 20,
                          fontWeight: FontWeight.w800,
                          color: MoolColors.navy,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ),
          ),
          child: ExcludeSemantics(
            child: ConstrainedBox(
              constraints: const BoxConstraints(minHeight: 48),
              child: Wrap(
                alignment: textAlign == TextAlign.end
                    ? WrapAlignment.end
                    : WrapAlignment.start,
                crossAxisAlignment: WrapCrossAlignment.center,
                spacing: 4,
                children: [
                  _StoreMoneyText(summary.first, style: style),
                  Text(
                    summary.skip(1).join(' '),
                    style: textStyle.copyWith(fontSize: 12),
                  ),
                  const Icon(
                    Icons.info_outline_rounded,
                    size: 16,
                    color: MoolColors.navy,
                  ),
                ],
              ),
            ),
          ),
        ),
      );
    },
  );
}

