TextStyle _operatingCaptionStyle(BuildContext context) =>
    Theme.of(context).textTheme.bodyMedium!.copyWith(
      fontSize: 12, fontWeight: FontWeight.w500, color: _OperatingPalette.secondary);

class _OperatingGroups extends StatelessWidget {
  const _OperatingGroups({required this.children});
  final List<Widget> children;

  @override
  Widget build(BuildContext context) => LayoutBuilder(
    builder: (context, constraints) {
      final scale = MediaQuery.textScalerOf(context);
      final arranged = <Widget>[];
      for (var i = 0; i < children.length; i++) {
        if (children[i] is! _OperatingMetric) {
          arranged.add(children[i]);
          continue;
        }
        final metrics = <_OperatingMetric>[];
        while (i < children.length && children[i] is _OperatingMetric) {
          metrics.add(children[i++] as _OperatingMetric);
        }
        i--;
        var columns = constraints.maxWidth >= 290 && scale.scale(12) <= 15
            ? 3 : constraints.maxWidth >= 280 && scale.scale(12) <= 19 ? 2 : 1;
        // Measure amounts instead of truncating digits to fit the layout.
        for (final metric in metrics) {
          final measure = TextPainter(
            text: TextSpan(text: metric.value,
              style: const TextStyle(fontSize: 18, fontWeight: FontWeight.w700)),
            textDirection: Directionality.of(context), textScaler: scale,
          )..layout();
          while (columns > 1 &&
              measure.width + 28 > (constraints.maxWidth - (columns - 1) * 10) / columns) {
            columns--;
          }
          measure.dispose();
        }
        for (var start = 0; start < metrics.length; start += columns) {
          final row = metrics.skip(start).take(columns).toList();
          var captionHeight = 0.0;
          final cellWidth = (constraints.maxWidth - (row.length - 1) * 10) / row.length;
          for (final metric in row) {
            final caption = TextPainter(
              text: TextSpan(text: metric.label,
                style: _operatingCaptionStyle(context)),
              textDirection: Directionality.of(context), textScaler: scale,
            )..layout(maxWidth: cellWidth);
            if (caption.height > captionHeight) captionHeight = caption.height;
            caption.dispose();
          }
          arranged.add(Padding(
            padding: const EdgeInsets.symmetric(vertical: 3),
            child: IntrinsicHeight(child: Row(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                for (var col = 0; col < row.length; col++) ...[
                  if (col > 0) VerticalDivider(
                    key: Key('store-overview-column-guide-${row[col].id}'),
                    width: 10, thickness: 0.5, indent: 4, endIndent: 4,
                    color: const Color(0xFFE5E8F1),
                  ),
                  Expanded(child: _OperatingMetric(
                    id: row[col].id, label: row[col].label, value: row[col].value,
                    detail: row[col].detail, alertColor: row[col].alertColor,
                    onTap: row[col].onTap, captionHeight: captionHeight.ceilToDouble() + 2,
                  )),
                ],
              ],
            )),
          ));
        }
        if (metrics.any((m) => m.id == 'stock-spread')) {
          arranged.add(const Text(
            '*Potential from unsold stock · before tax, discounts & expenses; not net profit',
            style: TextStyle(fontSize: 11, color: _OperatingPalette.secondary)));
        }
      }
      return Column(crossAxisAlignment: CrossAxisAlignment.stretch,
        children: arranged);
    },
  );
}

class _OperatingMetric extends StatelessWidget {
  const _OperatingMetric({
    required this.id, required this.label, required this.value,
    required this.detail, this.alertColor, this.onTap,
    this.captionHeight, this.compact = false,
  });
  final String id, label, value, detail;
  final Color? alertColor;
  final double? captionHeight;
  final bool compact;
  final VoidCallback? onTap;
  bool get showInfo => !const {
    'invoice-count', 'skus', 'low-stock', 'out-of-stock',
  }.contains(id);

  void _explain(BuildContext context) => showDialog<void>(
    context: context,
    builder: (context) => AlertDialog(
      title: Text(label), content: Text(detail),
      actions: [TextButton(onPressed: () => Navigator.of(context).pop(),
        child: const Text('Close'))],
    ),
  );

  @override
  Widget build(BuildContext context) => Material(
    key: Key('store-metric-band-$id'),
    color: Colors.transparent,
    child: Tooltip(
      message: detail,
      child: InkWell(
        key: Key(onTap == null && showInfo
            ? 'store-overview-info-$id' : 'store-overview-open-$id'),
        onTap: onTap ?? (showInfo ? () => _explain(context) : null),
        borderRadius: BorderRadius.circular(6),
        child: ConstrainedBox(
          constraints: const BoxConstraints(minHeight: 48),
          child: Padding(
            padding: const EdgeInsets.symmetric(vertical: 3),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                SizedBox(height: captionHeight,
                  child: Align(alignment: Alignment.bottomLeft,
                    child: Text(label, style: _operatingCaptionStyle(context)))),
                const SizedBox(height: 3),
                Row(crossAxisAlignment: CrossAxisAlignment.center, children: [
                  Expanded(child: _StoreValueMotion(value: value, child: Text(value,
                    key: Key('store-overview-$id'),
                    style: TextStyle(fontSize: compact ? 17 : 18, fontWeight: FontWeight.w700,
                      color: alertColor ?? MoolColors.navy)))),
                  if (onTap != null)
                    const Icon(Icons.north_east_rounded, size: 14, color: _OperatingPalette.secondary),
                ]),
                if (id == 'billed')
                  const Text('Before returns', style: TextStyle(fontSize: 11,
                    color: _OperatingPalette.secondary)),
              ],
            ),
          ),
        ),
      ),
    ),
  );
}

double _storeRailWordWidth(
  BuildContext context,
  String labels, {
  TextStyle textStyle = const TextStyle(
    fontSize: 11,
    fontWeight: FontWeight.w700,
  ),
}) {
  final style = DefaultTextStyle.of(context).style.merge(textStyle);
  var width = 0.0;
  for (final word in labels.split(RegExp(r'\s+'))) {
    final painter = TextPainter(
      text: TextSpan(text: word, style: style),
      textDirection: Directionality.of(context),
      textScaler: MediaQuery.textScalerOf(context),
      maxLines: 1,
    )..layout();
    if (painter.width > width) width = painter.width;
    painter.dispose();
  }
  return width;
}

class _StoreAdaptiveRail extends StatelessWidget {
  const _StoreAdaptiveRail({
    required this.labels,
    required this.normalFlex,
    required this.builder,
    this.minimumItemWidths = const [],
  });
  final List<String> labels;
  final List<int> normalFlex;
  final Widget Function(List<int>) builder;
  final List<double> minimumItemWidths;

  @override
  Widget build(BuildContext context) {
    assert(
      minimumItemWidths.isEmpty || minimumItemWidths.length == labels.length,
    );
    if (MediaQuery.textScalerOf(context).scale(11) <= 16) {
      return builder(normalFlex);
    }
    final widths = labels
        .asMap()
        .entries
        .map(
          (entry) => (_storeRailWordWidth(context, entry.value) + 16)
              .clamp(
                minimumItemWidths.isEmpty ? 0 : minimumItemWidths[entry.key],
                double.infinity,
              )
              .ceil(),
        )
        .toList();
    return LayoutBuilder(
      builder: (context, constraints) {
        final minimum = widths
            .fold<int>(2, (total, width) => total + width)
            .toDouble();
        final needsScroll = minimum > constraints.maxWidth;
        final rail = SizedBox(
          width: needsScroll ? minimum : constraints.maxWidth,
          child: builder(widths),
        );
        if (!needsScroll) return rail;
        return SingleChildScrollView(
          scrollDirection: Axis.horizontal,
          child: rail,
        );
      },
    );
  }
}

class _StoreLiveBusinessPulse extends StatelessWidget {
  const _StoreLiveBusinessPulse({
    required this.session,
    this.compactHome = false,
    required this.onOrders,
    required this.onSales,
    required this.onStock,
    required this.onSettlement,
  });

  final WorkSession session;
  final bool compactHome;
  final VoidCallback onOrders;
  final VoidCallback onSales;
  final VoidCallback onStock;
  final VoidCallback onSettlement;

  @override
  Widget build(BuildContext context) {
    final finance = session.workspaceFinance;
    final review = session.workspaceFinanceUsesLegacyReview;
    String factLabel(String confirmed) => session.workspaceFinanceStale
        ? 'Last update'
        : finance != null || review
        ? confirmed
        : 'Update pending';
    final duesLabel = factLabel('Unpaid bills');
    final settlementLabel = factLabel('Available to settle');
    final duesValue = finance != null
        ? _purchaseAmount(finance.duesMinor)
        : review
        ? '₹${_formatStoreMinorAmount(session.workspaceCustomerBook.fold<int>(0, (total, customer) => total + customer.amountDueMinor))}'
        : '—';
    final settlementValue = finance != null
        ? _purchaseAmount(finance.availableMinor)
        : review
        ? '₹${_formatStoreAmount(session.workspaceSettlementEligible)}'
        : '—';
    final minimumAmountWidths = MediaQuery.textScalerOf(context).scale(11) <= 16
        ? const <double>[]
        : ['', duesValue, settlementValue].map<double>((value) {
            return _storeRailWordWidth(
                  context,
                  _storeSummaryAmount(value),
                  textStyle: const TextStyle(
                    fontSize: 14,
                    fontWeight: FontWeight.w800,
                    fontFeatures: [FontFeature.tabularFigures()],
                  ),
                ) +
                16;
          }).toList();
    return Semantics(
      container: true,
      label: 'Store finances',
      child: Material(
        key: const Key('work-store-finance-material'),
        color: Colors.white,
        textStyle: DefaultTextStyle.of(context).style,
        child: Container(
          key: const Key('work-live-status-bubbles'),
          decoration: const BoxDecoration(
            border: Border(bottom: BorderSide(color: Color(0xFFE5E8F1))),
          ),
          child: _StoreAdaptiveRail(
            // Reserve each column's own readable label and amount width.
            minimumItemWidths: minimumAmountWidths,
            labels: [
              'View statement',
              'Collect dues $duesLabel',
              'MoolSocial settlement $settlementLabel',
            ],
            normalFlex: const [1, 1, 1],
            builder: (flex) => IntrinsicHeight(
              key: const Key('work-store-live-business-pulse'),
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Expanded(
                    flex: flex[0],
                    child: TextButton(
                      key: const Key('work-pulse-sales'),
                      onPressed: onSales,
                      style: TextButton.styleFrom(
                        foregroundColor: const Color(0xFF252B38),
                        minimumSize: Size(48, compactHome ? 64 : 72),
                        alignment: compactHome
                            ? Alignment.bottomCenter
                            : Alignment.center,
                        padding: EdgeInsets.symmetric(
                          horizontal: 4,
                          vertical: compactHome ? 4 : 0,
                        ),
                      ),
                      child: SizedBox(
                        height: compactHome
                            ? MediaQuery.textScalerOf(context).scale(28)
                            : null,
                        child: const Text(
                          'View statement',
                          textAlign: TextAlign.center,
                          style: TextStyle(
                            fontSize: 11,
                            height: 1.15,
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                      ),
                    ),
                  ),
                  _StorePulseDivider(),
                  _StorePulseMetric(
                    keyName: 'work-pulse-dues',
                    compactHome: compactHome,
                    flex: flex[1],
                    label: 'Collect dues',
                    contextLabel: duesLabel,
                    value: duesValue,
                    icon: Icons.payments_outlined,
                    onTap: onOrders,
                  ),
                  _StorePulseDivider(),
                  _StorePulseMetric(
                    keyName: 'work-pulse-settlement',
                    compactHome: compactHome,
                    flex: flex[2],
                    label: 'MoolSocial settlement',
                    contextLabel: settlementLabel,
                    value: settlementValue,
                    icon: Icons.account_balance_wallet_outlined,
                    onTap: onSettlement,
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }
}

