Future<void> _showWorkspacePickupSheet(
  BuildContext context,
  WorkSession session,
) async {
  if (session.currentWorkspaceOrder?.isCustomerCollection == true) {
    context.go('/app/work/workspace/dashboard');
    return;
  }
  final pageContext = context;
  var pickupCode = '';
  String? error;
  await showModalBottomSheet<void>(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    showDragHandle: true,
    builder: (sheetContext) => StatefulBuilder(
      builder: (context, setSheetState) => AnimatedPadding(
        duration: const Duration(milliseconds: 180),
        padding: EdgeInsets.fromLTRB(
          18,
          0,
          18,
          MediaQuery.viewInsetsOf(context).bottom +
              MediaQuery.viewPaddingOf(context).bottom +
              18,
        ),
        child: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              const Text(
                'Confirm customer pickup',
                style: TextStyle(
                  color: MoolColors.navy,
                  fontSize: 20,
                  fontWeight: FontWeight.w900,
                ),
              ),
              Text(
                '${session.workspaceOrderCustomer} · ₹${session.workspaceOrderAmount}',
                style: const TextStyle(color: MoolColors.muted),
              ),
              const SizedBox(height: 4),
              const Text(
                'Enter the 6-digit pickup code shown to the customer. The invoice is created after confirmation.',
                style: TextStyle(color: MoolColors.muted),
              ),
              const SizedBox(height: 12),
              TextField(
                key: const Key('work-pickup-code'),
                autofocus: true,
                keyboardType: TextInputType.number,
                textInputAction: TextInputAction.done,
                maxLength: 6,
                onChanged: (value) => pickupCode = value,
                decoration: InputDecoration(
                  labelText: 'Customer pickup code',
                  errorText: error,
                  prefixIcon: const Icon(Icons.password_rounded),
                ),
              ),
              const SizedBox(height: 8),
              FilledButton.icon(
                key: const Key('work-pickup-confirm'),
                onPressed: session.workspaceHandoverBusy
                    ? null
                    : () async {
                        final success = await session.verifyWorkspacePickup(
                          pickupCode,
                        );
                        if (!sheetContext.mounted) return;
                        if (!success) {
                          setSheetState(() => error = session.errorMessage);
                          return;
                        }
                        final invoice = session.latestWorkspaceInvoice;
                        Navigator.of(sheetContext).pop();
                        await Future<void>.delayed(
                          const Duration(milliseconds: 260),
                        );
                        if (invoice != null && pageContext.mounted) {
                          await _showWorkspaceInvoiceSheet(
                            pageContext,
                            session,
                            invoice,
                          );
                        }
                      },
                icon: const Icon(Icons.verified_rounded),
                label: const Text('Confirm pickup'),
              ),
            ],
          ),
        ),
      ),
    ),
  );
}

String _workspaceInvoiceMessage(
  WorkSession session,
  WorkspaceCustomerInvoice invoice,
  String? invoiceAccount,
  String? invoiceStore,
  String invoiceStoreName,
) {
  final finance = session.workspaceFinance;
  final payment =
      finance?.accountScope == invoiceAccount &&
          finance?.workspaceId == invoiceStore &&
          session.activeWorkspace?.id == invoiceStore
      ? finance?.payments
            .where(
              (p) =>
                  p.invoiceId == invoice.id &&
                  p.orderId == invoice.orderId &&
                  p.valid,
            )
            .firstOrNull
      : null;
  final status = payment == null
      ? 'Payment status unavailable'
      : '${payment.label} · Received ${_purchaseAmount(payment.paidMinor)} · Due ${_purchaseAmount(payment.dueMinor)}';
  final billing = invoice.billingDetails;
  final customerDetails = [
    if (billing.name.trim().isNotEmpty) 'Customer: ${billing.name.trim()}',
    if (billing.business && billing.businessName.trim().isNotEmpty)
      'Business: ${billing.businessName.trim()}',
    if (billing.business && billing.gst.trim().isNotEmpty)
      'GST: ${billing.gst.trim()}',
    if (billing.address.trim().isNotEmpty)
      'Billing address: ${billing.address.trim()}',
  ].join('\n');
  return '${invoice.id} from $invoiceStoreName\n'
      '${customerDetails.isEmpty ? '' : '$customerDetails\n'}'
      '${invoice.items}\n'
      '${invoice.discountMinor == 0 ? '' : 'Subtotal ₹${_formatStoreMinorAmount(invoice.subtotalMinor)}\nDiscount −₹${_formatStoreMinorAmount(invoice.discountMinor)}\n'}'
      'Total ₹${_formatStoreMinorAmount(invoice.payableMinor)} · Payment method: ${invoice.payment}\n$status';
}

Future<void> _showWorkspaceInvoiceSheet(
  BuildContext context,
  WorkSession session,
  WorkspaceCustomerInvoice invoice,
) async {
  final router = GoRouter.of(context);
  final returnRoute = GoRouterState.of(context).uri.toString();
  final account = session.workspaceFinance?.accountScope;
  final store = session.activeWorkspace?.id;
  final name = invoice.sellerName.trim().isNotEmpty
      ? invoice.sellerName
      : session.activeWorkspace?.name ?? session.workName;
  ModalRoute<bool>? route;
  final chat = await showModalBottomSheet<bool>(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    showDragHandle: true,
    builder: (sheetContext) {
      route = ModalRoute.of<bool>(sheetContext);
      return _StoreInvoiceSurface(
        session: session,
        invoice: invoice,
        onClose: () => Navigator.pop(sheetContext),
        onOpenChat: () => Navigator.pop(sheetContext, true),
      );
    },
  );
  if (chat != true) return;
  await route?.completed;
  if (!context.mounted ||
      session.activeWorkspace?.id != store ||
      session.workspaceFinance?.accountScope != account) {
    return;
  }
  router.push(
    Uri(
      path: '/app/chat/inbox',
      queryParameters: {
        'type': 'business',
        'return': returnRoute,
        'recipient': invoice.customer,
        'draft': _workspaceInvoiceMessage(
          session,
          invoice,
          account,
          store,
          name,
        ),
      },
    ).toString(),
  );
}

class _StoreInvoiceSurface extends StatefulWidget {
  const _StoreInvoiceSurface({
    required this.session,
    required this.invoice,
    required this.onClose,
    this.onOpenChat,
    this.onRecord,
    this.receiptEditor,
    this.embedded = false,
    this.counterAppearance = false,
    this.orderDetails = false,
    super.key,
  });
  final WorkSession session;
  final WorkspaceCustomerInvoice invoice;
  final VoidCallback onClose;
  final VoidCallback? onOpenChat;
  final ValueChanged<WorkspacePaymentRecord>? onRecord;
  final Widget? receiptEditor;
  final bool embedded;
  final bool counterAppearance;
  final bool orderDetails;
  @override
  State<_StoreInvoiceSurface> createState() => _StoreInvoiceSurfaceState();
}

class _StoreInvoiceSurfaceState extends State<_StoreInvoiceSurface> {
  final _invoiceScroll = ScrollController();
  final _invoiceActions = GlobalKey();
  void _showInvoiceActions() {
    final target = _invoiceActions.currentContext;
    if (target != null) {
      Scrollable.ensureVisible(target, alignment: 0,
          duration: const Duration(milliseconds: 180));
    }
  }

  @override
  void didUpdateWidget(covariant _StoreInvoiceSurface oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.receiptEditor != null && widget.receiptEditor == null) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted && _invoiceScroll.hasClients) _invoiceScroll.jumpTo(0);
      });
    }
  }

  @override
  void dispose() {
    _invoiceScroll.dispose();
    super.dispose();
  }

  WorkSession get session => widget.session;
  WorkspaceCustomerInvoice get invoice => widget.invoice;
  bool get _counterInvoice =>
      widget.counterAppearance ||
      session.workspaceOrders.any(
        (order) => order.id == invoice.orderId && order.source == 'Counter',
      );
  late final invoiceAccount = session.workspaceFinance?.accountScope;
  late final invoiceStore = session.activeWorkspace?.id;
  late final invoiceDeliveryScope = session.storeInvoiceDeliveryScope;
  late final invoiceStoreName = invoice.sellerName.trim().isNotEmpty
      ? invoice.sellerName
      : session.activeWorkspace?.name ?? session.workName;
  String? shareError;
  bool openingWhatsApp = false;
  void _openAdjustments(WorkspacePaymentRecord payment) {
    openAdjustments(context, session, invoice, payment, invoiceAccount, invoiceStore);
  }
  static void openAdjustments(BuildContext context, WorkSession session,
      WorkspaceCustomerInvoice invoice, WorkspacePaymentRecord payment,
      String? account, String? store) {
    if (account == null || store == null) return;
    showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      builder: (context) => FractionallySizedBox(
        heightFactor: .9,
        child: AnimatedBuilder(
          animation: session,
          builder: (context, _) {
            final finance = session.workspaceFinance;
            final matching = finance?.payments.any(
              (p) => p.valid && p.invoiceId == invoice.id &&
                  p.orderId == payment.orderId &&
                  p.customerId == payment.customerId,
            ) ?? false;
            if (session.activeWorkspace?.id != store ||
                (finance != null && (finance.workspaceId != store ||
                    finance.accountScope != account))) {
              return const Center(child: Text('Return to this invoice’s Store to view it.'));
            }
            if (finance == null || !matching) {
              return Center(child: Padding(
                padding: const EdgeInsets.all(16),
                child: Text(finance == null
                    ? 'Payment records are unavailable. Close and reopen this invoice after records have loaded.'
                    : 'This invoice’s payment record is unavailable. Close and check its saved records before recording an adjustment.'),
              ));
            }
            return _StoreFinanceSurface(
              session: session,
              section: 'payments',
              returnsOnly: true,
              focus: (
                accountScope: account, workspaceId: store,
                orderId: payment.orderId, customerId: payment.customerId,
                payoutId: null, operationId: null,
              ),
            );
          },
        ),
      ),
    );
  }
  void _openPdf() {
    if (session.activeWorkspace?.id != invoiceStore ||
        session.workspaceFinance?.accountScope != invoiceAccount) {
      return;
    }
    final order = session.workspaceOrders
        .where((value) => value.id == invoice.orderId)
        .firstOrNull;
    final payment = session.workspaceFinance?.payments
        .where(
          (value) =>
              value.valid &&
              value.invoiceId == invoice.id &&
              value.orderId == invoice.orderId,
        )
        .firstOrNull;
    final request = WorkInvoicePdfRequest(
      accountId: invoiceAccount ?? '',
      storeId: invoiceStore ?? '',
      invoice: invoice,
      items: order?.itemSnapshots ?? const [],
      paymentStatus: payment == null
          ? 'Payment status unavailable'
          : '${payment.label} · Received ${_purchaseAmount(payment.paidMinor)} · Due ${_purchaseAmount(payment.dueMinor)}',
    );
    Navigator.of(context).push(
      MaterialPageRoute<void>(
        builder: (_) => WorkInvoicePdfScreen(
          request: request,
          source: createWorkInvoicePdfSource(),
          scopeChanges: session,
          isCurrent: () =>
              session.activeWorkspace?.id == invoiceStore &&
              session.workspaceFinance?.accountScope == invoiceAccount,
        ),
      ),
    );
  }

  @override
  void initState() {
    super.initState();
    // Freeze identity before any account/Store change can rebuild this view.
    invoiceAccount;
    invoiceStore;
    invoiceDeliveryScope;
    invoiceStoreName;
  }

  String invoiceMessage() => _workspaceInvoiceMessage(
    session,
    invoice,
    invoiceAccount,
    invoiceStore,
    invoiceStoreName,
  );

  Widget _invoiceItemRows() {
    final order = session.workspaceOrders
        .where((order) => order.id == invoice.orderId)
        .firstOrNull;
    if (order == null || order.itemSnapshots.isEmpty) {
      return Text(invoice.items);
    }
    return Column(
      key: const Key('work-invoice-item-table'),
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        const Row(
          children: [
            Expanded(
              child: Text(
                'Item',
                style: TextStyle(fontSize: 12, color: MoolColors.muted),
              ),
            ),
            Text(
              'Amount',
              style: TextStyle(fontSize: 12, color: MoolColors.muted),
            ),
          ],
        ),
        for (final line in order.itemSnapshots)
          Padding(
            padding: EdgeInsets.symmetric(vertical: widget.orderDetails ? 5 : 8),
            child: _StoreMoneyLine(
              alignAmountToEnd: true,
              leading: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  if (session.workspaceCatalogueItems
                          .where(
                            (product) =>
                                product.id == line.productId &&
                                product.title == line.name &&
                                product.pack == line.pack,
                          )
                          .firstOrNull
                      case final product?) ...[
                    StoreProductThumbnail(
                      product: product,
                      extent: 32,
                      session: session,
                    ),
                    const SizedBox(width: 8),
                  ],
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          line.name,
                          style: TextStyle(
                            fontSize: widget.orderDetails ? 13 : 14,
                            fontWeight: FontWeight.w600,
                            color: MoolColors.ink,
                          ),
                        ),
                        const SizedBox(height: 2),
                        Text(
                          '${line.pack} · ${line.quantity} × ${_purchaseAmount(line.unitPricePaise)}',
                          style: TextStyle(
                            fontSize: widget.orderDetails ? 11 : 12,
                            color: MoolColors.muted,
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
              value: _purchaseAmount(
                invoice.discountMinor == 0
                    ? line.lineTotalPaise
                    : line.unitPricePaise * line.quantity,
              ),
              style: TextStyle(
                fontSize: widget.orderDetails ? 13 : 14,
                fontWeight: FontWeight.w700,
                color: widget.orderDetails ? MoolColors.ink : MoolColors.navy,
              ),
            ),
          ),
      ],
    );
  }

  Widget _recordedPayments(WorkspacePaymentRecord payment) {
    final ledger = session.workspaceFinance?.customerLedgers
        .where(
          (ledger) =>
              ledger.valid &&
              ledger.accountScope == invoiceAccount &&
              ledger.workspaceId == invoiceStore &&
              ledger.customerId == payment.customerId,
        )
        .firstOrNull;
    final entries =
        ledger?.entries
            .where(
              (entry) =>
                  entry.valid &&
                  entry.invoiceId == invoice.id &&
                  entry.orderId == invoice.orderId &&
                  entry.kind == WorkspaceLedgerEntryKind.collection &&
                  entry.state == WorkspaceLedgerPostingState.posted,
            )
            .toList(growable: false) ??
        const <WorkspaceCustomerLedgerEntry>[];
    if (entries.isEmpty) return const SizedBox.shrink();
    final tile = ExpansionTile(
      key: const Key('work-invoice-recorded-payments'),
      minTileHeight: widget.orderDetails ? 48 : null,
      shape: widget.orderDetails ? const Border() : null,
      collapsedShape: widget.orderDetails ? const Border() : null,
      tilePadding: EdgeInsets.zero,
      title: Text('Recorded payments', style: widget.orderDetails
          ? const TextStyle(fontSize: 12, color: MoolColors.muted) : null),
      children: [
        for (final entry in entries)
          Padding(
            padding: EdgeInsets.only(bottom: widget.orderDetails ? 4 : 12),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                if (widget.orderDetails)
                  _StoreMoneyLine(
                    alignAmountToEnd: true,
                    leading: Text(entry.channel.label,
                      style: const TextStyle(fontSize: 12, color: MoolColors.ink)),
                    value: _purchaseAmount(entry.amountMinor),
                    style: const TextStyle(fontSize: 12, color: MoolColors.navy,
                        fontWeight: FontWeight.w600),
                  )
                else Text(
                  '${entry.channel.label} · ${_purchaseAmount(entry.amountMinor)}',
                  style: TextStyle(fontWeight: FontWeight.w600,
                      fontSize: widget.orderDetails ? 12 : null,
                      color: widget.orderDetails ? MoolColors.ink : null),
                ),
                if (widget.orderDetails)
                  Text('${MaterialLocalizations.of(context).formatShortDate(entry.occurredAt.toLocal())} · '
                    '${MaterialLocalizations.of(context).formatTimeOfDay(TimeOfDay.fromDateTime(entry.occurredAt.toLocal()))}',
                    style: const TextStyle(fontSize: 11, color: MoolColors.muted)),
                if (entry.paymentReference?.trim().isNotEmpty == true)
                  SelectableText('Reference: ${entry.paymentReference}',
                      key: PageStorageKey((invoiceAccount, invoiceStore,
                          invoice.id, 'receipt-reference', entry.id)),
                      style: widget.orderDetails ? const TextStyle(
                          fontSize: 11, color: MoolColors.muted) : null),
              ],
            ),
          ),
      ],
    );
    return widget.orderDetails ? KeyedSubtree(
        key: PageStorageKey((invoiceAccount, invoiceStore, invoice.id, 'recorded-payments')),
        child: tile) : tile;
  }

  Widget _paidReceipt(WorkspacePaymentRecord payment) {
    final billing = invoice.billingDetails;
    final customer = billing.business && billing.businessName.trim().isNotEmpty
        ? billing.businessName.trim()
        : billing.name.trim().isNotEmpty
        ? billing.name.trim()
        : invoice.customer;
    final issued = invoice.issuedAt.toLocal();
    return Column(
      key: const Key('work-paid-invoice-receipt'),
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Container(
          padding: const EdgeInsets.all(16),
          decoration: BoxDecoration(
            color: Colors.white,
            border: Border.all(
              color: widget.counterAppearance
                  ? MoolColors.success
                  : const Color(0xFFE5E8F1),
            ),
            borderRadius: BorderRadius.circular(16),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  Icon(
                    Icons.check_circle_rounded,
                    color: widget.counterAppearance
                        ? MoolColors.success
                        : const Color(0xFF16704A),
                    size: 18,
                  ),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Text(
                      payment.label,
                      key: const Key('work-invoice-payment-summary'),
                      style: TextStyle(
                        color: widget.counterAppearance
                            ? MoolColors.success
                            : const Color(0xFF16704A),
                        fontSize: 13,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 6),
              Text(
                customer,
                style: const TextStyle(
                  fontSize: 14,
                  color: MoolColors.ink,
                  fontWeight: FontWeight.w600,
                ),
              ),
            ],
          ),
        ),
        const SizedBox(height: 8),
        _invoiceItemRows(),
        const Divider(height: 1),
        _invoiceTotal(),
        Text(
          'Received ${_purchaseAmount(payment.paidMinor)} · Due ${_purchaseAmount(payment.dueMinor)}',
          style: const TextStyle(color: MoolColors.muted),
        ),
        if (payment.refundedMinor > 0)
          Text(
            'Refunded ${_purchaseAmount(payment.refundedMinor)}',
            key: const Key('work-invoice-refunded-summary'),
            style: const TextStyle(color: MoolColors.muted),
          ),
        _recordedPayments(payment),
        ExpansionTile(
          key: const Key('work-invoice-details'),
          tilePadding: EdgeInsets.zero,
          childrenPadding: const EdgeInsets.only(bottom: 12),
          shape: const Border(),
          collapsedShape: const Border(),
          title: const Text(
            'Invoice details',
            style: TextStyle(
              fontSize: 13,
              color: MoolColors.muted,
              fontWeight: FontWeight.w600,
            ),
          ),
          children: [
            Align(
              alignment: Alignment.centerLeft,
              child: Text(
                [
                  '${invoice.id} · ${invoice.customer}',
                  invoiceStoreName,
                  ...?invoice.seller?.detailLines,
                  '${issued.day}/${issued.month}/${issued.year}',
                  if (billing.business && billing.name.trim().isNotEmpty)
                    billing.name,
                  if (billing.business && billing.gst.trim().isNotEmpty)
                    'GST: ${billing.gst}',
                  if (billing.address.trim().isNotEmpty) billing.address,
                ].join('\n'),
                style: const TextStyle(
                  fontSize: 12,
                  color: MoolColors.muted,
                  height: 1.5,
                ),
              ),
            ),
          ],
        ),
      ],
    );
  }

  void _openChat(BuildContext context) {
    if (widget.onOpenChat != null) {
      widget.onOpenChat!();
      return;
    }
    GoRouter.of(context).push(
      Uri(
        path: '/app/chat/inbox',
        queryParameters: {
          'type': 'business',
          'return': GoRouterState.of(context).uri.toString(),
          'recipient': invoice.customer,
          'draft': invoiceMessage(),
        },
      ).toString(),
    );
  }

