  // Orders composes the existing invoice rows/totals and payment owners inline.
  // Other invoice callers retain their approved presentation and modal behavior.
  Widget _orderInvoice(WorkspacePaymentRecord? payment, bool canAdjust) {
    final localizations = MaterialLocalizations.of(context);
    final issued = invoice.issuedAt.toLocal();
    return Column(
      key: const Key('work-order-inline-invoice'),
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Row(children: [
          Expanded(child: Text('Invoice · Issued ${localizations.formatShortDate(issued)}',
              style: const TextStyle(fontSize: 11, color: MoolColors.muted))),
          TextButton.icon(key: const Key('work-invoice-open-pdf'),
              onPressed: _openPdf,
              style: TextButton.styleFrom(minimumSize: const Size(48, 48),
                  padding: const EdgeInsets.symmetric(horizontal: 8),
                  textStyle: const TextStyle(fontSize: 12)),
              icon: const Icon(Icons.picture_as_pdf_outlined, size: 18),
              label: const Text('PDF')),
        ]),
        Text(invoice.id, key: const Key('work-order-invoice-reference'),
            style: const TextStyle(fontSize: 11, color: MoolColors.ink)),
        const SizedBox(height: 4),
        _InvoiceCollectionSummary(session: session, invoice: invoice,
            accountScope: invoiceAccount, storeId: invoiceStore, orderDetails: true),
        const Divider(height: 12),
        _invoiceItemRows(),
        _invoiceTotal(),
        if (payment != null && !session.workspaceFinanceStale)
          _recordedPayments(payment),
        KeyedSubtree(
          key: PageStorageKey((invoiceAccount, invoiceStore, invoice.id, 'billing-details')),
          child: ExpansionTile(
          key: const Key('work-invoice-details'), tilePadding: EdgeInsets.zero,
          minTileHeight: 48,
          shape: const Border(), collapsedShape: const Border(),
          title: const Text('Billing details', style: TextStyle(
              fontSize: 12, color: MoolColors.muted)),
          children: [Align(alignment: Alignment.centerLeft,
              child: Text([
                'Sold by: $invoiceStoreName', ...?invoice.seller?.detailLines,
                if (invoice.billingDetails.business && invoice.billingDetails.gst.isNotEmpty)
                  'Customer GST: ${invoice.billingDetails.gst}',
                if (invoice.billingDetails.address.isNotEmpty) invoice.billingDetails.address,
              ].join('\n'), style: const TextStyle(fontSize: 12, color: MoolColors.ink)))],
        )),
        if (canAdjust && !session.workspaceFinanceStale && payment != null)
          Align(alignment: Alignment.centerLeft, child: TextButton.icon(
              key: const Key('work-invoice-adjustments'),
              onPressed: () => _openAdjustments(payment),
              icon: const Icon(Icons.assignment_return_outlined, size: 18),
              label: const Text('Returns & refunds'),
              style: TextButton.styleFrom(textStyle: const TextStyle(fontSize: 12)))),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    if (session.activeWorkspace?.id == invoiceStore &&
        session.workspaceFinance == null && invoiceAccount != null) {
      return const Center(child: Text('Payment records are unavailable. Close and reopen this invoice after records have loaded.'));
    }
    if (session.activeWorkspace?.id != invoiceStore ||
        session.workspaceFinance?.accountScope != invoiceAccount) {
      return const Center(
        child: Text('Return to this invoice’s Store to view it.'),
      );
    }
    final finance = session.workspaceFinance;
    final payment =
        finance?.accountScope == invoiceAccount &&
            finance?.workspaceId == invoiceStore
        ? finance?.payments
              .where(
                (record) =>
                    record.valid &&
                    record.invoiceId == invoice.id &&
                    record.orderId == invoice.orderId,
              )
              .firstOrNull
        : null;
    final issued = invoice.issuedAt.toLocal();
    final paid = payment != null && payment.dueMinor == 0 &&
        payment.paidMinor > 0 && payment.paidMinor >= payment.amountMinor;
    final settlementLedger = finance?.customerLedgers.where((ledger) =>
        ledger.valid && ledger.accountScope == invoiceAccount &&
        ledger.workspaceId == invoiceStore &&
        ledger.customerId == payment?.customerId).firstOrNull;
    final adjusted = (payment?.refundedMinor ?? 0) > 0 ||
        payment?.state == WorkspacePaymentState.refundPending ||
        (finance?.customerLedgers.any(
          (ledger) => ledger.customerId == payment?.customerId &&
              (ledger.invoiceBalance(invoice.id)?.creditedMinor ?? 0) > 0,
        ) ?? false);
    final canAdjust = payment != null &&
        (session.workspaceOrders.any((order) => order.id == invoice.orderId &&
            order.isCompleted && order.hasCompleteItemSnapshot) ||
        (finance?.customerLedgers.any((ledger) => ledger.customerId == payment.customerId &&
            (ledger.invoiceBalance(invoice.id)?.refundableMinor ?? 0) > 0) ?? false));
    if (widget.orderDetails) return _orderInvoice(payment, canAdjust);
    return StatefulBuilder(
      builder: (sheetContext, updateSheet) => SafeArea(
        top: false,
        bottom: !widget.embedded,
        child: Padding(
          padding: const EdgeInsets.fromLTRB(18, 8, 18, 18),
          child: SingleChildScrollView(
            controller: _invoiceScroll,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Row(
                  children: [
                    Expanded(
                      child: Text(
                        widget.counterAppearance
                            ? 'Invoice created'
                            : 'Invoice',
                        key: const Key('work-invoice-title'),
                        style: TextStyle(
                          color: MoolColors.ink,
                          fontSize: widget.counterAppearance ? 18 : 21,
                          fontWeight: FontWeight.w700,
                        ),
                      ),
                    ),
                    if (payment != null && (!paid || canAdjust)) IconButton(
                      key: const Key('work-invoice-jump-actions'),
                      tooltip: 'Payment and return actions',
                      onPressed: _showInvoiceActions,
                      icon: const Icon(Icons.keyboard_double_arrow_down_rounded),
                    ),
                    IconButton(
                      key: const Key('work-invoice-open-pdf'),
                      tooltip: 'Open PDF',
                      onPressed: _openPdf,
                      icon: const Icon(Icons.picture_as_pdf_outlined),
                    ),
                    if (!widget.embedded)
                      IconButton(
                        tooltip: 'Close invoice',
                        onPressed: widget.onClose,
                        icon: const Icon(Icons.close_rounded),
                      ),
                  ],
                ),
                if (paid)
                  _paidReceipt(payment)
                else ...[
                  if (payment != null)
                    Container(
                      key: const Key('work-invoice-pending-accent'),
                      padding: widget.counterAppearance
                          ? const EdgeInsets.only(left: 8)
                          : EdgeInsets.zero,
                      decoration: widget.counterAppearance
                          ? const BoxDecoration(
                              border: Border(
                                left: BorderSide(
                                  color: MoolColors.orange,
                                  width: 3,
                                ),
                              ),
                            )
                          : null,
                      child: Text(
                        payment.label,
                        key: const Key('work-invoice-payment-summary'),
                        style: TextStyle(
                          fontWeight: FontWeight.w600,
                          color: widget.counterAppearance
                              ? MoolColors.navy
                              : null,
                        ),
                      ),
                    ),
                  const SizedBox(height: 8),
                  Text(
                    invoice.billingDetails.name.trim().isNotEmpty
                        ? invoice.billingDetails.name
                        : invoice.customer,
                    style: TextStyle(
                      fontWeight: FontWeight.w600,
                      fontSize: widget.counterAppearance ? 14 : 17,
                    ),
                  ),
                  if (invoice.billingDetails.name.trim().isNotEmpty)
                    Text(
                      invoice.customer,
                      style: const TextStyle(color: MoolColors.muted),
                    ),
                  const SizedBox(height: 12),
                  Container(
                    padding: widget.counterAppearance
                        ? const EdgeInsets.symmetric(vertical: 8)
                        : EdgeInsets.all(
                            MediaQuery.textScalerOf(sheetContext).scale(1) > 1.5
                                ? 8
                                : 14,
                          ),
                    decoration: BoxDecoration(
                      color: widget.counterAppearance
                          ? Colors.white
                          : const Color(0xFFF4F6FF),
                      borderRadius: BorderRadius.circular(18),
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        _invoiceItemRows(),
                        const Divider(height: 1),
                        _invoiceTotal(),
                        Text(
                          storeInvoicePaymentMethod(invoice.payment, payment,
                              settlementLedger?.entries ?? const []),
                          style: const TextStyle(color: MoolColors.muted),
                        ),
                      ],
                    ),
                  ),
                  const SizedBox(height: 8),
                  KeyedSubtree(key: _invoiceActions, child: _InvoiceCollectionSummary(
                    session: session,
                    invoice: invoice,
                    accountScope: invoiceAccount,
                    storeId: invoiceStore,
                    onRecord: widget.onRecord,
                    receiptEditor: widget.receiptEditor,
                  )),
                  if (payment != null) _recordedPayments(payment),
                  ExpansionTile(
                    key: const Key('work-invoice-details'),
                    tilePadding: EdgeInsets.zero,
                    childrenPadding: const EdgeInsets.only(bottom: 12),
                    expandedCrossAxisAlignment: CrossAxisAlignment.start,
                    title: const Text('Invoice details'),
                    children: [
                      Text(invoice.id),
                      Text('Sold by: $invoiceStoreName'),
                      for (final line
                          in invoice.seller?.detailLines ?? const <String>[])
                        Text(line),
                      Text(
                        'Invoice date: ${issued.day}/${issued.month}/${issued.year}',
                      ),
                      if (invoice.billingDetails.business &&
                          invoice.billingDetails.businessName.trim().isNotEmpty)
                        Text(invoice.billingDetails.businessName),
                      if (invoice.billingDetails.business &&
                          invoice.billingDetails.gst.trim().isNotEmpty)
                        Text('GST: ${invoice.billingDetails.gst}'),
                      if (invoice.billingDetails.address.trim().isNotEmpty)
                        Text(invoice.billingDetails.address),
                    ],
                  ),
                ],
                if (paid && canAdjust) SizedBox(key: _invoiceActions),
                if (canAdjust)
                  Align(
                    alignment: Alignment.centerLeft,
                    child: TextButton.icon(
                      key: const Key('work-invoice-adjustments'),
                      onPressed: () => _openAdjustments(payment),
                      icon: const Icon(Icons.assignment_return_outlined, size: 18),
                      label: const Text('Returns & refunds'),
                    ),
                  ),
                if (!adjusted && session.workspaceOrders.any(
                  (order) =>
                      order.id == invoice.orderId &&
                      order.source == 'Counter' &&
                      !order.needsDelivery,
                )) ...[
                  const SizedBox(height: 12),
                  Text(
                    storeCounterSettlementHint(payment,
                        settlementLedger?.entries ?? const []),
                    key: Key('work-counter-handover-hint'),
                    style: const TextStyle(
                      color: MoolColors.muted,
                      fontSize: 12,
                      height: 1.35,
                    ),
                  ),
                ],
                if (shareError != null) ...[
                  const SizedBox(height: 8),
                  Semantics(
                    liveRegion: true,
                    child: Text(
                      shareError!,
                      key: const Key('work-invoice-share-error'),
                      style: const TextStyle(color: MoolColors.navy),
                    ),
                  ),
                ],
                if (_counterInvoice)
                  _StoreInvoiceDeliveryPreferenceView(
                    key: ValueKey((invoiceDeliveryScope, invoice.id)),
                    session: session,
                    scope: invoiceDeliveryScope,
                  ),
                if (!_counterInvoice) ...[
                  const SizedBox(height: 12),
                  Align(
                    alignment: Alignment.centerLeft,
                    child: TextButton.icon(
                      key: const Key('work-invoice-share-chat'),
                      onPressed: () => _openChat(sheetContext),
                      icon: const Icon(Icons.chat_bubble_outline_rounded),
                      label: const Text('Share in MoolSocial Chat'),
                    ),
                  ),
                  Align(
                    alignment: Alignment.centerLeft,
                    child: TextButton.icon(
                      key: const Key('work-invoice-share-whatsapp'),
                      onPressed: openingWhatsApp
                          ? null
                          : () async {
                              final digits = invoice.customer.replaceAll(
                                RegExp(r'\D'),
                                '',
                              );
                              final mobile = digits.length == 10
                                  ? '91$digits'
                                  : digits;
                              if (!RegExp(r'^91[6-9]\d{9}$').hasMatch(mobile)) {
                                updateSheet(() {
                                  shareError =
                                      'This invoice needs a valid customer phone number for WhatsApp. You can send it in MoolSocial Chat.';
                                });
                                return;
                              }
                              updateSheet(() {
                                shareError = null;
                                openingWhatsApp = true;
                              });
                              try {
                                final opened = await launchUrl(
                                  Uri.https('wa.me', '/$mobile', {
                                    'text': invoiceMessage(),
                                  }),
                                  mode: LaunchMode.externalApplication,
                                );
                                if (!sheetContext.mounted) return;
                                if (opened) {
                                  widget.onClose();
                                  session.showNotice(
                                    'Invoice opened in WhatsApp. Complete sending it there.',
                                  );
                                } else {
                                  updateSheet(() {
                                    shareError =
                                        'WhatsApp could not open. Try again or use MoolSocial Chat.';
                                  });
                                }
                              } on Object {
                                if (sheetContext.mounted) {
                                  updateSheet(() {
                                    shareError =
                                        'WhatsApp could not open. Try again or use MoolSocial Chat.';
                                  });
                                }
                              } finally {
                                if (sheetContext.mounted) {
                                  updateSheet(() => openingWhatsApp = false);
                                }
                              }
                            },
                      icon: const Icon(Icons.send_outlined),
                      label: const Text('Share on WhatsApp'),
                    ),
                  ),
                ],
              ],
            ),
          ),
        ),
      ),
    );
  }
}

