class _WorkspaceSearchSurface extends StatelessWidget {
  const _WorkspaceSearchSurface({
    required this.session,
    required this.query,
    this.ordersOnly = false,
    required this.scrollController,
    required this.onClear,
    required this.onOpenRecord,
  });

  final WorkSession session;
  final String query;
  final bool ordersOnly;
  final ScrollController scrollController;
  final VoidCallback onClear;
  final ValueChanged<_WorkspaceSearchRecord> onOpenRecord;

  @override
  Widget build(BuildContext context) {
    final normalized = query.trim().toLowerCase();
    final results = _workspaceSearchRecords(session, normalized,
        ordersOnly: ordersOnly)
        .where((record) =>
            !ordersOnly || record.kind == _WorkspaceSearchKind.order)
        .toList();
    return AnimatedSwitcher(
      key: const Key('work-dashboard-search-screen'),
      // Repeated empty/results states can overlap outgoing fades. Let the
      // switcher give each transition its own identity.
      transitionBuilder: (child, animation) =>
          FadeTransition(opacity: animation, child: child),
      duration: MediaQuery.of(context).disableAnimations
          ? Duration.zero
          : const Duration(milliseconds: 160),
      child: results.isEmpty
          ? ordersOnly
              ? Align(
                  key: const Key('work-dashboard-search-empty'),
                  alignment: AlignmentDirectional.topStart,
                  child: SingleChildScrollView(
                    keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
                    padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(normalized.isEmpty ? 'No saved orders yet' : 'No matching order',
                          style: const TextStyle(color: MoolColors.navy,
                            fontSize: 14, fontWeight: FontWeight.w600)),
                        const SizedBox(height: 4),
                        Text(normalized.isEmpty
                            ? 'Saved orders will appear here.'
                            : 'Try the customer’s name, phone or order number.',
                          style: const TextStyle(color: MoolColors.ink, fontSize: 12)),
                      ],
                    ),
                  ),
                )
              : Center(
              key: const Key('work-dashboard-search-empty'),
              child: SingleChildScrollView(
                keyboardDismissBehavior:
                    ScrollViewKeyboardDismissBehavior.onDrag,
                child: Padding(
                  padding: const EdgeInsets.all(MoolSpacing.lg),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      const Icon(
                        Icons.manage_search_rounded,
                        size: 46,
                        color: MoolColors.muted,
                      ),
                      const SizedBox(height: MoolSpacing.sm),
                      Text(
                        ordersOnly
                            ? (normalized.isEmpty
                                ? 'No saved orders yet'
                                : 'No matching order')
                            : normalized.isEmpty
                            ? 'Search products, orders, customers or records'
                            : 'No matching store record',
                        textAlign: TextAlign.center,
                        style: const TextStyle(
                          color: MoolColors.navy,
                          fontSize: 17,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      if (normalized.isNotEmpty) ...[
                        const SizedBox(height: MoolSpacing.sm),
                        TextButton.icon(
                          key: const Key('work-dashboard-search-clear'),
                          onPressed: onClear,
                          icon: const Icon(Icons.close_rounded),
                          label: const Text('Clear search'),
                        ),
                      ],
                    ],
                  ),
                ),
              ),
            )
          : ListView.separated(
              key: const Key('work-dashboard-search-results'),
              controller: scrollController,
              keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
              padding: EdgeInsets.fromLTRB(
                MediaQuery.textScalerOf(context).scale(1) >= 2
                    ? 8
                    : MoolSpacing.md,
                MoolSpacing.sm,
                MediaQuery.textScalerOf(context).scale(1) >= 2
                    ? 8
                    : MoolSpacing.md,
                MoolSpacing.xl,
              ),
              itemCount: results.length,
              separatorBuilder: (_, _) =>
                  const SizedBox(height: MoolSpacing.xs),
              itemBuilder: (context, index) {
                final destination = results[index];
                if (ordersOnly) {
                  final order = session.visibleWorkspaceOrders
                      .where((record) => record.id == destination.entityId).firstOrNull;
                  if (order == null) return const SizedBox.shrink();
                  return _OrdersHistoryRow(
                    session: session, order: order,
                    searchResult: true,
                    onOpen: () => onOpenRecord(destination),
                  );
                }
                return _WorkspaceNavigationRow(
                  keyName: 'work-search-${destination.id}',
                  icon: destination.icon,
                  title: destination.title,
                  detail: destination.detail,
                  amount: destination.amount,
                  wideMoney: destination.kind == _WorkspaceSearchKind.purchase,
                  amountLabel: switch (destination.kind) {
                    _WorkspaceSearchKind.order => 'Order total',
                    _WorkspaceSearchKind.invoice => 'Invoice total',
                    _WorkspaceSearchKind.purchase => 'Purchase total',
                    _ => 'Price',
                  },
                  onTap: () => onOpenRecord(destination),
                );
              },
            ),
    );
  }
}

String _customerBalanceText(WorkspaceCustomerRecord customer) =>
    !customer.balanceAvailable
    ? 'Balance unavailable'
    : _purchaseAmount(customer.amountDueMinor);

String _purchaseAmount(int minor) {
  final magnitude = minor.abs();
  return '${minor < 0 ? '−' : ''}₹${_formatStoreAmount(magnitude ~/ 100)}'
      '${magnitude % 100 == 0 ? '' : '.${(magnitude % 100).toString().padLeft(2, '0')}'}';
}

class _StoreReceiptEditor extends StatefulWidget {
  const _StoreReceiptEditor({
    super.key,
    required this.session,
    required this.purchase,
  });
  final WorkSession session;
  final WorkspacePurchaseRecord purchase;
  @override
  State<_StoreReceiptEditor> createState() => _StoreReceiptEditorState();
}

class _StoreReceiptEditorState extends State<_StoreReceiptEditor> {
  bool _open = false, _loading = false, _restored = false;
  final _counts = <String, TextEditingController>{};
  final _returns = <String, TextEditingController>{};
  final _problems = <String, WorkspaceReceiptProblem>{};
  final _note = TextEditingController();
  final _noteKey = GlobalKey();

  Future<void> _start({bool issue = false}) async {
    setState(() {
      _open = true;
      _loading = true;
    });
    final session = widget.session;
    await session.loadWorkspaceReceiptDraft(widget.purchase);
    if (!mounted) return;
    if (session.workspaceReceiptDraftLoaded(widget.purchase) &&
        session.workspaceReceiptDraft(widget.purchase) == null) {
      // Bind even an empty draft to the lines currently being checked.
      await session.saveWorkspaceReceiptDraft(
        widget.purchase,
        countedPacks: const {},
        problems: const {},
        note: '',
      );
    }
    if (!mounted) return;
    final draft = session.workspaceReceiptDraft(widget.purchase);
    if (!_restored && draft != null) {
      for (final line in draft.lines) {
        _counts[line.id] = TextEditingController(
          text: draft.countedPacks[line.id] ?? '',
        );
        _returns[line.id] = TextEditingController(
          text: draft.returnedPacks[line.id] ?? '',
        );
      }
      _problems.addAll(draft.problems);
      _note.text = draft.note;
      _restored = true;
    }
    setState(() => _loading = false);
    if (issue && _restored) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        final target = _noteKey.currentContext;
        if (mounted && target != null) {
          unawaited(Scrollable.ensureVisible(target, alignment: .3));
        }
      });
    }
  }

  Future<void> _save() async {
    await widget.session.saveWorkspaceReceiptDraft(
      widget.purchase,
      countedPacks: _counts.map(
        (id, controller) => MapEntry(id, controller.text),
      ),
      problems: _problems,
      returnedPacks: _returns.map(
        (id, controller) => MapEntry(id, controller.text),
      ),
      note: _note.text,
    );
    if (mounted) setState(() {});
  }

  @override
  void dispose() {
    for (final controller in _counts.values) {
      controller.dispose();
    }
    for (final controller in _returns.values) {
      controller.dispose();
    }
    _note.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final session = widget.session;
    final purchase = widget.purchase;
    final draft = session.workspaceReceiptDraft(purchase);
    final ownReviewReceipt =
        draft != null &&
        session.canConfirmStoreReviewReceipt(purchase) &&
        purchase.receiptReference?.startsWith('TEST-') == true &&
        draft.matchesPurchasedItems(purchase);
    final lines = _open && draft != null && !ownReviewReceipt
        ? draft.lines
        : purchase.lines;
    final message = session.workspaceReceiptDraftMessage(purchase);
    final enlarged = MediaQuery.textScalerOf(context).scale(14) > 21;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        if (!_open)
          Wrap(
            spacing: 8,
            children: [
              TextButton.icon(
                key: const Key('work-receipt-start'),
                onPressed: () => _start(),
                icon: const Icon(Icons.inventory_2_outlined),
                label: const Text('Receive stock'),
                style: TextButton.styleFrom(minimumSize: const Size(48, 48)),
              ),
              TextButton(
                key: const Key('work-receipt-report'),
                onPressed: () => _start(issue: true),
                style: TextButton.styleFrom(minimumSize: const Size(48, 48)),
                child: const Text('Report issue'),
              ),
            ],
          )
        else ...[
          Row(
            children: [
              const Expanded(
                child: Text(
                  'Check delivery',
                  style: TextStyle(
                    fontWeight: FontWeight.w700,
                    color: MoolColors.navy,
                  ),
                ),
              ),
              TextButton(
                key: const Key('work-receipt-close'),
                onPressed: () {
                  FocusScope.of(context).unfocus();
                  setState(() => _open = false);
                },
                style: TextButton.styleFrom(minimumSize: const Size(48, 48)),
                child: const Text('Close'),
              ),
            ],
          ),
          const Text(
            'Count the packs in this delivery. Stock stays unchanged until the receipt is confirmed.',
            style: TextStyle(fontSize: 12, color: MoolColors.muted),
          ),
          if (_loading) const Text('Opening your draft…'),
          if (!_loading && !_restored)
            TextButton(
              key: const Key('work-receipt-retry-open'),
              onPressed: () => _start(),
              child: const Text('Try again'),
            ),
          if (draft != null &&
              !draft.matchesSnapshot(purchase) &&
              !ownReviewReceipt)
            const Padding(
              padding: EdgeInsets.symmetric(vertical: 8),
              child: Text(
                'Delivery updated. Close to compare the latest items with your saved checks.',
                key: Key('work-receipt-stale'),
                style: TextStyle(fontSize: 12, fontWeight: FontWeight.w600),
              ),
            ),
        ],
        for (final line in lines)
          Padding(
            key: ValueKey('work-purchase-line-${line.id}'),
            padding: const EdgeInsets.symmetric(vertical: 10),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  '${line.name}${line.pack.isEmpty ? '' : ' · ${line.pack}'}',
                  style: const TextStyle(fontWeight: FontWeight.w700),
                ),
                Text('${_purchaseAmount(line.unitPriceMinor)} / pack'),
                Text(
                  'Ordered ${line.orderedPacks} packs · Received ${line.receivedPacks == null ? 'not confirmed' : '${line.receivedPacks} packs'}',
                ),
                if (line.receivedPacks != null &&
                    line.receivedPacks != line.orderedPacks)
                  Text(
                    line.receivedPacks! < line.orderedPacks
                        ? '${line.orderedPacks - line.receivedPacks!} packs outstanding'
                        : '${line.receivedPacks! - line.orderedPacks} extra packs reported',
                    style: const TextStyle(
                      fontSize: 12,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                if (_open && _restored) ...[
                  const SizedBox(height: 8),
                  TextField(
                    key: ValueKey('work-receipt-count-${line.id}'),
                    controller: _counts[line.id],
                    keyboardType: TextInputType.number,
                    textInputAction: TextInputAction.next,
                    decoration: InputDecoration(
                      labelText: 'Packs checked',
                      errorText:
                          (_counts[line.id]?.text.trim().isNotEmpty ?? false) &&
                              draft?.counted(line.id) == null
                          ? 'Enter a whole number of packs.'
                          : null,
                      errorMaxLines: 3,
                    ),
                    onChanged: (_) {
                      unawaited(_save());
                    },
                  ),
                  if (session.canConfirmStoreReviewReceipt(purchase))
                    TextField(
                      key: ValueKey('work-supplier-return-count-${line.id}'),
                      controller: _returns[line.id],
                      keyboardType: TextInputType.number,
                      decoration: const InputDecoration(
                        labelText: 'Returned packs',
                        helperText:
                            'Include any packs already returned for this delivery.',
                        helperMaxLines: 3,
                      ),
                      onChanged: (_) {
                        unawaited(_save());
                      },
                    ),
                  const SizedBox(height: 8),
                  DropdownButtonFormField<String>(
                    key: ValueKey('work-receipt-problem-${line.id}'),
                    initialValue: _problems[line.id]?.name ?? 'none',
                    isExpanded: true,
                    isDense: !enlarged,
                    itemHeight: null,
                    decoration: const InputDecoration(labelText: 'Item issue'),
                    items: [
                      const DropdownMenuItem(
                        value: 'none',
                        child: Text('No issue noted'),
                      ),
                      for (final problem in WorkspaceReceiptProblem.values)
                        DropdownMenuItem(
                          value: problem.name,
                          child: Text(problem.label),
                        ),
                    ],
                    onChanged: (value) {
                      if (value == null) return;
                      if (value == 'none') {
                        _problems.remove(line.id);
                      } else {
                        _problems[line.id] = WorkspaceReceiptProblem.values
                            .byName(value);
                      }
                      unawaited(_save());
                    },
                  ),
                ],
              ],
            ),
          ),
        if (_open && _restored) ...[
          TextField(
            key: _noteKey,
            controller: _note,
            minLines: 1,
            maxLines: enlarged ? 2 : 3,
            maxLength: 2000,
            decoration: const InputDecoration(
              labelText: 'Delivery note',
              helperText: 'Add details if needed.',
              helperMaxLines: 3,
              helperStyle: TextStyle(fontSize: 12),
              counterStyle: TextStyle(fontSize: 11),
            ),
            onChanged: (_) {
              unawaited(_save());
            },
          ),
          if (session.canConfirmStoreReviewReceipt(purchase))
            FilledButton.tonal(
              key: const Key('work-receipt-confirm-test'),
              onPressed: _loading
                  ? null
                  : () async {
                      setState(() => _loading = true);
                      try {
                        await _save();
                        await session.confirmStoreReviewReceipt(purchase);
                      } finally {
                        if (mounted) {
                          setState(() => _loading = false);
                        }
                      }
                    },
              child: const Text('Confirm test receipt'),
            )
          else
            const Text(
              'Sending this receipt is not available yet.',
              style: TextStyle(fontSize: 12, color: MoolColors.muted),
            ),
          if (session.canConfirmStoreReviewReceipt(purchase))
            TextButton(
              key: const Key('work-supplier-return-confirm-test'),
              onPressed: _loading
                  ? null
                  : () async {
                      setState(() => _loading = true);
                      try {
                        await _save();
                        await session.confirmStoreReviewSupplierReturn(
                          purchase,
                        );
                      } finally {
                        if (mounted) {
                          setState(() => _loading = false);
                        }
                      }
                    },
              child: const Text('Confirm test return'),
            ),
        ],
        if (_open && message != null)
          Text(
            message,
            key: const Key('work-receipt-save-state'),
            style: const TextStyle(fontSize: 12),
          ),
        if (_open &&
            _restored &&
            message?.startsWith('Draft not saved') == true)
          TextButton(
            key: const Key('work-receipt-retry-save'),
            onPressed: _save,
            child: const Text('Retry saving'),
          ),
      ],
    );
  }
}

/// Presentation only: number ambiguous choices against the complete ledger,
/// never the filtered picker. Recorded order is not physical arrival order.
@visibleForTesting
String storeBillGoodsReceiptLabel(
  Iterable<WorkspaceSupplierGoodsReceipt> receipts,
  WorkspaceSupplierGoodsReceipt receipt,
  WorkspaceSupplierGoodsReceiptLine line,
) {
  final base = '${receipt.reference} · ${receipt.deliveredOn} · ${line.purchaseUnit}';
  final group = [
    for (final other in receipts)
      if (other.reference == receipt.reference && other.deliveredOn == receipt.deliveredOn)
        for (final item in other.lines)
          if (item.productId == line.productId && item.purchaseUnit == line.purchaseUnit)
            (other, item),
  ]..sort((a, b) {
      final time = a.$1.recordedAt.compareTo(b.$1.recordedAt);
      if (time != 0) return time;
      final identity = a.$1.id.compareTo(b.$1.id);
      return identity != 0 ? identity : a.$2.sourceLineId.compareTo(b.$2.sourceLineId);
    });
  if (group.length < 2) return base;
  final index = group.indexWhere((pair) =>
    pair.$1.id == receipt.id && pair.$2.sourceLineId == line.sourceLineId);
  if (index < 0) return base;
  return '$base\nReceipt record ${index + 1} · Receipt line totals: '
    'Accepted ${_ReceivingLineInput._quantity(line.acceptedMilli)} ${line.purchaseUnit} · '
    'Damaged ${_ReceivingLineInput._quantity(line.damagedMilli)} ${line.purchaseUnit}';
}

/// Matches immutable supplier records; this surface never receives Stock or pays.
class _StoreBillGoodsMatch extends StatefulWidget {
  const _StoreBillGoodsMatch({super.key, required this.session, required this.copy,
    required this.onOpenCopy});
  final WorkSession session;
  final WorkspacePurchaseSavedCopy copy;
  final Future<void> Function(WorkspacePurchaseSavedCopy copy) onOpenCopy;
  @override
  State<_StoreBillGoodsMatch> createState() => _StoreBillGoodsMatchState();
}

class _StoreBillGoodsMatchState extends State<_StoreBillGoodsMatch>
    with AutomaticKeepAliveClientMixin<_StoreBillGoodsMatch> {
  @override
  bool get wantKeepAlive => true;
  late final _scope = widget.session.workspaceSupplierScope;
  final _quantity = TextEditingController(), _free = TextEditingController(text: '0');
  final _accepted = TextEditingController(), _damaged = TextEditingController(text: '0');
  final _numerator = TextEditingController(text: '1'), _denominator = TextEditingController(text: '1');
  bool _opened = false, _busy = false, _loaded = false, _reviewVerified = false, _conversion = false;
  bool _uncertain = false, _knownUnstored = false;
  int? _item, _bookRevision;
  (String, String)? _receiptKey;
  WorkspaceSupplierBillGoodsAllocation? _frozen;
  WorkspaceBillGoodsReviewCancellation? _cancelAttempt;
  WorkspaceSupplierBillGoodsReview? _otherReview;
  final _savedReviewAnchor = GlobalKey();
  String? _error, _notice;
  WorkSession get session => widget.session;
  bool get _current => mounted && _scope != null && _scope == session.workspaceSupplierScope;
  WorkspaceSupplierLedger? get _ledger => session.workspaceInvoiceHistoryLoaded
    ? session.workspaceSupplierLedger(widget.copy.supplier.id) : null;
  bool get _committed => _frozen != null &&
    jsonEncode(_ledger?.billGoodsAllocations[_frozen!.operationId]?.toJson()) == jsonEncode(_frozen!.toJson());
  bool get _dirty => _frozen == null && (_item != null || _receiptKey != null ||
    _quantity.text.isNotEmpty || _accepted.text.isNotEmpty);
  bool get _editable => _current && _loaded && _ledger != null && !_busy && !_uncertain &&
    !session.workspaceSupplierRecoveryRequired && _frozen == null && _otherReview == null;
  List<(WorkspaceSupplierGoodsReceipt, WorkspaceSupplierGoodsReceiptLine)> get _receipts {
    if (_item == null || _ledger == null) return const [];
    final product = widget.copy.draft.goods[_item!]['productId'];
    return [for (final receipt in _ledger!.goodsReceipts.values)
      if (session.workspaceGoodsReceiptDrafts.any((review) => review.supplierId == widget.copy.supplier.id &&
          jsonEncode(review.receipt.toJson()) == jsonEncode(receipt.toJson())))
        for (final line in receipt.lines) if (line.productId == product) (receipt, line)];
  }
  (WorkspaceSupplierGoodsReceipt, WorkspaceSupplierGoodsReceiptLine)? get _receipt =>
    _receipts.where((pair) => (pair.$1.id, pair.$2.sourceLineId) == _receiptKey).singleOrNull;
  String _reviewReceiptLabel(String receiptId, String lineId) {
    final receipt = _ledger?.goodsReceipts[receiptId];
    final line = receipt?.lines.where((item) => item.sourceLineId == lineId).firstOrNull;
    if (receipt == null || line == null) return receipt?.reference ?? receiptId;
    final label = storeBillGoodsReceiptLabel(_ledger!.goodsReceipts.values, receipt, line);
    // Keep the approved compact summary for an unambiguous receipt.
    return label.contains('\n') ? label : receipt.reference;
  }
  @override
  void initState() { super.initState(); unawaited(_recover()); }
  @override
  void dispose() {
    for (final c in [_quantity, _free, _accepted, _damaged, _numerator, _denominator]) { c.dispose(); }
    super.dispose();
  }
  Future<bool> confirmLeave() async {
    if (_busy) return false;
    if (_frozen != null && !_reviewVerified && !_committed && !_knownUnstored) {
      setState(() { _opened = true; _error = 'Review save status is unverified. Retry saved status before leaving.'; _uncertain = true; });
      return false;
    }
    if (!_dirty && !_knownUnstored) return true; // Only a verified saved review survives leaving.
    final leave = await showDialog<bool>(context: context, builder: (context) => AlertDialog(
      title: const Text('Leave goods match?'),
      content: const Text('These matching quantities are not saved. The supplier bill and received Stock stay unchanged.'),
      actions: [TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Keep editing')),
        TextButton(onPressed: () => Navigator.pop(context, true), child: const Text('Discard changes'))]));
    if (mounted && leave == true) setState(_clear);
    return mounted && leave == true;
  }
  Future<void> _recover() async {
    if (!_current) return;
    setState(() { _busy = true; _error = null; });
    final ready = await session.loadWorkspaceSuppliers(retry: true) && await session.recoverCustomerLedger();
    if (!_current) return;
    final ledger = _ledger;
    final exact = ledger != null && jsonEncode(ledger.purchaseBills[widget.copy.draft.id]?.copy.toJson()) ==
      jsonEncode(widget.copy.toJson());
    _bookRevision = session.workspacePurchaseEntryRevision;
    _loaded = ready && exact && _bookRevision != null;
    if (!_loaded) {
      setState(() { _busy = false; _uncertain = true; _error = 'Saved bill or supplier account is unavailable. Retry without adding these goods again.'; });
      return;
    }
    _uncertain = false;
    for (final review in session.workspaceBillGoodsReviews.where((r) => r.supplierId == widget.copy.supplier.id)) {
      final posted = ledger!.billGoodsAllocations[review.allocation.operationId];
      final cancelled = session.workspaceBillGoodsCancellations.any((c) => c.operationId == review.allocation.operationId);
      if (posted != null && (cancelled || jsonEncode(posted.toJson()) != jsonEncode(review.allocation.toJson()))) {
        setState(() { _busy = false; _uncertain = true; _error = 'Saved goods matching needs recovery. Do not receive or match these goods again.'; });
        return;
      }
    }
    final pending = session.workspaceBillGoodsReviews.where((review) =>
      review.supplierId == widget.copy.supplier.id &&
      !session.workspaceBillGoodsCancellations.any((c) => c.operationId == review.allocation.operationId) &&
      !ledger!.billGoodsAllocations.containsKey(review.allocation.operationId)).toList();
    _otherReview = pending.where((r) => r.allocation.copyId != widget.copy.id ||
      r.allocation.copyRevision != widget.copy.revision).firstOrNull;
    if (pending.length > 1) { _uncertain = true; _error = 'More than one unfinished match needs recovery. Do not prepare another match.'; }
    final own = pending.where((r) => r.allocation.copyId == widget.copy.id &&
      r.allocation.copyRevision == widget.copy.revision).singleOrNull;
    if (own != null) {
      if (_frozen != null && jsonEncode(_frozen!.toJson()) != jsonEncode(own.allocation.toJson())) {
        setState(() { _busy = false; _uncertain = true; _error = 'Another saved matching review was found. Keep this attempt and recover before continuing.'; });
        return;
      }
      _frozen = own.allocation; _reviewVerified = true; _opened = true;
    }
    if (_frozen != null) {
      final cancellation = session.workspaceBillGoodsCancellations.where((c) => c.operationId == _frozen!.operationId).singleOrNull;
      final posted = ledger!.billGoodsAllocations[_frozen!.operationId];
      final savedReview = session.workspaceBillGoodsReviews.where((r) => r.allocation.operationId == _frozen!.operationId).singleOrNull;
      _reviewVerified = savedReview != null && savedReview.supplierId == widget.copy.supplier.id &&
        jsonEncode(savedReview.allocation.toJson()) == jsonEncode(_frozen!.toJson());
      _knownUnstored = savedReview == null && posted == null && cancellation == null;
      if (cancellation != null && posted != null) {
        _uncertain = true;
        _error = 'Saved match and cancellation conflict. Recover the supplier account; do not replace this match.';
      } else if (cancellation != null) {
        _clear(); _notice = 'Matching review cancelled. Bill, Stock and payments are unchanged.';
      } else if (posted != null && jsonEncode(posted.toJson()) != jsonEncode(_frozen!.toJson())) {
        _uncertain = true;
        _error = 'Saved matching details conflict. Recover before continuing.';
      } else if ((savedReview != null && !_reviewVerified) || (posted != null && savedReview == null)) {
        _uncertain = true; _error = 'Saved matching review is missing or changed. Recover before continuing.';
      }
    }
    setState(() { _busy = false; });
  }
  void _clear() {
    _knownUnstored = false; _uncertain = false; _error = null; _notice = null;
    _frozen = null; _reviewVerified = false; _cancelAttempt = null; _item = null; _receiptKey = null;
    _quantity.clear(); _accepted.clear(); _free.text = '0'; _damaged.text = '0'; _conversion = false;
  }
  void _chooseReceipt((String, String)? key) {
    _receiptKey = key; _conversion = false;
    final pair = _receipt;
    if (pair == null || _item == null) return;
    final unit = widget.copy.draft.goods[_item!]['pack']!.trim();
    final previous = _ledger!.billGoodsAllocations.values.where((link) =>
      link.billId == widget.copy.draft.id && link.billLineIndex == _item).firstOrNull;
    _numerator.text = '${previous?.stockUnitsNumerator ?? (unit == pair.$2.stockUnit ? 1 :
      unit == pair.$2.purchaseUnit ? pair.$2.unitsPerPack : 1)}';
    _denominator.text = '${previous?.stockUnitsDenominator ?? 1}';
  }
  WorkspaceSupplierBillGoodsAllocation? _snapshot() {
    final pair = _receipt;
    if (_item == null || pair == null || !_conversion || _ledger == null) return null;
    final qty = _ReceivingLineInput.milli(_quantity.text), free = _ReceivingLineInput.milli(_free.text);
    final accepted = _ReceivingLineInput.milli(_accepted.text), damaged = _ReceivingLineInput.milli(_damaged.text);
    final numerator = int.tryParse(_numerator.text), denominator = int.tryParse(_denominator.text);
    if ([qty, free, accepted, damaged, numerator, denominator].any((v) => v == null)) return null;
    final line = widget.copy.draft.goods[_item!];
    return WorkspaceSupplierBillGoodsAllocation(operationId: session.newWorkspaceBillGoodsLinkId(),
      receiptId: pair.$1.id, receiptLineId: pair.$2.sourceLineId, billId: widget.copy.draft.id,
      copyId: widget.copy.id, copyRevision: widget.copy.revision, billLineIndex: _item!,
      productId: pair.$2.productId, billUnit: line['pack']!.trim(), stockUnit: pair.$2.stockUnit,
      stockUnitsNumerator: numerator!, stockUnitsDenominator: denominator!, billQuantityMilli: qty!,
      freeBillQuantityMilli: free!, acceptedReceiptMilli: accepted!, damagedReceiptMilli: damaged!,
      conversionReviewed: true, linkedAt: DateTime.now().toUtc());
  }
  Future<void> _saveReview() async {
    if (!_current || !_loaded || _busy || _bookRevision == null || _ledger == null) return;
    final link = _frozen ?? _snapshot();
    if (link == null || _ledger!.allocateBillGoods(link, expectedRevision: _ledger!.revision) == null) {
      setState(() => _error = 'Check remaining invoice/receipt quantities and the exact unit conversion. No goods or payment changed.');
      return;
    }
    final supplierRevision = _ledger!.revision;
    setState(() { _busy = true; _frozen = link; _knownUnstored = false; _error = null; });
    final saved = await session.saveWorkspaceBillGoodsReview(link, supplierId: widget.copy.supplier.id,
      scope: _scope!, expectedPurchaseRevision: _bookRevision!, expectedSupplierRevision: supplierRevision);
    if (!_current) return;
    setState(() { _busy = false; _reviewVerified = saved; _bookRevision = session.workspacePurchaseEntryRevision;
      _uncertain = !saved;
      if (!saved) _error = session.workspaceSupplierError ?? 'Review status needs recovery. Retry saved status before changing the match.'; });
    if (saved && mounted) {
      FocusScope.of(context).unfocus();
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!_current || !_opened || _busy || !_reviewVerified ||
            _frozen?.operationId != link.operationId || _committed ||
            ModalRoute.of(context)?.isCurrent != true) {
          return;
        }
        final anchor = _savedReviewAnchor.currentContext;
        if (anchor != null) {
          unawaited(Scrollable.ensureVisible(anchor, alignment: 0.15,
            duration: const Duration(milliseconds: 200)));
        }
      });
    }
  }
  Future<void> _confirm() async {
    if (!_current || _busy || !_loaded || !_reviewVerified || _frozen == null || _bookRevision == null || _ledger == null) return;
    setState(() { _busy = true; _error = null; });
    final saved = await session.confirmWorkspaceSupplierBillGoodsAllocation(_frozen!, supplierId: widget.copy.supplier.id,
      scope: _scope!, expectedSupplierRevision: _ledger!.revision, expectedPurchaseRevision: _bookRevision!, requireSavedReview: true);
    if (!_current) return;
    setState(() { _busy = false; _uncertain = !saved;
      if (saved) { _notice = 'Goods matched. Stock, supplier balance and payments are unchanged.'; }
      else { _error = session.workspaceSupplierError ?? 'Matching status is unverified. Retry saved status before preparing another match.'; } });
  }
  Future<void> _cancel() async {
    if (!_current || _busy || !_reviewVerified || _frozen == null || _committed || _bookRevision == null) return;
    _cancelAttempt ??= WorkspaceBillGoodsReviewCancellation(operationId: _frozen!.operationId,
      supplierId: widget.copy.supplier.id, revision: _bookRevision! + 1, cancelledAt: DateTime.now().toUtc(),
      reason: 'Retailer cancelled goods matching review to correct quantities');
    setState(() { _busy = true; _error = null; });
    final saved = await session.abandonWorkspaceBillGoodsReview(_frozen!.operationId, supplierId: widget.copy.supplier.id,
      scope: _scope!, expectedRevision: _cancelAttempt!.revision - 1,
      cancelledAt: _cancelAttempt!.cancelledAt, reason: _cancelAttempt!.reason);
    if (!_current) return;
    setState(() { _busy = false; if (saved) { _clear(); _bookRevision = session.workspacePurchaseEntryRevision;
        _notice = 'Matching review cancelled. Bill, Stock and payments are unchanged.'; }
      else { _uncertain = true; _error = session.workspaceSupplierError ?? 'Cancellation status needs recovery. Retry saved status.'; } });
  }
  Widget _field(String label, TextEditingController controller, String key, {bool locked = false}) =>
    _purchaseCompactLabeledField(label, width: 112, field: TextField(key: Key(key), controller: controller,
      enabled: _editable && !locked, keyboardType: const TextInputType.numberWithOptions(decimal: true),
      decoration: const InputDecoration(), onChanged: (_) => setState(() {})));
  @override
  Widget build(BuildContext context) {
    super.build(context);
    final ledger = _ledger;
    final pair = _receipt;
    final links = ledger?.billGoodsAllocations.values ?? const <WorkspaceSupplierBillGoodsAllocation>[];
    final billedLinks = links.where((link) => link.billId == widget.copy.draft.id && link.billLineIndex == _item);
    final receiptLinks = pair == null ? const <WorkspaceSupplierBillGoodsAllocation>[] :
      links.where((link) => link.receiptId == pair.$1.id && link.receiptLineId == pair.$2.sourceLineId);
    final line = _item == null ? null : widget.copy.draft.goods[_item!];
    final printedQuantity = line == null ? null : _ReceivingLineInput.milli(line['quantity'] ?? '');
    final freeText = (line?['freeQuantity'] ?? '').trim();
    final printedFree = line == null ? null : freeText.isEmpty ? 0 : _ReceivingLineInput.milli(freeText);
    final printedQuantitiesKnown = printedQuantity != null && printedFree != null;
    final priorMatches = links.where((link) => link.copyId == widget.copy.id && link.copyRevision == widget.copy.revision);
    final hasOlderReceipt = line != null && ledger != null && ledger.goodsReceipts.values.any((receipt) =>
      receipt.lines.any((item) => item.productId == line['productId']));
    final conversionLocked = billedLinks.isNotEmpty || (pair != null &&
      (line?['pack']?.trim() == pair.$2.stockUnit || line?['pack']?.trim() == pair.$2.purchaseUnit));
    final pendingCopy = _otherReview == null ? null : session.workspacePurchaseCopies.where((copy) =>
      copy.id == _otherReview!.allocation.copyId && copy.revision == _otherReview!.allocation.copyRevision).singleOrNull;
    final matchingProgress = _current && _loaded && !_busy && !_uncertain &&
      !session.workspaceSupplierRecoveryRequired && !session.workspaceGoodsReceiptRecoveryPending
        ? ledger?.goodsProgressFor(widget.copy) : null;
    final fullyMatched = matchingProgress != null && matchingProgress.totalItems > 0 &&
      matchingProgress.matchedItems == matchingProgress.totalItems;
    // Do not conceal unsaved input or a frozen/recovery attempt when progress changes.
    final completedView = fullyMatched && !_dirty && _frozen == null && _otherReview == null;
    return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      TextButton.icon(key: const Key('work-bill-goods-open'), onPressed: _busy ? null : () async {
        if (_opened && !await confirmLeave()) return;
        if (_current) setState(() => _opened = !_opened);
      }, icon: Icon(_opened ? Icons.expand_less : Icons.link, size: 18),
        label: Text(completedView ? 'View received goods' : 'Match received goods')),
      if (_opened) ...[
        if (!completedView) Text(
          'Match this bill to saved goods. This does not add Stock or record a payment.',
          style: const TextStyle(fontSize: 12, color: MoolColors.ink)),
        for (final match in priorMatches) Padding(
          key: ValueKey(('work-bill-goods-saved-match', match.operationId)),
          padding: const EdgeInsets.symmetric(vertical: 4),
          child: DefaultTextStyle.merge(
            style: const TextStyle(fontSize: 12, color: MoolColors.ink),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text('${widget.copy.draft.goods[match.billLineIndex]['name']}',
                style: const TextStyle(fontWeight: FontWeight.w600)),
              Text('Invoiced: ${_ReceivingLineInput._quantity(match.billQuantityMilli)} · '
                'Free: ${_ReceivingLineInput._quantity(match.freeBillQuantityMilli)} · Unit: ${match.billUnit}'),
              Text('Accepted: ${_ReceivingLineInput._quantity(match.acceptedReceiptMilli)} · '
                'Damaged: ${_ReceivingLineInput._quantity(match.damagedReceiptMilli)} · Unit: '
                '${ledger?.goodsReceipts[match.receiptId]?.lines.where((line) => line.sourceLineId == match.receiptLineId).firstOrNull?.purchaseUnit ?? match.stockUnit}'),
              Text('Receipt: ${_reviewReceiptLabel(match.receiptId, match.receiptLineId)}'),
              if (match.billUnit != match.stockUnit || match.stockUnitsNumerator != match.stockUnitsDenominator)
                Text('Unit conversion: ${match.stockUnitsDenominator} ${match.billUnit} = '
                  '${match.stockUnitsNumerator} ${match.stockUnit}'),
            ]),
          ),
        ),
        if (_error != null) Text(_error!, key: const Key('work-bill-goods-error'),
          style: const TextStyle(fontSize: 12, color: MoolColors.ink)),
        if (!_loaded || _uncertain || ledger == null || session.workspaceSupplierRecoveryRequired) TextButton(key: const Key('work-bill-goods-recover'),
          onPressed: _busy ? null : _recover, child: const Text('Retry saved status')),
        if (_otherReview != null) ...[
          const Text('Finish the saved match for this supplier’s other bill first.'),
          if (pendingCopy != null) TextButton(onPressed: _busy ? null : () => widget.onOpenCopy(pendingCopy),
            child: Text('Open invoice ${pendingCopy.draft.invoiceReference}')),
        ] else if (_frozen != null) ...[
          Text('Receipt: ${_reviewReceiptLabel(_frozen!.receiptId, _frozen!.receiptLineId)}'),
          Text(key: _savedReviewAnchor, '${widget.copy.draft.goods[_frozen!.billLineIndex]['name']} · '
            '${_ReceivingLineInput._quantity(_frozen!.billQuantityMilli)} invoiced + '
            '${_ReceivingLineInput._quantity(_frozen!.freeBillQuantityMilli)} free · Unit: ${_frozen!.billUnit}'),
          Text('Accepted ${_ReceivingLineInput._quantity(_frozen!.acceptedReceiptMilli)} · '
            'Damaged ${_ReceivingLineInput._quantity(_frozen!.damagedReceiptMilli)} · Unit: '
            '${ledger?.goodsReceipts[_frozen!.receiptId]?.lines.where((l) => l.sourceLineId == _frozen!.receiptLineId).firstOrNull?.purchaseUnit ?? ''}'),
          if (_committed) ...[
            const Text('Match confirmed · no Stock or payment change'),
            if (!fullyMatched) TextButton(key: const Key('work-bill-goods-next'),
              onPressed: _busy || !_current || _uncertain || !_reviewVerified || session.workspaceSupplierRecoveryRequired
                ? null : () => setState(_clear), child: const Text('Match another item')),
          ] else if (_error == null) Wrap(spacing: 8, children: [
            TextButton(key: const Key('work-bill-goods-confirm'), onPressed: _busy || !_reviewVerified ? null : _confirm,
              child: const Text('Confirm match')),
            if (!_reviewVerified) TextButton(onPressed: _busy ? null : _saveReview, child: const Text('Save review again')),
            TextButton(key: const Key('work-bill-goods-cancel'), onPressed: _busy || !_reviewVerified ? null : _cancel,
              child: const Text('Cancel matching review')),
          ]),
        ] else if (completedView) ...[
          const Text('All invoice quantities matched', key: Key('work-bill-goods-complete'),
            style: TextStyle(fontSize: 12, color: MoolColors.ink)),
        ] else if (_loaded && !_uncertain) ...[
          DropdownButtonFormField<int>(key: ValueKey(('work-bill-goods-item', _item)), initialValue: _item,
            isExpanded: true, decoration: const InputDecoration(labelText: 'Item on supplier invoice'),
            items: [for (final (index, item) in widget.copy.draft.goods.indexed)
              if ((item['productId'] ?? '').isNotEmpty) DropdownMenuItem(value: index,
                child: Text('${index + 1}. ${item['name']} · ${item['pack']}', maxLines: 2))],
            onChanged: _editable ? (value) => setState(() { _item = value; _receiptKey = null; _conversion = false; }) : null),
          if (widget.copy.draft.goods.every((item) => (item['productId'] ?? '').isEmpty))
            const Text('This accepted bill has no saved product links. Do not guess matches by item name; review the product mapping first.'),
          if (_item != null) ...[
            if (printedQuantitiesKnown) Text('Remaining on bill: ${_ReceivingLineInput._quantity(printedQuantity - billedLinks.fold<int>(0, (s, l) => s + l.billQuantityMilli))} invoiced, '
              '${_ReceivingLineInput._quantity(printedFree - billedLinks.fold<int>(0, (s, l) => s + l.freeBillQuantityMilli))} free · Unit: ${line!['pack']}')
            else const Text('Invoice quantity is unclear. Check the supplier bill before matching; it is not treated as zero.'),
            DropdownButtonFormField<(String, String)>(key: ValueKey(('work-bill-goods-receipt', _receiptKey, _item)),
              initialValue: _receiptKey, isExpanded: true, isDense: false, itemHeight: null,
              decoration: const InputDecoration(labelText: 'Saved goods receipt'),
              selectedItemBuilder: (context) => [for (final received in _receipts)
                if (_receiptKey == (received.$1.id, received.$2.sourceLineId))
                  Text(storeBillGoodsReceiptLabel(ledger!.goodsReceipts.values, received.$1, received.$2))
                else const SizedBox.shrink()],
              items: [for (final received in _receipts) DropdownMenuItem(value: (received.$1.id, received.$2.sourceLineId),
                child: Text(storeBillGoodsReceiptLabel(ledger!.goodsReceipts.values, received.$1, received.$2)))],
              onChanged: _editable ? (value) => setState(() => _chooseReceipt(value)) : null),
            if (_receipts.isEmpty) Text(hasOlderReceipt
              ? 'Goods are already recorded, but their saved review is unavailable for matching. Do not receive them again.'
              : 'No saved goods receipt for this product. Check whether Stock was already added before recording receipt.'),
            if (pair != null) ...[
              Text('Remaining receipt: ${_ReceivingLineInput._quantity(pair.$2.acceptedMilli - receiptLinks.fold<int>(0, (s, l) => s + l.acceptedReceiptMilli))} accepted, '
                '${_ReceivingLineInput._quantity(pair.$2.damagedMilli - receiptLinks.fold<int>(0, (s, l) => s + l.damagedReceiptMilli))} damaged · Unit: ${pair.$2.purchaseUnit}'),
              Wrap(spacing: 12, runSpacing: 8, children: [
                _field('Invoiced qty', _quantity, 'work-bill-goods-quantity'), _field('Free qty', _free, 'work-bill-goods-free'),
                _field('Accepted qty', _accepted, 'work-bill-goods-accepted'), _field('Damaged qty', _damaged, 'work-bill-goods-damaged'),
              ]),
              Text('Bill unit: ${line!['pack']} · Stock unit: ${pair.$2.stockUnit}. '
                'Conversion = Stock units ÷ Bill units.'),
              Wrap(spacing: 12, children: [_field('Stock units', _numerator, 'work-bill-goods-numerator', locked: conversionLocked),
                _field('Bill units', _denominator, 'work-bill-goods-denominator', locked: conversionLocked)]),
              CheckboxListTile(key: const Key('work-bill-goods-conversion'), contentPadding: EdgeInsets.zero,
                value: _conversion, onChanged: _editable ? (value) => setState(() => _conversion = value ?? false) : null,
                title: Text('I checked quantities and units (${line['pack']} → ${pair.$2.stockUnit}).')),
              const Text('Damaged quantity matching does not record a supplier credit or refund.'),
              TextButton(key: const Key('work-bill-goods-save'), onPressed: _editable && printedQuantitiesKnown ? _saveReview : null,
                child: const Text('Save matching review')),
            ],
          ],
        ],
        if (_notice != null) Text(_notice!, key: const Key('work-bill-goods-notice')),
      ],
    ]);
  }
}

// Keep short numeric inputs compact without clipping their full field labels.
// The visible caption is excluded from semantics: the input announces it once.
Widget _purchaseCompactLabeledField(String label, {required double width, required Widget field}) =>
  SizedBox(width: width, child: Column(crossAxisAlignment: CrossAxisAlignment.start,
    mainAxisSize: MainAxisSize.min, children: [
      ExcludeSemantics(child: Text(label, style: const TextStyle(fontSize: 13, color: MoolColors.ink))),
      const SizedBox(height: 4),
      Semantics(label: label, child: field),
    ]));

class _PurchaseGoodsInput {
  _PurchaseGoodsInput([Map<String, String>? saved])
      : productId = saved?['productId'] ?? '',
        name = TextEditingController(text: saved?['name'] ?? ''),
        pack = TextEditingController(text: saved?['pack'] ?? ''),
        quantity = TextEditingController(text: saved?['quantity'] ?? ''),
        cost = TextEditingController(text: saved?['cost'] ?? ''),
        extra = {for (final key in WorkspacePurchaseEntryDraft.goodsExtraKeys)
          key: TextEditingController(text: saved?[key] ?? '')};
  String productId;
  final TextEditingController name, pack, quantity, cost;
  final stockSearch = TextEditingController();
  final Map<String, TextEditingController> extra;
  final focus = FocusNode(debugLabel: 'purchase-goods');
  Map<String, String> get fields => {'productId': productId, 'name': name.text,
    'pack': pack.text, 'quantity': quantity.text, 'cost': cost.text,
    for (final e in extra.entries) if (e.value.text.isNotEmpty) e.key: e.value.text};
  void dispose() { name.dispose(); pack.dispose(); quantity.dispose(); cost.dispose(); stockSearch.dispose(); focus.dispose();
    for (final c in extra.values) { c.dispose(); } }
}

class _PurchaseAdditionalInput {
  _PurchaseAdditionalInput(this.record)
    : label = TextEditingController(text: record.label),
      value = TextEditingController(text: record.value), reviewed = record.reviewed;
  WorkspacePurchaseAdditionalField record;
  final TextEditingController label, value;
  bool reviewed;
  WorkspacePurchaseAdditionalField get field => WorkspacePurchaseAdditionalField(
    id: record.id, label: label.text, value: value.text, section: record.section,
    itemIndex: record.itemIndex, summaryIndex: record.summaryIndex,
    sourceDigest: record.sourceDigest, sourcePage: record.sourcePage,
    sourceItemIndex: record.sourceItemIndex, reviewed: reviewed);
  void dispose() { label.dispose(); value.dispose(); }
}

class _StoreRecordPurchaseSurface extends StatefulWidget {
  const _StoreRecordPurchaseSurface({super.key, required this.session, required this.onBack, this.savedCopy,
    this.startNew = false, this.openingOnly = false, this.onReceiveGoods});
  final WorkSession session;
  final VoidCallback onBack;
  final ValueChanged<WorkspacePurchaseSavedCopy>? onReceiveGoods;
  final WorkspacePurchaseSavedCopy? savedCopy;
  final bool startNew, openingOnly;
  @override
  State<_StoreRecordPurchaseSurface> createState() => _StoreRecordPurchaseState();
}

class _StoreRecordPurchaseState extends State<_StoreRecordPurchaseSurface> {
  final _openingKey = GlobalKey<_StoreSupplierOpeningState>();
  final _billGoodsKey = GlobalKey<_StoreBillGoodsMatchState>();
  bool _billGoodsWasAccepted = false;
  static const _paperInk = Color(0xff202124);
  static const _paperMuted = Color(0xff59616d);
  static const _paperRule = Color(0xff92958f);
  static const _taxComponentLabels = {'cgst': 'CGST ₹', 'sgstAmount': 'SGST ₹',
    'utgst': 'UTGST ₹', 'igst': 'IGST ₹', 'cess': 'Cess ₹'};
  final _reviewAnchor = GlobalKey();
  final _saveErrorAnchor = GlobalKey();
  final _itemsAnchor = GlobalKey();
  final _sourceViewport = GlobalKey();
  final _documentPage = GlobalKey();
  final _previewZoom = TransformationController();
  final _recordedItemScroll = ScrollController(keepScrollOffset: false);
  final _recordedTaxScroll = ScrollController(keepScrollOffset: false);
  final _readingPointers = <int>{};
  bool _reviewFocused = false;
  WorkspacePurchaseInvoiceAttachment? _lastOriginal;
  int _lastOriginalPage = 0;
  WorkspacePurchaseInvoiceAttachment? _sourceAttachment;
  Uint8List? _sourceBytes;
  WorkPdfPage? _sourcePage;
  WorkPdfPreview _sourcePdf = WorkPdfPreview();
  int _sourceEpoch = 0;
  bool _sourceLoading = false, _sourceSaving = false;
  String? _sourceError, _sourceNotice;
  final _name = TextEditingController(), _phone = TextEditingController(),
      _address = TextEditingController(), _gstin = TextEditingController(),
      _reference = TextEditingController(), _date = TextEditingController();
  final _supplierFocus = FocusNode(debugLabel: 'purchase-supplier');
  final _goods = <_PurchaseGoodsInput>[];
  final _details = {for (final key in WorkspacePurchaseEntryDraft.detailKeys) key: TextEditingController()};
  final _attachments = <WorkspacePurchaseInvoiceAttachment>[];
  final _additional = <_PurchaseAdditionalInput>[];
  final _taxRows = <Map<String, TextEditingController>>[];
  final _fieldLabels = <String, String>{};
  List<Map<String, String>> get _printedTaxRows => [for (final row in _taxRows)
    {for (final e in row.entries) if (e.value.text.isNotEmpty) e.key: e.value.text}];
  late final (String, String, bool)? _scope = widget.session.workspaceSupplierScope;
  WorkspaceSupplierProfile? _supplier;
  WorkspacePurchaseEntryDraft? _original;
  WorkspacePurchaseSavedCopy? _copyAttempt;
  bool _copyVerified = false;
  int _shortageReadGeneration = 0;
  bool _shortageDraftKnown = false, _shortageDraftPresent = false;
  String? _copyAttemptInput;
  bool get _readOnly => widget.savedCopy != null;
  Map<String, String> get _exportLabels => {for (final e in _fieldLabels.entries)
    if (e.key.startsWith('work-purchase-'))
      e.key.substring('work-purchase-'.length).replaceFirst(RegExp(r'-\d+$'), ''): e.value};
  bool _recordedSaving = false;
  String? _recordedNotice;
  int? _revision;
  String _supplierId = '', _draftId = '', _baseline = '';
  String? _replaceReviewedDraftId;
  bool _loading = true, _busy = false, _leaving = false;
  String? _error, _notice;
  final _expandedSections = <String>{};
  bool get _current => _scope != null && _scope == widget.session.workspaceSupplierScope;
  String get _input => jsonEncode([_name.text, _phone.text, _address.text, _gstin.text,
    _reference.text, _date.text, _goods.map((line) => line.fields).toList(), _supplierId,
    {for (final e in _details.entries) if (e.value.text.isNotEmpty) e.key: e.value.text},
    _attachments.map((a) => a.toJson()).toList(),
    _additional.map((f) => f.field.toJson()).toList(), _printedTaxRows]);
  bool get _dirty => !_loading && _baseline != _input;
  @override
  void initState() { super.initState(); unawaited(_load()); }
  Future<void> _load({bool retry = false}) async {
    final generation = ++_shortageReadGeneration;
    setState(() { _shortageDraftKnown = false; _shortageDraftPresent = false; });
    final session = widget.session;
    final opened = await session.loadWorkspaceSuppliers(retry: retry);
    if (!mounted || generation != _shortageReadGeneration) return;
    if (!_current || !opened) {
      setState(() { _loading = false; _error = session.workspaceSupplierError ??
        'Your Store is unavailable. Reopen this Store to continue.'; });
      return;
    }
    final copy = widget.savedCopy;
    if (copy != null && !session.workspacePurchaseCopies.any((c) => c.id == copy.id &&
        jsonEncode(c.toJson()) == jsonEncode(copy.toJson()))) {
      setState(() { _loading = false; _error = 'This saved purchase copy is unavailable. Return to Purchases and retry.'; });
      return;
    }
    if (copy != null) {
      await session.recoverCustomerLedger();
      if (!mounted || !_current || generation != _shortageReadGeneration) return;
    }
    if (widget.startNew && copy == null && !session.workspacePurchaseDraftReviewed) {
      setState(() { _loading = false; _error = 'Finish and save the current purchase copy before starting another bill. Return to Purchases to resume it.'; });
      return;
    }
    _replaceReviewedDraftId = widget.startNew && copy == null ? session.workspacePurchaseEntryDraft?.id : null;
    _original = copy?.draft ?? (widget.startNew ? null : session.workspacePurchaseEntryDraft);
    _revision = copy?.revision ?? session.workspacePurchaseEntryRevision;
    _draftId = _original?.id ?? session.newWorkspacePurchaseDraftId();
    _supplier = copy?.supplier ?? session.workspaceSuppliers.where((p) => p.id == _original?.supplierId).firstOrNull;
    _supplierId = _supplier?.id ?? session.newWorkspaceSupplierId();
    _name.text = _supplier?.name ?? '';
    _phone.text = _supplier?.phone ?? '';
    _address.text = _supplier?.address ?? '';
    _gstin.text = _supplier?.gstin ?? '';
    _reference.text = _original?.invoiceReference ?? '';
    _date.text = _original?.invoiceDate ?? '';
    for (final e in _details.entries) { e.value.text = _original?.details[e.key] ?? ''; }
    _attachments..clear()..addAll(_original?.attachments ?? const []);
    for (final field in _additional) { field.dispose(); }
    _additional..clear()..addAll((_original?.additionalFields ?? const []).map(_PurchaseAdditionalInput.new));
    for (final row in _taxRows) { for (final c in row.values) { c.dispose(); } }
    _taxRows..clear()..addAll([for (final row in _original?.printedTaxRows ?? const <Map<String, String>>[])
      {for (final key in WorkspacePurchaseEntryDraft.printedTaxKeys)
        key: TextEditingController(text: row[key] ?? '')}]);
    for (final line in _goods) { line.dispose(); }
    _goods
      ..clear()
      ..addAll((_original?.goods ?? [<String, String>{}]).map(_PurchaseGoodsInput.new));
    _baseline = _input;
    _copyVerified = copy != null;
    if (_readOnly) _reviewFocused = true;
    setState(() { _loading = false; _error = null; });
    if (copy != null) unawaited(_readShortageActionDraft(copy, generation));
  }
  Future<void> _readShortageActionDraft(WorkspacePurchaseSavedCopy copy, int generation) async {
    final session = widget.session, key = widget.session.supplierShortageRecoveryFormKey(copy);
    setState(() { _shortageDraftKnown = false; _shortageDraftPresent = false; });
    if (key == null) return; // Unavailable namespace is not proof of absence.
    try {
      final saved = await session.readLedgerForm(key);
      if (!mounted || !_current || generation != _shortageReadGeneration ||
          session.supplierShortageRecoveryFormKey(copy) != key ||
          !session.workspacePurchaseCopies.any((candidate) => candidate.id == copy.id &&
            jsonEncode(candidate.toJson()) == jsonEncode(copy.toJson()))) { return; }
      setState(() {
        _shortageDraftKnown = true;
        _shortageDraftPresent = saved != null && saved.fields.isNotEmpty;
      });
    } on Object {
      // Keep recovery discoverable; failure is never an empty-draft result.
    }
  }
  void _chooseSupplier(WorkspaceSupplierProfile p) {
    if (_supplierId != p.id) { _clearSupplierInstructions(); }
    setState(() { _supplier = p; _supplierId = p.id; _name.text = p.name;
      _phone.text = p.phone; _address.text = p.address; _gstin.text = p.gstin; });
    _supplierFocus.unfocus();
  }
  void _clearSupplierInstructions() {
    for (final key in const ['supplierEmail', 'bankName', 'bankAccount', 'bankIfsc',
        'bankBranch', 'upiType', 'upiId', 'paymentQrStatus', 'terms', 'signatory', 'paymentTerms']) {
      _details[key]!.clear();
    }
  }
  Future<bool> confirmLeave() async {
    if (widget.openingOnly) {
      return await (_openingKey.currentState?.confirmLeave() ?? Future.value(true));
    }
    if (_busy || _leaving) return false;
    if (!await (_billGoodsKey.currentState?.confirmLeave() ?? Future.value(true))) return false;
    if (!mounted) return false;
    _leaving = true;
    FocusScope.of(context).unfocus();
    final discard = !_dirty || await showDialog<bool>(context: context, builder: (context) =>
      AlertDialog(title: const Text('Leave purchase draft?'),
        content: const Text('Unsaved changes will be discarded. Your last saved draft stays available.'),
        actions: [TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Keep editing')),
          TextButton(onPressed: () => Navigator.pop(context, true), child: const Text('Discard changes'))])) == true;
    _leaving = false;
    if (mounted && discard && !_readOnly && _scope != null) {
      widget.session.dismissWorkspacePurchaseValidation(_scope!);
    }
    return mounted && discard;
  }
  Future<void> _back() async {
    if (await confirmLeave() && mounted) widget.onBack();
  }
  Future<void> _addGoodsProduct(_PurchaseGoodsInput line) async {
    if (_busy || !_current || _scope == null || line.name.text.trim().isEmpty) return;
    FocusScope.of(context).unfocus();
    final id = 'custom-${DateTime.now().microsecondsSinceEpoch}';
    final defaults = widget.session.workspaceProductDefaults;
    final product = WorkspaceCatalogueItem(
      id: id, canonicalId: id, categoryId: 'other', brand: '',
      title: line.name.text.trim(), variant: '', pack: line.pack.text.trim(),
      sku: 'SKU-${id.substring(7)}', barcode: '',
      // The bill can use decimal prices; the product editor accepts whole rupees.
      // Never round or replace the original bill price to make it fit.
      purchasePrice: int.tryParse(line.cost.text.trim()) ?? 0,
      sellingPrice: int.tryParse(line.extra['sellingPrice']!.text.trim()) ?? 0,
      mrp: int.tryParse(line.extra['mrp']!.text.trim()),
      unitPrice: '', stock: 0, available: false, publicListing: false,
      deliveryPromise: 'Store pickup or local delivery', origin: '',
      visualLabel: 'Product image pending', visualKind: 'catalogue-packshot',
      stockMode: defaults.stockMode, lowStockThreshold: defaults.lowStockThreshold,
    );
    setState(() => _busy = true);
    try {
      final savedId = await Navigator.of(context).push<String>(MaterialPageRoute(
        builder: (pageContext) => Scaffold(
          appBar: AppBar(title: const Text('Add product')),
          body: SafeArea(child: _CatalogueProductEditor(
            session: widget.session, product: product, embeddedPage: true,
            purchaseScope: _scope,
            onSaved: () => Navigator.of(pageContext).pop(product.id),
          )),
        ),
      ));
      if (!mounted || savedId == null) return;
      if (!_current) {
        setState(() => _error = 'You are in a different Store. Reopen the Store for this bill before matching items.');
        return;
      }
      final saved = widget.session.workspaceCatalogueItems.where((p) => p.id == savedId).firstOrNull;
      if (saved == null || !_goods.contains(line)) {
        setState(() => _error = 'Cannot find the saved product. Choose its match in Stock again.');
        return;
      }
      setState(() => line.productId = saved.id);
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }
  Future<void> _save({bool reviewed = false}) async {
    if (_readOnly || _busy || !_current || _scope == null) return;
    final now = DateTime.now();
    var profile = WorkspaceSupplierProfile(id: _supplierId, name: _name.text.trim(),
      phone: _phone.text.trim().replaceAll(RegExp(r'[\s()-]'), ''),
      address: _address.text.trim(), gstin: _gstin.text.trim().toUpperCase(),
      createdAt: _supplier?.createdAt ?? now, updatedAt: now);
    var draft = WorkspacePurchaseEntryDraft(id: _draftId, supplierId: profile.id,
      invoiceReference: _reference.text.trim(), invoiceDate: _date.text.trim(),
      createdAt: _original?.createdAt ?? now, updatedAt: now,
      goods: _goods.map((line) => line.fields).toList(),
      details: {for (final e in _details.entries) if (e.value.text.isNotEmpty) e.key: e.value.text},
      attachments: _attachments, additionalFields: _additional.map((f) => f.field).toList(),
      printedTaxRows: _printedTaxRows);
    if (reviewed) {
      if (_name.text.trim().isEmpty || _reference.text.trim().isEmpty || _date.text.trim().isEmpty ||
          !_goods.any((line) => line.name.text.trim().isNotEmpty)) {
        _showSaveError('Enter supplier, invoice number/date and items before saving a purchase copy. Save draft to finish later.');
        return;
      }
      if (_copyAttempt == null || _copyAttemptInput != _input) {
        _copyAttemptInput = _input;
        _copyAttempt = WorkspacePurchaseSavedCopy(
          id: '$_draftId-reviewed-r${(_revision ?? 0) + 1}',
          storeName: widget.session.activeWorkspace?.name ?? 'Store',
          revision: (_revision ?? 0) + 1, savedAt: now, supplier: profile, draft: draft,
          labels: _exportLabels);
      }
      profile = _copyAttempt!.supplier;
      draft = _copyAttempt!.draft;
    }
    if (profile.validationError != null || !draft.valid) {
      _showSaveError(profile.validationError ??
        'Check your entries before saving. Each extra detail needs a heading (up to 120 characters) and details (up to 4,000). Keep up to 200 extra details and 48,000 characters in total. Your entries are kept.');
      return;
    }
    FocusScope.of(context).unfocus();
    setState(() { _busy = true; _error = null; });
    try {
      for (final attachment in _attachments) {
        await widget.session.workspacePurchaseInvoiceCapture.read(_scope!, _draftId, attachment);
      }
    } on Object catch (e) {
      if (mounted) {
        setState(() => _busy = false);
        _showSaveError(e is WorkGatewayException ? e.message :
          'Could not open the attached bill. Your entries are kept; attach the original again.');
      }
      return;
    }
    if (!mounted || !_current) {
      if (mounted) setState(() => _busy = false);
      return;
    }
    final saved = await widget.session.saveWorkspacePurchaseEntry(profile, scope: _scope!,
      draft: draft, expectedRevision: _revision, reviewedCopy: reviewed ? _copyAttempt : null,
      replaceReviewedDraftId: _replaceReviewedDraftId);
    if (!mounted) return;
    setState(() => _busy = false);
    if (saved && _current) {
      _baseline = _input;
      widget.onBack();
    } else {
      _showSaveError(widget.session.workspaceSupplierError ??
        'Return to the Store where you started this bill. Your entries are kept.');
    }
  }
  void _showSaveError(String message) {
    if (!mounted) return;
    if (_current) FocusScope.of(context).unfocus();
    setState(() => _error = message);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || !_current || _error != message) return;
      final target = _saveErrorAnchor.currentContext;
      if (target != null && target.mounted) {
        // Reveal the beginning even when large text exceeds a short viewport.
        unawaited(Scrollable.ensureVisible(target, alignment: 0,
          duration: const Duration(milliseconds: 200)));
      }
    });
  }
  Future<void> _refreshSaved() async {
    if (_busy || !_current) return;
    if (_draftId.isEmpty || _readOnly) { await _load(retry: true); return; }
    setState(() { _busy = true; _error = null; });
    final opened = await widget.session.loadWorkspaceSuppliers(retry: true);
    if (!mounted) return;
    setState(() => _busy = false);
    if (!_current || !opened) {
      setState(() => _error = widget.session.workspaceSupplierError ??
        'Cannot reopen saved purchases. Your entries are kept; retry.');
      return;
    }
    final attempted = _copyAttempt;
    if (attempted != null && widget.session.workspacePurchaseCopies.any((c) =>
        jsonEncode(c.toJson()) == jsonEncode(attempted.toJson()))) {
      // Reconcile a committed operation without writing its old draft back.
      _baseline = _input;
      widget.onBack();
      return;
    }
    final latest = widget.session.workspacePurchaseEntryDraft;
    final retainedReviewedDraft = _replaceReviewedDraftId != null &&
      latest?.id == _replaceReviewedDraftId && widget.session.workspacePurchaseDraftReviewed;
    if (latest != null && latest.id != _draftId && !retainedReviewedDraft) {
      setState(() => _error = 'Another purchase draft is saved. Your entries are kept; return to Purchases to choose it.');
      return;
    }
    setState(() {
      _original = retainedReviewedDraft ? null : latest;
      if (!retainedReviewedDraft) _replaceReviewedDraftId = null;
      _supplier = widget.session.workspaceSuppliers.where((p) => p.id == _supplierId).firstOrNull;
      _revision = widget.session.workspacePurchaseEntryRevision;
      _copyAttempt = null;
      _copyAttemptInput = null;
      _notice = 'Saved records refreshed. Your entries are kept; review the purchase before saving again.';
      _reviewFocused = false;
    });
  }
  @override
  void dispose() {
    for (final c in [_name, _phone, _address, _gstin, _reference, _date]) { c.dispose(); }
    for (final c in _details.values) { c.dispose(); }
    _supplierFocus.dispose();
    _previewZoom.dispose();
    _recordedItemScroll.dispose();
    _recordedTaxScroll.dispose();
    _sourceEpoch++;
    _sourcePdf.dispose();
    for (final line in _goods) { line.dispose(); }
    for (final field in _additional) { field.dispose(); }
    for (final row in _taxRows) { for (final c in row.values) { c.dispose(); } }
    super.dispose();
  }
  Widget _extraFields(String section, {int? itemIndex, int? summaryIndex}) {
    final selected = _additional.where((f) => f.record.section == section &&
      f.record.itemIndex == itemIndex && f.record.summaryIndex == summaryIndex);
    final owner = '$section-${itemIndex ?? 'all'}-${summaryIndex ?? 'all'}';
    final heading = switch (section) {
      'supplier' => 'Extra supplier details', 'buyer' => 'Extra billed-to details',
      'items' => itemIndex == null ? 'Item details to match' : 'Extra item details',
      'tax' => summaryIndex == null ? 'Extra tax details' : 'Extra tax-row details',
      'receipt' => 'Extra delivery details', 'payment' => 'Extra payment details',
      _ => 'Extra invoice details',
    };
    return _section('$heading${selected.isEmpty ? '' : ' · ${selected.length}'}',
      'work-purchase-extra-$owner', [
        if (selected.isEmpty) const Text('Add any heading and its details that appear on your invoice.',
          style: TextStyle(fontSize: 11, color: MoolColors.muted)),
        for (final input in selected) ...[
          if (input.record.sourceItemIndex != null && input.record.itemIndex == null) ...[
            Text('From scanned item ${input.record.sourceItemIndex! + 1}. Choose the entered item it belongs to.',
              style: const TextStyle(fontSize: 11, color: MoolColors.muted)),
            DropdownButtonFormField<int>(key: Key('purchase-extra-match-${input.record.id}'),
              isExpanded: true, decoration: const InputDecoration(labelText: 'Choose invoice item',
                filled: false, isDense: true),
