  void _closeSource() {
    _sourceEpoch++;
    _sourcePdf.dispose();
    _sourcePdf = WorkPdfPreview();
    _sourceAttachment = null;
    _sourceBytes = null;
    _sourcePage = null;
    _sourceLoading = false;
    _sourceError = _sourceNotice = null;
  }
  bool _sourceCurrent(int epoch) => mounted && _current && epoch == _sourceEpoch &&
    _attachments.any((a) => a.digest == _sourceAttachment?.digest);
  Future<void> _openSource(WorkspacePurchaseInvoiceAttachment attachment, {int page = 0}) async {
    if (_busy || _sourceSaving || !_current || _scope == null) return;
    _closeSource();
    _lastOriginal = attachment;
    _lastOriginalPage = page;
    final epoch = _sourceEpoch;
    setState(() { _sourceAttachment = attachment; _sourceLoading = true; });
    _previewPurchase(recorded: false);
    try {
      final bytes = await widget.session.workspacePurchaseInvoiceCapture.read(_scope!, _draftId, attachment);
      if (!_sourceCurrent(epoch)) return;
      _sourceBytes = bytes;
      if (attachment.contentType == 'application/pdf') {
        final rendered = await _sourcePdf.render(bytes, page: page);
        if (!_sourceCurrent(epoch)) return;
        _sourcePage = rendered;
      }
    } on WorkGatewayException catch (error) {
      if (_sourceCurrent(epoch)) _sourceError = error.message;
    } on WorkPdfPreviewException catch (error) {
      if (_sourceCurrent(epoch)) { _sourceError = error.message; }
    } on Object {
      if (_sourceCurrent(epoch)) _sourceError = 'Cannot open the original invoice. Retry, or attach the original again.';
    } finally {
      if (_sourceCurrent(epoch)) {
        setState(() => _sourceLoading = false);
        _positionReview();
      }
    }
  }
  Future<void> _sourceTurnPage(int index) async {
    if (_sourceLoading || _sourceBytes == null || _sourcePage == null ||
        index < 0 || index >= _sourcePage!.pageCount) { return; }
    final epoch = _sourceEpoch;
    if (!_sourceCurrent(epoch)) return;
    setState(() { _sourceLoading = true; _sourceError = null; });
    try {
      final page = await _sourcePdf.render(_sourceBytes!, page: index);
      if (_sourceCurrent(epoch)) {
        _previewZoom.value = Matrix4.identity();
        _sourcePage = page;
        _lastOriginalPage = index;
      }
    } on WorkPdfPreviewException catch (error) {
      if (_sourceCurrent(epoch)) { _sourceError = error.message; }
    } finally {
      if (_sourceCurrent(epoch)) setState(() => _sourceLoading = false);
    }
  }
  Future<void> _downloadSource() async {
    final attachment = _sourceAttachment;
    final epoch = _sourceEpoch;
    if (_sourceSaving || attachment == null || !_sourceCurrent(epoch) || _scope == null) return;
    setState(() { _sourceSaving = true; _sourceNotice = _sourceError = null; });
    try {
      // Recheck the saved source's ownership, length and hash before handing its
      // unchanged bytes to the existing system save picker, never a page image.
      final bytes = await widget.session.workspacePurchaseInvoiceCapture.read(_scope!, _draftId, attachment);
      if (!_sourceCurrent(epoch)) return;
      final extension = switch (attachment.contentType) {
        'application/pdf' => 'pdf', 'image/png' => 'png',
        'image/jpeg' => 'jpg', 'image/webp' => 'webp', _ => throw StateError('Unsupported original'),
      };
      final result = await FilePicker.saveFile(dialogTitle: 'Save supplier invoice copy',
        fileName: 'purchase-original-${attachment.digest.substring(0, 16)}.$extension',
        mimeType: attachment.contentType, type: FileType.custom, allowedExtensions: [extension], bytes: bytes);
      if (_sourceCurrent(epoch)) {
        _sourceNotice = result == null
          ? 'Download cancelled. Supplier copy kept.' : 'Supplier copy saved.';
      }
    } on WorkGatewayException catch (error) {
      if (_sourceCurrent(epoch)) { _sourceError = error.message; }
    } on Object {
      if (_sourceCurrent(epoch)) _sourceError = 'Could not save the supplier copy. It is kept; retry.';
    } finally {
      if (mounted) setState(() => _sourceSaving = false);
    }
  }
  StorePurchaseAccountingSnapshot get _accountingSnapshot => !_readOnly
    ? StorePurchaseAccountingSnapshot.draft
    : StorePurchaseAccountingSnapshot.capture(copy: widget.savedCopy!, scope: _scope,
        recovered: _current && widget.session.workspaceSupplierScope == _scope &&
          widget.session.workspaceInvoiceHistoryLoaded && !widget.session.workspaceSupplierRecoveryRequired,
        ledger: widget.session.workspaceSupplierLedger(widget.savedCopy!.supplier.id));
  bool _recordedCurrent(WorkspacePurchaseEntryDraft draft, WorkspaceSupplierProfile supplier, int revision) =>
    mounted && _current && widget.session.workspaceSuppliersLoaded && !_dirty && !_busy && !widget.session.workspaceSupplierSaving &&
    (_readOnly ? widget.session.workspacePurchaseCopies.any((c) => c.id == widget.savedCopy!.id &&
      jsonEncode(c.toJson()) == jsonEncode(widget.savedCopy!.toJson())) :
    widget.session.workspaceSupplierError == null && _original == draft && _supplier == supplier &&
    widget.session.workspacePurchaseEntryDraft == draft && widget.session.workspacePurchaseEntryRevision == revision &&
    widget.session.workspaceSuppliers.contains(supplier) && draft.supplierId == supplier.id);
  Future<void> _downloadRecorded() async {
    if (_recordedSaving) return;
    final draft = _original, supplier = _supplier, revision = _revision;
    if (draft == null || supplier == null || revision == null || !_recordedCurrent(draft, supplier, revision)) {
      setState(() => _recordedNotice = _readOnly
        ? 'Saved purchase copy is unavailable. Reopen it from Purchases and retry.'
        : _dirty || draft == null
        ? 'Save draft, then reopen it to download the saved copy. Your entries are kept.'
        : 'Saved details changed or are unavailable. Reopen this purchase draft and retry.');
      return;
    }
    final accounting = _accountingSnapshot;
    bool evidenceCurrent() => _recordedCurrent(draft, supplier, revision) &&
      accounting.sameEvidence(_accountingSnapshot);
    setState(() { _recordedSaving = true; _recordedNotice = null; });
    try {
      final bytes = await generateStorePurchaseRecordedCopy(draft: draft, supplier: supplier,
        storeName: widget.savedCopy?.storeName ?? widget.session.activeWorkspace?.name ?? 'Store', storeId: _scope!.$2,
        revision: revision, labels: widget.savedCopy?.labels ?? _exportLabels, isSavedCopy: _readOnly,
        accounting: accounting);
      if (!evidenceCurrent()) {
        if (mounted && _current) {
          setState(() => _recordedNotice = _readOnly
            ? !_recordedCurrent(draft, supplier, revision)
              ? 'Saved purchase copy changed or is unavailable. Reopen it from Purchases before downloading.'
              : 'Supplier account status changed. Reopen this purchase before downloading.'
            : 'Saved details changed. Reopen this purchase draft before downloading.');
        }
        return;
      }
      // Filename binds to the saved entry version, not typed bill text.
      final stamp = draft.updatedAt.microsecondsSinceEpoch;
      final result = await FilePicker.saveFile(dialogTitle: 'Save recorded purchase copy',
        fileName: 'purchase-recorded-$stamp-r$revision.pdf', mimeType: 'application/pdf',
        type: FileType.custom, allowedExtensions: ['pdf'], bytes: bytes);
      if (evidenceCurrent()) {
        setState(() => _recordedNotice = result == null
          ? _readOnly ? 'Download cancelled. Your saved purchase copy is kept.'
            : 'Download cancelled. Your saved draft is kept.'
          : _readOnly ? 'Purchase copy downloaded.' : 'Recorded copy saved.');
      }
    } on FormatException catch (error) {
      if (mounted && _current) setState(() => _recordedNotice = error.message);
    } on Object {
      if (mounted && _current) {
        setState(() => _recordedNotice = _readOnly
          ? 'Could not download the purchase copy. It is kept; retry.'
          : 'Could not download the recorded copy. Your saved draft is kept; retry.');
      }
    } finally {
      if (mounted) setState(() => _recordedSaving = false);
    }
  }
  String _invoiceMoney(String text, {bool currency = false}) {
    final minor = WorkspacePurchaseEntryDraft.printedPaise(text);
    if (minor == null) return text;
    final absolute = minor.abs();
    return '${minor < 0 ? '−' : ''}${currency ? '₹' : ''}'
      '${_formatStoreAmount(absolute ~/ 100)}.${(absolute % 100).toString().padLeft(2, '0')}';
  }
  Widget _reviewCopies() {
    final original = _sourceAttachment != null;
    final attachment = _attachments.where((a) => a.digest == _lastOriginal?.digest).firstOrNull
        ?? _attachments.firstOrNull;
    return Wrap(key: const Key('purchase-review-toolbar'), crossAxisAlignment: WrapCrossAlignment.center, children: [
      if (attachment != null) Semantics(selected: original, child: TextButton(
        key: const Key('purchase-review-original'),
        style: TextButton.styleFrom(disabledForegroundColor: MoolColors.navy,
          minimumSize: const Size(48,48), padding: const EdgeInsets.symmetric(horizontal:4),
          textStyle: TextStyle(fontSize: 12, fontWeight: original ? FontWeight.w700 : FontWeight.w500)),
        onPressed: original || _sourceSaving ? null : () => _openSource(attachment,
          page: attachment.digest == _lastOriginal?.digest ? _lastOriginalPage : 0),
        child: const Text('Supplier copy'))),
      Semantics(selected: !original, child: TextButton(key: const Key('purchase-original-recorded'),
        style: TextButton.styleFrom(disabledForegroundColor: MoolColors.navy,
          minimumSize: const Size(48,48), padding: const EdgeInsets.symmetric(horizontal:4),
          textStyle: TextStyle(fontSize: 12, fontWeight: original ? FontWeight.w500 : FontWeight.w700)),
        onPressed: !original || _sourceSaving ? null : _previewPurchase,
        child: const Text('Recorded copy'))),
      if (original) IconButton(key: const Key('purchase-original-download'),
        constraints: const BoxConstraints(minWidth: 48, minHeight: 48),
        tooltip: _sourceSaving ? 'Saving copy…' : 'Download supplier copy',
        onPressed: _sourceSaving ? null : _downloadSource,
        icon: const Icon(Icons.download_outlined, size: 20, color: MoolColors.navy)),
      if (!original) IconButton(tooltip: _recordedSaving ? 'Preparing copy…' : 'Download recorded purchase copy',
        key: const Key('purchase-recorded-download'),
        constraints: const BoxConstraints(minWidth: 48, minHeight: 48),
        onPressed: _recordedSaving ? null : _downloadRecorded,
        icon: const Icon(Icons.download_outlined, size: 20, color: MoolColors.navy)),
      _invoiceTools(original: original),
    ]);
  }
  void _zoomInvoice() {
    final box = _sourceViewport.currentContext?.findRenderObject();
    if (box is! RenderBox) return;
    final centre = box.size.center(Offset.zero);
    final scene = _previewZoom.toScene(centre);
    final scale = (_previewZoom.value.getMaxScaleOnAxis() * 2).clamp(.05, 8.0);
    _previewZoom.value = Matrix4.diagonal3Values(scale, scale, 1)
      ..setTranslationRaw(centre.dx - scene.dx * scale, centre.dy - scene.dy * scale, 0);
  }
  void _fitInvoice() {
    final viewport = _sourceViewport.currentContext?.findRenderObject();
    final page = _documentPage.currentContext?.findRenderObject();
    if (viewport is! RenderBox || page is! RenderBox || page.size.isEmpty) return;
    final widthScale = viewport.size.width / page.size.width;
    final heightScale = viewport.size.height / page.size.height;
    final scale = (widthScale < heightScale ? widthScale : heightScale).clamp(.05, 1.0);
    _previewZoom.value = Matrix4.diagonal3Values(scale, scale, 1)
      ..setTranslationRaw((viewport.size.width - page.size.width * scale) / 2, 0, 0);
  }
  void _readingPointer(PointerEvent event, bool down) {
    final changed = down ? _readingPointers.add(event.pointer) : _readingPointers.remove(event.pointer);
    if (changed && mounted) setState(() {});
  }
  Widget _invoiceViewer(String key, double viewportHeight, Widget Function(double width) page) =>
    LayoutBuilder(builder: (context, constraints) => SizedBox(key: _sourceViewport,
      // Reserve space for comparison controls and the fixed draft actions.
      // The page starts at readable width; its remaining height pans inside.
      height: (viewportHeight * .55).clamp(160.0, 650.0),
      child: Listener(onPointerDown: (e) => _readingPointer(e, true),
        onPointerUp: (e) => _readingPointer(e, false), onPointerCancel: (e) => _readingPointer(e, false),
        child: ClipRect(child: ColoredBox(color: const Color(0xffe8ebef),
          child: InteractiveViewer(key: Key(key), transformationController: _previewZoom,
            constrained: false, alignment: Alignment.topLeft, minScale: .05, maxScale: 8,
            child: SizedBox(key: _documentPage,
              width: key == 'purchase-review-zoom' ? constraints.maxWidth
                : constraints.maxWidth < 760 ? 760 : constraints.maxWidth,
              child: page(key == 'purchase-review-zoom' ? constraints.maxWidth
                : constraints.maxWidth < 760 ? 760 : constraints.maxWidth))))))));
  Widget _invoiceTools({required bool original}) => Wrap(
    crossAxisAlignment: WrapCrossAlignment.center, children: [
      if (original && _sourcePage != null) Row(mainAxisSize: MainAxisSize.min, children: [
        IconButton(key: const Key('purchase-original-prev'), tooltip: 'Previous page',
          constraints: const BoxConstraints(minWidth: 48, minHeight: 48),
          onPressed: _sourceLoading || _sourcePage!.index == 0 ? null : () => _sourceTurnPage(_sourcePage!.index - 1),
          icon: const Icon(Icons.chevron_left, size: 20)),
        Text('Page ${_sourcePage!.index + 1} of ${_sourcePage!.pageCount}',
          style: const TextStyle(fontSize: 12, color: _paperInk)),
        IconButton(key: const Key('purchase-original-next'), tooltip: 'Next page',
          constraints: const BoxConstraints(minWidth: 48, minHeight: 48),
          onPressed: _sourceLoading || _sourcePage!.index + 1 == _sourcePage!.pageCount ? null : () => _sourceTurnPage(_sourcePage!.index + 1),
          icon: const Icon(Icons.chevron_right, size: 20)),
      ]),
      IconButton(key: Key(original ? 'purchase-original-zoom-in' : 'purchase-review-zoom-in'),
        tooltip: 'Zoom in', constraints: const BoxConstraints(minWidth: 48, minHeight: 48),
        onPressed: _zoomInvoice, icon: const Icon(Icons.zoom_in, size: 20, color: MoolColors.navy)),
      IconButton(key: Key(original ? 'purchase-original-fit' : 'purchase-review-fit'),
        tooltip: 'Fit page', constraints: const BoxConstraints(minWidth: 48, minHeight: 48),
        onPressed: _fitInvoice, icon: const Icon(Icons.fit_screen_outlined, size: 20, color: MoolColors.navy)),
    ]);
  List<Widget> _reviewOriginal(double viewportHeight) {
    final attachment = _sourceAttachment!;
    final image = attachment.contentType == 'application/pdf' ? _sourcePage?.bytes : _sourceBytes;
    return [Column(key: const Key('purchase-original-view'),
      crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        _reviewCopies(),
        const Text('Supplier copy · kept unchanged',
          style: TextStyle(fontSize: 12, color: _paperInk)),
        if (_sourceLoading) Row(children: [const Expanded(child: Text('Opening supplier copy…')),
          TextButton(key: const Key('purchase-original-cancel'), onPressed: _previewPurchase, child: const Text('Cancel'))]),
        if (_sourceError != null) ...[
          Text(_sourceError!, style: const TextStyle(fontSize: 12, color: Color(0xffa52a2a))),
          TextButton(key: const Key('purchase-original-retry'), onPressed: _sourceSaving ? null : () => _openSource(attachment),
            child: const Text('Retry copy')),
        ],
        if (_sourceNotice != null) Text(_sourceNotice!, style: const TextStyle(fontSize: 12, color: _paperInk)),
        if (image != null) ...[
          _invoiceViewer('purchase-original-zoom', viewportHeight, (width) => Semantics(
            image: true, label: 'Supplier invoice copy', child: Image.memory(image,
              width: width, fit: BoxFit.contain, gaplessPlayback: true, excludeFromSemantics: true,
              frameBuilder: (context, child, frame, synchronous) {
                final decoded = child is RawImage ? child.image : null;
                // Keep a finite page before image decoding; use the actual source
                // aspect ratio as soon as available, never stretch its pixels.
                final ratio = decoded != null ? decoded.width / decoded.height
                  : _sourcePage != null ? _sourcePage!.width / _sourcePage!.height : 1 / 1.414;
                return AspectRatio(aspectRatio: ratio, child: child);
              }))),
        ],
        _section('Bill file details', 'purchase-original-file-details', [
          SelectableText(attachment.fileName, key: const Key('purchase-original-filename'),
            style: const TextStyle(fontSize: 12, color: _paperInk)),
          SelectableText('SHA-256: ${attachment.digest}',
            style: const TextStyle(fontSize: 11, color: _paperMuted)),
        ]),
      ])];
  }
  void _previewPurchase({bool recorded = true}) {
    FocusScope.of(context).unfocus();
    _previewZoom.value = Matrix4.identity();
    for (final controller in [_recordedItemScroll, _recordedTaxScroll]) {
      if (controller.hasClients) controller.jumpTo(0);
    }
    setState(() {
      _reviewFocused = true;
      _readingPointers.clear();
      if (recorded) _closeSource();
      _expandedSections.add('work-purchase-review-section');
    });
    _positionReview();
  }
  void _positionReview() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      final target = _reviewAnchor.currentContext;
      if (mounted && target != null) {
        unawaited(Scrollable.ensureVisible(target, alignment: 0, duration: const Duration(milliseconds: 180)));
      }
    });
  }
  String _detailGroup(String key) {
    const invoiceKeys = {'invoiceReference', 'invoiceDate', 'documentType', 'documentTitle',
      'originalInvoiceDate', 'poReference', 'documentCopy', 'reverseCharge', 'eInvoiceStatus',
      'irn', 'ackNumber', 'ackDate', 'qrStatus', 'eInvoiceDeclaration'};
    const receiptKeys = {'receiptStatus', 'receivedDate', 'expectedDeliveryDate', 'shippingTerms'};
    const paymentKeys = {'paymentStatus', 'paidAmount', 'dueDate', 'paymentMethod', 'paymentReference',
      'paymentDate', 'paymentTerms', 'printedPaymentMark', 'terms', 'paymentQrStatus', 'signatureStatus',
      'signatory', 'printedCompanyLabel', 'printedSignatoryLabel', 'printedDeclaration', 'printedFooter', 'notes'};
    return key.startsWith('supplier') ? 'supplier' : invoiceKeys.contains(key) ? 'invoice'
      : key.startsWith('buyer') || key.startsWith('delivery') || key.startsWith('placeOfSupply') ? 'buyer'
      : receiptKeys.contains(key) ? 'receipt'
      : key.startsWith('bank') || key.startsWith('upi') || paymentKeys.contains(key) ? 'payment' : 'tax';
  }
  void _reviewItemAmounts() {
    setState(() {
      _reviewFocused = false;
      _expandedSections.remove('work-purchase-review-section');
      _expandedSections.add('work-purchase-items-section');
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      final target = _itemsAnchor.currentContext;
      if (mounted && target != null) {
        unawaited(Scrollable.ensureVisible(target, alignment: 0, duration: const Duration(milliseconds: 180)));
      }
    });
  }
  List<Widget> _reviewPurchase(double viewportHeight) => [
    LayoutBuilder(builder: (context, constraints) => Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: _reviewPurchaseAtWidth(viewportHeight, constraints.maxWidth))),
  ];
  List<Widget> _reviewPurchaseAtWidth(double viewportHeight, double readingWidth) {
    final paperWidth = readingWidth - 1.4;
    const quantityKeys = {'receivedQuantity', 'damagedQuantity', 'shortQuantity'};
    const rule = BorderSide(color: Color(0xff89929c), width: .7);
    const printedStyle = TextStyle(fontSize: 12, color: Color(0xff171b20), height: 1.25);
    final used = <String>{};
    const moneyKeys = {'supplyValue', 'billDiscount', 'taxableValue', 'cgst', 'sgstAmount', 'sgst',
      'utgst', 'igst', 'cess', 'freight', 'otherCharges', 'roundOff', 'totalTax', 'invoiceTotal',
      'amountPayable', 'paidAmount', 'mrp', 'sellingPrice', 'lineTotal', 'taxAmount'};
    Widget value(String label, String text, String id, {bool cell = false, bool amount = false}) => Padding(
      key: ValueKey('purchase-review-$id'), padding: EdgeInsets.symmetric(vertical: cell ? 4 : 3),
      child: Column(crossAxisAlignment: amount ? CrossAxisAlignment.end : CrossAxisAlignment.start, children: [
        if (!cell && label.isNotEmpty) Text(label,
          style: const TextStyle(fontSize: 10, color: Color(0xff424b55), height: 1.2)),
        Text(text, textAlign: amount ? TextAlign.right : TextAlign.left, style: printedStyle),
      ]));
    Widget detail(String key, {bool cell = false, bool amount = false}) {
      used.add(key);
      final text = _details[key]!.text;
      return value(storePurchaseCopyDetailLabel(key, _fieldLabels['work-purchase-$key']!,
        isSavedCopy: _readOnly), moneyKeys.contains(key) ? _invoiceMoney(text)
        : key == 'documentType' ? storePurchaseDocumentTypeLabel(text) : text,
        key, cell: cell, amount: amount);
    }
    List<Widget> selected(Iterable<String> keys) => [for (final key in keys)
      if (!used.contains(key) && _details[key]!.text.isNotEmpty) detail(key)];
    List<Widget> extras(String group, {int? item, int? row}) => [
      for (final input in _additional.where((input) => input.record.section == group &&
          input.record.itemIndex == item && input.record.summaryIndex == row))
        if (input.value.text.isNotEmpty) value(input.label.text.isEmpty ? 'Extra detail — add heading' : input.label.text,
          input.value.text, 'extra-${input.record.id}'),
    ];
    List<Widget> details(String group) => [for (final e in _details.entries)
      if (!used.contains(e.key) && _detailGroup(e.key) == group && e.value.text.isNotEmpty) detail(e.key)];
    Widget column(List<Widget> children) => Padding(padding: const EdgeInsets.all(12),
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: children));
    Widget heading(String text) => Padding(padding: const EdgeInsets.only(bottom: 5), child: Text(text,
      style: printedStyle.copyWith(fontWeight: FontWeight.w700)));
    Widget pair(String key, List<Widget> left, List<Widget> right) {
      // An optional block with only its heading must not become an empty cell.
      final optional = key == 'buyer' || key == 'bank-signatory' || key == 'notes-terms';
      final hasLeft = !optional || left.length > 1;
      final hasRight = !optional || right.length > 1;
      if (!hasLeft && !hasRight) return const SizedBox.shrink();
      return DecoratedBox(key: Key('purchase-review-paper-$key'),
        decoration: const BoxDecoration(border: Border(bottom: rule)),
        child: Builder(builder: (context) {
          if (readingWidth < 600 && hasLeft && hasRight) {
            if (key == 'header') {
              final fullWidth = paperWidth - 24;
              final fieldWidth = readingWidth < 320 ||
                  MediaQuery.textScalerOf(context).scale(1) > 1.3 ? fullWidth : (fullWidth - 12) / 2;
              return column([
                ...left,
                const SizedBox(height: 8),
                right.first,
                Wrap(spacing: 12, runSpacing: 2, children: [
                  for (final field in right.skip(1)) SizedBox(width: fieldWidth, child: field),
                ]),
              ]);
            }
            return column([...left, const SizedBox(height: 8), ...right]);
          }
          return hasLeft && hasRight ? Table(border: const TableBorder(verticalInside: rule), children: [
            TableRow(children: [column(left), column(right)]),
          ]) : column(hasLeft ? left : right);
        }));
    }
    Widget readingTable(Widget table, String key, ScrollController controller) =>
      readingWidth >= 760 ? table
        : Scrollbar(controller: controller, thumbVisibility: true, thickness: 2,
          radius: const Radius.circular(2),
          child: SingleChildScrollView(key: Key(key), controller: controller,
            scrollDirection: Axis.horizontal, padding: const EdgeInsets.only(bottom: 5),
            child: SizedBox(width: 760, child: table)));
    Widget itemCell(String text, String id, {bool amount = false}) => value('', text, id, cell: true, amount: amount);
    Widget itemExtra(_PurchaseGoodsInput line, int index, String key, {bool amount = false}) =>
      line.extra[key]!.text.isEmpty ? const Text('—', style: printedStyle)
        : itemCell(moneyKeys.contains(key) ? _invoiceMoney(line.extra[key]!.text) : line.extra[key]!.text,
          'item-$index-$key', amount: amount);
    const primaryItemKeys = {'printedSerial', 'hsn', 'unitCode', 'taxableValue', 'taxAmount', 'lineTotal'};
    const recordedPaymentKeys = {'paymentStatus', 'paidAmount', 'paymentMethod',
      'paymentReference', 'paymentDate', 'paymentTerms'};
    // Paper contains entered supplier-document facts. POS observations stay outside it.
    final title = _details['documentTitle']!.text;
    if (title.isNotEmpty) used.add('documentTitle');
    final copy = _details['documentCopy']!.text;
    if (copy.isNotEmpty) used.add('documentCopy');
    final paperParts = <Widget>[
      Container(padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
        decoration: const BoxDecoration(border: Border(bottom: rule)), child: Row(children: [
          Expanded(child: Padding(key: title.isEmpty ? null : const ValueKey('purchase-review-documentTitle'),
            padding: EdgeInsets.zero, child: Text(storePurchaseSupplierDocumentHeading(
              title: title, type: _details['documentType']!.text),
              style: const TextStyle(fontSize: 22, fontWeight: FontWeight.w700, letterSpacing: 1.8,
                color: Color(0xff17395c))))),
          if (copy.isNotEmpty) Flexible(child: value('', copy, 'documentCopy', cell: true, amount: true)),
        ])),
      pair('header', [
        Text(_name.text.isEmpty ? 'Supplier details not entered' : _name.text,
          key: const ValueKey('purchase-review-supplier-Supplier name'),
          style: printedStyle.copyWith(fontSize: 18, fontWeight: FontWeight.w700)),
        for (final e in {'Supplier GSTIN':_gstin.text, 'Supplier address':_address.text,
            'Mobile / phone':_phone.text}.entries)
          if (e.value.isNotEmpty) value(e.key,e.value,'supplier-${e.key}'),
        ...details('supplier'), ...extras('supplier'),
      ], [
        heading('Invoice details'),
        if (_reference.text.isNotEmpty) value('Supplier invoice No.',_reference.text,'reference'),
        if (_date.text.isNotEmpty) value('Invoice date',_date.text,'date'),
        ...selected(['originalInvoiceDate','dueDate','poReference','placeOfSupply','placeOfSupplyCode']),
        ...details('invoice'), ...extras('invoice'),
      ]),
      pair('buyer', [
        heading('Billed to'),
        ...selected(['buyerName','buyerAddress','buyerPhone','buyerEmail','buyerGstin','buyerUin','buyerState','buyerStateCode']),
        ...extras('buyer'),
      ], [
        heading('Shipping address'),
        ...selected(['deliveryAddress','deliveryState','deliveryStateCode']),
        ...details('buyer'),
      ]),
      DecoratedBox(key: const Key('purchase-review-paper-items'),
        decoration: const BoxDecoration(border: Border(bottom: rule)),
        child: readingTable(Table(key: const Key('purchase-review-item-table'),
          columnWidths: const {0:FlexColumnWidth(.4),1:FlexColumnWidth(3),2:FlexColumnWidth(.85),
            3:FlexColumnWidth(.65),4:FlexColumnWidth(.8),5:FlexColumnWidth(.6),
            6:FlexColumnWidth(1),7:FlexColumnWidth(1),8:FlexColumnWidth(1)},
          border: const TableBorder(horizontalInside: rule, verticalInside: rule), children: [
            TableRow(decoration: const BoxDecoration(color: Color(0xfff0f3f5)), children: [
              for (final label in ['#','Item / description','HSN / SAC','Units','Rate ₹','Qty','Taxable value ₹','Tax ₹','Amount ₹'])
                Padding(padding: const EdgeInsets.all(6), child: Text(label,
                  style: printedStyle.copyWith(fontSize: 10, fontWeight: FontWeight.w700))),
            ]),
            for (final (index,line) in _goods.indexed) TableRow(children: [
              Padding(padding: const EdgeInsets.all(6), child: line.extra['printedSerial']!.text.isEmpty
                ? Text('${index+1}',style:printedStyle) : itemExtra(line,index,'printedSerial')),
              Padding(padding: const EdgeInsets.all(6), child: Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
                if (line.name.text.isNotEmpty) itemCell(line.name.text,'item-$index'),
                if (line.pack.text.isNotEmpty) value('Pack / unit',line.pack.text,'item-$index-Pack / unit'),
                for (final e in line.extra.entries)
                  if (!quantityKeys.contains(e.key) && !primaryItemKeys.contains(e.key) && e.value.text.isNotEmpty)
                    value(_fieldLabels['work-purchase-${e.key}-$index']!,
                      moneyKeys.contains(e.key) ? _invoiceMoney(e.value.text) : e.value.text,'item-$index-${e.key}'),
                ...extras('items',item:index),
              ])),
              Padding(padding:const EdgeInsets.all(6),child:itemExtra(line,index,'hsn')),
              Padding(padding:const EdgeInsets.all(6),child:itemExtra(line,index,'unitCode')),
              Padding(padding:const EdgeInsets.all(6),child:line.cost.text.isEmpty ? const Text('—',style:printedStyle)
                : itemCell(_invoiceMoney(line.cost.text),'item-$index-Rate ₹',amount:true)),
              Padding(padding:const EdgeInsets.all(6),child:line.quantity.text.isEmpty ? const Text('—',style:printedStyle)
                : itemCell(line.quantity.text,'item-$index-Qty',amount:true)),
              Padding(padding:const EdgeInsets.all(6),child:itemExtra(line,index,'taxableValue',amount:true)),
              Padding(padding:const EdgeInsets.all(6),child:itemExtra(line,index,'taxAmount',amount:true)),
              Padding(padding:const EdgeInsets.all(6),child:itemExtra(line,index,'lineTotal',amount:true)),
            ]),
          ]), 'purchase-review-item-scroll', _recordedItemScroll)),
      if (extras('items').isNotEmpty) column(extras('items')),
      Expanded(child: Row(key:const Key('purchase-review-item-space'),
        crossAxisAlignment:CrossAxisAlignment.stretch,children:[
          for(final weight in [40,300,85,65,80,60,100,100,100]) Expanded(flex:weight,
            child:const DecoratedBox(decoration:BoxDecoration(border:Border(right:rule)))),
        ])),
      pair('totals', [
        ...selected(['printedTotalItems','printedTotalQuantity','priceBasis','taxTreatment']),
        ...extras('tax'),
      ], [
        for (final key in ['supplyValue','billDiscount','taxableValue','cgst','sgstAmount','sgst','utgst','igst',
            'cess','freight','otherCharges','roundOff','totalTax','invoiceTotal','amountPayable'])
          if (_details[key]!.text.isNotEmpty) Padding(key: ValueKey('purchase-review-$key'),
            padding: const EdgeInsets.symmetric(vertical: 3), child: Row(crossAxisAlignment:CrossAxisAlignment.start,children:[
              Expanded(child:Text(_fieldLabels['work-purchase-$key']!.replaceAll('₹', '').trim(),style:printedStyle)),
              const SizedBox(width:12),
              Flexible(child:Text(_invoiceMoney(_details[key]!.text, currency:true),textAlign:TextAlign.right,
                style:printedStyle.copyWith(fontSize:key=='invoiceTotal'?18:12,
                  fontWeight:key=='invoiceTotal'?FontWeight.w700:FontWeight.w500))),
            ])),
      ]),
    ];
    used.addAll(['supplyValue','billDiscount','taxableValue','cgst','sgstAmount','sgst','utgst','igst',
      'cess','freight','otherCharges','roundOff','totalTax','invoiceTotal','amountPayable']);
    final amountWords = selected(['amountInWords']);
    final remainingTax = details('tax');
    paperParts.addAll([
      if (amountWords.isNotEmpty) column(amountWords),
      if (_taxRows.isNotEmpty) column([
        heading('HSN / tax summary as on invoice'),
