  Widget _compactFields(List<Widget> fields, {double width = 138}) => LayoutBuilder(
    builder: (context, constraints) {
      final preferred = MediaQuery.textScalerOf(context).scale(1) > 1.3 ? 190.0 : width;
      final columns = ((constraints.maxWidth + 12) / (preferred + 12)).floor().clamp(1, 3);
      final fitted = (constraints.maxWidth - 12 * (columns - 1)) / columns;
      return Wrap(spacing: 12, runSpacing: 6, children: [for (final field in fields)
        SizedBox(width: field is TextField &&
            (field.keyboardType.index == TextInputType.number.index || field.keyboardType == TextInputType.datetime)
          ? fitted.clamp(0, 190).toDouble() : fitted, child: field)]);
    });
  Future<void> _capture(WorkProofSource source) async {
    if (_busy || !_current || _scope == null) return;
    if (_attachments.length >= 3) { setState(() => _error = 'Keep up to 3 invoice pages or files.'); return; }
    FocusScope.of(context).unfocus();
    setState(() { _busy = true; _error = null; });
    try {
      final a = await widget.session.workspacePurchaseInvoiceCapture.capture(_scope!, _draftId, source);
      if (!mounted || !_current || a == null) return;
      if (_attachments.any((old) => old.digest == a.digest)) {
        setState(() => _error = 'This invoice page is already attached.');
      } else if (_attachments.fold<int>(0, (sum, old) => sum + old.byteLength) + a.byteLength > 20*1024*1024) {
        setState(() => _error = 'Keep invoice attachments within 20 MB in total.');
      } else { setState(() => _attachments.add(a)); }
    } on Object catch (e) {
      if (mounted) {
        setState(() => _error = e is WorkGatewayException ? e.message :
          'The invoice could not be attached. Your form is kept; retry or enter its details manually.');
      }
    } finally { if (mounted) setState(() => _busy = false); }
  }
  Future<void> _scan(WorkspacePurchaseInvoiceAttachment a) async {
    if (_busy || !_current || _scope == null) return;
    setState(() { _busy = true; _error = null; });
    try {
      final read = await widget.session.workspacePurchaseInvoiceCapture.scan(_scope!, _draftId, a);
      if (!mounted || !_current) return;
      final index = _attachments.indexOf(a);
      if (index >= 0) { setState(() {
        _attachments[index] = read;
        final suggestions = WorkPurchaseInvoiceSuggestions.parse(read.detectedText);
        final retained = _retainDetectedExtras(read, suggestions, useGoods: false);
        _openSuggestedSections(suggestions);
        if (suggestions.fields.isEmpty && suggestions.goods.isEmpty && suggestions.additionalFields.isEmpty) {
          _notice = 'No clear bill details found. Your entries are kept; enter details manually.';
        } else {
          _notice = 'Check the bill details, then tap Fill blank fields. '
            '${suggestions.goods.isEmpty ? 'Items were not identified; enter them from your bill.'
              : 'Match the items to Stock before saving.'}'
            '${retained ? '' : ' Extra details need checking against the supplier copy.'}';
          if (suggestions.goods.isEmpty) _expandedSections.add('work-purchase-items-section');
        }
      }); }
    } on Object catch (e) {
      if (mounted) {
        setState(() => _error = e is WorkGatewayException ? e.message :
          'Text could not be read. Your invoice is kept; retry or enter its details manually.');
      }
    } finally { if (mounted) setState(() => _busy = false); }
  }
  bool _retainDetectedExtras(WorkspacePurchaseInvoiceAttachment a,
      WorkPurchaseInvoiceSuggestions suggestions, {required bool useGoods}) {
    var keptAll = !suggestions.additionalOverflow;
    for (final field in suggestions.additionalFields) {
      // An extracted row index does not identify an existing manually entered item.
      if (field.itemIndex != null && !useGoods) { keptAll = false; }
      final id = '${a.digest.substring(0, 16)}-${field.id}';
      final existing = _additional.where((f) => f.record.id == id).firstOrNull;
      if (existing != null) {
        if (useGoods && field.itemIndex != null && existing.record.itemIndex == null) {
          final kept = existing.field;
          existing.record = WorkspacePurchaseAdditionalField(id: kept.id, label: kept.label,
            value: kept.value, section: kept.section, itemIndex: field.itemIndex,
            sourceDigest: kept.sourceDigest, sourcePage: kept.sourcePage,
            sourceItemIndex: kept.sourceItemIndex, reviewed: kept.reviewed);
        }
        continue;
      }
      final size = _additional.fold<int>(0, (sum, f) => sum + f.label.text.length + f.value.text.length);
      if (_additional.length >= 200 || size + field.label.length + field.value.length > 48000) {
        keptAll = false; continue;
      }
      _additional.add(_PurchaseAdditionalInput(WorkspacePurchaseAdditionalField(
        id: id, label: field.label, value: field.value, section: field.section,
        itemIndex: useGoods ? field.itemIndex : null,
        sourceItemIndex: field.itemIndex, sourceDigest: a.digest)));
    }
    return keptAll;
  }
  void _applySuggestions(WorkspacePurchaseInvoiceAttachment a) {
    final suggestions = WorkPurchaseInvoiceSuggestions.parse(a.detectedText);
    if (suggestions.fields.isEmpty && suggestions.goods.isEmpty && suggestions.additionalFields.isEmpty) {
      setState(() => _notice = 'No clear bill details found. Your entries are kept; enter details manually.');
      return;
    }
    final targets = {'supplierName': _name, 'supplierGstin': _gstin,
      'supplierAddress': _address, 'supplierPhone': _phone,
      'invoiceReference': _reference, 'invoiceDate': _date, ..._details};
    setState(() {
      var filled = 0;
      for (final e in suggestions.fields.entries) {
        final target = targets[e.key];
        if (target != null && target.text.trim().isEmpty) {
          target.text = e.value;
          filled++;
        }
      }
      // Goods are never merged into entered lines or automatically linked to an inventory ID.
      final useGoods = _goods.length == 1 && _goods.single.fields.values.every((v) => v.isEmpty) &&
        !_additional.any((f) => f.record.itemIndex != null) && suggestions.goods.isNotEmpty;
      if (useGoods) {
        _goods.single.dispose();
        _goods..clear()..addAll(suggestions.goods.map(_PurchaseGoodsInput.new));
      }
      final keptAll = _retainDetectedExtras(a, suggestions, useGoods: useGoods);
      _error = null;
      _openSuggestedSections(suggestions);
      _notice = '${filled > 0 ? 'Blank fields filled.' : 'Scanned details are ready for review.'} '
        'Earlier entries kept. '
        '${suggestions.goods.isEmpty ? 'Items were not identified; enter them from your bill.'
          : useGoods ? 'Match scanned items to Stock before saving.'
          : 'Your item rows were kept; enter any missing items from the bill.'}'
        '${keptAll ? '' : ' Extra details need checking against the supplier copy.'}';
      if (suggestions.goods.isEmpty) _expandedSections.add('work-purchase-items-section');
    });
  }
  void _openSuggestedSections(WorkPurchaseInvoiceSuggestions suggestions) {
    for (final key in suggestions.fields.keys) {
      _expandedSections.add(switch (_detailGroup(key)) {
        'supplier' => 'work-purchase-supplier-section', 'invoice' => 'work-purchase-invoice-section',
        'buyer' => 'work-purchase-buyer-details', 'receipt' => 'work-purchase-receipt-details',
        'payment' => 'work-purchase-payment-details', _ => 'work-purchase-tax-details',
      });
    }
    if (suggestions.goods.isNotEmpty) _expandedSections.add('work-purchase-items-section');
    for (final line in suggestions.goods) {
      if (const ['receivedQuantity', 'damagedQuantity', 'shortQuantity'].any((key) =>
          (line[key] ?? '').isNotEmpty)) {
        _expandedSections.add('work-purchase-receipt-details');
      }
    }
    if (suggestions.additionalFields.isNotEmpty) {
      _expandedSections.add('work-purchase-invoice-section');
      for (final field in suggestions.additionalFields) {
        _expandedSections.add(switch (field.section) {
          'supplier' => 'work-purchase-supplier-section', 'buyer' => 'work-purchase-buyer-details',
          'items' => 'work-purchase-items-section', 'tax' => 'work-purchase-tax-details',
          'receipt' => 'work-purchase-receipt-details', 'payment' => 'work-purchase-payment-details',
          _ => 'work-purchase-invoice-section',
        });
      }
    }
  }
