  Widget _savedCopyView(double height) {
    final copy = widget.savedCopy!;
    // Keep the historical labels, not wording derived from a later editable draft.
    for (final key in _fieldLabels.keys.toList()) {
      final normalized = key.substring('work-purchase-'.length).replaceFirst(RegExp(r'-\d+$'), '');
      if (copy.labels.containsKey(normalized)) _fieldLabels[key] = copy.labels[normalized]!;
    }
    return ListView(key: const Key('work-purchase-saved-copy'), primary: false,
      physics: _readingPointers.isEmpty ? null : const NeverScrollableScrollPhysics(),
      padding: const EdgeInsets.all(12), children: [
        Row(children: [const Expanded(child: Text('Purchase copy',
          style: TextStyle(fontSize: 16, fontWeight: FontWeight.w700, color: MoolColors.navy))),
          TextButton(key: const Key('work-purchase-copy-close'), onPressed: _back, child: const Text('Close'))]),
        Text('Saved ${_registerDate(copy.savedAt)} · Revision ${copy.revision}',
          style: const TextStyle(fontSize: 11, color: _paperMuted)),
        _savedBillActions(copy),
        ...(_sourceAttachment == null ? _reviewPurchase(height) : _reviewOriginal(height)),
      ]);
  }
  WorkspaceOpeningBillInclusion? _billTreatment(WorkspacePurchaseSavedCopy copy,
      WorkspaceSupplierLedger ledger) {
    final opening = ledger.openingRecord;
    final day = copy.draft.invoiceIssuedDay;
    if (opening == null || day == null) return null;
    final links = opening.bills.where((link) => link.draftId == copy.draft.id).toList();
    if (links.isNotEmpty) {
      final link = links.singleOrNull;
      return link != null && link.copyId == copy.id && link.copyRevision == copy.revision &&
          link.inclusion != WorkspaceOpeningBillInclusion.unknown ? link.inclusion : null;
    }
    final date = DateTime.parse(opening.asOfDate);
    return day.isAfter(DateTime.utc(date.year, date.month, date.day))
      ? WorkspaceOpeningBillInclusion.excluded : null;
  }
  Widget _savedBillAdjustmentRail(List<Widget> actions) {
    if (actions.isEmpty) return const SizedBox.shrink();
    return LayoutBuilder(builder: (context, constraints) {
      final actionWidth = constraints.maxWidth - (actions.length > 1 ? 26 : 0) - 8;
      return Row(key: const Key('work-purchase-adjustment-actions'), children: [
      Expanded(child: SingleChildScrollView(key: const Key('work-purchase-adjustment-scroll'),
        scrollDirection: Axis.horizontal, child: Row(children: [
          for (final action in actions) Padding(padding: const EdgeInsets.only(right: 8),
            child: ConstrainedBox(constraints: BoxConstraints(maxWidth: actionWidth < 48 ? 48 : actionWidth), child: action)),
        ]))),
      if (actions.length > 1) const Tooltip(message: 'Swipe actions left or right',
        child: SizedBox(width: 26, child: Icon(Icons.swap_horiz,
          key: Key('work-purchase-adjustment-scroll-hint'), size: 18, color: MoolColors.navy))),
      ]);
    });
  }
  Widget _savedBillActions(WorkspacePurchaseSavedCopy copy) {
    final session = widget.session;
    final ready = _current && session.workspaceInvoiceHistoryLoaded &&
        !session.workspaceSupplierRecoveryRequired;
    final ledger = ready ? session.workspaceSupplierLedger(copy.supplier.id) : null;
    final accepted = ledger?.purchaseBills[copy.draft.id];
    final same = accepted != null && jsonEncode(accepted.copy.toJson()) == jsonEncode(copy.toJson());
    if (ready) _billGoodsWasAccepted = same;
    final treatment = ledger == null ? null : _billTreatment(copy, ledger);
    final canReviewOpening = ledger?.openingRecord != null &&
      copy.draft.invoiceIssuedDay != null &&
      !ledger!.openingRecord!.bills.any((link) => link.draftId == copy.draft.id);
    final latest = session.workspaceLatestPurchaseCopies.where((item) => item.draft.id == copy.draft.id).toList();
    final latestExact = latest.length == 1 && jsonEncode(latest.single.toJson()) == jsonEncode(copy.toJson());
    final progress = same && !session.workspaceGoodsReceiptRecoveryPending ? ledger?.goodsProgressFor(copy) : null;
    final remaining = same ? ledger?.manualBillRemainingMinor(copy.draft.id) : null;
    final shortageHistory = same && ledger!.shortageClaims.values.any((claim) =>
      claim.copyId == copy.id && claim.copyRevision == copy.revision);
    final shortageEligible = same && session.supplierShortageFormKey(copy) != null &&
      _supplierShortageOptions(copy, ledger!).isNotEmpty;
    final shortageUnverified = !ready || !_shortageDraftKnown;
    final showShortage = shortageUnverified || _shortageDraftPresent || shortageHistory || shortageEligible;
    return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      Text(!ready ? 'Supplier account status unavailable'
        : same ? 'Bill confirmed in supplier account'
        : accepted != null ? 'Another saved revision is confirmed · this copy is not posted'
        : 'Not posted to books', key: const Key('work-purchase-bill-status'),
        style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w600, color: MoolColors.navy)),
      if (same) ...[
        Text(progress == null ? 'Goods · matching status unavailable'
          : !progress.hasMatches ? 'Goods · not matched to this bill'
          : progress.matchedItems == progress.totalItems ? 'Goods · all items matched'
          : 'Goods · partly matched (${progress.matchedItems}/${progress.totalItems} complete items)',
          key: const Key('work-purchase-goods-status'),
          style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w600, color: MoolColors.navy)),
        if (progress?.damaged == true || progress?.shortage == true || progress?.returnedOnMatchedDelivery == true)
          Text([if (progress!.damaged) 'Damaged goods matched', if (progress.shortage) 'Bill shortage recorded',
            if (progress.returnedOnMatchedDelivery) 'Return on matched delivery'].join(' · '),
            key: const Key('work-purchase-goods-exceptions'), style: const TextStyle(fontSize: 11, color: _paperMuted)),
        Text(workPurchaseNextStep(progress: progress, remainingMinor: remaining),
          key: const Key('work-purchase-next-step'), style: const TextStyle(fontSize: 11, color: _paperMuted)),
        if (widget.onReceiveGoods != null && progress != null &&
            progress.matchedItems < progress.totalItems)
          TextButton.icon(key: const Key('work-purchase-bill-receive-goods'),
            onPressed: _busy ? null : () async {
              if (!await confirmLeave() || !mounted || !_current) return;
              final acceptedNow = session.workspaceSupplierLedger(copy.supplier.id)?.purchaseBills[copy.draft.id];
              if (acceptedNow != null && jsonEncode(acceptedNow.copy.toJson()) == jsonEncode(copy.toJson())) {
                widget.onReceiveGoods!(copy);
              }
            }, icon: const Icon(Icons.inventory_2_outlined, size: 18), label: const Text('Receive goods')),
      ],
      if (same) ...[
        Wrap(spacing: 8, crossAxisAlignment: WrapCrossAlignment.center, children: [
          const Text('Payment', style: TextStyle(fontSize: 12, fontWeight: FontWeight.w600, color: MoolColors.navy)),
          Text(ledger!.manualBillRemainingMinor(copy.draft.id) == null
            ? 'Individual bill due not yet verified'
            : ledger.manualBillRemainingMinor(copy.draft.id)! < 0
              ? 'Credit with supplier ${_purchaseAmount(-ledger.manualBillRemainingMinor(copy.draft.id)!)}'
              : 'Bill due ${_purchaseAmount(ledger.manualBillRemainingMinor(copy.draft.id)!)}',
            key: const Key('work-purchase-payment-status')),
          if (session.workspaceSupplierMoneyInputAvailable)
          TextButton.icon(key: const Key('work-purchase-record-payment'),
            onPressed: _busy ? null : () async {
              if (!await confirmLeave() || !mounted || !_current) return;
              final currentLedger = session.workspaceSupplierLedger(copy.supplier.id);
              final currentBill = currentLedger?.purchaseBills[copy.draft.id];
              if (currentBill == null || jsonEncode(currentBill.copy.toJson()) != jsonEncode(copy.toJson())) {
                await _load(retry: true);
                return;
              }
              await _showSupplierMoneyEntry(context, session, _StoreSupplierMoneyTarget(
                supplierId: copy.supplier.id,
                copy: currentLedger!.manualBillRemainingMinor(copy.draft.id) == null ? null : copy));
              if (mounted && _current) await _load(retry: true);
            }, icon: const Icon(Icons.payments_outlined, size: 18),
            label: Text(ledger.manualBillRemainingMinor(copy.draft.id) == null
              ? 'Record account payment' : remaining! <= 0 ? 'Bill payment details' : 'Record payment')),
          if (session.workspaceSupplierMoneyInputAvailable && remaining != null && remaining <= 0)
            TextButton.icon(key: const Key('work-purchase-record-advance'),
              onPressed: _busy ? null : () async {
                if (!await confirmLeave() || !mounted || !_current) return;
                final currentBill = session.workspaceSupplierLedger(copy.supplier.id)?.purchaseBills[copy.draft.id];
                if (currentBill == null || jsonEncode(currentBill.copy.toJson()) != jsonEncode(copy.toJson())) {
                  await _load(retry: true);
                  return;
                }
                await _showSupplierMoneyEntry(context, session,
                  _StoreSupplierMoneyTarget(supplierId: copy.supplier.id, advance: true));
                if (mounted && _current) await _load(retry: true);
              }, icon: const Icon(Icons.account_balance_wallet_outlined, size: 18),
              label: const Text('Record advance paid')),
        ]),
        _StoreSupplierLedgerSummary(session: session, ledger: ledger, billId: copy.draft.id, compact: true),
      ],
      _savedBillAdjustmentRail([
      if (same && session.workspaceSupplierAllocationInputAvailable)
        TextButton.icon(
          key: const Key('work-purchase-allocate-money'),
          onPressed: _busy ? null : () async {
            if (!await confirmLeave() || !mounted) return;
            await _showSupplierAllocation(context, session, copy);
            if (mounted && _current) await _load(retry: true);
          }, icon: const Icon(Icons.link_outlined, size: 18),
          label: const Text('Link payment / credit')),
      if (_copyVerified && showShortage && session.supplierShortageRecoveryFormKey(copy) != null)
        TextButton.icon(
          key: const Key('work-purchase-review-shortage'), onPressed: _busy ? null : () async {
            if (!await confirmLeave() || !mounted) return;
            await _showSupplierShortage(context, session, copy);
            if (mounted && _current) await _load(retry: true);
          }, icon: const Icon(Icons.inventory_2_outlined, size: 18),
          label: Text(shortageUnverified ? 'Recover shortages'
            : _shortageDraftPresent ? 'Resume shortage review'
            : shortageHistory ? 'Shortages' : 'Short delivery')),
      if (same && session.supplierCreditFormKey(copy) != null)
        TextButton.icon(
          key: const Key('work-purchase-record-credit'), onPressed: _busy ? null : () async {
            if (!await confirmLeave() || !mounted) return;
            await _showSupplierCredit(context, session, copy);
            if (mounted && _current) await _load(retry: true);
          }, icon: const Icon(Icons.receipt_long_outlined, size: 18),
          label: const Text('Supplier credit note')),
      if (_copyVerified && session.workspaceSupplierOpeningRecord(copy.supplier.id) != null)
        TextButton.icon(
          key: const Key('work-purchase-record-supplier-refund'), onPressed: _busy ? null : () async {
            if (!await confirmLeave() || !mounted) return;
            await _showSupplierRefund(context, session, _StoreSupplierRefundTarget(
              supplierId: copy.supplier.id, sourceKind: WorkspaceSupplierRefundSourceKind.manualBillSurplus,
              sourceId: copy.draft.id, label: 'Bill ${copy.draft.invoiceReference}', copy: copy,
              opening: session.workspaceSupplierOpeningRecord(copy.supplier.id)!));
            if (mounted && _current) await _load(retry: true);
          }, icon: const Icon(Icons.call_received_outlined, size: 18),
          label: const Text('Refund received')),
      ]),
      if (same || (_billGoodsWasAccepted && !ready)) _StoreBillGoodsMatch(key: _billGoodsKey, session: session, copy: copy,
        onOpenCopy: (other) async {
          if (!await confirmLeave() || !mounted) return;
          final detailKey = GlobalKey<_StoreRecordPurchaseState>();
          var leaving = false;
          var allowPop = false;
          await Navigator.of(context).push<void>(MaterialPageRoute(builder: (pageContext) =>
            StatefulBuilder(builder: (routeContext, updateRoute) {
              void finishPop() {
                if (!routeContext.mounted || allowPop) return;
                updateRoute(() => allowPop = true);
                WidgetsBinding.instance.addPostFrameCallback((_) {
                  if (routeContext.mounted) Navigator.of(routeContext).pop();
                });
              }
              Future<void> requestPop() async {
                if (leaving || allowPop) return;
                leaving = true;
                final approved = await (detailKey.currentState?.confirmLeave() ?? Future.value(false));
                leaving = false;
                if (approved) finishPop();
              }
              return PopScope(canPop: allowPop,
                onPopInvokedWithResult: (didPop, result) { if (!didPop) unawaited(requestPop()); },
                child: Scaffold(body: SafeArea(child: _StoreRecordPurchaseSurface(key: detailKey,
                  session: session, savedCopy: other, onBack: finishPop))));
            })));
          if (mounted && _current) await _load(retry: true);
        }),
      if (session.workspaceSupplierOpeningConfirmationAvailable && !ready)
        TextButton(key: const Key('work-purchase-bill-recover'),
          onPressed: _busy ? null : () => _load(retry: true), child: const Text('Retry supplier account')),
      if (ready && accepted == null && treatment == null)
        Text(ledger?.openingRecord == null
          ? 'Purchases → Opening dues: confirm this supplier’s starting balance. Confirm zero only if there are no earlier dues or advances.'
          : canReviewOpening
            ? 'Check whether this whole bill was included in the starting balance before confirming it.'
            : 'This bill conflicts with the saved starting-balance details. Review those details before confirming; the saved bill is kept unchanged.',
          style: const TextStyle(fontSize: 11, color: _paperMuted)),
      if (ready && accepted == null && !latestExact)
        const Text('Open the latest saved revision to confirm this bill.',
          style: TextStyle(fontSize: 11, color: _paperMuted)),
      if (ready && accepted == null && (treatment != null || canReviewOpening) && latestExact &&
          session.workspaceSupplierOpeningConfirmationAvailable)
        TextButton.icon(key: const Key('work-purchase-bill-confirm'),
          onPressed: _busy || session.workspaceSupplierSaving ? null : () => _confirmSavedBill(copy),
          icon: const Icon(Icons.check_circle_outline, size: 18), label: const Text('Confirm bill in supplier account')),
      if (_notice != null) Text(_notice!, key: const Key('work-purchase-bill-notice'),
        style: const TextStyle(fontSize: 12, color: _paperInk)),
    ]);
  }
  Future<void> _confirmSavedBill(WorkspacePurchaseSavedCopy copy) async {
    final session = widget.session;
    final scope = _scope;
    final ledger = session.workspaceSupplierLedger(copy.supplier.id);
    if (_busy || !_current || scope == null ||
        !session.workspaceInvoiceHistoryLoaded || ledger == null) { return; }
    final invoiceTotal = WorkspacePurchaseEntryDraft.printedPaise(copy.draft.details['invoiceTotal']);
    if (invoiceTotal == null) {
      setState(() => _notice = 'Enter the invoice total as shown on the supplier bill before confirming.');
      return;
    }
    var treatment = _billTreatment(copy, ledger);
    WorkspaceSupplierBillOpeningReview? openingReview;
    if (treatment == null && (ledger.openingRecord == null ||
        ledger.openingRecord!.bills.any((link) => link.draftId == copy.draft.id) ||
        copy.draft.invoiceIssuedDay == null)) {
      return;
    }
    final bookRevision = session.workspacePurchaseEntryRevision;
    if (bookRevision == null) return;
    FocusScope.of(context).unfocus();
    setState(() => _busy = true);
    if (treatment == null) {
      final opening = ledger.openingRecord!;
      treatment = await showDialog<WorkspaceOpeningBillInclusion>(context: context,
        builder: (context) => AlertDialog(scrollable: true, title: const Text('Was this bill included?'),
          content: Text('${copy.supplier.name}\n'
            'Starting balance: ${_purchaseAmount(opening.amountMinor!)} '
            '${opening.supplierCredit ? 'advance / credit with supplier' : 'owed to supplier'}\n'
            'Dated ${_registerDate(DateTime.parse(opening.asOfDate))}\n'
            'Invoice total: ${_purchaseAmount(invoiceTotal)}\n'
            'Choose only after checking the whole supplier invoice. If unsure or partly included, cancel and check with the supplier.'),
          actions: [
            TextButton(onPressed: () => Navigator.pop(context), child: const Text('Cancel')),
            TextButton(onPressed: () => Navigator.pop(context, WorkspaceOpeningBillInclusion.included),
              child: const Text('Whole bill already included')),
            TextButton(onPressed: () => Navigator.pop(context, WorkspaceOpeningBillInclusion.excluded),
              child: const Text('Not included — add bill amount')),
          ]));
      if (!mounted || !_current) return;
      if (treatment == null) { setState(() => _busy = false); return; }
      openingReview = WorkspaceSupplierBillOpeningReview(openingId: opening.id,
        openingRevision: opening.revision, treatment: treatment);
    }
    final confirmed = await showDialog<bool>(context: context, builder: (context) => AlertDialog(scrollable: true,
      title: const Text('Confirm supplier bill?'),
      content: Text(treatment == WorkspaceOpeningBillInclusion.included
        ? 'Invoice total ${_purchaseAmount(invoiceTotal)} is already included in the confirmed starting balance. No amount is added again. Included does not mean paid. Stock and payments stay unchanged.'
        : WorkspacePurchaseEntryDraft.printedPaise(copy.draft.details['invoiceTotal']) == 0
          ? 'This zero-total bill will be recorded without adding an amount owed. Stock and payments stay unchanged.'
          : 'Invoice total ${_purchaseAmount(invoiceTotal)} will be added to the supplier account. No payment is recorded; any supplier advance is retained. Stock stays unchanged.'),
      actions: [TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Cancel')),
        TextButton(key: const Key('work-purchase-bill-confirm-accept'),
          onPressed: () => Navigator.pop(context, true), child: const Text('Confirm bill'))]));
    if (!mounted || !_current) return;
    setState(() => _busy = false);
    if (confirmed != true) return;
    if (session.workspacePurchaseEntryRevision != bookRevision ||
        session.workspaceSupplierLedger(copy.supplier.id)?.revision != ledger.revision) {
      setState(() => _notice = 'Saved records changed. Reopen this bill before confirming.');
      return;
    }
    setState(() { _busy = true; _notice = null; });
    final saved = await session.confirmWorkspacePurchaseBill(copy, scope: scope,
      expectedPurchaseRevision: bookRevision, expectedLedgerRevision: ledger.revision,
      openingTreatment: treatment, openingReview: openingReview, confirmedAt: DateTime.now());
    if (!mounted || !_current) return;
    setState(() { _busy = false;
      _notice = saved ? 'Bill confirmed in supplier account. Confirming the bill does not change Stock or record a payment.'
        : session.workspaceSupplierError ?? 'Confirmation status needs recovery. Retry the supplier account before confirming again.'; });
  }
  Widget _goodsRow(int index) {
    final line = _goods[index];
    final linkedProduct = widget.session.workspaceCatalogueItems.where((p) => p.id == line.productId).firstOrNull;
    final query = line.stockSearch.text.toLowerCase().trim();
    final matches = widget.session.workspaceCatalogueItems.where((p) =>
      '${p.title} ${p.sku} ${p.barcode}'.toLowerCase().contains(query)).take(5);
    final sameDescription = linkedProduct != null &&
      linkedProduct.title.trim() == line.name.text.trim() && linkedProduct.pack.trim() == line.pack.text.trim();
    final itemTaxFields = [_field('Taxable value ₹', line.extra['taxableValue']!, 'work-purchase-taxableValue-$index',
        keyboard: const TextInputType.numberWithOptions(decimal: true)),
      _field('Tax amount ₹', line.extra['taxAmount']!, 'work-purchase-taxAmount-$index',
        keyboard: const TextInputType.numberWithOptions(decimal: true))];
    return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      Row(children: [Padding(padding: const EdgeInsets.only(right: 8),
        child: Text('${index + 1}', semanticsLabel: 'Item ${index + 1}',
          style: const TextStyle(fontSize: 12, color: _paperMuted))),
        Expanded(child: _field('Item / description', line.name, 'work-purchase-item-$index',
        lookup: true)),
        if (_goods.length > 1) Tooltip(message: 'Remove item ${index + 1}', child: TextButton(
          key: Key('work-purchase-remove-item-$index'), onPressed: () => _removeInvoiceRow(index),
          child: const Text('Remove')))]),
      if (line.productId.isNotEmpty) Row(children: [Expanded(child: Text(linkedProduct == null
        ? 'Linked Stock product unavailable. Match this item again.'
        : sameDescription ? 'Linked to Stock' : 'Stock: ${linkedProduct.title} · ${linkedProduct.pack}',
        key: Key('work-purchase-stock-link-$index'),
        style: const TextStyle(fontSize: 11, color: _paperMuted))),
        TextButton(key: Key('work-purchase-change-stock-$index'),
          onPressed: () => setState(() => line.productId = ''), child: const Text('Change product'))]),
      if (line.name.text.trim().isNotEmpty && line.productId.isEmpty)
        Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [Row(children: [
          const Expanded(child: Text('Choose a saved product below, or Add product if it is new.',
            key: Key('work-purchase-unmatched-item'),
            style: TextStyle(fontSize: 11, color: MoolColors.ink))),
          TextButton(key: Key('work-purchase-add-product-$index'),
            style: TextButton.styleFrom(minimumSize: const Size(48, 48),
              textStyle: const TextStyle(fontSize: 12, fontWeight: FontWeight.w700)),
            onPressed: () => _addGoodsProduct(line), child: const Text('Add product')),
        ]), _field('Find saved product', line.stockSearch, 'work-purchase-stock-search-$index',
          focus: line.focus, lookup: true, hint: 'Name, SKU or barcode')]),
      if (line.focus.hasFocus && line.productId.isEmpty && query.isNotEmpty)
        for (final p in matches) TextButton(onPressed: () {
          setState(() => line.productId = p.id);
          line.focus.unfocus();
        }, style: TextButton.styleFrom(alignment: Alignment.centerLeft),
          child: Text('${p.title} · ${p.pack}', style: const TextStyle(fontSize: 12, color: MoolColors.navy))),
      LayoutBuilder(builder: (context, constraints) {
        final scaled = MediaQuery.textScalerOf(context).scale(1).clamp(1.0, 2.0);
        final quantityWidth = (76 * scaled).clamp(0, constraints.maxWidth).toDouble();
        final priceWidth = (96 * scaled).clamp(0, constraints.maxWidth).toDouble();
        final packWidth = constraints.maxWidth < quantityWidth + priceWidth + 100
          ? constraints.maxWidth : constraints.maxWidth - quantityWidth - priceWidth - 24;
        return Wrap(spacing: 12, runSpacing: 4, children: [
        SizedBox(width: packWidth,
          child: _field('Pack / unit', line.pack, 'work-purchase-pack-$index')),
        SizedBox(width: quantityWidth, child: _field('Qty', line.quantity, 'work-purchase-quantity-$index',
          limit: 12, keyboard: const TextInputType.numberWithOptions(decimal: true))),
        SizedBox(width: priceWidth, child: _field('Rate ₹', line.cost, 'work-purchase-cost-$index',
          limit: 12, keyboard: const TextInputType.numberWithOptions(decimal: true))),
      ]); }),
      _compactFields([_field('HSN / SAC', line.extra['hsn']!, 'work-purchase-hsn-$index'),
        _field('Item amount ₹', line.extra['lineTotal']!, 'work-purchase-lineTotal-$index',
          keyboard: const TextInputType.numberWithOptions(decimal: true)),
        ...itemTaxFields]),
      _section('Item details', 'work-purchase-item-details-$index', [
        _field('S No. / item No.', line.extra['printedSerial']!, 'work-purchase-printedSerial-$index'),
        _field('Model / specifications', line.extra['specifications']!,
          'work-purchase-specifications-$index', limit: 1000, multiline: true),
        const Text('HSN is the item code printed on the bill. Leave unavailable details blank.',
          style: TextStyle(fontSize: 11, color: MoolColors.ink)),
        _compactFields([for (final e in const {'barcode':'Barcode / item code',
          'unitCode':'Unit code on bill',
          'freeQuantity':'Free qty', 'batch':'Batch No.', 'expiry':'Expiry date', 'mrp':'MRP ₹',
          'sellingPrice':'Selling price ₹', 'discount':'Discount ₹', 'gstRate':'GST %', 'cess':'Cess ₹'}.entries)
          _field(e.value, line.extra[e.key]!, 'work-purchase-${e.key}-$index', limit: 200,
            hint: e.key == 'expiry' ? 'DD/MM/YYYY' : e.key == 'barcode' ? 'Barcode / supplier code' : null,
            keyboard: const ['hsn','barcode','batch','expiry','unitCode'].contains(e.key) ? null :
              const TextInputType.numberWithOptions(decimal: true))]),
        _section('Item GST breakup', 'work-purchase-gst-split-$index', [
          const Text('Copy each tax rate and amount shown. Leave components not shown blank.',
            style: TextStyle(fontSize: 11, color: MoolColors.muted)),
          _compactFields([for (final e in const {'cgstRate':'CGST %', 'cgst':'CGST ₹',
            'sgstRate':'SGST %', 'sgst':'SGST ₹', 'utgstRate':'UTGST %', 'utgst':'UTGST ₹',
            'igstRate':'IGST %', 'igst':'IGST ₹', 'cessRate':'Cess %'}.entries)
            _field(e.value, line.extra[e.key]!, 'work-purchase-${e.key}-$index', limit: 200,
              keyboard: const TextInputType.numberWithOptions(decimal: true))]),
        ]), _extraFields('items', itemIndex: index)]),
      const SizedBox(height: 6),
      const Divider(height: 1, thickness: .7, color: _paperRule),
    ]);
  }
}

class _StoreSupplierOpeningSurface extends StatefulWidget {
  const _StoreSupplierOpeningSurface({
    super.key,
    required this.session,
    required this.onBack,
  });
  final WorkSession session;
  final VoidCallback onBack;
  @override
  State<_StoreSupplierOpeningSurface> createState() =>
      _StoreSupplierOpeningState();
}

class _StoreSupplierOpeningState extends State<_StoreSupplierOpeningSurface> {
  final _date = TextEditingController(),
      _amount = TextEditingController(),
      _note = TextEditingController();
  final _relations = <String, WorkspaceOpeningBillInclusion>{};
  (String, String, bool)? _scope;
  String? _supplierId, _basisId, _error;
  int? _revision;
  int _selectionEpoch = 0;
  bool _known = false,
      _credit = false,
      _editing = true,
      _busy = false,
      _leaving = false;
  String _baseline = '';
  bool _postingRecovered = false;
  WorkspaceSupplierOpeningRecord? _viewed, _attempt;
  WorkSession get session => widget.session;
  bool get _current =>
      _scope != null && _scope == session.workspaceSupplierScope;
  String get _input => jsonEncode([
    _supplierId,
    _date.text,
    _amount.text,
    _note.text,
    _known,
    _credit,
    _relations.map((k, v) => MapEntry(k, v.name)),
  ]);
  bool get _dirty => _editing && _input != _baseline;
  @override
  void initState() {
    super.initState();
    _scope = session.workspaceSupplierScope;
    _revision = session.workspacePurchaseEntryRevision;
    _baseline = _input;
    if (session.workspaceSupplierOpeningConfirmationAvailable) {
      unawaited(_recoverPosting());
    }
  }

  Future<void> _recoverPosting() async {
    final recovered = await session.recoverCustomerLedger();
    if (!mounted || !_current) {
      return;
    }
    setState(() {
      _postingRecovered = recovered;
      if (recovered && !_editing) {
        _error = null;
      }
      if (!recovered) {
        _error = session.customerLedgerRecoveryError ??
            'Supplier account could not be opened. Saved records are kept; try again.';
      }
    });
  }

  bool get _accountReady => _current && _postingRecovered &&
      !session.workspaceSupplierRecoveryRequired;
  bool get _posted {
    final proof = _supplierId == null ? null :
        session.workspaceSupplierLedger(_supplierId!)?.openingRecord;
    return _accountReady && proof != null && _viewed != null &&
        jsonEncode(proof.toJson()) == jsonEncode(_viewed!.toJson());
  }

  Future<void> _confirmOpening() async {
    final record = _viewed;
    if (_busy || _editing || !_accountReady || record == null || _revision == null ||
        !session.workspaceSupplierOpeningConfirmationAvailable) {
      return;
    }
    FocusScope.of(context).unfocus();
    setState(() => _busy = true);
    try {
      final confirmed = await showDialog<bool>(context: context,
        builder: (context) => AlertDialog(
          title: const Text('Confirm opening balance?'),
          content: Text('${record.amountMinor == null ? 'Amount not known' : _purchaseAmount(record.amountMinor!)} · '
            '${record.supplierCredit ? 'Advance / credit with supplier' : 'You owe the supplier'}\n'
            'This adds the starting balance to the supplier account. It does not add Stock or record a payment.'),
          actions: [
            TextButton(onPressed: () => Navigator.pop(context, false),
              child: const Text('Cancel')),
            FilledButton(key: const Key('work-opening-confirm-accept'),
              onPressed: () => Navigator.pop(context, true),
              child: const Text('Confirm balance')),
          ],
        ));
      if (confirmed != true || !mounted || !_current) {
        return;
      }
      final saved = await session.confirmWorkspaceSupplierOpeningRecord(record,
        scope: _scope!, expectedRevision: _revision!, confirmedAt: DateTime.now());
      if (!mounted || !_current) {
        return;
      }
      setState(() {
        _postingRecovered = session.workspaceInvoiceHistoryLoaded;
        _error = saved ? null : session.workspaceSupplierError ??
          'Balance confirmation was not completed. Reopen the saved supplier account before trying again.';
      });
    } finally {
      if (mounted) {
        setState(() => _busy = false);
      }
    }
  }

  @override
  void dispose() {
    _date.dispose();
    _amount.dispose();
    _note.dispose();
    super.dispose();
  }

  Future<bool> confirmLeave() async {
    if (_busy || _leaving || session.workspaceSupplierSaving) return false;
    if (!_dirty) return true;
    _leaving = true;
    FocusScope.of(context).unfocus();
    final discard = await showDialog<bool>(
      context: context,
      builder: (context) => AlertDialog(
        title: const Text('Leave opening dues?'),
        content: const Text(
          'Discard only these unsaved changes? Saved purchases and opening records stay available.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context, false),
            child: const Text('Keep editing'),
          ),
          TextButton(
            onPressed: () => Navigator.pop(context, true),
            child: const Text('Discard changes'),
          ),
        ],
      ),
    );
    _leaving = false;
    return mounted && discard == true;
  }

  List<WorkspacePurchaseSavedCopy> get _bills {
    return session.workspaceLatestPurchaseCopies
        .where((c) => c.supplier.id == _supplierId)
        .toList()
      ..sort((a, b) => b.savedAt.compareTo(a.savedAt));
  }

  void _show(String supplierId, {WorkspaceSupplierOpeningRecord? version}) {
    _supplierId = supplierId;
    _revision = session.workspacePurchaseEntryRevision;
    _viewed = version ?? session.workspaceSupplierOpeningRecord(supplierId);
    _basisId = _viewed?.basisId ?? session.newWorkspaceSupplierOpeningId();
    _date.text = _viewed?.asOfDate ?? '';
    _amount.text = _viewed?.amountMinor == null
        ? ''
        : (_viewed!.amountMinor! / 100).toStringAsFixed(2);
    _note.text = _viewed?.sourceNote ?? '';
    _known = _viewed?.amountMinor != null;
    _credit = _viewed?.supplierCredit ?? false;
    _relations.clear();
    _editing = _viewed == null;
    _attempt = null;
    _error = null;
    _baseline = _input;
  }

  void _changed({bool clearBills = true}) {
    setState(() {
      if (clearBills) _relations.clear();
      _attempt = null;
      _error = null;
    });
  }

  Future<void> _save() async {
    if (_busy || !_editing || !_current || _supplierId == null) return;
    final amount = _known
        ? WorkspacePurchaseEntryDraft.printedPaise(_amount.text)
        : null;
    if (_known && (amount == null || amount < 0)) {
      setState(
        () => _error =
            'Enter the confirmed amount in rupees, or choose Amount not known.',
      );
      return;
    }
    final scope = _scope!;
    _attempt ??= WorkspaceSupplierOpeningRecord(
      id: '$_basisId-r${(_revision ?? 0) + 1}',
      basisId: _basisId!,
      account: scope.$1,
      store: scope.$2,
      qa: scope.$3,
      supplierId: _supplierId!,
      revision: (_revision ?? 0) + 1,
      asOfDate: _date.text.trim(),
      savedAt: DateTime.now(),
      amountMinor: amount,
      supplierCredit: _credit,
      sourceNote: _note.text.trim(),
      bills: [
        for (final b in _bills)
          WorkspaceOpeningBillLink(
            copyId: b.id,
            copyRevision: b.revision,
            draftId: b.draft.id,
            inclusion:
                _relations[b.id] ?? WorkspaceOpeningBillInclusion.unknown,
          ),
      ],
    );
    if (!_attempt!.valid) {
      setState(
        () => _error =
            'Choose the supplier, enter a valid date (YYYY-MM-DD) and explain where this starting amount comes from.',
      );
      return;
    }
    FocusScope.of(context).unfocus();
    setState(() {
      _busy = true;
      _error = null;
    });
    if (session.workspaceSupplierRecoveryError != null) {
      await session.loadWorkspaceSuppliers(retry: true);
    }
    final saved = await session.saveWorkspaceSupplierOpeningRecord(
      _attempt!,
      scope: scope,
      expectedRevision: _revision,
    );
    if (!mounted) return;
    setState(() {
      _busy = false;
      if (saved && _current) {
        _show(_supplierId!);
      } else {
        _error =
            session.workspaceSupplierError ??
            'Return to the Store where you started. Your entries are kept.';
      }
    });
  }

  Widget _field(
    String label,
    TextEditingController controller,
    String key, {
    bool money = false,
    int lines = 1,
  }) => TextField(
    key: Key(key),
    controller: controller,
    readOnly: !_editing || _busy || !_current,
    maxLines: lines,
    maxLength: lines > 1 ? 4000 : 40,
    keyboardType: money
        ? const TextInputType.numberWithOptions(decimal: true)
        : TextInputType.text,
    style: const TextStyle(fontSize: 13, color: MoolColors.ink),
    onChanged: (_) => _changed(),
    decoration: InputDecoration(
      labelText: label,
      filled: false,
      counterText: '',
      border: InputBorder.none,
      enabledBorder: InputBorder.none,
      focusedBorder: InputBorder.none,
      labelStyle: const TextStyle(fontSize: 12, color: MoolColors.ink),
    ),
  );
  @override
  Widget build(BuildContext context) {
    if (!_current) {
      return ListView(
        padding: const EdgeInsets.all(12),
        children: [
          const Text(
            'Return to the Store where you started. Unsaved opening entries are kept.',
          ),
          TextButton(
            onPressed: _busy
                ? null
                : () async {
                    if (await confirmLeave() && mounted) widget.onBack();
                  },
            child: const Text('Close'),
          ),
        ],
      );
    }
    final usable =
        _current &&
        !_busy &&
        session.workspaceSuppliersLoaded &&
        !session.workspaceSupplierSaving;
    final history = session.workspaceSupplierOpeningRecords
        .where((r) => r.supplierId == _supplierId)
        .toList();
    return ListView(
      key: const Key('work-opening-dues-form'),
      primary: false,
      keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
      padding: EdgeInsets.fromLTRB(
        12,
        0,
        12,
        20 + MediaQuery.viewInsetsOf(context).bottom,
      ),
      children: [
        Wrap(
          spacing: 8,
          crossAxisAlignment: WrapCrossAlignment.center,
          children: [
            const Text(
              'Opening dues record',
              style: TextStyle(
                fontSize: 16,
                fontWeight: FontWeight.w700,
                color: MoolColors.navy,
              ),
            ),
            Text(
              !_accountReady
                ? 'Supplier account status unavailable'
                : _posted ? 'Confirmed in supplier account' : 'Not posted',
              key: const Key('work-opening-posting-status'),
              style: const TextStyle(
                fontSize: 12,
                fontWeight: FontWeight.w600,
                color: MoolColors.ink,
              ),
            ),
            TextButton(
              key: const Key('work-opening-close'),
              onPressed: _busy
                  ? null
                  : () async {
                      if (await confirmLeave() && mounted) widget.onBack();
                    },
              child: const Text('Close'),
            ),
          ],
        ),
        Text(
          _posted ? 'The starting balance is kept. Record subsequent goods and payments separately.' :
          'Save the starting amount, check supporting bills, then confirm the balance in the supplier account. Saving alone does not change dues, Stock or payments.',
          style: const TextStyle(fontSize: 12, color: MoolColors.ink),
        ),
        if (_posted && _supplierId != null && session.workspaceSupplierMoneyInputAvailable) ...[
          Wrap(spacing: 8, children: [
            TextButton.icon(key: const Key('work-opening-record-payment'),
              onPressed: _busy || !_current
                ? null : () async {
                  await _showSupplierMoneyEntry(context, session, _StoreSupplierMoneyTarget(supplierId: _supplierId!));
                  if (mounted && _current) await _recoverPosting();
                }, icon: const Icon(Icons.payments_outlined, size: 18),
                label: const Text('Record account payment')),
            TextButton.icon(key: const Key('work-opening-record-advance'),
              onPressed: _busy || !_current ? null : () async {
                await _showSupplierMoneyEntry(context, session, _StoreSupplierMoneyTarget(supplierId: _supplierId!, advance: true));
                if (mounted && _current) await _recoverPosting();
              }, icon: const Icon(Icons.account_balance_wallet_outlined, size: 18), label: const Text('Record advance paid')),
          ]),
        ],
        if (_posted && _supplierId != null)
          _StoreSupplierLedgerSummary(session: session, ledger: session.workspaceSupplierLedger(_supplierId!)),
        if (_posted && _supplierId != null && session.workspaceSupplierOpeningRecord(_supplierId!) != null)
          Align(alignment: Alignment.centerLeft, child: TextButton.icon(
            key: const Key('work-opening-record-refund'), onPressed: _busy || !_current ? null : () async {
              await _chooseSupplierRefund(context, session, _supplierId!);
              if (mounted && _current) await _recoverPosting();
            }, icon: const Icon(Icons.call_received_outlined, size: 18),
            label: const Text('Refund received / saved requests'))),
        if (!_current)
          const Text(
            'Return to the Store where you started. Unsaved entries are kept.',
          ),
        if (session.workspaceSuppliers.isEmpty)
          const Padding(
            padding: EdgeInsets.symmetric(vertical: 8),
            child: Text(
              'No saved supplier yet. Close, choose Record purchase, enter the supplier name and Save draft. Invoice details can be added later.',
            ),
          ),
        DropdownButtonFormField<String>(
          key: ValueKey(('work-opening-supplier', _supplierId, _selectionEpoch)),
          initialValue: _supplierId,
          isExpanded: true,
          decoration: const InputDecoration(
            labelText: 'Supplier',
            filled: false,
          ),
          items: [
            for (final p in session.workspaceSuppliers)
              DropdownMenuItem(
                value: p.id,
                child: Text(p.name, overflow: TextOverflow.ellipsis),
              ),
          ],
          onChanged: !usable
              ? null
              : (id) async {
                  final change = id != null &&
                      id != _supplierId &&
                      await confirmLeave() &&
                      mounted;
                  if (!mounted) return;
                  setState(() {
                    _selectionEpoch++;
                    if (change) _show(id);
                  });
                },
        ),
        if (_supplierId != null) ...[
          if (history.isNotEmpty)
            DropdownButtonFormField<int>(
              key: ValueKey(('opening-version', _viewed?.id, _selectionEpoch)),
              initialValue: _viewed?.revision,
              isExpanded: true,
              decoration: const InputDecoration(
                labelText: 'Saved version',
                filled: false,
              ),
              items: [
                for (final r in history)
                  DropdownMenuItem(
                    value: r.revision,
                    child: Text(
                      '${r.asOfDate} · ${r.amountMinor == null ? 'Amount unknown' : _purchaseAmount(r.amountMinor!)} · v${r.revision}',
                      overflow: TextOverflow.ellipsis,
                    ),
                  ),
