              onChanged: !usable
                  ? null
                  : (rev) async {
                      final change = await confirmLeave();
                      if (!mounted) return;
                      setState(() {
                        _selectionEpoch++;
                        if (change && rev != null) {
                          _show(_supplierId!, version: history.firstWhere((r) => r.revision == rev));
                        }
                      });
                    },
            ),
          _field('As on date (YYYY-MM-DD)', _date, 'work-opening-date'),
          DropdownButtonFormField<bool>(
            key: ValueKey(('opening-known', _known, _viewed?.id)),
            initialValue: _known,
            isExpanded: true,
            decoration: const InputDecoration(
              labelText: 'Starting amount',
              filled: false,
            ),
            items: const [
              DropdownMenuItem(value: false, child: Text('Amount not known')),
              DropdownMenuItem(value: true, child: Text('Amount confirmed')),
            ],
            onChanged: !usable || !_editing
                ? null
                : (v) {
                    if (v != null) {
                      _known = v;
                      _changed();
                    }
                  },
          ),
          if (_known) ...[
            _field('Amount ₹', _amount, 'work-opening-amount', money: true),
            DropdownButtonFormField<bool>(
              key: ValueKey(('opening-credit', _credit, _viewed?.id)),
              initialValue: _credit,
              isExpanded: true,
              decoration: const InputDecoration(
                labelText: 'Who owes this amount?',
                filled: false,
              ),
              items: const [
                DropdownMenuItem(
                  value: false,
                  child: Text('You owe the supplier'),
                ),
                DropdownMenuItem(
                  value: true,
                  child: Text('Supplier owes you / credit available'),
                ),
              ],
              onChanged: !usable || !_editing
                  ? null
                  : (v) {
                      if (v != null) {
                        _credit = v;
                        _changed();
                      }
                    },
            ),
          ],
          _field(
            'Where is this amount from? / Notes',
            _note,
            'work-opening-note',
            lines: 2,
          ),
          const Text(
            'Supporting bills',
            style: TextStyle(
              fontSize: 13,
              fontWeight: FontWeight.w700,
              color: MoolColors.navy,
            ),
          ),
          if (_editing) ...[
            const Text(
              'Check each bill. Included means already counted in this starting amount; bill totals are not added again.',
              style: TextStyle(fontSize: 12, color: MoolColors.ink),
            ),
            if (_bills.isEmpty)
              const Text(
                'No saved purchase copies for this supplier. The starting record can be saved without a bill.',
              ),
            for (final b in _bills)
              DropdownButtonFormField<WorkspaceOpeningBillInclusion>(
                key: ValueKey((
                  'opening-bill',
                  b.id,
                  _basisId,
                  _editing,
                  _relations[b.id],
                )),
                initialValue:
                    _relations[b.id] ?? WorkspaceOpeningBillInclusion.unknown,
                isExpanded: true,
                decoration: InputDecoration(
                  labelText:
                      '${b.draft.invoiceReference} · ${b.draft.invoiceDate} · v${b.revision}',
                  filled: false,
                ),
                items: const [
                  DropdownMenuItem(
                    value: WorkspaceOpeningBillInclusion.unknown,
                    child: Text('Inclusion not confirmed'),
                  ),
                  DropdownMenuItem(
                    value: WorkspaceOpeningBillInclusion.included,
                    child: Text('Already included'),
                  ),
                  DropdownMenuItem(
                    value: WorkspaceOpeningBillInclusion.excluded,
                    child: Text('Not included'),
                  ),
                ],
                onChanged: !usable
                    ? null
                    : (v) {
                        if (v != null) {
                          _relations[b.id] = v;
                          _changed(clearBills: false);
                        }
                      },
              ),
          ] else ...[
            if (_viewed!.bills.isEmpty)
              const Text('No supporting bills recorded.'),
            for (final link in _viewed!.bills)
              Text(
                '${session.workspacePurchaseCopies.firstWhere((c) => c.id == link.copyId).draft.invoiceReference} · v${link.copyRevision} · '
                '${switch (link.inclusion) {
                  WorkspaceOpeningBillInclusion.included => 'Already included',
                  WorkspaceOpeningBillInclusion.excluded => 'Not included',
                  _ => 'Inclusion not confirmed',
                }}',
                style: const TextStyle(fontSize: 12, color: MoolColors.ink),
              ),
          ],
          if (_error != null)
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 8),
              child: Text(
                _error!,
                key: const Key('work-opening-error'),
                style: const TextStyle(fontSize: 12, color: MoolColors.ink),
              ),
            ),
          Wrap(
            spacing: 8,
            children: [
              if (_editing)
                FilledButton(
                  key: const Key('work-opening-save'),
                  style: FilledButton.styleFrom(
                    minimumSize: const Size(48, 48),
                    backgroundColor: MoolColors.navy,
                    foregroundColor: Colors.white,
                    textStyle: const TextStyle(
                      fontFamily: 'Inter',
                      fontSize: 13,
                    ),
                  ),
                  onPressed: usable ? _save : null,
                  child: Text(
                    _busy
                        ? 'Saving…'
                        : _attempt != null && _error != null
                        ? 'Retry save'
                        : 'Save opening record',
                  ),
                )
              else if (!_posted && _viewed ==
                  session.workspaceSupplierOpeningRecord(_supplierId!))
                TextButton(
                  key: const Key('work-opening-correct'),
                  onPressed: !usable
                      ? null
                      : () => setState(() {
                          _editing = true;
                          _relations.clear();
                          _attempt = null;
                          _baseline = '';
                          _error = null;
                        }),
                  child: const Text('Correct record'),
                ),
              if (_accountReady && !_editing && !_posted && _viewed != null &&
                  _viewed == session.workspaceSupplierOpeningRecord(_supplierId!) &&
                  session.workspaceSupplierOpeningConfirmationAvailable)
                FilledButton(
                  key: const Key('work-opening-confirm'),
                  onPressed: usable && _postingRecovered && _known &&
                      _viewed == session.workspaceSupplierOpeningRecord(_supplierId!) &&
                      _viewed!.bills.every((b) => b.inclusion != WorkspaceOpeningBillInclusion.unknown)
                      ? _confirmOpening : null,
                  child: Text(_busy ? 'Confirming…' : 'Confirm opening balance'),
                ),
              if (!_accountReady && session.workspaceSupplierOpeningConfirmationAvailable)
                TextButton(key: const Key('work-opening-recover'),
                  onPressed: usable ? _recoverPosting : null,
                  child: const Text('Reopen supplier account')),
            ],
          ),
          if (!_editing && !_posted && _viewed != null &&
              session.workspaceSupplierOpeningConfirmationAvailable &&
              (!_known || _viewed!.bills.any((b) => b.inclusion == WorkspaceOpeningBillInclusion.unknown)))
            const Text('Choose Correct record to check the amount and which bills are included before confirming.',
              style: TextStyle(fontSize: 12, color: MoolColors.ink)),
        ],
      ],
    );
  }
}

class _ReceivingLineInput {
  _ReceivingLineInput(this.id, {WorkspaceSupplierGoodsReceiptLine? saved})
    : original = saved, productId = saved?.productId ?? '', unit = TextEditingController(text: saved?.purchaseUnit ?? ''),
      factor = TextEditingController(text: '${saved?.unitsPerPack ?? 1}'),
      expected = TextEditingController(text: saved?.expectedMilli == null ? '' : _quantity(saved!.expectedMilli!)),
      delivered = TextEditingController(text: saved == null ? '' : _quantity(saved.deliveredMilli)),
      damaged = TextEditingController(text: saved == null ? '0' : _quantity(saved.damagedMilli)),
      short = TextEditingController(text: saved == null ? '0' : _quantity(saved.shortMilli)),
      prior = {for (final e in saved?.priorStockUnits.entries ?? const <MapEntry<String, int>>[])
        e.key: TextEditingController(text: '${e.value}')};
  final String id;
  final WorkspaceSupplierGoodsReceiptLine? original;
  String productId;
  bool arrives = true;
  final TextEditingController unit, factor, expected, delivered, damaged, short;
  final Map<String, TextEditingController> prior;
  static String _quantity(int value) => (value / 1000).toStringAsFixed(3).replaceFirst(RegExp(r'\.?0+$'), '');
  static int? milli(String text) {
    if (!RegExp(r'^\d+(\.\d{1,3})?$').hasMatch(text.trim())) return null;
    final parts = text.trim().split('.');
    final whole = int.tryParse(parts.first);
    if (whole == null || whole > 2147483) return null;
    return whole * 1000 + int.parse(parts.length == 1 ? '0' : parts.last.padRight(3, '0'));
  }
  void dispose() { for (final c in [unit, factor, expected, delivered, damaged, short, ...prior.values]) { c.dispose(); } }
}

/// Receiving is independent of entering a supplier bill. Persist the reviewed
/// operation before posting and always resume its exact immutable snapshot.
class _StoreReceiveGoodsSurface extends StatefulWidget {
  const _StoreReceiveGoodsSurface({super.key, required this.session, required this.onBack,
    this.initialSupplierId, this.initialBill});
  final WorkSession session;
  final VoidCallback onBack;
  final String? initialSupplierId;
  final WorkspacePurchaseSavedCopy? initialBill;
  @override
  State<_StoreReceiveGoodsSurface> createState() => _StoreReceiveGoodsState();
}

class _StoreReceiveGoodsState extends State<_StoreReceiveGoodsSurface> {
  late final _scope = widget.session.workspaceSupplierScope;
  final _reference = TextEditingController(), _day = TextEditingController();
  final _lines = <_ReceivingLineInput>[];
  String? _supplierId;
  String _groupId = '', _arrivalId = '';
  int? _bookRevision;
  WorkspaceSupplierGoodsReceipt? _frozen;
  WorkspaceGoodsReceiptReviewCancellation? _cancelAttempt;
  WorkspaceGoodsReceiptSaveResult? _postResult;
  _LedgerFormAutosave? _draft;
  final _supplierPicker = GlobalKey<FormFieldState<String>>();
  bool _busy = true, _loaded = false, _reviewVerified = false;
  bool _discarding = false;
  bool _billReceiptChosen = false;
  Future<bool>? _leaveDecision;
  String? _error, _notice;
  WorkSession get session => widget.session;
  bool get _current => mounted && _scope != null && _scope == session.workspaceSupplierScope;
  WorkspaceSupplierLedger? get _ledger => _supplierId == null ? null : session.workspaceSupplierLedger(_supplierId!);
  bool get _committed => _frozen != null && _ledger?.goodsReceipts.containsKey(_frozen!.id) == true;
  bool get _billContextValid => widget.initialBill == null ||
    (_supplierId == widget.initialBill!.supplier.id && session.workspacePurchaseCopies.any((copy) =>
      copy.id == widget.initialBill!.id && copy.revision == widget.initialBill!.revision &&
      copy.draft.id == widget.initialBill!.draft.id && copy.supplier.id == _supplierId));
  bool get _cancelled => _frozen != null && session.workspaceGoodsReceiptCancellations.any((c) => c.receiptId == _frozen!.id);
  bool get _conflict => _committed && _cancelled;
  bool get _savedStatusResolved => _loaded && _reviewVerified && !_conflict &&
    session.workspaceSupplierRecoveryError == null && !session.workspaceSupplierRecoveryRequired && !session.workspaceGoodsReceiptRecoveryPending &&
    _postResult != WorkspaceGoodsReceiptSaveResult.statusUnknown;
  bool get _hasPendingArrival {
    final group = _ledger?.goodsReceipts.values.where((r) => r.expectedDeliveryId == _groupId).toList() ?? [];
    final expected = <String, int?>{for (final receipt in group) for (final line in receipt.lines) line.sourceLineId: line.expectedMilli};
    return expected.isNotEmpty && expected.entries.any((entry) => entry.value == null ||
      group.expand((r) => r.lines).where((line) => line.sourceLineId == entry.key)
        .fold<int>(0, (total, line) => total + line.deliveredMilli) < entry.value!);
  }
  String get _input => jsonEncode([_reference.text, _day.text, for (final line in _lines)
    [line.id, line.productId, line.arrives, line.unit.text, line.factor.text, line.expected.text,
      line.delivered.text, line.damaged.text, line.short.text,
      {for (final e in line.prior.entries) if (e.value.text.isNotEmpty) e.key: e.value.text}]]);
  @override
  void initState() { super.initState(); unawaited(_recover()); }
  @override
  void dispose() { _draft?.removeListener(_draftChanged); _draft?.dispose(); _reference.dispose(); _day.dispose(); for (final line in _lines) { line.dispose(); } super.dispose(); }
  void _draftChanged() { if (_current) setState(() {}); }
  Map<String, String> get _draftFields => {'arrivalId': _arrivalId, 'groupId': _groupId, 'input': _input};
  void _saveInput() {
    if (!_current || _frozen != null || _arrivalId.isEmpty || _draft?.key == null) return;
    final fields = _draftFields;
    if (!WorkspaceLedgerFormDraft(key: _draft!.key!, revision: 1, fields: fields).valid) {
      _draft!.error = 'Delivery input is too long. Shorten the details before saving.';
      _draft!.changed();
      return;
    }
    _draft!.save(fields);
  }
  Future<bool> _flushInput() async {
    if (_supplierId == null || _frozen != null) return true;
    if (_discarding) {
      if (_current) setState(() => _error = 'Draft discard is not verified. Retry discard before leaving.');
      return false;
    }
    _saveInput();
    final saved = await _draft?.flush() ?? false;
    if (_current && !saved) setState(() { _error = 'Delivery input is not saved yet. Retry saving before leaving or reviewing.'; });
    return saved && _current;
  }
  void _resumeSupplierInput(Map<String, String> fields) {
    final reviews = session.workspaceGoodsReceiptDrafts.where((r) => r.supplierId == _supplierId &&
      !session.workspaceGoodsReceiptCancellations.any((c) => c.receiptId == r.receipt.id)).toList();
    final arrival = fields['arrivalId'];
    final reviewed = reviews.where((r) => r.receipt.id == arrival).firstOrNull;
    if (reviewed != null) { _restore(reviewed.receipt); return; }
    if (fields.isNotEmpty && !session.workspaceGoodsReceiptCancellations.any((c) => c.receiptId == arrival)) {
      if (_ledger?.goodsReceipts.containsKey(arrival) == true ||
          reviews.any((r) => _ledger?.goodsReceipts.containsKey(r.receipt.id) != true)) {
        throw StateError('Saved receipt review unavailable');
      }
      final values = jsonDecode(fields['input']!) as List;
      final group = fields['groupId']!;
      final originals = <String, WorkspaceSupplierGoodsReceiptLine>{
        for (final receipt in _ledger?.goodsReceipts.values ?? const <WorkspaceSupplierGoodsReceipt>[])
          if (receipt.expectedDeliveryId == group)
            for (final line in receipt.lines) line.sourceLineId: line};
      final restored = <_ReceivingLineInput>[];
      for (final value in values.skip(2).cast<List>()) {
        final original = originals[value[0]];
        if (original != null && (value[1] != original.productId || value[3] != original.purchaseUnit ||
            value[4] != '${original.unitsPerPack}' || value[5] !=
              (original.expectedMilli == null ? '' : _ReceivingLineInput._quantity(original.expectedMilli!)))) {
          throw StateError('Inherited delivery mapping changed');
        }
      }
      for (final value in values.skip(2).cast<List>()) {
        final line = _ReceivingLineInput(value[0] as String, saved: originals[value[0]]);
        line.productId = value[1] as String; line.arrives = value[2] as bool;
        for (final (index, controller) in [line.unit, line.factor, line.expected, line.delivered, line.damaged, line.short].indexed) {
          controller.text = value[index + 3] as String;
        }
        for (final c in line.prior.values) { c.dispose(); }
        line.prior.clear();
        for (final entry in (value[9] as Map).entries) {
          line.prior[entry.key as String] = TextEditingController(text: entry.value as String);
        }
        restored.add(line);
      }
      for (final line in _lines) { line.dispose(); }
      _lines..clear()..addAll(restored);
      _arrivalId = arrival!; _groupId = group;
      _reference.text = values[0] as String; _day.text = values[1] as String;
      _frozen = null; _reviewVerified = false; _cancelAttempt = null; _postResult = null;
      _notice = 'Unfinished delivery restored · Stock has not changed.';
    } else if (reviews.isNotEmpty) { _restore(reviews.last.receipt); }
    else { _newArrival(); }
  }
  Future<void> _retryInput() async {
    if (!_current || _busy || _draft == null) return;
    if (_discarding) { await _discardInput(); return; }
    setState(() { _busy = true; _error = null; });
    if (!_draft!.ready) {
      final fields = await _draft!.load();
      if (!_current) return;
      if (fields != null) {
        try { _resumeSupplierInput(fields); }
        on Object { _draft!.ready = false; _error = 'Saved delivery input needs recovery. Do not re-enter these goods.'; }
      }
    } else { await _flushInput(); }
    if (_current) setState(() => _busy = false);
  }
  Future<void> _discardInput() async {
    final draft = _draft, supplier = _supplierId, arrival = _arrivalId, input = _input;
    if (!_current || _busy || _frozen != null || draft?.ready != true) return;
    if (!_discarding) {
      final discard = await showDialog<bool>(context: context, builder: (context) => AlertDialog(
        title: const Text('Discard delivery draft?'),
        content: const Text('Only this unfinished draft will be removed. Saved goods, Stock and supplier account stay unchanged.'),
        titleTextStyle: const TextStyle(fontSize: 14, fontWeight: FontWeight.w600, color: MoolColors.navy),
        contentTextStyle: const TextStyle(fontSize: 12, color: MoolColors.ink),
        titlePadding: const EdgeInsets.fromLTRB(16, 12, 16, 8), contentPadding: const EdgeInsets.symmetric(horizontal: 16),
        actionsPadding: const EdgeInsets.all(8),
        actions: [TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Keep draft')),
          TextButton(onPressed: () => Navigator.pop(context, true), child: const Text('Discard draft'))]));
      if (discard != true || !_current || !identical(draft, _draft) || supplier != _supplierId ||
          arrival != _arrivalId || input != _input) {
        return;
      }
    }
    setState(() { _busy = true; _discarding = true; _error = null; });
    draft!.save(const {});
    final saved = await draft.flush();
    if (!_current || !identical(draft, _draft) || supplier != _supplierId) return;
    if (!saved) {
      setState(() { _busy = false; _error = 'Draft discard is not verified. Retry discard; do not re-enter this delivery.'; });
      return;
    }
    for (final line in _lines) { line.dispose(); } _lines.clear();
    _reference.clear(); _day.clear(); _arrivalId = ''; _groupId = '';
    _discarding = false;
    await _recover();
    if (_current) {
      setState(() => _notice = _loaded
        ? 'Delivery draft discarded. Saved goods history is unchanged.'
        : 'Delivery draft discarded. Recover saved goods status before continuing.');
    }
  }
  Future<void> _recover() async {
    if (mounted) setState(() { _busy = true; _error = null; });
    final ready = await session.loadWorkspaceSuppliers(retry: true) &&
      await session.loadWorkspaceInventory(retry: true) && await session.recoverCustomerLedger();
    if (!_current) return;
    _bookRevision = session.workspacePurchaseEntryRevision;
    if (ready && _frozen != null) {
      _reviewVerified = session.workspaceGoodsReceiptDrafts.any((r) => r.supplierId == _supplierId &&
        jsonEncode(r.receipt.toJson()) == jsonEncode(_frozen!.toJson()));
      _postResult = _committed ? session.workspaceGoodsReceiptRecoveryPending
        ? WorkspaceGoodsReceiptSaveResult.stockRecoveryPending : WorkspaceGoodsReceiptSaveResult.saved
        : WorkspaceGoodsReceiptSaveResult.notPosted;
    }
    setState(() { _busy = false; _loaded = ready; if (!ready) _error = 'Saved receiving status is unavailable. Retry without clearing Store data.'; });
    if (ready && _supplierId != null && _arrivalId.isEmpty && _draft?.ready == true) _resumeSupplierInput(const {});
    if (ready && _supplierId == null && widget.initialSupplierId != null) await _chooseSupplier(widget.initialSupplierId!);
  }
  void _restore(WorkspaceSupplierGoodsReceipt receipt) {
    for (final line in _lines) { line.dispose(); }
    _lines..clear()..addAll(receipt.lines.map((line) => _ReceivingLineInput(line.sourceLineId, saved: line)));
    _arrivalId = receipt.id; _groupId = receipt.expectedDeliveryId;
    _reference.text = receipt.reference; _day.text = receipt.deliveredOn;
    _frozen = receipt; _reviewVerified = true; _cancelAttempt = null; _postResult = null;
  }
  Future<void> _chooseSupplier(String id) async {
    if (_supplierId == id) return;
    if (_busy) { _supplierPicker.currentState?.didChange(_supplierId); return; }
    setState(() => _busy = true);
    if (!await _flushInput()) {
      if (_current) setState(() { _busy = false; _supplierPicker.currentState?.didChange(_supplierId); });
      return;
    }
    if (!_current) return;
    _draft?.removeListener(_draftChanged); _draft?.dispose();
    _supplierId = id;
    _frozen = null; _reviewVerified = false; _error = null; _notice = null;
    for (final line in _lines) { line.dispose(); } _lines.clear();
    _reference.clear(); _day.clear(); _arrivalId = ''; _groupId = '';
    _draft = _LedgerFormAutosave(session, session.supplierReceivingInputFormKey(id))..addListener(_draftChanged);
    final fields = await _draft!.load();
    if (!_current) return;
    if (fields != null) {
      try { _resumeSupplierInput(fields); }
      on Object { _draft!.ready = false; _error = 'Saved delivery input needs recovery. Do not re-enter these goods.'; }
    }
    setState(() => _busy = false);
  }
  void _newArrival({WorkspaceSupplierGoodsReceipt? previous}) {
    _billReceiptChosen = true;
    for (final line in _lines) { line.dispose(); }
    _lines.clear();
    if (previous != null) {
      final inherited = <String, WorkspaceSupplierGoodsReceiptLine>{
        for (final receipt in _ledger?.goodsReceipts.values ?? const <WorkspaceSupplierGoodsReceipt>[])
          if (receipt.expectedDeliveryId == previous.expectedDeliveryId)
            for (final line in receipt.lines) line.sourceLineId: line,
        for (final line in previous.lines) line.sourceLineId: line,
      };
      for (final saved in inherited.values) {
        final line = _ReceivingLineInput(saved.sourceLineId, saved: saved);
        line.delivered.clear(); line.damaged.text = '0'; line.short.text = '0';
        final earlier = _ledger?.goodsReceipts.values.where((r) => r.expectedDeliveryId == previous.expectedDeliveryId)
          .expand((r) => r.lines).where((l) => l.sourceLineId == saved.sourceLineId)
          .fold<int>(0, (sum, l) => sum + l.deliveredMilli) ?? 0;
        line.arrives = saved.expectedMilli == null || earlier < saved.expectedMilli!;
        for (final c in line.prior.values) { c.dispose(); } line.prior.clear();
        _lines.add(line);
      }
    } else { _lines.add(_ReceivingLineInput(session.newWorkspaceDeliveryLineId())); }
    _arrivalId = session.newWorkspaceGoodsReceiptId();
    _groupId = previous?.expectedDeliveryId ?? session.newWorkspaceDeliveryGroupId();
    _reference.text = previous?.reference ?? '';
    _day.text = DateTime.now().toIso8601String().substring(0, 10);
    _frozen = null; _reviewVerified = false; _cancelAttempt = null; _postResult = null;
    _error = null; _notice = null;
    _saveInput();
  }
  WorkspaceSupplierGoodsReceipt? _snapshot() {
    final values = <WorkspaceSupplierGoodsReceiptLine>[];
    for (final input in _lines) {
      if (!input.arrives) continue;
      final product = session.workspaceCatalogueItems.where((p) => p.id == input.productId).singleOrNull;
      final delivered = _ReceivingLineInput.milli(input.delivered.text);
      final damage = _ReceivingLineInput.milli(input.damaged.text);
      final short = _ReceivingLineInput.milli(input.short.text);
      final expected = input.expected.text.trim().isEmpty ? null : _ReceivingLineInput.milli(input.expected.text);
      final factor = int.tryParse(input.factor.text);
      if (product == null || delivered == null || damage == null || short == null || factor == null ||
          (input.expected.text.trim().isNotEmpty && expected == null)) { return null; }
      final prior = <String, int>{};
      for (final e in input.prior.entries) {
        final amount = int.tryParse(e.value.text.trim());
        if (e.value.text.trim().isEmpty || amount == 0) continue;
        if (amount == null || amount < 0) { return null; }
        prior[e.key] = amount;
      }
      values.add(WorkspaceSupplierGoodsReceiptLine(sourceLineId: input.id, productId: product.id,
        productLabel: input.original?.productId == product.id ? input.original!.productLabel : product.title,
        purchaseUnit: input.unit.text.trim(), stockUnit: product.pack,
        unitsPerPack: factor, deliveredMilli: delivered, acceptedMilli: delivered - damage,
        damagedMilli: damage, shortMilli: short, expectedMilli: expected, priorStockUnits: prior));
    }
    final receipt = WorkspaceSupplierGoodsReceipt(id: _arrivalId, expectedDeliveryId: _groupId,
      reference: _reference.text.trim(), deliveredOn: _day.text.trim(), recordedAt: DateTime.now().toUtc(), lines: values);
    return receipt.valid ? receipt : null;
  }
  Future<void> _review() async {
    if (_frozen == null) {
      setState(() => _busy = true);
      final saved = await _flushInput();
      if (!_current) return;
      setState(() => _busy = false);
      if (!saved) return;
    }
    final receipt = _frozen ?? _snapshot();
    if (!_current || _supplierId == null || receipt == null || _bookRevision == null) {
      setState(() { _error = 'Choose saved Stock items, enter a delivery reference/date and check quantities. Up to 3 decimal places; accepted goods must convert to whole Stock units.'; });
      return;
    }
    setState(() { _frozen = receipt; _busy = true; _error = null; });
    final saved = await session.saveWorkspaceGoodsReceiptDraft(receipt, supplierId: _supplierId!,
      scope: _scope!, expectedRevision: _bookRevision!);
    if (!_current) return;
    setState(() { _busy = false; _reviewVerified = saved; _bookRevision = session.workspacePurchaseEntryRevision;
      if (!saved && !session.workspaceSupplierRecoveryRequired) _frozen = null;
      if (!saved) _error = session.workspaceSupplierError ?? 'Review status needs recovery. Keep this delivery reference and retry recovery.'; });
  }
  Future<void> _post() async {
    if (!_current || !_loaded || !_reviewVerified || _frozen == null || _ledger == null || _bookRevision == null) return;
    setState(() { _busy = true; _error = null; });
    final result = await session.confirmWorkspaceSupplierGoodsReceipt(_frozen!, supplierId: _supplierId!,
      scope: _scope!, expectedPurchaseRevision: _bookRevision!, expectedSupplierRevision: _ledger!.revision,
      requireSavedReview: true);
    if (!_current) return;
    setState(() { _busy = false; _postResult = result; _notice = result == WorkspaceGoodsReceiptSaveResult.saved
      ? 'Goods recorded. Supplier bill and payment are separate.' : null;
      if (result != WorkspaceGoodsReceiptSaveResult.saved) _error = session.workspaceSupplierError ?? 'Receiving status needs recovery. Do not add these goods again.'; });
  }
  Future<void> _cancel() async {
    if (!_current || _frozen == null || _bookRevision == null || _committed) return;
    _cancelAttempt ??= WorkspaceGoodsReceiptReviewCancellation(receiptId: _frozen!.id, supplierId: _supplierId!,
      revision: _bookRevision! + 1, cancelledAt: DateTime.now().toUtc(), reason: 'Retailer cancelled receiving review to correct goods');
    setState(() { _busy = true; _error = null; });
    final saved = await session.abandonWorkspaceGoodsReceiptReview(_frozen!.id, supplierId: _supplierId!,
      scope: _scope!, expectedRevision: _cancelAttempt!.revision - 1,
      cancelledAt: _cancelAttempt!.cancelledAt, reason: _cancelAttempt!.reason);
    if (!_current) return;
    setState(() { _busy = false; _bookRevision = session.workspacePurchaseEntryRevision;
      if (!saved) _error = session.workspaceSupplierError ?? 'Cancellation is unverified. Retry recovery before replacing this review.'; });
  }
  Future<bool> confirmLeave() {
    final active = _leaveDecision;
    if (active != null) return active;
    final decision = _confirmLeave();
    _leaveDecision = decision;
    return decision.whenComplete(() {
      if (identical(_leaveDecision, decision)) _leaveDecision = null;
    });
  }
  Future<bool> _confirmLeave() async {
    if (_busy) return false;
    if (_frozen != null && !_reviewVerified) {
      setState(() { _error = 'Review save is unverified. Recover saved status or retry this exact review before closing.'; });
      return false;
    }
    if (_frozen == null && _supplierId != null) {
      setState(() => _busy = true);
      final saved = await _flushInput();
      if (!_current) return false;
      setState(() => _busy = false);
      if (!saved) return false;
    }
    return _current;
  }
  Future<void> _close() async {
    if (await confirmLeave() && _current) widget.onBack();
  }
  Widget _receivingHeader(String title) => ListenableBuilder(
    listenable: FocusManager.instance,
    builder: (context, child) {
      final focusContext = FocusManager.instance.primaryFocus?.context;
      final receivingFocus = focusContext?.findAncestorStateOfType<_StoreReceiveGoodsState>() == this;
      return Row(key: const Key('work-receive-header'), children: [
        if (receivingFocus) IconButton(
          key: const Key('work-receive-hide-keyboard'), tooltip: 'Hide keyboard',
          constraints: const BoxConstraints(minWidth: 48, minHeight: 48),
          onPressed: () => FocusManager.instance.primaryFocus?.unfocus(),
          icon: const Icon(Icons.keyboard_hide_outlined)),
        Expanded(child: Text(title, style: const TextStyle(fontSize: 16,
          fontWeight: FontWeight.w700, color: MoolColors.navy))),
        TextButton(onPressed: _busy ? null : _close, child: const Text('Close')),
      ]);
    });
  Widget _field(String label, TextEditingController controller, String key, {bool number = true, bool enabled = true, String? errorText}) =>
    LayoutBuilder(builder: (context, constraints) {
      final available = constraints.hasBoundedWidth ? constraints.maxWidth
          : MediaQuery.sizeOf(context).width - 24;
      final measure = TextPainter(text: TextSpan(text: label,
        style: const TextStyle(fontSize: 12)), textDirection: Directionality.of(context),
        textScaler: MediaQuery.textScalerOf(context))..layout();
      final desired = measure.width + 16;
      measure.dispose();
      final width = (desired < 116 ? 116.0 : desired).clamp(0.0, available).toDouble();
      return SizedBox(width: number ? width : double.infinity, child: TextField(key: ValueKey(key), controller: controller,
      enabled: !_busy && _loaded && !_discarding && _draft?.ready == true && _frozen == null && enabled,
      onChanged: (_) { setState(() {}); _saveInput(); },
      keyboardType: number ? const TextInputType.numberWithOptions(decimal: true) : TextInputType.text,
      style: const TextStyle(fontSize: 13, color: MoolColors.ink),
      decoration: InputDecoration(label: Text(label, key: ValueKey('$key-label'),
        maxLines: 3, softWrap: true, overflow: TextOverflow.visible), isDense: true, filled: false,
        errorText: errorText, errorMaxLines: 2,
        errorBorder: const UnderlineInputBorder(borderSide: BorderSide(color: Color(0xffa52a2a))),
        focusedErrorBorder: const UnderlineInputBorder(borderSide: BorderSide(color: Color(0xffa52a2a))),
        floatingLabelBehavior: FloatingLabelBehavior.always,
        labelStyle: const TextStyle(fontSize: 12, color: MoolColors.ink),
        contentPadding: const EdgeInsets.symmetric(vertical: 10), constraints: const BoxConstraints(minHeight: 48),
        border: const UnderlineInputBorder(), enabledBorder: const UnderlineInputBorder(),
        focusedBorder: const UnderlineInputBorder(borderSide: BorderSide(color: MoolColors.navy)),
        disabledBorder: const UnderlineInputBorder())));
    });
  @override
  Widget build(BuildContext context) {
    final editable = !_busy && _loaded && !_discarding && _frozen == null && (_supplierId == null || _draft?.ready == true);
    final bill = widget.initialBill;
    final linkedReceiptIds = bill == null ? const <String>{} : _ledger?.billGoodsAllocations.values
      .where((link) => link.billId == bill.draft.id && link.copyId == bill.id && link.copyRevision == bill.revision)
      .map((link) => link.receiptId).toSet() ?? const <String>{};
