          }, child: Text('View delivery ${_frozen!.reference}')),
        ],
        TextButton(key: const Key('work-receive-bill-new-delivery'), onPressed: _busy ? null : () {
          if (_current && _billContextValid && _savedStatusResolved) setState(() => _newArrival());
