  Widget _lineView(_ReceivingLineInput line, int index) {
    final product = session.workspaceCatalogueItems.where((p) => p.id == line.productId).singleOrNull;
    final inherited = _ledger?.goodsReceipts.values.any((r) => r.expectedDeliveryId == _groupId && r.lines.any((l) => l.sourceLineId == line.id)) ?? false;
    final prior = session.workspaceReceiptPriorStock(line.productId);
    for (final entry in prior.entries) { line.prior.putIfAbsent(entry.key.id, TextEditingController.new); }
    final delivered = _ReceivingLineInput.milli(line.delivered.text), damage = _ReceivingLineInput.milli(line.damaged.text);
    final factor = int.tryParse(line.factor.text);
    final accepted = delivered == null || damage == null ? null : delivered - damage;
    final stock = accepted == null || factor == null || accepted < 0 || accepted * factor % 1000 != 0 ? null : accepted * factor ~/ 1000;
    final linked = line.prior.values.fold<int>(0, (sum, c) => sum + (int.tryParse(c.text) ?? 0));
    final expected = _ReceivingLineInput.milli(line.expected.text);
    final earlier = _ledger?.goodsReceipts.values.where((r) => r.expectedDeliveryId == _groupId)
      .expand((r) => r.lines).where((l) => l.sourceLineId == line.id).fold<int>(0, (sum, l) => sum + l.deliveredMilli) ?? 0;
    final saved = _committed ? _frozen!.lines.where((l) => l.sourceLineId == line.id).singleOrNull : null;
    if (saved != null && !_conflict) {
      Widget figure(String label, String value) => Row(children: [
        Expanded(child: Text(label, style: const TextStyle(fontSize: 13, color: MoolColors.ink))),
        Text(value, style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600, color: MoolColors.navy)),
      ]);
      String qty(int value) => _ReceivingLineInput._quantity(value);
      return Padding(key: ValueKey(('receiving-line', line.id)), padding: const EdgeInsets.symmetric(vertical: 10),
        child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          Text('${index + 1}. ${saved.productLabel}', style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w600, color: MoolColors.navy)),
          Text('This arrival · ${saved.purchaseUnit}', style: const TextStyle(fontSize: 12, color: MoolColors.ink)),
          const SizedBox(height: 6),
          figure('Delivered', qty(saved.deliveredMilli)),
          figure('Accepted', qty(saved.acceptedMilli)),
          if (saved.damagedMilli > 0) figure('Damaged · not added to Stock', qty(saved.damagedMilli)),
          if (saved.shortMilli > 0) figure('Short in this arrival', qty(saved.shortMilli)),
          if (saved.linkedStockUnits > 0) figure('Already in Stock · linked', '${saved.linkedStockUnits}'),
          figure('${session.workspaceGoodsReceiptRecoveryPending ? 'Awaiting Stock recovery' : 'Added to Stock'} · ${saved.stockUnit}', '${saved.newStockUnits}'),
          const SizedBox(height: 6),
          Text(expected == null ? 'Total delivered ${qty(earlier)} · expected quantity not entered'
            : 'Total delivered ${qty(earlier)} of ${qty(expected)} · pending ${qty(expected - earlier)}',
            key: ValueKey('work-receive-total-$index'), style: const TextStyle(fontSize: 12, color: MoolColors.ink)),
          const Divider(height: 16),
        ]));
    }
    return Padding(key: ValueKey(('receiving-line', line.id)), padding: const EdgeInsets.symmetric(vertical: 12), child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      Row(children: [Expanded(child: Text('Item ${index + 1}', style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600, color: MoolColors.navy))),
        if (!_busy && _frozen == null && !inherited && _lines.length > 1) TextButton(key: ValueKey('work-receive-remove-$index'),
          onPressed: () => setState(() { _lines.remove(line); line.dispose(); _saveInput(); }), child: const Text('Remove item'))]),
      if (inherited && _frozen == null) CheckboxListTile(key: ValueKey('work-receive-arrives-$index'),
        value: line.arrives, dense: true, contentPadding: EdgeInsets.zero, controlAffinity: ListTileControlAffinity.leading,
        title: const Text('Received in this delivery', style: TextStyle(fontSize: 12)),
        onChanged: _busy || !_loaded || _discarding || _draft?.ready != true ? null : (value) => setState(() { line.arrives = value ?? false; _saveInput(); })),
      if (!line.arrives) Text('${line.original?.productLabel ?? product?.title ?? 'Saved item'} · not received this time. Earlier goods history is unchanged.',
        style: const TextStyle(fontSize: 12)),
      if (line.arrives) ...[
      DropdownButtonFormField<String>(key: ValueKey('work-receive-product-$index'), initialValue: line.productId.isEmpty ? null : line.productId,
        isExpanded: true, style: const TextStyle(fontSize: 13, color: MoolColors.ink),
        decoration: const InputDecoration(labelText: 'Match saved Stock product', filled: false,
          floatingLabelBehavior: FloatingLabelBehavior.always, labelStyle: TextStyle(fontSize: 12, color: MoolColors.ink),
          contentPadding: EdgeInsets.symmetric(vertical: 8), enabledBorder: UnderlineInputBorder(),
          focusedBorder: UnderlineInputBorder(borderSide: BorderSide(color: MoolColors.navy))),
        items: [for (final p in session.workspaceCatalogueItems.where((p) => p.stockMode == WorkspaceStockMode.exactQuantity))
          DropdownMenuItem(value: p.id, child: Text('${p.title} · ${p.pack}')),
          if (line.productId.isNotEmpty && (product == null || product.stockMode != WorkspaceStockMode.exactQuantity))
            DropdownMenuItem(value: line.productId, enabled: false, child: const Text('Saved product unavailable · recover Stock'))],
        onChanged: !_busy && _loaded && !_discarding && _draft?.ready == true && _frozen == null && !inherited ? (value) => setState(() {
          line.productId = value ?? ''; for (final c in line.prior.values) { c.dispose(); } line.prior.clear();
          line.unit.text = session.workspaceCatalogueItems.where((p) => p.id == value).firstOrNull?.pack ?? '';
          line.factor.text = '1';
          _saveInput();
        }) : null),
      Wrap(spacing: 12, runSpacing: 12, children: [
        _field('Delivery unit', line.unit, 'work-receive-unit-$index', number: false, enabled: !inherited),
        _field('Stock units / unit', line.factor, 'work-receive-factor-$index', enabled: !inherited),
        _field('Expected qty', line.expected, 'work-receive-expected-$index', enabled: !inherited,
          errorText: expected == null && line.expected.text.trim().isNotEmpty ? 'Enter a complete qty' : null),
        _field('Delivered qty', line.delivered, 'work-receive-delivered-$index'),
        _field('Damaged qty', line.damaged, 'work-receive-damaged-$index'),
        _field('Short this arrival', line.short, 'work-receive-short-$index'),
      ]),
      Text('Accepted: ${accepted == null || accepted < 0 ? 'Check quantities' : _ReceivingLineInput._quantity(accepted)}${product == null ? '' : ' · Stock unit: ${product.pack}'}', style: const TextStyle(fontSize: 12)),
      if (prior.isNotEmpty) const Text('Already entered in Stock? Link only the matching original entry below.', style: TextStyle(fontSize: 12)),
      for (final entry in prior.entries) Row(children: [Expanded(child: Text('${entry.key.reason}\n${_registerDate(entry.key.occurredAt)} · original ${entry.key.quantityDelta} · unlinked ${entry.value}', style: const TextStyle(fontSize: 12))),
        _field('Link Stock units', line.prior[entry.key.id]!, 'work-receive-prior-$index-${entry.key.id}')]),
      Text(stock == null ? 'Check conversion: accepted goods must equal whole Stock units.' : 'Accepted Stock units $stock − earlier linked $linked = add ${stock - linked}',
        style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w600, color: MoolColors.navy)),
      if (expected != null || line.expected.text.trim().isEmpty)
      Text(expected == null ? 'Pending qty: expected quantity not entered'
        : 'Earlier delivered ${_ReceivingLineInput._quantity(earlier)} · pending before this arrival ${_ReceivingLineInput._quantity(expected - earlier)}', style: const TextStyle(fontSize: 12)),
      ],
      const Divider(height: 16),
    ]));
  }
}

class _StorePurchasesSurface extends StatefulWidget {
  const _StorePurchasesSurface({
    required this.session,
    this.statement = false,
    this.onTrackPurchase,
    this.onPurchaseBack,
    this.purchaseEntryKey,
    this.receivingKey,
  });
  final WorkSession session;
  final bool statement;
  final ValueChanged<String>? onTrackPurchase;
  final VoidCallback? onPurchaseBack;
  final GlobalKey<_StoreRecordPurchaseState>? purchaseEntryKey;
  final GlobalKey<_StoreReceiveGoodsState>? receivingKey;

  @override
  State<_StorePurchasesSurface> createState() => _StorePurchasesSurfaceState();
}

class _StorePurchasesSurfaceState extends State<_StorePurchasesSurface> {
  WorkSession get session => widget.session;
  bool get statement => widget.statement;
  String? _storeId, _lastViewedId;
  bool _showedDetails = false;
  final _returnRowKey = GlobalKey();
  final _purchaseSearch = TextEditingController();
  final _purchaseSearchFocus = FocusNode(debugLabel: 'purchase-search');
  List<String>? _purchaseHistory;
  String _purchaseFilter = 'All';
  bool _recordPurchase = false, _openingOnly = false;
  bool _receiveGoods = false;
  String? _receivingSupplierId;
  WorkspacePurchaseSavedCopy? _returnReceivingCopy;
  Object? _surfaceScope;
  bool _newPurchase = false;
  WorkspacePurchaseSavedCopy? _savedCopy;

  @override
  void initState() {
    super.initState();
    _purchaseSearchFocus.addListener(_refreshPurchaseSearch);
    if (!statement) {
      unawaited(_loadEntry());
    }
  }

  Future<void> _loadEntry() async {
    await session.loadWorkspaceSuppliers();
    if (mounted) setState(() {});
  }

  void _refreshPurchaseSearch() {
    if (mounted) setState(() {});
  }

  @override
  void dispose() {
    _purchaseSearch.dispose();
    _purchaseSearchFocus.removeListener(_refreshPurchaseSearch);
    _purchaseSearchFocus.dispose();
    super.dispose();
  }

  bool _matchesReceiptFilter(WorkspacePurchaseRecord record) =>
      switch (_purchaseFilter) {
        'Incoming' => record.stage != WorkspaceSupplyStage.unknown &&
            record.stage.incoming,
        'Needs receipt' =>
          record.stage != WorkspaceSupplyStage.cancelled &&
          record.stage != WorkspaceSupplyStage.returned &&
          (record.receiptState == WorkspaceReceiptState.partial ||
           record.receiptState == WorkspaceReceiptState.disputed ||
           (record.stage == WorkspaceSupplyStage.delivered &&
            record.receiptState == WorkspaceReceiptState.awaiting)),
        'Received' => record.receiptState == WorkspaceReceiptState.confirmed,
        _ => true,
      };

  @override
  Widget build(BuildContext context) {
    final storeId = session.activeWorkspace?.id;
    final history = session.workspaceRecentSearches('purchases');
    if (_storeId != storeId || _surfaceScope != session.workspaceSupplierScope || !identical(_purchaseHistory, history)) {
      _storeId = storeId;
      _surfaceScope = session.workspaceSupplierScope;
      _lastViewedId = null;
      _showedDetails = false;
      _purchaseHistory = history;
      _purchaseSearch.clear();
      _purchaseFilter = 'All';
      _recordPurchase = false;
      _receiveGoods = false;
      _receivingSupplierId = null; _returnReceivingCopy = null;
      _openingOnly = false;
      _newPurchase = false;
      _savedCopy = null;
    }
    if (_receiveGoods && !statement) {
      final scope = session.workspaceSupplierScope;
      return _StoreReceiveGoodsSurface(key: widget.receivingKey, session: session, initialSupplierId: _receivingSupplierId,
        initialBill: _returnReceivingCopy,
        onBack: () {
          if (!mounted || scope != session.workspaceSupplierScope) return;
          setState(() { _receiveGoods = false; _receivingSupplierId = null;
            _savedCopy = _returnReceivingCopy; _returnReceivingCopy = null; });
        });
    }
    if ((_recordPurchase || _savedCopy != null) && !statement) {
      return _StoreRecordPurchaseSurface(
        key: widget.purchaseEntryKey ?? ValueKey(('record-purchase', session.workspaceSupplierScope, _savedCopy?.id)), session: session,
        savedCopy: _savedCopy,
        openingOnly: _openingOnly,
        startNew: _newPurchase,
        onReceiveGoods: (copy) => setState(() { _returnReceivingCopy = copy;
          _receivingSupplierId = copy.supplier.id; _savedCopy = null;
          _recordPurchase = false; _openingOnly = false; _newPurchase = false; _receiveGoods = true; }),
        onBack: () => setState(() { _recordPurchase = false; _openingOnly = false; _newPurchase = false; _savedCopy = null; }));
    }
    final selected = session.focusedWorkspacePurchase;
    final returning =
        _showedDetails && session.focusedWorkspacePurchaseId == null;
    _showedDetails = session.focusedWorkspacePurchaseId != null;
    if (selected != null) _lastViewedId = selected.shipmentId;
    if (returning) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        final target = _returnRowKey.currentContext;
        if (mounted &&
            target != null &&
            target.mounted &&
            session.activeWorkspace?.id == storeId &&
            session.focusedWorkspacePurchaseId == null) {
          unawaited(Scrollable.ensureVisible(target, alignment: .5));
        }
      });
    }
    if (session.focusedWorkspacePurchaseId != null) {
      if (selected == null) {
        return ListView(
          primary: false,
          padding: const EdgeInsets.all(16),
          children: [
            TextButton(
              onPressed:
                  widget.onPurchaseBack ??
                  session.clearWorkspacePurchaseSelection,
              child: Text(
                widget.onPurchaseBack == null
                    ? 'Back to purchases'
                    : 'Back to search',
              ),
            ),
            const _DeskEmpty(
              icon: Icons.local_shipping_outlined,
              title: 'Purchase update unavailable',
              detail: 'Return to your linked purchases and try again.',
            ),
          ],
        );
      }
      final updatedAt = selected.updatedAt.toLocal();
      return ListView(
        key: PageStorageKey(
          'work-purchase-details-$storeId-${selected.shipmentId}-$statement',
        ),
        primary: false,
        padding: EdgeInsets.symmetric(
          horizontal: MediaQuery.textScalerOf(context).scale(1) >= 2 ? 8 : 16,
          vertical: 16,
        ),
        children: [
          Row(
            children: [
              IconButton(
                key: const Key('work-purchase-back'),
                tooltip: widget.onPurchaseBack == null
                    ? 'Back to purchases'
                    : 'Back to search',
                onPressed:
                    widget.onPurchaseBack ??
                    session.clearWorkspacePurchaseSelection,
                icon: const Icon(Icons.arrow_back_rounded),
              ),
              Expanded(
                child: Text(
                  selected.supplierName,
                  style: const TextStyle(
                    fontSize: 18,
                    fontWeight: FontWeight.w800,
                    color: MoolColors.navy,
                  ),
                ),
              ),
            ],
          ),
          Text(
            selected.stage.label,
            key: const Key('work-purchase-stage'),
            style: const TextStyle(
              color: MoolColors.navy,
              fontWeight: FontWeight.w700,
            ),
          ),
          const SizedBox(height: 8),
          Text(
            'Order ${selected.orderId}',
            style: const TextStyle(fontSize: 12),
          ),
          if (selected.shipmentId != selected.orderId)
            Text('Shipment ${selected.shipmentId}'),
          if (selected.purchaseId != null &&
              selected.purchaseId != selected.orderId)
            Text('Purchase ${selected.purchaseId}'),
          const Divider(height: 24),
          _StoreMoneyLine(
            leading: const Text('Order total'),
            value: _purchaseAmount(selected.amountMinor),
            style: const TextStyle(
              fontSize: 20,
              fontWeight: FontWeight.w800,
              color: MoolColors.navy,
            ),
          ),
          Text(
            selected.paymentLabel.isEmpty
                ? 'Payment update unavailable'
                : selected.paymentLabel,
          ),
          _StoreSupplierLedgerSummary(
            session: session,
            ledger: session.workspaceSupplierLedger(selected.supplierId),
            orderId: selected.orderId,
          ),
          if (selected.paymentTermLabel?.isNotEmpty == true)
            Text('Agreed terms · ${selected.paymentTermLabel}'),
          if (selected.balanceDueLabel?.isNotEmpty == true)
            Text('Balance terms · ${selected.balanceDueLabel}'),
          if (selected.paymentMethod?.isNotEmpty == true)
            Text('Order payment method · ${selected.paymentMethod}'),
          if (selected.purchaseOrderReference?.isNotEmpty == true)
            Text('Purchase order · ${selected.purchaseOrderReference}'),
          if (session.canConfirmStoreReviewReceipt(selected) &&
              session.supplierPaymentFormKey(selected) != null)
            TextButton.icon(
              key: const Key('supplier-payment-open'),
              icon: const Icon(Icons.receipt_long_outlined),
              label: const Text('Record test payment'),
              onPressed: () => showModalBottomSheet<void>(
                context: context,
                isScrollControlled: true,
                useSafeArea: true,
                builder: (_) =>
                    _StoreMoneyEntrySheet(session: session, purchase: selected),
              ),
            ),
          const SizedBox(height: 14),
          if (selected.stage.incoming &&
              selected.expectedArrival?.isNotEmpty == true)
            Text('Delivery estimate · ${selected.expectedArrival}'),
          if (selected.deliveryPartner?.isNotEmpty == true)
            Text('Delivery partner · ${selected.deliveryPartner}'),
          if (selected.trackingReference?.isNotEmpty == true)
            Text('Tracking · ${selected.trackingReference}'),
          if (selected.address?.isNotEmpty == true)
            Text('Deliver to · ${selected.address}'),
          Text(
            'Updated ${updatedAt.day}/${updatedAt.month}/${updatedAt.year} '
            '${updatedAt.hour.toString().padLeft(2, '0')}:${updatedAt.minute.toString().padLeft(2, '0')}',
            key: const Key('work-purchase-updated-at'),
            style: const TextStyle(fontSize: 11, color: MoolColors.muted),
          ),
          const Text(
            'Live location unavailable',
            style: TextStyle(fontSize: 11, color: MoolColors.muted),
          ),
          if (selected.updateNote?.isNotEmpty == true)
            Text(selected.updateNote!),
          _StoreIssueReviews(
            session: session,
            target: WorkspaceIssueTarget.supplierShipment,
            referenceId: selected.shipmentId,
          ),
          const Divider(height: 24),
          Text(
            selected.receiptState.label,
            key: const Key('work-purchase-receipt-status'),
            style: const TextStyle(
              fontWeight: FontWeight.w700,
              color: MoolColors.navy,
            ),
          ),
          if (selected.receiptReference?.isNotEmpty == true)
            Text('Receipt · ${selected.receiptReference}'),
          if (selected.invoiceReference?.isNotEmpty == true)
            Text('Invoice · ${selected.invoiceReference}'),
          if (selected.lines.isEmpty) ...[
            Text(selected.itemSummary),
            const Text('Item quantities are awaiting an update.'),
          ],
          if (selected.lines.isNotEmpty)
            _StoreReceiptEditor(
              key: ValueKey((
                selected.accountScope,
                selected.workspaceId,
                selected.shipmentId,
              )),
              session: session,
              purchase: selected,
            ),
        ],
      );
    }
    final records =
        (statement
                ? session.filteredWorkspacePurchases
                : session.workspacePurchases)
            .toList()
          ..sort((a, b) => a.createdAt.compareTo(b.createdAt));
    if (statement && !session.workspacePurchasesConnected) {
      return ListView(
        primary: false,
        padding: const EdgeInsets.all(16),
        children: const [
          _DeskEmpty(
            icon: Icons.local_shipping_outlined,
            title: 'Purchase updates unavailable',
            detail:
                'Supplier orders for this Store will appear here when available.',
          ),
        ],
      );
    }
    if (statement) {
      return _StoreVoucherRegister(
        identity: ('purchases', storeId, session.workspaceMoneyPeriod),
        headers: const [
          'Order date',
          'Particulars',
          'Reference type',
          'Invoice reference',
          'Amount (₹)',
        ],
        rows: [
          for (final record in records)
            [
              _registerDate(record.createdAt),
              record.supplierName,
              'Purchase order',
              record.invoiceReference ?? 'Unavailable',
              _formatStoreMinorAmount(record.amountMinor),
            ],
        ],
        rowKeys: [
          for (final record in records)
            ValueKey('work-purchase-${record.shipmentId}'),
        ],
        amountColumns: const {4},
        total: _formatStoreMinorAmount(
          records.fold<int>(0, (sum, record) => sum + record.amountMinor),
        ),
        notice: 'Linked purchase orders · not posted purchase vouchers',
        empty: session.workspacePurchasesComplete
            ? 'No linked purchases in this period.'
            : 'Complete purchase history unavailable.',
        onOpen: (index) {
          if (session.activeWorkspace?.id == storeId) {
            session.selectWorkspacePurchase(records[index].shipmentId);
          }
        },
      );
    }
    records.sort((a, b) {
      final byDate = b.createdAt.compareTo(a.createdAt);
      return byDate != 0 ? byDate : a.shipmentId.compareTo(b.shipmentId);
    });
    final terms = _purchaseSearch.text.trim().toLowerCase().split(RegExp(r'\s+'));
    final visible = records.where((record) {
      final searchable = [record.supplierName, record.orderId, record.shipmentId,
        record.purchaseId, record.invoiceReference, record.purchaseOrderReference,
        record.itemSummary, ...record.lines.map((line) => '${line.name} ${line.pack}')]
          .whereType<String>().join(' ').toLowerCase();
      return _matchesReceiptFilter(record) && terms.every(searchable.contains);
    }).toList();
    final savedCopies = session.workspacePurchaseCopies.where((c) => _purchaseFilter == 'All' &&
      terms.every('${c.supplier.name} ${c.supplier.phone} ${c.draft.invoiceReference} ${c.draft.invoiceDate}'
        .toLowerCase().contains)).toList()..sort((a, b) => b.savedAt.compareTo(a.savedAt));
    return CustomScrollView(
      key: PageStorageKey('work-purchases-$storeId-$statement'),
      primary: false,
      keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
      slivers: [
        SliverToBoxAdapter(child: Padding(
          padding: const EdgeInsets.symmetric(horizontal: 12),
          child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            LayoutBuilder(builder: (context, constraints) {
              final stacked = constraints.maxWidth < MediaQuery.textScalerOf(context).scale(260);
              const heading = Text('Purchases', style: TextStyle(fontSize: 16,
                fontWeight: FontWeight.w800, color: MoolColors.navy));
              return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                if (stacked) heading,
                Row(children: [
              if (!stacked) heading,
              if (!stacked) const SizedBox(width: 8),
              Expanded(child: SingleChildScrollView(key: const Key('work-purchase-actions'), scrollDirection: Axis.horizontal,
                child: Row(children: [
              if (session.workspacePurchaseDraftReviewed) TextButton.icon(
                key: const Key('work-purchase-new'),
                style: TextButton.styleFrom(minimumSize: const Size(48, 48),
                  foregroundColor: MoolColors.navy, padding: const EdgeInsets.symmetric(horizontal: 8)),
                onPressed: () { _purchaseSearchFocus.unfocus();
                  setState(() { _openingOnly = false; _newPurchase = true; _recordPurchase = true; }); },
                icon: const Icon(Icons.add_rounded, size: 16),
                label: const Text('New purchase', style: TextStyle(fontSize: 12))),
              TextButton.icon(key: const Key('work-purchase-record'),
                style: TextButton.styleFrom(minimumSize: const Size(48, 48),
                  foregroundColor: MoolColors.navy, padding: const EdgeInsets.symmetric(horizontal: 8)),
                onPressed: () { _purchaseSearchFocus.unfocus();
                  setState(() { _openingOnly = false; _newPurchase = false; _recordPurchase = true; }); },
                icon: Icon(session.workspacePurchaseDraftReviewed ? Icons.edit_outlined : Icons.add_rounded,
                  size: 16),
                label: Text(session.workspacePurchaseEntryDraft == null ? 'Record purchase'
                  : session.workspacePurchaseDraftReviewed ? 'Edit entry' : 'Resume purchase',
                  style: const TextStyle(fontSize: 12))),
                    if (!statement) TextButton.icon(key: const Key('work-purchase-receive-goods'),
                      onPressed: !session.workspaceSuppliersLoaded ? null : () {
                        _purchaseSearchFocus.unfocus(); setState(() => _receiveGoods = true);
                      }, icon: const Icon(Icons.inventory_2_outlined, size: 16),
                      label: const Text('Receive goods', style: TextStyle(fontSize: 12))),
                    if (!statement)
                      TextButton.icon(
                        key: const Key('work-purchase-opening'),
                        style: TextButton.styleFrom(
                          minimumSize: const Size(48, 48),
                          foregroundColor: MoolColors.navy,
                          padding: const EdgeInsets.symmetric(horizontal: 8),
                        ),
                        onPressed: !session.workspaceSuppliersLoaded
                            ? null
                            : () {
                                _purchaseSearchFocus.unfocus();
                                setState(() {
                                  _openingOnly = true;
                                  _newPurchase = false;
                                  _savedCopy = null;
                                  _recordPurchase = true;
                                });
                              },
                        icon: const Icon(
                          Icons.account_balance_wallet_outlined,
                          size: 16,
                        ),
                        label: const Text(
                          'Opening dues',
                          style: TextStyle(fontSize: 12),
                        ),
                      ),
            ]))),
              const Tooltip(message: 'Swipe actions left or right', child: Icon(Icons.chevron_right, size: 18, color: MoolColors.navy)),
            ]),
              ]);
            }),
            StoreRecentSearches(
              controller: _purchaseSearch,
              focusNode: _purchaseSearchFocus,
              history: history,
              isCurrent: () => identical(history, session.workspaceRecentSearches('purchases')),
              onChanged: (_) => setState(() {}),
              child: TextField(
                key: const Key('work-purchase-search'),
                controller: _purchaseSearch,
                focusNode: _purchaseSearchFocus,
                textInputAction: TextInputAction.search,
                onChanged: (_) => setState(() {}),
                onSubmitted: (_) => _purchaseSearchFocus.unfocus(),
                style: const TextStyle(fontSize: 13, color: MoolColors.ink),
                decoration: InputDecoration(
                  hintText: 'Search supplier, order or invoice',
                  filled: false, isDense: true,
                  border: InputBorder.none, enabledBorder: InputBorder.none,
                  focusedBorder: InputBorder.none, disabledBorder: InputBorder.none,
                  errorBorder: InputBorder.none, focusedErrorBorder: InputBorder.none,
                  prefixIcon: const Icon(Icons.search_rounded, size: 21, color: MoolColors.navy),
                  suffixIcon: _purchaseSearch.text.isEmpty && !_purchaseSearchFocus.hasFocus ? null : IconButton(
                    key: Key(_purchaseSearch.text.isEmpty ? 'work-purchase-search-close' : 'work-purchase-search-clear'),
                    tooltip: _purchaseSearch.text.isEmpty ? 'Close purchase search' : 'Clear purchase search',
                    onPressed: () {
                      if (_purchaseSearch.text.isEmpty) {
                        _purchaseSearchFocus.unfocus();
                      } else {
                        setState(_purchaseSearch.clear);
                      }
                    },
                    icon: const Icon(Icons.close_rounded, size: 18)),
                ),
              ),
            ),
            SizedBox(
              height: (MediaQuery.textScalerOf(context).scale(12) + 24).clamp(48.0, double.infinity).toDouble(),
              child: ListView(scrollDirection: Axis.horizontal, children: [
                for (final filter in const ['All', 'Incoming', 'Needs receipt', 'Received'])
                  Padding(padding: const EdgeInsets.only(right: 6),
                    child: TextButton(
                      key: Key('work-purchase-filter-${filter.toLowerCase().replaceAll(' ', '-')}'),
                      style: TextButton.styleFrom(
                        foregroundColor: MoolColors.navy,
                        backgroundColor: _purchaseFilter == filter
                            ? MoolColors.navy.withValues(alpha: .06) : Colors.transparent,
                        minimumSize: const Size(48, 48),
                        padding: const EdgeInsets.symmetric(horizontal: 8)),
                      onPressed: () { _purchaseSearchFocus.unfocus();
                        setState(() => _purchaseFilter = filter); },
                      child: Semantics(selected: _purchaseFilter == filter,
                        child: Text(filter, style: TextStyle(fontSize: 12,
                            fontWeight: _purchaseFilter == filter ? FontWeight.w800 : FontWeight.w500))),
                    )),
              ]),
            ),
          ]),
        )),
        SliverPadding(
          padding: const EdgeInsets.fromLTRB(12, 6, 12, 12),
          sliver: SliverList(delegate: SliverChildBuilderDelegate((context, index) {
            if (index == 0) { return Column(
              crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            if (!statement && session.workspaceSupplierRecoveryError != null) ...[
              Text(session.workspaceSupplierRecoveryError!, style: const TextStyle(fontSize: 12, color: MoolColors.ink)),
              TextButton(onPressed: () async { await session.loadWorkspaceSuppliers(retry: true);
                if (mounted) setState(() {}); }, child: const Text('Retry saved purchases')),
            ],
            if (!statement && savedCopies.isNotEmpty) ...[
              const Text('Saved purchase copies', style: TextStyle(fontSize: 13,
                fontWeight: FontWeight.w700, color: MoolColors.navy)),
            ],
            if (!statement && _purchaseFilter != 'All' && session.workspacePurchaseCopies.isNotEmpty)
              const Padding(padding: EdgeInsets.only(bottom: 6), child: Text(
                'Receipt filters show MoolSocial deliveries. Choose All for saved purchase copies.',
                style: TextStyle(fontSize: 11, color: MoolColors.ink))),
            if (!session.workspacePurchasesConnected)
              const Padding(padding: EdgeInsets.only(bottom: 6), child: Text(
                'MoolSocial purchase updates unavailable · manual bill drafts remain available',
                style: TextStyle(fontSize: 11, color: MoolColors.ink)))
            else if (!session.workspacePurchasesComplete)
              const Padding(padding: EdgeInsets.only(bottom: 6), child: Text(
                'Available updates only · full history unavailable',
                style: TextStyle(fontSize: 11, color: MoolColors.muted))),
            if (visible.isEmpty && savedCopies.isEmpty) ...[
              Text(records.isEmpty ? 'No linked supplier deliveries' : 'No matching purchases',
                  style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w700, color: MoolColors.navy)),
              Text(records.isEmpty
                  ? 'MoolSocial supplier orders and receipt updates will appear here.'
                  : 'Try another supplier or reference, or clear the filters.',
                  style: const TextStyle(fontSize: 12, color: MoolColors.ink)),
              if (_purchaseFilter != 'All' || _purchaseSearch.text.isNotEmpty)
                Align(alignment: Alignment.centerLeft, child: TextButton(
                  key: const Key('work-purchase-reset'),
                  onPressed: () { _purchaseSearchFocus.unfocus();
                    setState(() { _purchaseSearch.clear(); _purchaseFilter = 'All'; }); },
                  child: const Text('Show all purchases'))),
            ],
            ]); }
            if (index <= savedCopies.length) {
              final copy = savedCopies[index - 1];
              final amount = WorkspacePurchaseEntryDraft.printedPaise(copy.draft.details['invoiceTotal'] ?? '');
              final accepted = session.workspaceInvoiceHistoryLoaded
                ? session.workspaceSupplierLedger(copy.supplier.id)?.purchaseBills[copy.draft.id] : null;
              final postingStatus = !session.workspaceInvoiceHistoryLoaded ? 'Supplier status not checked'
                : accepted == null ? 'Not posted'
                : jsonEncode(accepted.copy.toJson()) == jsonEncode(copy.toJson())
                  ? 'Bill confirmed' : 'Different revision confirmed';
              return InkWell(key: ValueKey('work-purchase-copy-${copy.id}'),
                onTap: () {
                  if (!session.workspaceSuppliersLoaded || !session.workspacePurchaseCopies.contains(copy) ||
                      session.activeWorkspace?.id != storeId) { return; }
                  _purchaseSearchFocus.unfocus();
                  setState(() => _savedCopy = copy);
                }, child: Padding(padding: const EdgeInsets.symmetric(vertical: 10),
                  child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                    _StoreMoneyLine(alignAmountToEnd: true,
                      leading: Text(copy.supplier.name, style: const TextStyle(fontSize: 13,
                        fontWeight: FontWeight.w700, color: MoolColors.navy)),
                      value: amount == null ? 'Total not entered' : _purchaseAmount(amount),
                      style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w700, color: MoolColors.navy)),
                    Text('${copy.draft.invoiceReference} · ${copy.draft.invoiceDate}',
                      style: const TextStyle(fontSize: 12, color: MoolColors.ink)),
                    Row(children: [Expanded(child: Text('Saved ${_registerDate(copy.savedAt)} · Revision ${copy.revision} · $postingStatus',
                      style: const TextStyle(fontSize: 11, color: MoolColors.muted))),
                      const Icon(Icons.chevron_right_rounded, size: 18, color: MoolColors.navy)]),
                    const Divider(height: 1),
                  ])));
            }
            final record = visible[index - savedCopies.length - 1];
            return KeyedSubtree(
                key: record.shipmentId == _lastViewedId ? _returnRowKey : null,
                child: InkWell(
                  key: ValueKey('work-purchase-${record.shipmentId}'),
                  onTap: () {
                    if (session.activeWorkspace?.id != storeId ||
                        !identical(history, session.workspaceRecentSearches('purchases'))) { return; }
                    _purchaseSearchFocus.unfocus();
                    session.selectWorkspacePurchase(record.shipmentId);
                  },
                  child: Padding(padding: const EdgeInsets.symmetric(vertical: 10),
                    child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                      _StoreMoneyLine(
                        alignAmountToEnd: true,
                        leading: Text(record.supplierName, style: const TextStyle(
                            fontSize: 13, fontWeight: FontWeight.w700, color: MoolColors.navy)),
                        value: _purchaseAmount(record.amountMinor),
                        style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w800, color: MoolColors.navy)),
                      Text('${_registerDate(record.createdAt)} · ${record.orderId}',
                          style: const TextStyle(fontSize: 11, color: MoolColors.muted)),
                      if (record.invoiceReference?.isNotEmpty == true)
                        Text('Invoice ${record.invoiceReference}', style: const TextStyle(fontSize: 11)),
                      Text(record.itemSummary, style: const TextStyle(fontSize: 12, color: MoolColors.ink)),
                      Wrap(spacing: 8, runSpacing: 2, children: [
                        Text(record.stage.label, style: const TextStyle(fontSize: 11, color: MoolColors.navy)),
                        Text(record.receiptState.label, style: const TextStyle(fontSize: 11, color: MoolColors.ink)),
                      ]),
                      Row(children: [
                        Expanded(child: Text(record.paymentLabel.trim().isEmpty
                            ? 'Payment update unavailable' : record.paymentLabel,
                            style: const TextStyle(fontSize: 11, color: MoolColors.ink))),
                        TextButton(
                          key: ValueKey('work-purchase-open-${record.shipmentId}'),
                          style: TextButton.styleFrom(foregroundColor: MoolColors.navy,
                              minimumSize: const Size(48, 48), padding: const EdgeInsets.symmetric(horizontal: 6)),
                          onPressed: () {
                            if (session.activeWorkspace?.id != storeId ||
                                !identical(history, session.workspaceRecentSearches('purchases'))) { return; }
                            _purchaseSearchFocus.unfocus();
                            _lastViewedId = record.shipmentId;
                            if (record.stage != WorkspaceSupplyStage.unknown &&
                                record.stage.incoming && widget.onTrackPurchase != null) {
                              widget.onTrackPurchase!(record.shipmentId);
                            } else { session.selectWorkspacePurchase(record.shipmentId); }
                          },
                          child: Row(mainAxisSize: MainAxisSize.min, children: [
                            Text(record.stage != WorkspaceSupplyStage.unknown && record.stage.incoming
                                ? 'Track' : 'Details', style: const TextStyle(fontSize: 11)),
                            const Icon(Icons.chevron_right_rounded, size: 16),
                          ])),
                      ]),
                      const Divider(height: 1),
                    ])),
                ),
              );
          }, childCount: visible.length + savedCopies.length + 1)),
        ),
      ],
    );
  }
}

Future<void> _showSupplierStatement(BuildContext context, WorkSession session,
    WorkspaceSupplierLedger ledger) async {
  final scope = session.workspaceSupplierScope;
  if (scope == null || scope.$1 != ledger.accountScope || scope.$2 != ledger.workspaceId) return;
  final identity = jsonEncode(ledger.toJson());
  try {
    final now = DateTime.now();
    final statement = StoreSupplierStatement(source: ledger, storeName: session.activeWorkspace!.name,
      from: ledger.openingRecord == null
        ? ledger.entries.isEmpty ? now : ledger.entries.map((e) => e.postedAt.toLocal()).reduce((a, b) => a.isBefore(b) ? a : b)
        : DateTime.parse(ledger.openingRecord!.asOfDate),
      until: DateTime(now.year, now.month, now.day + 1), generatedAt: now, reviewOnly: scope.$3);
    if (!context.mounted) return;
    await showModalBottomSheet<void>(context: context, isScrollControlled: true, useSafeArea: true, showDragHandle: false,
      builder: (_) => FractionallySizedBox(heightFactor: .95, child: StoreSupplierStatementPanel(
        statement: statement, changes: session,
        isCurrent: () => session.workspaceSupplierScope == scope &&
          jsonEncode(session.workspaceSupplierLedger(ledger.supplierId)?.toJson()) == identity)));
  } on Object {
    if (context.mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Supplier records need recovery. Close and reopen the account.')));
    }
  }
}

class _StoreSupplierLedgerSummary extends StatelessWidget {
  const _StoreSupplierLedgerSummary({
    required this.session,
    required this.ledger,
    this.orderId,
    this.billId,
    this.compact = false,
  });
  final WorkSession session;
  final WorkspaceSupplierLedger? ledger;
  final String? orderId, billId;
  final bool compact;

  @override
  Widget build(BuildContext context) {
    final current = ledger;
    if (current == null) {
      return const Text('Supplier account balance unavailable');
    }
    final credit = current.creditMinor;
    final payable = current.payableMinor;
    final starting = orderId == null && billId == null &&
        current.openingBalanceMinor != null ? current.openingRecord : null;
    final entries = current.entries.where((entry) => orderId != null
      ? entry.orderId == orderId : billId != null ? entry.billId == billId : true);
    return ExpansionTile(
      key: PageStorageKey((
        'supplier-ledger-expansion',
        current.accountScope,
        current.workspaceId,
        current.supplierId,
        orderId,
        billId,
      )),
      tilePadding: EdgeInsets.zero,
      minTileHeight: compact ? 48 : null,
      title: compact ? Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        const Text('Supplier account', style: TextStyle(fontSize: 12, fontWeight: FontWeight.w600)),
        Text(payable == null || credit == null ? 'Full balance unavailable'
          : credit > 0 ? 'Credit with supplier ${_purchaseAmount(credit)}'
          : 'Amount payable ${_purchaseAmount(payable)}', style: const TextStyle(fontSize: 11)),
      ]) : const Text('Supplier account'),
      subtitle: compact ? null : Text(
        payable == null || credit == null
            ? 'Full balance unavailable'
            : credit > 0
            ? 'Credit with supplier ${_purchaseAmount(credit)}'
            : 'Amount payable ${_purchaseAmount(payable)}',
      ),
      children: [
        Align(alignment: Alignment.centerLeft, child: TextButton.icon(
          key: ValueKey('supplier-statement-open-${current.supplierId}'),
          onPressed: () => _showSupplierStatement(context, session, current),
          icon: const Icon(Icons.receipt_long_outlined, size: 18), label: const Text('Supplier statement'))),
        if (!current.historyComplete || current.openingBalanceMinor == null)
          const Text(
            'Showing available entries. Full account history is unavailable.',
          ),
        Text(orderId != null ? 'Entries for this order' : billId != null
          ? 'Entries linked to this bill' : 'Supplier account entries'),
        if (starting != null)
          ListTile(
            key: const Key('supplier-ledger-starting-balance'),
            dense: true,
            contentPadding: EdgeInsets.zero,
            title: Text(current.openingBalanceMinor! < 0
              ? 'Starting credit with supplier' : 'Starting dues'),
            subtitle: Text('As on ${_registerDate(DateTime.parse(starting.asOfDate))} · Not a new payment'),
            trailing: Text(_purchaseAmount(current.openingBalanceMinor!.abs())),
          ),
        if (entries.isEmpty)
          Text(starting != null ? 'No subsequent financial entries'
            : 'No confirmed financial entries available'),
        for (final entry in entries)
          ListTile(
            contentPadding: EdgeInsets.zero,
            title: Text(switch (entry.kind) {
              WorkspaceSupplierEntryKind.bill => 'Supplier bill',
              WorkspaceSupplierEntryKind.advance => 'Advance paid',
              WorkspaceSupplierEntryKind.payment => 'Payment recorded',
              WorkspaceSupplierEntryKind.creditNote => 'Supplier credit note',
              WorkspaceSupplierEntryKind.refund => 'Refund received',
            }),
            subtitle: Text(
              [
                entry.reference,
                if (entry.paymentMethod != null) entry.paymentMethod!,
              ].join(' · '),
            ),
            trailing: Text(_purchaseAmount(entry.amountMinor)),
          ),
        if (orderId == null) ...[
          for (final link in current.billMoneyAllocations.values.where(
            (item) => billId == null || item.billId == billId ||
              (item.sourceKind == WorkspaceSupplierMoneySourceKind.manualBillSurplus && item.sourceId == billId)))
            ListTile(dense: true, contentPadding: EdgeInsets.zero,
              title: Text(link.sourceKind == WorkspaceSupplierMoneySourceKind.manualBillSurplus
                ? 'Bill credit applied · not another payment' : 'Recorded money linked · not another payment'),
              subtitle: Text('${link.sourceKind == WorkspaceSupplierMoneySourceKind.manualBillSurplus
                ? '${current.purchaseBills[link.sourceId]?.copy.draft.invoiceReference ?? link.sourceId} → ' : ''}'
                '${current.purchaseBills[link.billId]?.copy.draft.invoiceReference ?? link.billId} · ${_registerDate(link.recordedAt)}'),
              trailing: Text(_purchaseAmount(link.amountMinor))),
          if (current.billMoneyAllocations.isNotEmpty && current.unassignedAccountBalanceMinor != null)
            Text(current.unassignedAccountBalanceMinor! < 0
              ? 'Other / unassigned credit ${_purchaseAmount(-current.unassignedAccountBalanceMinor!)}'
              : 'Other / unassigned dues ${_purchaseAmount(current.unassignedAccountBalanceMinor!)}'),
        ],
      ],
    );
  }
}

class _StoreStatementSurface extends StatefulWidget {
  const _StoreStatementSurface({
    required this.session,
    this.salesOnly = false,
    this.showNewSaleAction = true,
    this.onNewSale,
    this.onOpenOperation,
    super.key,
  });
  final WorkSession session;
  final bool salesOnly;
  final bool showNewSaleAction;
  final VoidCallback? onNewSale;
  final ValueChanged<_WorkspaceOperation>? onOpenOperation;
  @override
  State<_StoreStatementSurface> createState() => _StoreStatementSurfaceState();
}

class _StoreStatementSurfaceState extends State<_StoreStatementSurface> {
  bool _openingExchange = false;
  Future<void> _resumeExchangeBill({bool returnSaved = false}) async {
    final account = widget.session.workspaceFinance?.accountScope;
    final store = widget.session.activeWorkspace?.id;
    final resume = await showDialog<bool>(context: context, builder: (dialogContext) => AlertDialog(
      scrollable: true,
      title: const Text('Unfinished sale'),
      content: Text(returnSaved
        ? 'Your return is saved. Resume or finish the existing bill before choosing replacement items. Nothing in that bill will be cleared.'
        : 'Resume or finish the existing bill before starting an exchange. This return has not been recorded; your saved bill will not be cleared.'),
      actions: [
        TextButton(onPressed: () => Navigator.pop(dialogContext, false), child: const Text('Close')),
        TextButton(key: const Key('exchange-resume-sale'),
          onPressed: () => Navigator.pop(dialogContext, true), child: const Text('Resume sale')),
      ]));
    if (!mounted || resume != true) return;
    if (widget.session.workspaceFinance?.accountScope != account || widget.session.activeWorkspace?.id != store) {
      widget.session.showNotice('Store changed. Open the saved sale in the current Store.');
      return;
    }
    widget.onNewSale?.call();
  }

  Future<bool> _exchangeSteps({bool returnSaved = false}) async =>
    await showDialog<bool>(context: context, builder: (dialogContext) => AlertDialog(
      scrollable: true,
      title: Text(returnSaved ? 'Return saved · Choose replacements' : 'How exchange works'),
      content: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.start, children: [
          if (!returnSaved) const Text('1. Find the original invoice and record the items returned.'),
          const Text('2. Create the replacement invoice without recording payment, then choose “Use customer credit” if credit is available.'),
          const SizedBox(height: 8),
          const Text('If money is still due, use Collect dues for the replacement invoice. If credit remains, open the original invoice → Returns & refunds to record the eligible refund. If both are zero, no further payment is needed.'),
          const SizedBox(height: 8),
          const Text('A return may only reduce an unpaid bill; use only the available credit shown. Credit is not a cash payment, and recording a refund does not send money.'),
          if (returnSaved) ...[
            const SizedBox(height: 8),
            const Text('Continue later: use Resume sale for a saved replacement bill. To start a new bill, use Customer credit if available, otherwise Counter sale for the same customer. Do not record the same return again.'),
          ],
        ])),
      actions: [
        TextButton(onPressed: () => Navigator.pop(dialogContext, false), child: Text(returnSaved ? 'Later' : 'Close')),
        if (returnSaved) TextButton(key: const Key('exchange-choose-replacements'),
          onPressed: () => Navigator.pop(dialogContext, true), child: const Text('Choose replacements')),
      ])) == true;

  Future<void> _openExchange(WorkspaceCustomerInvoice invoice, WorkspacePaymentRecord payment) async {
    if (_openingExchange) return;
    _openingExchange = true;
    final session = widget.session;
    final account = session.workspaceFinance?.accountScope;
    final store = session.activeWorkspace?.id;
    try {
      await session.loadWorkspaceCounterDraft();
      if (!mounted || account == null || store == null ||
          !_exchangeSelection || session.workspaceFinance?.accountScope != account ||
          session.activeWorkspace?.id != store) { return; }
      if (session.currentWorkspaceOrderId == null &&
          (session.workspaceOrderQuantities.isNotEmpty || session.workspaceOrderCustomer.trim().isNotEmpty)) {
        await _resumeExchangeBill();
        return;
      }
      final order = session.workspaceOrders.where((o) => o.id == invoice.orderId).firstOrNull;
      final finance = session.workspaceFinance;
      if (widget.onNewSale == null || !session.customerReturnAvailable || order == null ||
          !order.isCompleted || !order.hasCompleteItemSnapshot || finance == null ||
          finance.workspaceId != store || session.workspaceFinanceStale ||
          !finance.payments.any((p) => p.valid && p.invoiceId == invoice.id &&
            p.orderId == order.id && p.customerId == payment.customerId && p.revision == payment.revision)) {
        session.showNotice('Recover this sale’s return records before starting an exchange.');
        return;
      }
      var recorded = false;
      final ledger = finance.customerLedgers.where((l) =>
        l.accountScope == account && l.workspaceId == store &&
        l.customerId == payment.customerId).firstOrNull;
      final remaining = _remainingReturnUnits(order, payment, ledger);
      if (remaining == null || remaining == 0) {
        session.showNotice(remaining == 0 ? 'All items on this invoice have already been returned.'
          : 'Recover this sale’s return records before starting an exchange.');
        return;
      }
      ModalRoute<dynamic>? returnRoute;
      await showModalBottomSheet<void>(context: context, isScrollControlled: true,
        useSafeArea: true, isDismissible: false, enableDrag: false,
        builder: (sheetContext) {
          returnRoute = ModalRoute.of(sheetContext);
          return _CustomerReturnSheet(session: session, payment: payment, order: order,
            account: account, store: store, onRecorded: () => recorded = true);
        });
      await returnRoute?.completed;
      if (!mounted || !recorded || session.workspaceFinance?.accountScope != account ||
          session.activeWorkspace?.id != store) { return; }
      if (!await _exchangeSteps(returnSaved: true) || !mounted) return;
      await _startCustomerSale(account: account, store: store,
        customerId: payment.customerId, customerName: invoice.customer, requireEmptyBill: true);
    } finally {
      _openingExchange = false;
    }
  }

  Future<bool> _startCustomerSale({required String account, required String store,
      required String customerId, required String customerName, bool requireEmptyBill = false}) async {
    final session = widget.session;
    await session.loadWorkspaceCounterDraft();
    if (!mounted || widget.onNewSale == null || session.workspaceFinance?.accountScope != account ||
        session.activeWorkspace?.id != store) { return false; }
    if (requireEmptyBill && session.currentWorkspaceOrderId == null &&
        (session.workspaceOrderQuantities.isNotEmpty || session.workspaceOrderCustomer.trim().isNotEmpty)) {
      await _resumeExchangeBill(returnSaved: true);
      return false;
    }
    if (session.currentWorkspaceOrderId == null && session.workspaceOrderCustomer.trim().isNotEmpty &&
        workspaceCustomerMobile(session.workspaceOrderCustomer) != customerId) {
      session.showNotice('Resume or finish the existing customer bill before starting this sale.');
      return false;
    }
    if (!session.prepareWorkspaceOrder(source: 'Counter', fulfilment: 'At the shop')) return false;
    session.updateWorkspaceCounterDetails(customer: customerName);
    if (workspaceCustomerMobile(session.workspaceOrderCustomer) != customerId) {
      session.updateWorkspaceCounterDetails(customer: customerId);
    }
    widget.onNewSale?.call();
    return true;
  }

  bool _openingCustomerCredit = false;
  Future<bool> _retryCustomerCredit(String message) async => mounted &&
      await showDialog<bool>(context: context, builder: (dialogContext) => AlertDialog(
        title: const Text('Customer credit'), content: Text(message), actions: [
          TextButton(onPressed: () => Navigator.pop(dialogContext, false), child: const Text('Close')),
          TextButton(key: const Key('customer-credit-retry'),
            onPressed: () => Navigator.pop(dialogContext, true), child: const Text('Retry')),
        ])) == true;

  Future<void> _openCustomerCredit() async {
    if (_openingCustomerCredit) return;
    _openingCustomerCredit = true;
    try {
      while (mounted && await _chooseCustomerCredit()) {}
    } finally { _openingCustomerCredit = false; }
  }

  Future<bool> _chooseCustomerCredit() async {
    final session = widget.session;
    final store = session.activeWorkspace?.id;
    final recovered = await session.recoverCustomerLedger();
    final finance = session.workspaceFinance;
    if (!mounted) return false;
    if (session.activeWorkspace?.id != store) {
      session.showNotice('Store changed. Open Customer credit in the current Store.');
      return false;
    }
    if (!recovered || finance == null || !finance.valid || session.workspaceFinanceStale) {
      return _retryCustomerCredit('Customer credit could not be verified. Retry loading saved records. No sale or credit has been changed.');
    }
    final usable = finance.customerLedgers.where((ledger) =>
      ledger.accountScope == finance.accountScope && ledger.workspaceId == finance.workspaceId &&
      _availableCustomerCredit(ledger) > 0).toList();
    final search = TextEditingController();
    ModalRoute<dynamic>? creditRoute;
    final selected = await showModalBottomSheet<WorkspaceCustomerLedger>(context: context,
      isScrollControlled: true, useSafeArea: true,
      builder: (sheetContext) { creditRoute = ModalRoute.of(sheetContext); return StatefulBuilder(builder: (context, update) =>
        Padding(padding: EdgeInsets.fromLTRB(16, 12, 16, MediaQuery.viewInsetsOf(context).bottom + 12),
          child: SizedBox(height: (MediaQuery.sizeOf(context).height - MediaQuery.viewInsetsOf(context).bottom -
              MediaQuery.paddingOf(context).vertical - 32) * .65,
            child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
              Row(children: [const Expanded(child: Text('Customer credit', style: TextStyle(fontSize: 18, fontWeight: FontWeight.w700))),
                IconButton(tooltip: 'Close', onPressed: () => Navigator.pop(sheetContext), icon: const Icon(Icons.close))]),
              TextField(key: const Key('customer-credit-search'), controller: search,
                onChanged: (_) => update(() {}), decoration: const InputDecoration(
                  hintText: 'Search customer name or phone', prefixIcon: Icon(Icons.search),
                  filled: false, border: InputBorder.none, enabledBorder: InputBorder.none,
                  focusedBorder: InputBorder.none)),
              Expanded(child: ListView(children: [
                if (usable.isEmpty) const Text('No available customer credit.'),
                if (finance.customerLedgers.any((l) => !l.valid || !l.historyComplete))
                  const Text('Some customer records are incomplete. Credit is shown only where it can be verified.'),
                if (usable.isNotEmpty && !usable.any((l) =>
                    '${l.customerName} ${l.customerId}'.toLowerCase().contains(search.text.trim().toLowerCase())))
                  const Text('No matching customer with available credit.'),
                for (final ledger in usable.where((l) =>
                    '${l.customerName} ${l.customerId}'.toLowerCase().contains(search.text.trim().toLowerCase()))) ...[
                  _CustomerLedgerStatement(ledger: ledger),
                  Row(children: [Expanded(child: Text('Available credit ${_purchaseAmount(_availableCustomerCredit(ledger))}')),
                    TextButton(onPressed: widget.onNewSale == null
                        ? null : () => Navigator.pop(sheetContext, ledger), child: const Text('Start sale'))]),
                  const Divider(height: 1),
                ],
              ])),
            ])))); });
    // Dispose after the route's exit animation no longer uses its TextField.
    await creditRoute?.completed;
    search.dispose();
    if (!mounted || selected == null) return false;
    if (session.activeWorkspace?.id != store ||
        session.workspaceFinance?.accountScope != finance.accountScope) {
      session.showNotice('Store or account changed. Open Customer credit again.');
      return false;
    }
    if (!identical(session.workspaceFinance, finance) || session.workspaceFinanceStale) {
      return _retryCustomerCredit('Customer credit changed while you were choosing. Reload the latest balances and select the customer again. No sale has been started.');
    }
    await _startCustomerSale(account: finance.accountScope, store: finance.workspaceId,
      customerId: selected.customerId, customerName: selected.customerName);
    return false;
  }

  String _book = 'Sales';
  String _invoicePeriod = 'Today';
  DateTimeRange? _invoiceRange;
  final _invoiceSearch = TextEditingController();
  Object? _salesScope;
  bool _salesActionsExpanded = true;
  bool _returnSelection = false;
  bool _exchangeSelection = false;
  String _salesQueryBeforeReturns = '';
  bool _salesActionsBeforeReturns = false;
  void _toggleReturnSelection({bool exchange = false}) {
    FocusScope.of(context).unfocus();
    setState(() {
      if (_returnSelection) {
        _invoiceSearch.text = _salesQueryBeforeReturns;
        _salesActionsExpanded = _salesActionsBeforeReturns;
      } else {
        _salesQueryBeforeReturns = _invoiceSearch.text;
        _salesActionsBeforeReturns = _salesActionsExpanded;
        _salesActionsExpanded = false;
        _invoiceSearch.clear();
      }
      _returnSelection = !_returnSelection;
      _exchangeSelection = _returnSelection && exchange;
    });
  }
  String get _salesPeriodLabel => _invoicePeriod == 'Custom range' && _invoiceRange != null
      ? '${_registerDate(_invoiceRange!.start)} – ${_registerDate(_invoiceRange!.end)}'
      : _invoicePeriod;

  void _changeSalesBrowse(VoidCallback change) {
    setState(change);
    if (_returnSelection) return;
    PageStorage.maybeOf(context)?.writeState(context,
      (query: _invoiceSearch.text, period: _invoicePeriod, range: _invoiceRange, expanded: _salesActionsExpanded),
      identifier: ('sales-browse', _salesScope));
  }

  @override
  void dispose() {
    _invoiceSearch.dispose();
    super.dispose();
  }
  WorkspaceCustomerInvoice? _selectedInvoice;
  String? _invoiceStoreScope;
  String? _invoiceAccountScope;
  bool closeSelectedInvoice() {
    if (_selectedInvoice == null && _returnSelection) {
      _toggleReturnSelection();
      return true;
    }
    if (_selectedInvoice == null) return false;
    setState(() => _selectedInvoice = null);
    return true;
  }

  Future<void> _openSalesStatement() async {
    final session = widget.session;
    final scope = session.workspaceStockHistoryScope();
    if (scope == null || !session.workspaceInvoiceHistoryLoaded) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Sales records are not ready. Please retry after loading.')));
      return;
    }
    final now = DateTime.now(), today = DateUtils.dateOnly(DateTime.now());
    final from = switch (_invoicePeriod) {
      'Week' => DateTime(today.year, today.month, today.day - 6),
      'Month' => DateTime(today.year, today.month),
      'Year' => DateTime(today.year),
      'Custom range' => _invoiceRange?.start ?? today,
      _ => today,
    };
    final last = _invoicePeriod == 'Custom range' ? _invoiceRange?.end ?? today : today;
    try {
      final statement = StoreSalesStatement(accountId: scope.accountScope, storeId: scope.workspaceId,
        reviewOnly: const bool.fromEnvironment('MOOLSOCIAL_UI_REVIEW_ONLY'),
        storeName: session.activeWorkspace!.name, from: from,
        until: DateTime(last.year, last.month, last.day + 1), generatedAt: now,
        invoices: session.workspaceInvoices,
        finance: !session.workspaceFinanceStale && !session.workspaceFinanceUsesLegacyReview ? session.workspaceFinance : null);
      if (!mounted) return;
      await showModalBottomSheet<void>(context: context, isScrollControlled: true, useSafeArea: true,
        showDragHandle: false,
        builder: (sheetContext) => SizedBox(height: MediaQuery.sizeOf(sheetContext).height *
            (MediaQuery.orientationOf(sheetContext) == Orientation.landscape ? 1 : .78),
          child: StoreSalesStatementPanel(statement: statement,
            onClose: () => Navigator.pop(sheetContext),
            changes: session, isCurrent: () => mounted && session.workspaceStockHistoryScope()?.key == scope.key)));
    } on FormatException catch (e) {
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(e.message)));
    }
  }

  Widget _compactInvoices(WorkSession session, {Widget? salesPeriodControl, Widget? inlineSearch}) {
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    final start = !widget.salesOnly
        ? session.workspaceMoneyPeriodStart
        : switch (_invoicePeriod) {
            'Week' => today.subtract(const Duration(days: 6)),
            'Month' => DateTime(now.year, now.month),
            'Year' => DateTime(now.year),
            'Custom range' => _invoiceRange?.start ?? today,
            _ => today,
          };
    final end = _invoicePeriod == 'Custom range' && _invoiceRange != null
        ? DateTime(
            _invoiceRange!.end.year,
            _invoiceRange!.end.month,
            _invoiceRange!.end.day + 1,
          )
        : DateTime(now.year, now.month, now.day + 1);
    final invoices =
        session.workspaceInvoices
            .where(
              (invoice) =>
                  (_returnSelection || start == null || !invoice.issuedAt.isBefore(start)) &&
                  (_returnSelection || invoice.issuedAt.isBefore(end)),
            )
            .toList()
          ..sort((a, b) {
            final date = widget.salesOnly
                ? b.issuedAt.compareTo(a.issuedAt)
                : a.issuedAt.compareTo(b.issuedAt);
            return date == 0 ? a.id.compareTo(b.id) : date;
          });
    final totalMinor = invoices.fold<int>(
      0,
      (sum, invoice) => sum + invoice.payableMinor,
    );
    if (widget.salesOnly) {
      final finance = session.workspaceFinance;
      final financeReady = finance != null && finance.valid && finance.historyComplete &&
          finance.workspaceId == session.activeWorkspace?.id &&
          !session.workspaceFinanceStale && !session.workspaceFinanceUsesLegacyReview &&
          !finance.asOf.isAfter(now);
      final payments = <(String, String?), List<WorkspacePaymentRecord>>{};
      if (financeReady) {
        for (final payment in finance.payments) {
          payments.putIfAbsent((payment.orderId, payment.invoiceId), () => []).add(payment);
        }
      }
      final query = _invoiceSearch.text.trim().toLowerCase();
      final matches = invoices.where((invoice) =>
        '${invoice.id} ${invoice.orderId} ${invoice.customer} ${invoice.billingDetails.name} ${invoice.billingDetails.businessName}'.toLowerCase().contains(query)).toList();
      return LayoutBuilder(builder: (context, viewport) => Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        if (_returnSelection)
          ConstrainedBox(constraints: BoxConstraints(maxHeight: viewport.maxHeight * .45), child: SingleChildScrollView(child: Padding(padding: const EdgeInsets.symmetric(horizontal: 12),
            child: Row(children: [
              Expanded(child: Text(_exchangeSelection ? 'Exchange' : 'Returns & refunds · All saved sales',
                style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w600))),
              if (_exchangeSelection) IconButton(tooltip: 'How exchange works',
                onPressed: () => _exchangeSteps(), icon: const Icon(Icons.info_outline, size: 18)),
              IconButton(tooltip: 'Back to sales register', onPressed: _toggleReturnSelection,
                icon: const Icon(Icons.close_rounded, size: 18)),
            ])))),
        if (!_returnSelection)
        ConstrainedBox(constraints: BoxConstraints(maxHeight: viewport.maxHeight * .45), child: SingleChildScrollView(child: Padding(
          key: const Key('work-sales-period-summary'),
          padding: const EdgeInsets.symmetric(horizontal: 12),
          child: Row(children: [
            if (inlineSearch != null) Expanded(flex: 2, child: inlineSearch),
            Expanded(flex: 5, child: Column(mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            Wrap(alignment: WrapAlignment.spaceBetween, crossAxisAlignment: WrapCrossAlignment.center,
              spacing: 4, runSpacing: 0, children: [
                ?salesPeriodControl,
                Semantics(label: 'Billed sales for $_salesPeriodLabel', child: Column(
                  crossAxisAlignment: CrossAxisAlignment.end, mainAxisSize: MainAxisSize.min, children: [
                    const Text('Billed', style: TextStyle(fontSize: 11, color: MoolColors.muted)),
                    Text('₹${_formatStoreMinorAmount(totalMinor)}', key: const Key('work-sales-period-total'),
                      style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w700, color: MoolColors.ink,
                        fontFeatures: [FontFeature.tabularFigures()])),
                  ])),
                TextButton.icon(key: const Key('work-sales-statement'), onPressed: () {
                    FocusScope.of(context).unfocus();
                    _openSalesStatement();
                  },
                  style: TextButton.styleFrom(padding: const EdgeInsets.symmetric(horizontal: 4),
                    minimumSize: const Size(48, 48), foregroundColor: MoolColors.navy),
                  icon: const Icon(Icons.description_outlined, size: 16),
                  label: const Text('Sales statement', style: TextStyle(fontSize: 12))),
              ]),
            if (_invoicePeriod == 'Custom range')
              Padding(padding: const EdgeInsets.only(bottom: 4),
                child: Text(_salesPeriodLabel, style: const TextStyle(fontSize: 11, color: MoolColors.muted))),
          ])),
          ]),
        ))),
        Expanded(child: ListView.separated(
          key: PageStorageKey(('sales-invoices', _salesScope, _returnSelection, _invoicePeriod, _invoiceRange, query)),
          keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
          padding: const EdgeInsets.only(bottom: 12),
          itemCount: matches.isEmpty ? 1 : matches.length,
          separatorBuilder: (_, _) => const Divider(height: 1, thickness: .5),
          itemBuilder: (context, index) {
            if (matches.isEmpty) { return Padding(padding: const EdgeInsets.all(16),
              child: Text(_returnSelection
                ? (query.isEmpty ? 'No saved invoices available. A return needs the original sale.' : 'No matching sale. Check the invoice number, customer name or phone.')
                : query.isEmpty ? 'No recorded invoices in this period.' : 'No matching invoices in this period. Clear search or change the period.',
                style: const TextStyle(fontSize: 13, color: MoolColors.muted))); }
            final invoice = matches[index];
            final candidates = payments[(invoice.orderId, invoice.id)] ?? const <WorkspacePaymentRecord>[];
            final payment = candidates.length == 1 ? candidates.single : null;
            final status = payment == null ? 'Payment status unavailable'
                : '${payment.state.label}${payment.dueMinor > 0 ? ' · Due ₹${_formatStoreMinorAmount(payment.dueMinor)}' : ''}';
            final details = Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text(_RecentCounterCustomer(invoice.customer, invoice.billingDetails).label,
                style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600, color: MoolColors.ink)),
              Text(_registerDate(invoice.issuedAt),
                style: const TextStyle(fontSize: 11, color: MoolColors.muted)),
            ]);
            final amount = Text('₹${_formatStoreMinorAmount(invoice.payableMinor)}', textAlign: TextAlign.right,
              style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600, color: MoolColors.ink,
                fontFeatures: [FontFeature.tabularFigures()]));
            return InkWell(
              key: ValueKey('work-sales-invoice-${invoice.id}'),
              onTap: () { FocusScope.of(context).unfocus();
                if (_returnSelection && payment != null) {
                  if (_exchangeSelection) { _openExchange(invoice, payment); return; }
                  _StoreInvoiceSurfaceState.openAdjustments(context, session, invoice, payment,
                    finance?.accountScope, session.activeWorkspace?.id);
                  return;
                }
                if (_returnSelection) {
                  ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:
                    Text('Payment records unavailable. Open the original invoice and recover its records before recording a return.')));
                }
                setState(() {
                _selectedInvoice = invoice;
                _invoiceStoreScope = session.activeWorkspace?.id;
                _invoiceAccountScope = session.workspaceFinance?.accountScope;
              }); },
              child: Padding(padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
                child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                LayoutBuilder(builder: (context, box) =>
                  MediaQuery.textScalerOf(context).scale(13) > 19.5 || box.maxWidth < 300
                  ? Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [details, const SizedBox(height: 4), amount])
                  : Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                      Expanded(flex: 3, child: details), const SizedBox(width: 12), Expanded(flex: 2, child: amount),
                    ])),
                Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Expanded(child: Text(invoice.id, style: const TextStyle(fontSize: 11, color: MoolColors.muted))),
                  const Icon(Icons.chevron_right_rounded, size: 18, color: MoolColors.navy),
                ]),
                Text(status, key: ValueKey('work-sales-status-${invoice.id}'),
                  style: TextStyle(fontSize: 11, color: payment != null && payment.dueMinor > 0 ? MoolColors.navy : MoolColors.muted)),
              ])),
            );
          },
        )),
      ]));
    }
    final register = _StoreVoucherRegister(
      identity: (
        'sales',
        session.workspaceStockHistoryScope()?.key,
        widget.salesOnly ? _invoicePeriod : session.workspaceMoneyPeriod,
      ),
      headers: const [
        'Date',
        'Particulars',
        'Voucher Type',
        'Voucher No.',
        'Amount (₹)',
      ],
      rows: [
        for (final invoice in invoices)
          [
            _registerDate(invoice.issuedAt),
            invoice.customer,
            'Sales',
            invoice.id,
            _formatStoreMinorAmount(invoice.payableMinor),
          ],
      ],
      rowKeys: [
        for (final invoice in invoices)
          ValueKey('work-sales-invoice-${invoice.id}'),
      ],
      amountColumns: const {4},
      total: _formatStoreMinorAmount(totalMinor),
      notice: 'Recorded invoices only · not a customer balance statement',
      empty: 'No recorded invoices in this period.',
      onOpen: (index) => setState(() {
        _selectedInvoice = invoices[index];
        _invoiceStoreScope = session.activeWorkspace?.id;
        _invoiceAccountScope = session.workspaceFinance?.accountScope;
      }),
    );
    return register;
  }

  @override
  Widget build(BuildContext context) {
    final session = widget.session;
    final salesScope = session.workspaceStockHistoryScope()?.key ?? session.activeWorkspace?.id;
    if (_salesScope != salesScope) {
      _salesScope = salesScope;
      _invoiceSearch.clear();
      _returnSelection = false;
      _exchangeSelection = false;
      _salesQueryBeforeReturns = '';
      _salesActionsExpanded = true;
      _invoicePeriod = 'Today';
      _invoiceRange = null;
      final saved = PageStorage.maybeOf(context)?.readState(context, identifier: ('sales-browse', _salesScope));
      if (saved is ({String query, String period, DateTimeRange? range, bool expanded})) {
        _invoiceSearch.text = saved.query;
        _invoicePeriod = saved.period;
        _invoiceRange = saved.range;
        _salesActionsExpanded = saved.expanded;
      }
    }
    if (_selectedInvoice != null) {
      if (session.activeWorkspace?.id != _invoiceStoreScope ||
          session.workspaceFinance?.accountScope != _invoiceAccountScope) {
        _selectedInvoice = null;
      } else {
        return _StoreInvoiceSurface(
          key: ValueKey(_selectedInvoice!.id),
          session: session,
          invoice: _selectedInvoice!,
          embedded: true,
          onClose: () => setState(() => _selectedInvoice = null),
        );
      }
    }
    final largeText = MediaQuery.textScalerOf(context).scale(14) > 21;
    final titleText = Text(
      widget.salesOnly || _book == 'Sales'
          ? 'Sales Register'
          : _book == 'Purchases'
          ? 'Purchase records'
          : _book == 'Expenses'
          ? 'Expense Register'
          : 'Cash / Bank Book',
      style: TextStyle(
        fontSize: 16,
        fontWeight: FontWeight.w800,
        color: MoolColors.navy,
      ),
    );
    final title = titleText;
    final periodControl = PopupMenuButton<String>(
      key: const Key('work-statement-period'),
      tooltip: widget.salesOnly ? 'Sales period · $_salesPeriodLabel' : 'Statement period',
      onSelected: (period) async {
        if (widget.salesOnly) {
          if (period == 'Custom range') {
            final range = await showDateRangePicker(
              context: context,
              firstDate: DateTime(2000),
              lastDate: DateTime.now(),
              initialDateRange: _invoiceRange,
              calendarDelegate: const _StoreDayFirstCalendarDelegate(),
              errorFormatText: 'Use DD/MM/YYYY',
              helpText: MediaQuery.orientationOf(context) == Orientation.landscape &&
                      MediaQuery.textScalerOf(context).scale(1) > 1.3
                  ? 'DD/MM/YYYY'
                  : 'Dates · DD/MM/YYYY',
              fieldStartLabelText: 'From',
              fieldEndLabelText: 'To',
              fieldStartHintText: '',
              fieldEndHintText: '',
              builder: (pickerContext, picker) {
                if (MediaQuery.orientationOf(pickerContext) != Orientation.landscape ||
                    MediaQuery.textScalerOf(pickerContext).scale(1) <= 1.3) {
                  return picker!;
                }
                final theme = Theme.of(pickerContext);
                return Theme(
                  data: theme.copyWith(
                    textTheme: theme.textTheme.copyWith(
                      headlineSmall: theme.textTheme.headlineSmall?.copyWith(fontSize: 14)),
                    datePickerTheme: theme.datePickerTheme.copyWith(
                    headerHelpStyle: (theme.datePickerTheme.headerHelpStyle ??
                        theme.textTheme.labelLarge)?.copyWith(fontSize: 11),
                  )),
                  child: picker!,
                );
              },
            );
            if (!mounted || range == null) return;
            _changeSalesBrowse(() {
              _invoicePeriod = period;
              _invoiceRange = range;
            });
          } else {
            _changeSalesBrowse(() => _invoicePeriod = period);
          }
          return;
        }
        if (_book == 'Purchases') {
          session.clearWorkspacePurchaseSelection();
        }
        session.setWorkspaceMoneyPeriod(period);
      },
      itemBuilder: (_) => [
        for (final period
            in widget.salesOnly
                ? ['Today', 'Week', 'Month', 'Year', 'Custom range']
                : ['Today', 'Week', 'Month', 'Financial year'])
          PopupMenuItem(value: period, child: Text(period)),
      ],
      child: Padding(
        padding: widget.salesOnly
            ? const EdgeInsets.symmetric(horizontal: 4, vertical: 14)
            : const EdgeInsets.all(12),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              widget.salesOnly
                  ? (_invoicePeriod == 'Custom range' ? 'Dates' : _invoicePeriod)
                  : session.workspaceMoneyPeriod,
              style: const TextStyle(
                color: MoolColors.navy,
                fontWeight: FontWeight.w700,
              ),
            ),
            const Icon(Icons.expand_more_rounded, size: 18),
          ],
        ),
      ),
    );
    if (widget.salesOnly) {
      final hasDraft = session.workspaceOrderSource == 'Counter' &&
          session.workspaceOrderFulfilment == 'At the shop' && session.currentWorkspaceOrderId == null &&
          (session.workspaceOrderCustomer.trim().isNotEmpty || session.workspaceOrderQuantities.isNotEmpty);
      final landscapeBand = !_returnSelection &&
          MediaQuery.sizeOf(context).width >= 700 &&
          MediaQuery.sizeOf(context).height <= 450 &&
          MediaQuery.textScalerOf(context).scale(1) <= 1.3;
      final searchControl = StoreRecentSearches(
            controller: _invoiceSearch,
            history: session.workspaceRecentSearches(_exchangeSelection ? 'sales-exchange' : _returnSelection ? 'sales-returns' : 'sales'),
            isCurrent: () => _salesScope == (session.workspaceStockHistoryScope()?.key ?? session.activeWorkspace?.id),
            onChanged: (_) => _changeSalesBrowse(() {}),
            child: Row(children: [
              Expanded(child: TextField(
                key: const Key('work-sales-search'), controller: _invoiceSearch,
                textInputAction: TextInputAction.search,
                onChanged: (_) => _changeSalesBrowse(() {}),
                onSubmitted: (_) => FocusScope.of(context).unfocus(),
                style: const TextStyle(fontSize: 13, color: MoolColors.ink),
                decoration: InputDecoration(
                  hintText: _returnSelection ? 'Search phone, name or invoice'
                      : landscapeBand ? 'Search sales' : 'Search invoices or customers',
                  hintMaxLines: _returnSelection ? 3 : 1, filled: false, isDense: true,
                  border: InputBorder.none, enabledBorder: InputBorder.none, focusedBorder: InputBorder.none,
                  disabledBorder: InputBorder.none, errorBorder: InputBorder.none, focusedErrorBorder: InputBorder.none,
                  contentPadding: EdgeInsets.symmetric(vertical: _returnSelection ? 6 : 12),
                  fillColor: Colors.transparent, focusColor: Colors.transparent, hoverColor: Colors.transparent,
                  prefixIcon: const Icon(Icons.search_rounded, size: 21, color: MoolColors.navy),
                  suffixIcon: _invoiceSearch.text.isEmpty ? null : IconButton(
                    tooltip: 'Clear invoice search', onPressed: () => _changeSalesBrowse(_invoiceSearch.clear),
                    icon: const Icon(Icons.close_rounded, size: 18)),
                ),
              )),
            ]),
          );
      final salesFrame = _StockQuickActionsFrame(
        keyPrefix: 'work-sales',
        expanded: _salesActionsExpanded,
        onToggle: () { FocusScope.of(context).unfocus(); _changeSalesBrowse(() => _salesActionsExpanded = !_salesActionsExpanded); },
        actions: [
          if (widget.showNewSaleAction)
            _StoreEdgeAction(keyName: 'work-sales-new-counter-sale', icon: hasDraft ? Icons.edit_note_rounded : Icons.add_rounded,
              label: hasDraft ? 'Resume sale' : 'Counter sale', onTap: widget.onNewSale),
          _StoreEdgeAction(keyName: 'work-sales-exchange', icon: Icons.swap_horiz_rounded,
            label: 'Exchange', onTap: () => _toggleReturnSelection(exchange: true)),
          _StoreEdgeAction(keyName: 'work-sales-customer-credit', icon: Icons.account_balance_wallet_outlined,
            label: 'Customer credit', onTap: _openCustomerCredit),
          _StoreEdgeAction(keyName: 'work-sales-returns', icon: Icons.assignment_return_outlined,
            label: 'Returns & refunds', onTap: _returnSelection ? null : _toggleReturnSelection),
          if (widget.onOpenOperation != null) ...[
            _StoreEdgeAction(keyName: 'work-sales-dues', icon: Icons.account_balance_wallet_outlined,
              label: 'Collect dues', onTap: () => widget.onOpenOperation!(_WorkspaceOperation.dues)),
          ],
        ],
        child: ColoredBox(color: Colors.white, child: Column(key: const Key('work-store-statement'), children: [
          if (!landscapeBand) searchControl,
          Expanded(child: _compactInvoices(session, salesPeriodControl: periodControl,
            inlineSearch: landscapeBand ? searchControl : null)),
        ])),
      );
      return _returnSelection ? salesFrame.child : salesFrame;
    }
    final content = Column(
      key: const Key('work-store-statement'),
      children: [
        if (_book != 'Purchases' || session.focusedWorkspacePurchaseId == null)
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 12, 12, 4),
            child: largeText
                ? Align(
                    alignment: Alignment.centerLeft,
                    child: Wrap(
                      spacing: 8,
                      crossAxisAlignment: WrapCrossAlignment.center,
                      children: [
                        title,
                        periodControl,
                      ],
                    ),
                  )
                : _StoreScaledPair(
                    flexibleSecond: false,
                    first: title,
                    second: periodControl,
                  ),
          ),
        if (!widget.salesOnly)
          SafeArea(
            top: false,
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 0),
              child: LayoutBuilder(
                builder: (context, constraints) => SingleChildScrollView(
                  scrollDirection: Axis.horizontal,
                  child: ConstrainedBox(
                    constraints: BoxConstraints(minWidth: constraints.maxWidth),
                    child: Row(
                      mainAxisAlignment: MainAxisAlignment.spaceEvenly,
                      children: [
                        for (final book in [
                          'Sales',
                          'Purchases',
                          'Expenses',
                          'Money',
                        ])
                          TextButton(
                            key: Key('work-statement-${book.toLowerCase()}'),
                            onPressed: _book == book
                                ? null
                                : () {
                                    session.clearWorkspacePurchaseSelection();
                                    setState(() => _book = book);
                                  },
                            style: TextButton.styleFrom(
                              backgroundColor: _book == book
                                  ? const Color(0xFFECEFFF)
                                  : null,
                              disabledForegroundColor: MoolColors.navy,
                              minimumSize: const Size(48, 48),
                            ),
                            child: Text(
                              book,
                              style: const TextStyle(fontSize: 12),
                            ),
                          ),
                      ],
                    ),
                  ),
                ),
              ),
            ),
          ),
        Expanded(
          child: KeyedSubtree(
            // Keep each ledger's place without sharing offsets across Stores,
            // accounts, periods or the review/confirmed data boundary.
            key: PageStorageKey((
              'store-statement',
              session.workspaceStockHistoryScope()?.key ??
                  (session, session.activeWorkspace?.id),
              session.workspaceMoneyPeriod,
              _book,
              session.workspaceFinanceUsesLegacyReview,
            )),
            child:
                _book == 'Sales'
                ? _compactInvoices(session)
                : _book == 'Purchases'
                ? _StorePurchasesSurface(session: session, statement: true)
                : _book == 'Money'
                ? _StoreExpensesSurface(
                    key: ValueKey((
                      session.workspaceStockHistoryScope()?.key,
                      'money',
                    )),
                    session: session,
                    statement: true,
                  )
                : !widget.salesOnly && _book == 'Expenses'
                ? _StoreExpensesSurface(session: session, register: true)
                : !session.workspaceFinanceUsesLegacyReview
                ? _StoreFinanceSurface(
                    session: session,
                    section: _book == 'Sales' ? 'payments' : 'expenses',
                    onOpenInvoice: (invoice) => setState(() {
                      _selectedInvoice = invoice;
                      _invoiceStoreScope = session.activeWorkspace?.id;
                      _invoiceAccountScope =
                          session.workspaceFinance?.accountScope;
                    }),
                  )
                : _StoreExpensesSurface(session: session),
          ),
        ),
      ],
    );
    return LayoutBuilder(
      builder: (context, constraints) {
        final minimumHeight = largeText ? 480.0 : 240.0;
        if (constraints.maxHeight >= minimumHeight) {
          return content;
        }
        return SingleChildScrollView(
          child: SizedBox(height: minimumHeight, child: content),
        );
      },
    );
  }
}

String _registerDate(DateTime value) {
  final date = value.toLocal();
  return '${date.day.toString().padLeft(2, '0')}/${date.month.toString().padLeft(2, '0')}/${date.year}';
}

// Register totals are sums of recorded vouchers, never inferred ledger balances.
class _StoreVoucherRegister extends StatefulWidget {
  const _StoreVoucherRegister({
    required this.identity,
    required this.headers,
    required this.rows,
    required this.total,
    required this.notice,
    required this.empty,
    this.rowKeys = const [],
    this.amountColumns = const {},
    this.onOpen,
    this.footer,
  });
  final Object identity;
  final List<String> headers;
  final List<List<String>> rows;
  final List<Key> rowKeys;
  final String total, notice, empty;
  final Set<int> amountColumns;
  final ValueChanged<int>? onOpen;
  final List<String>? footer;
  @override
  State<_StoreVoucherRegister> createState() => _StoreVoucherRegisterState();
}

class _StoreVoucherRegisterState extends State<_StoreVoucherRegister> {
  final horizontal = ScrollController();
  @override
  void dispose() {
    horizontal.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final scale = MediaQuery.textScalerOf(context).scale(12) / 12;
    final widths = [
      for (var i = 0; i < widget.headers.length; i++)
        (i == 0
                ? 100.0
                : i == 1
                ? 180.0
                : 150.0) *
            scale,
    ];
    Widget row(List<String> cells, {bool heading = false, Key? entryKey}) =>
        Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            for (var i = 0; i < cells.length; i++)
              SizedBox(
                key: i == 0 ? entryKey : null,
                width: widths[i],
                child: Padding(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 8,
                    vertical: 10,
                  ),
                  child: Text(
                    cells[i],
                    textAlign: widget.amountColumns.contains(i)
                        ? TextAlign.right
                        : TextAlign.left,
                    style: TextStyle(
                      fontSize: 12,
                      color: MoolColors.navy,
                      fontWeight: heading ? FontWeight.w700 : FontWeight.w400,
                    ),
                  ),
                ),
              ),
          ],
        );
    return Column(
      key: const Key('work-voucher-register'),
      children: [
        Expanded(
          child: Scrollbar(
            controller: horizontal,
            thumbVisibility: true,
            child: SingleChildScrollView(
              controller: horizontal,
              scrollDirection: Axis.horizontal,
              child: SizedBox(
                width: widths.fold<double>(0, (a, b) => a + b),
                child: ListView.builder(
                  key: PageStorageKey(('voucher-register', widget.identity)),
                  itemCount: widget.rows.length + 2,
                  itemBuilder: (_, position) {
                    if (position == 0) {
                      return ColoredBox(
                        color: const Color(0xFFF0F3FF),
                        child: row(widget.headers, heading: true),
                      );
                    }
                    if (position == widget.rows.length + 1) {
                      return Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          if (widget.rows.isEmpty)
                            Padding(
                              padding: const EdgeInsets.all(16),
                              child: Text(widget.empty),
                            ),
                          const Divider(height: 1),
                          row(
                            widget.footer ??
                                [
                                  for (
                                    var i = 0;
                                    i < widget.headers.length;
                                    i++
                                  )
                                    i == 1
                                        ? 'Recorded total'
                                        : i == widget.headers.length - 1
                                        ? widget.total
                                        : '',
                                ],
                            heading: true,
                          ),
                        ],
                      );
                    }
                    final index = position - 1;
                    return Material(
                      color: index.isEven
                          ? Colors.white
                          : const Color(0xFFF8F9FC),
                      child: InkWell(
                        onTap: widget.onOpen == null
                            ? null
                            : () => widget.onOpen!(index),
                        child: ConstrainedBox(
                          constraints: const BoxConstraints(minHeight: 48),
                          child: Tooltip(
                            message: widget.notice,
                            child: row(
                              widget.rows[index],
                              entryKey: index < widget.rowKeys.length
                                  ? widget.rowKeys[index]
                                  : null,
                            ),
                          ),
                        ),
                      ),
                    );
                  },
                ),
              ),
            ),
          ),
        ),
      ],
    );
  }
}

