class _OperationActionCard extends StatelessWidget {
  const _OperationActionCard({
    required this.icon,
    required this.title,
    required this.detail,
    this.keyName,
    this.actionLabel,
    this.onPressed,
  });

  final String? keyName;
  final IconData icon;
  final String title;
  final String detail;
  final String? actionLabel;
  final VoidCallback? onPressed;

  @override
  Widget build(BuildContext context) {
    return WorkCard(
      keyName: keyName,
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          CircleAvatar(
            backgroundColor: const Color(0xFFEAF2FF),
            foregroundColor: MoolColors.navy,
            child: Icon(icon),
          ),
          const SizedBox(width: MoolSpacing.sm),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  title,
                  style: const TextStyle(
                    color: MoolColors.ink,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                const SizedBox(height: 3),
                Text(
                  detail,
                  style: const TextStyle(
                    color: MoolColors.muted,
                    fontSize: 10.5,
                    height: 1.3,
                  ),
                ),
                if (actionLabel != null && onPressed != null) ...[
                  const SizedBox(height: MoolSpacing.xs),
                  FilledButton.tonalIcon(
                    onPressed: onPressed,
                    icon: const Icon(Icons.arrow_forward_rounded, size: 17),
                    label: Text(actionLabel!),
                  ),
                ],
              ],
            ),
          ),
        ],
      ),
    );
  }
}

class _WorkspaceCatalogueSurface extends StatefulWidget {
  const _WorkspaceCatalogueSurface({
    required this.session,
    this.entryOnly = false,
    this.actionsExpanded,
    this.onToggleActions,
    this.onBuyStock,
    this.onPurchases,
    this.onGroupBuying,
    this.onStatement,
    super.key,
  });

  final WorkSession session;
  final bool entryOnly;
  final bool? actionsExpanded;
  final VoidCallback? onToggleActions;
  final VoidCallback? onBuyStock, onPurchases, onGroupBuying, onStatement;

  @override
  State<_WorkspaceCatalogueSurface> createState() =>
      _WorkspaceCatalogueSurfaceState();
}

class _WorkspaceCatalogueSurfaceState
    extends State<_WorkspaceCatalogueSurface> {
  final _stockActionKeys = <String, GlobalKey>{};
  final Set<Object> _localCollapsedActions = {};
  Object get _actionScope =>
      widget.session.workspaceStockHistoryScope()?.key ??
      widget.session.activeWorkspace?.id ??
      widget.session.workspaceId ??
      widget.session;
  bool get _actionsExpanded =>
      widget.actionsExpanded ?? !_localCollapsedActions.contains(_actionScope);
  void _toggleActions() {
    unawaited(HapticFeedback.selectionClick());
    if (widget.onToggleActions case final toggle?) {
      toggle();
    } else {
      setState(() {
        if (!_localCollapsedActions.remove(_actionScope)) {
          _localCollapsedActions.add(_actionScope);
        }
      });
    }
  }

  bool _retryingInventory = false;

  Future<void> _retryInventory() async {
    if (_retryingInventory) return;
    setState(() => _retryingInventory = true);
    try {
      if (await widget.session.loadWorkspaceInventory(retry: true)) {
        await widget.session.retryWorkspaceInventorySave();
      }
    } finally {
      if (mounted) setState(() => _retryingInventory = false);
    }
  }

  late final Widget _entryPage = _addProductEntry();

  void _restoreStockAction(String productId) {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      final target = _stockActionKeys[productId]?.currentContext;
      if (target != null) {
        unawaited(Scrollable.ensureVisible(target, alignment: .5));
      }
    });
  }

  WorkspaceCatalogueItem _blankProduct({String barcode = ''}) {
    final stamp = DateTime.now().microsecondsSinceEpoch;
    return WorkspaceCatalogueItem(
      id: 'custom-$stamp',
      canonicalId: 'custom-$stamp',
      categoryId: 'other',
      brand: '',
      title: '',
      variant: '',
      pack: '',
      sku: 'SKU-$stamp',
      barcode: barcode,
      purchasePrice: 0,
      sellingPrice: 0,
      unitPrice: '',
      stock: 0,
      deliveryPromise: 'Store pickup or local delivery',
      origin: '',
      visualLabel: 'Product image pending',
      visualKind: 'catalogue-packshot',
      available: false,
      publicListing:
          widget.session.workspaceProductDefaults.customerListingRequested,
      stockMode: widget.session.workspaceProductDefaults.stockMode,
      lowStockThreshold:
          widget.session.workspaceProductDefaults.lowStockThreshold,
    );
  }

  Widget _addProductEntry() {
    final storeId =
        widget.session.activeWorkspace?.id ?? widget.session.workspaceId;
    var tab = 0;
    var manualProduct = _blankProduct();
    WorkspaceCatalogueItem? catalogueProduct;
    var manualEditorKey = GlobalKey<_CatalogueProductEditorState>();
    var catalogueEditorKey = GlobalKey<_CatalogueProductEditorState>();
    bool storeUnchanged() {
      if (!mounted) return false;
      if ((widget.session.activeWorkspace?.id ?? widget.session.workspaceId) !=
          storeId) {
        widget.session.showError('Your store changed. Open Add product again.');
        return false;
      }
      return true;
    }

    return StatefulBuilder(
      builder: (pageContext, setPageState) => StoreAddProductEntryScreen(
        selectedIndex: tab,
        catalogueEditing: catalogueProduct != null,
        onCloseCatalogueEditor: () =>
            catalogueEditorKey.currentState?._requestEditorExit(),
        onSelected: (index) {
          if (!storeUnchanged() || index == tab) return;
          final editor = tab == 1 ? manualEditorKey.currentState
              : tab == 0 ? catalogueEditorKey.currentState : null;
          void changeMode() {
            if (!pageContext.mounted || !storeUnchanged()) return;
            setPageState(() {
              if (tab == 1) {
                manualProduct = _blankProduct();
                manualEditorKey = GlobalKey<_CatalogueProductEditorState>();
              } else if (tab == 0) {
                catalogueProduct = null;
                catalogueEditorKey = GlobalKey<_CatalogueProductEditorState>();
              }
              tab = index;
            });
          }
          if (editor == null) {
            changeMode();
          } else {
            unawaited(editor._requestEditorExit(afterExit: changeMode));
          }
        },
        catalogue: IndexedStack(
          index: catalogueProduct == null ? 0 : 1,
          children: [
            StoreAddProductSheet(
              embedded: true,
              catalogue: widget.session.referenceCatalogue,
              isStoreCurrent: storeUnchanged,
              savedCatalogueKeys: widget.session.workspaceCatalogueShortlist,
              recentSearches: widget.session.workspaceCatalogueSearchHistory,
              onBrowseChanged: () {
                if (storeUnchanged()) {
                  widget.session.notifyWorkspaceCatalogueBrowsingChanged();
                }
              },
              ownedProducts: List.of(widget.session.workspaceCatalogueItems),
              createProduct: (barcode) => _blankProduct(barcode: barcode),
              scanBarcode: () => showStoreProductScanner(pageContext),
              onAdd: (product) {
                if (!storeUnchanged()) return;
                if (catalogueProduct != null) return;
                final existing = widget.session.workspaceCatalogueItems;
                if (existing.any(
                  (item) =>
                      item.id == product.id ||
                      (item.canonicalId == product.canonicalId &&
                          item.pack == product.pack &&
                          item.variant == product.variant &&
                          item.barcode == product.barcode),
                )) {
                  setPageState(() {});
                  return;
                }
                if (existing.any((item) => item.sku == product.sku)) {
                  widget.session.showError(
                    'This SKU is already in your store. Edit the existing product.',
                  );
                  return;
                }
                setPageState(() {
                  catalogueProduct = product.copyWith(
                    stockMode:
                        widget.session.workspaceProductDefaults.stockMode,
                    lowStockThreshold: widget
                        .session
                        .workspaceProductDefaults
                        .lowStockThreshold,
                    purchasePrice: 0,
                    sellingPrice: 0,
                    unitPrice: '',
                    stock: 0,
                    available: false,
                    publicListing: widget
                        .session
                        .workspaceProductDefaults
                        .customerListingRequested,
                    compliance: product.compliance == null
                        ? null
                        : WorkspaceProductCompliance.fromJson({
                            ...product.compliance!.toJson(),
                            'manufacturedOrPackedOn': null,
                            'bestBeforeOrUseBy': null,
                          }),
                  );
                });
              },
              onSelected: (product) {
                if (storeUnchanged()) {
                  setPageState(() => catalogueProduct = product);
                }
              },
            ),
            if (catalogueProduct != null)
              _CatalogueProductEditor(
                key: catalogueEditorKey,
                session: widget.session,
                product: catalogueProduct!,
                stockEntryMethod: WorkspaceStockEntryMethod.catalogue,
                embeddedPage: true,
                guardRouteExit: false,
                onDone: () => setPageState(() => catalogueProduct = null),
                onSaved: () => Navigator.of(pageContext).pop(true),
              )
            else
              const SizedBox.shrink(),
          ],
        ),
        manual: _CatalogueProductEditor(
          key: manualEditorKey,
          session: widget.session,
          product: manualProduct,
          stockEntryMethod: WorkspaceStockEntryMethod.manual,
          embeddedPage: true,
          guardRouteExit: false,
          onSaved: () => Navigator.of(pageContext).pop(true),
          onDone: () => setPageState(() {
            manualProduct = _blankProduct();
            manualEditorKey = GlobalKey<_CatalogueProductEditorState>();
            tab = 0;
          }),
        ),
        importCsv: () async {
          if (!storeUnchanged()) {
            return 'Your store changed. Open Add product again.';
          }
          final result = await _importCatalogue(
            csvOnly: true,
            onSaved: () {
              if (pageContext.mounted && storeUnchanged()) {
                Navigator.of(pageContext).pop(true);
              }
            },
          );
          if (pageContext.mounted) setPageState(() {});
          return result;
        },
      ),
    );
  }

  Future<void> _edit(WorkspaceCatalogueItem product, {String? field}) async {
    await Navigator.of(context).push<void>(
      MaterialPageRoute(
        builder: (pageContext) => Scaffold(
          appBar: AppBar(title: const Text('Edit product')),
          body: SafeArea(
            child: _CatalogueProductEditor(
              session: widget.session,
              product: product,
              embeddedPage: true,
              initialField: field,
              onDone: () => Navigator.of(pageContext).pop(),
              onSaved: () => Navigator.of(pageContext).pop(),
            ),
          ),
        ),
      ),
    );
    if (mounted) {
      setState(() {});
      _restoreStockAction(product.id);
    }
  }

  Future<bool> _scan() async {
    final code = await showStoreProductScanner(context);
    if (!mounted || code == null || code.trim().isEmpty) return false;
    final normalized = code.trim().toLowerCase();
    final products = [
      ...widget.session.workspaceCatalogueItems,
      ...widget.session.referenceCatalogue,
    ];
    final product = products
        .where(
          (item) =>
              item.barcode.toLowerCase() == normalized ||
              item.sku.toLowerCase() == normalized ||
              item.canonicalId.toLowerCase() == normalized,
        )
        .firstOrNull;
    await _edit(product ?? _blankProduct(barcode: code.trim()));
    return true;
  }

  void _togglePublic(WorkspaceCatalogueItem product) {
    final makePublic = !product.publicListing;
    if (makePublic && !product.matchesMasterCatalogueIdentity) {
      widget.session.showError(
        'This product stays private until its details are reviewed.',
      );
      return;
    }
    if (makePublic && (product.sellingPrice <= 0 || !product.available)) {
      widget.session.showError(
        'Add a customer price and make this product available before publishing.',
      );
      return;
    }
    if (!widget.session.addOrUpdateWorkspaceProduct(
      product.copyWith(publicListing: makePublic),
    )) {
      return;
    }
    setState(() {});
  }

  // ignore: unused_element
  Future<void> _showMasterCatalogue() async {
    final ownedIds = widget.session.workspaceCatalogueItems
        .map((product) => product.id)
        .toSet();
    final products = workspaceMasterCatalogue
        .where((product) => !ownedIds.contains(product.id))
        .toList(growable: false);
    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      showDragHandle: true,
      builder: (sheetContext) => SizedBox(
        height: MediaQuery.sizeOf(context).height * .62,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Padding(
              padding: EdgeInsets.symmetric(horizontal: 18),
              child: Text(
                'Add from MoolSocial catalogue',
                style: TextStyle(
                  color: MoolColors.navy,
                  fontSize: 20,
                  fontWeight: FontWeight.w900,
                ),
              ),
            ),
            const Padding(
              padding: EdgeInsets.fromLTRB(18, 2, 18, 10),
              child: Text(
                'Choose a product, then confirm your price and availability.',
                style: TextStyle(color: MoolColors.muted),
              ),
            ),
            Expanded(
              child: products.isEmpty
                  ? const Center(
                      child: Text('All available products are already added.'),
                    )
                  : ListView.separated(
                      padding: const EdgeInsets.fromLTRB(14, 0, 14, 24),
                      itemCount: products.length,
                      separatorBuilder: (_, _) => const SizedBox(height: 8),
                      itemBuilder: (context, index) {
                        final product = products[index];
                        return _WorkspaceProductRow(
                          product: product,
                          session: widget.session,
                          owned: false,
                          onEdit: () {
                            Navigator.pop(sheetContext);
                            _edit(product);
                          },
                        );
                      },
                    ),
            ),
          ],
        ),
      ),
    );
  }

  Future<String?> _importCatalogue({
    bool csvOnly = false,
    VoidCallback? onSaved,
  }) async {
    final identity = widget.session.counterDraftIdentity;
    final storeId =
        widget.session.activeWorkspace?.id ?? widget.session.workspaceId;
    var invalidated = false;
    bool current() =>
        !invalidated &&
        mounted &&
        identity == widget.session.counterDraftIdentity &&
        storeId ==
            (widget.session.activeWorkspace?.id ?? widget.session.workspaceId);
    void trackScope() {
      if (!current()) invalidated = true;
    }

    widget.session.addListener(trackScope);
    try {
      final picked = await FilePicker.pickFile(
        type: FileType.custom,
        allowedExtensions: csvOnly ? const ['csv'] : const ['csv', 'json'],
      );
      if (!current()) return 'Your store changed. Import the file again.';
      if (picked == null) return null;
      if (await picked.length() > 10 * 1024 * 1024) {
        return 'Choose a file smaller than 10 MB.';
      }
      final bytes = await picked.readAsBytes();
      if (!current()) return 'Your store changed. Import the file again.';
      if (bytes.length > 10 * 1024 * 1024) {
        return 'Choose a file smaller than 10 MB.';
      }
      final review = WorkspaceProductImport.parse(
        utf8.decode(bytes),
        json: picked.name.toLowerCase().endsWith('.json'),
        catalogue: widget.session.referenceCatalogue,
        owned: List.of(widget.session.workspaceCatalogueItems),
        defaults: widget.session.workspaceProductDefaults,
      );
      if (!current()) return 'Your store changed. Import the file again.';
      if (!mounted) return null;
      var savedCount = 0;
      Map<String, String>? attemptedReview, attemptedStock;
      final saved = await Navigator.of(context).push<bool>(
        MaterialPageRoute(
          builder: (reviewContext) => StoreProductImportReviewScreen(
            recentSearches: widget.session.workspaceRecentSearches(
              'csv:${picked.name}',
            ),
            fileName: picked.name,
            review: review,
            correctRow: (row, readyProducts) async {
              if (!current() || !row.canCorrect) return null;
              // A presentation seed is not a validated or saveable import row.
              // Only an unambiguous exact identity may supply catalogue media.
              final raw = row.rawValues;
              final matches = widget.session.referenceCatalogue
                  .where(
                    (p) =>
                        p.title.trim().toLowerCase() ==
                            (raw['title'] ?? '').toLowerCase() &&
                        p.brand.trim().toLowerCase() ==
                            (raw['brand'] ?? '').toLowerCase() &&
                        p.variant.trim().toLowerCase() ==
                            (raw['variant'] ?? '').toLowerCase() &&
                        p.pack.trim().toLowerCase() ==
                            (raw['pack'] ?? '').toLowerCase() &&
                        ((raw['barcode'] ?? '').isEmpty ||
                            p.barcode == raw['barcode']) &&
                        ((raw['canonicalId'] ?? '').isEmpty ||
                            p.canonicalId == raw['canonicalId']),
                  )
                  .toList();
              final seed = matches.length == 1
                  ? matches.single
                  : _blankProduct();
              final corrected = await Navigator.of(reviewContext)
                  .push<WorkspaceProductImportRow>(
                    MaterialPageRoute(
                      builder: (editorContext) => Scaffold(
                        appBar: AppBar(
                          toolbarHeight: 48,
                          titleSpacing: 0,
                          title: Text(
                            'Correct product · Row ${row.number}',
                            style: const TextStyle(
                              fontSize: 16,
                              fontWeight: FontWeight.w700,
                              color: MoolColors.navy,
                            ),
                          ),
                        ),
                        body: SafeArea(
                          child: _CatalogueProductEditor(
                            session: widget.session,
                            product: seed,
                            embeddedPage: true,
                            importRow: row,
                            onDone: () => Navigator.of(editorContext).pop(),
                            validateImport: (values) {
                              if (!current()) {
                                throw const FormatException(
                                  'Your Store changed. Close this import and open the correct Store.',
                                );
                              }
                              return WorkspaceProductImport.revalidateRow(
                                row,
                                values,
                                catalogue: widget.session.referenceCatalogue,
                                owned: [
                                  ...widget.session.workspaceCatalogueItems,
                                ],
                                readyRows: readyProducts,
                                defaults:
                                    widget.session.workspaceProductDefaults,
                              );
                            },
                            onImportReviewed: (result) =>
                                Navigator.of(editorContext).pop(result),
                          ),
                        ),
                      ),
                    ),
                  );
              return current() ? corrected : null;
            },
            editProduct: (product) async {
              if (!current()) return null;
              return Navigator.of(reviewContext).push<WorkspaceCatalogueItem>(
                MaterialPageRoute(
                  builder: (editorContext) => Scaffold(
                    appBar: AppBar(
                      toolbarHeight: 48,
                      titleSpacing: 0,
                      title: const Text(
                        'Review product',
                        style: TextStyle(
                          fontSize: 16,
                          fontWeight: FontWeight.w700,
                          color: MoolColors.navy,
                        ),
                      ),
                    ),
                    body: SafeArea(
                      child: _CatalogueProductEditor(
                        session: widget.session,
                        product: product,
                        embeddedPage: true,
                        onDone: () => Navigator.of(editorContext).pop(),
                        onDraftReviewed: (edited) =>
                            Navigator.of(editorContext).pop(edited),
                      ),
                    ),
                  ),
                ),
              );
            },
            saveProducts: (products) async {
              if (!current()) {
                return 'Your store changed. Close this review and import again.';
              }
              if (widget.session.localInventoryEnabled) {
                if (!await widget.session.loadWorkspaceInventory(retry: true) ||
                    !current()) {
                  return widget.session.workspaceInventoryError ??
                      'Return to the same Store before importing.';
                }
                if (savedCount > 0) {
                  final owned = {
                    for (final p in widget.session.workspaceCatalogueItems)
                      p.id: p,
                  };
                  final submittedIds = products.map((p) => p.id).toSet();
                  // A retry must cover every frozen row exactly once. Row count
                  // and per-row equality alone would accept A/A in place of A/B.
                  if (products.length != savedCount || attemptedReview == null ||
                      attemptedStock == null ||
                      submittedIds.length != products.length ||
                      submittedIds.length != attemptedReview!.length ||
                      submittedIds.length != attemptedStock!.length ||
                      !submittedIds.containsAll(attemptedReview!.keys) ||
                      !submittedIds.containsAll(attemptedStock!.keys) ||
                      products.any(
                    (p) =>
                        attemptedReview![p.id] != jsonEncode(
                          p.copyWith(publicListing: false).toInventoryJson()) ||
                        attemptedStock![p.id] !=
                          jsonEncode(owned[p.id]?.toInventoryJson()),
                  )) {
                    return 'The reviewed products changed. Keep this review open and check the unsaved Store stock.';
                  }
                  return await widget.session.retryWorkspaceInventorySave() &&
                          current()
                      ? null
                      : widget.session.workspaceInventoryError ??
                            'Stock was not saved. Retry.';
                }
              }
              // Recheck against live inventory: it may have changed while reviewing.
              final owned = widget.session.workspaceCatalogueItems;
              final ids = owned.map((p) => p.id).toSet();
              final skus = owned.map((p) => p.sku.trim().toLowerCase()).toSet();
              final barcodes = owned
                  .where((p) => p.barcode.isNotEmpty)
                  .map((p) => p.barcode)
                  .toSet();
              final identities = owned
                  .map(WorkspaceProductImport.identity)
                  .toSet();
              for (final p in products) {
                if (!ids.add(p.id) ||
                    !skus.add(p.sku.trim().toLowerCase()) ||
                    (p.barcode.isNotEmpty && !barcodes.add(p.barcode)) ||
                    !identities.add(WorkspaceProductImport.identity(p))) {
                  return 'Store stock changed or contains a duplicate. Import the file again; nothing was added.';
                }
              }
              if (!widget.session.importWorkspaceProducts(
                products.map((p) => p.copyWith(publicListing: false)).toList(),
                addOnly: true,
                stockEntryMethod: csvOnly ? WorkspaceStockEntryMethod.csv : null,
              )) {
                return 'Goods receipt is being saved. Your reviewed products are kept; try again when it finishes.';
              }
              savedCount = products.length;
              // Freeze both sides of the attempted save. Provenance is created
              // by the session, not the review editor; retry it without inventing
              // a new entry time or hiding actual review/inventory changes.
              attemptedReview = Map.unmodifiable({for (final p in products)
                p.id: jsonEncode(p.copyWith(publicListing: false).toInventoryJson())});
              final attemptedOwned = {for (final p in widget.session.workspaceCatalogueItems)
                p.id: p};
              attemptedStock = Map.unmodifiable({for (final p in products)
                p.id: jsonEncode(attemptedOwned[p.id]?.toInventoryJson())});
              if (widget.session.localInventoryEnabled &&
                  !await widget.session.workspaceInventorySaved) {
                return widget.session.workspaceInventoryError ??
                    'Stock was not saved. Keep this review open and retry.';
              }
              return null;
            },
          ),
        ),
      );
      if (!current()) {
        return 'Your store changed. Open the correct Store to check its stock.';
      }
      if (saved != true) {
        if (savedCount > 0) {
          return 'Import review closed with unsaved stock changes. Return to Store stock to review and retry saving.';
        }
        return 'Import cancelled. No products were added.';
      }
      setState(() {});
      onSaved?.call();
      return '$savedCount products saved to Store stock. Nothing was published.';
    } on FormatException catch (error) {
      return error.message;
    } catch (_) {
      return 'Could not read this file. Choose a UTF-8 CSV or JSON file and try again.';
    } finally {
      widget.session.removeListener(trackScope);
    }
  }

  @override
  Widget build(BuildContext context) {
    if (widget.entryOnly) return _entryPage;
    return SizedBox.expand(
      key: const Key('work-dashboard-catalogue-screen'),
      child: _StockQuickActionsFrame(
        expanded: _actionsExpanded,
        onToggle: _toggleActions,
        actions: [
          _StoreEdgeAction(
            keyName: 'work-quick-add-products',
            icon: Icons.add_box_outlined,
            label: 'Add products',
            onTap: () async {
              await Navigator.of(context).push<bool>(
                MaterialPageRoute(
                  builder: (_) => _WorkspaceCatalogueSurface(
                    session: widget.session,
                    entryOnly: true,
                  ),
                ),
              );
              if (mounted) setState(() {});
            },
          ),
          if (widget.onBuyStock != null)
            _StoreEdgeAction(
              keyName: 'work-quick-buy',
              icon: Icons.inventory_2_outlined,
              label: 'Buy stock',
              onTap: widget.onBuyStock,
            ),
          if (widget.onPurchases != null)
            _StoreEdgeAction(
              keyName: 'work-incoming-purchases',
              icon: Icons.local_shipping_outlined,
              label: 'Purchases',
              onTap: widget.onPurchases,
            ),
          if (widget.onGroupBuying != null)
            _StoreEdgeAction(
              keyName: 'work-quick-group-buy',
              icon: Icons.groups_2_outlined,
              label: 'Buy together',
              onTap: widget.onGroupBuying,
            ),
        ],
        child: Column(
          children: [
            ListenableBuilder(
              listenable: widget.session,
              builder: (context, _) {
                final error = widget.session.workspaceInventoryError;
                if (error == null) return const SizedBox.shrink();
                return Padding(
                  key: const Key('store-inventory-save-error'),
                  padding: const EdgeInsets.symmetric(
                    horizontal: 12,
                    vertical: 6,
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        error,
                        style: const TextStyle(color: MoolColors.ink),
                      ),
                      TextButton(
                        onPressed: _retryingInventory ? null : _retryInventory,
                        child: Text(
                          _retryingInventory ? 'Saving…' : 'Retry stock save',
                        ),
                      ),
                    ],
                  ),
                );
              },
            ),
            Expanded(
              child: StoreAddProductSheet(
                key: ValueKey(
                  'store-stock-${widget.session.activeWorkspace?.id ?? widget.session.workspaceId}',
                ),
                embedded: true,
                stockOnly: true,
                onStockStatement: widget.onStatement,
                recentSearches: widget.session.workspaceRecentSearches('stock'),
                catalogue: const [],
                ownedProducts: List.of(widget.session.workspaceCatalogueItems),
                createProduct: (barcode) => _blankProduct(barcode: barcode),
                scanBarcode: () => showStoreProductScanner(context),
                onSelected: _edit,
                stockStatementBuilder: (products, count, vertical, loadMore) =>
                    _StoreStockStatementTable(
                      products: products,
                      bottomClearance: _actionsExpanded
                          ? 0
                          : _stockQuickTabHeight(context) + 6,
                      visibleCount: count,
                      vertical: vertical,
                      loadMore: loadMore,
                      rowBuilder:
                          (product, horizontal, frozenWidth, widths, height) =>
                              _WorkspaceProductRow(
                                product: product,
                                session: widget.session,
                                owned: true,
                                statement: true,
                                horizontal: horizontal,
                                frozenWidth: frozenWidth,
                                statementWidths: widths,
                                statementHeight: height,
                                stockActionKey: _stockActionKeys.putIfAbsent(
                                  product.id,
                                  () => GlobalKey(),
                                ),
                                onEdit: () => _edit(product),
                                onChangePrice: () =>
                                    _edit(product, field: 'sellingPrice'),
                                onUpdateStock: () =>
                                    _edit(product, field: 'stock'),
                                onEditField: (field) =>
                                    _edit(product, field: field),
                                onTogglePublic: () => _togglePublic(product),
                              ),
                    ),
