double _stockQuickTabHeight(BuildContext context) {
  final painter = TextPainter(
    text: TextSpan(
      text: 'Quick actions',
      style: DefaultTextStyle.of(
        context,
      ).style.merge(const TextStyle(fontSize: 11, fontWeight: FontWeight.w600)),
    ),
    textDirection: TextDirection.ltr,
    textScaler: MediaQuery.textScalerOf(context),
  )..layout();
  final height = painter.width.ceilToDouble() + 41;
  painter.dispose();
  return height;
}

/// Shared horizontal action shelf, collapsed manually to the corner control.
class _StockQuickActionsFrame extends StatelessWidget {
  const _StockQuickActionsFrame({
    required this.child,
    required this.actions,
    required this.expanded,
    required this.onToggle,
    this.keyPrefix = 'work-stock',
  });
  final Widget child;
  final List<Widget> actions;
  final bool expanded;
  final VoidCallback onToggle;
  final String keyPrefix;

  @override
  Widget build(BuildContext context) => LayoutBuilder(
    builder: (context, box) {
      // Preserve full-sized text and targets in short accessibility viewports.
      // Keep actions fixed while the register can use a readable scroll extent.
      final textScaler = MediaQuery.textScalerOf(context);
      final minimumHeight = textScaler.scale(200);
      Widget readableContent = child;
      if (MediaQuery.orientationOf(context) == Orientation.landscape &&
          textScaler.scale(1) > 1.3 &&
          box.hasBoundedHeight && box.maxHeight < minimumHeight + (expanded ? 54 : 0)) {
        readableContent = SingleChildScrollView(
          key: Key('$keyPrefix-large-landscape-scroll'),
          keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
          child: Builder(builder: (scrollContext) => NotificationListener<OverscrollNotification>(
            onNotification: (notification) {
              if (notification.metrics.axis != Axis.vertical) return false;
              final outer = Scrollable.of(scrollContext).position;
              final target = (outer.pixels + notification.overscroll)
                  .clamp(outer.minScrollExtent, outer.maxScrollExtent);
              if (target == outer.pixels) return false;
              outer.jumpTo(target);
              return true;
            },
            child: SizedBox(
              key: Key('$keyPrefix-readable-content'),
              height: minimumHeight,
              child: child,
            ),
          )),
        );
      }
      final desiredHeight = _stockQuickTabHeight(context);
      final short = box.maxHeight < desiredHeight + 12;
      final tabHeight = short ? 48.0 : desiredHeight;
      final label = expanded ? 'Hide Quick actions' : 'Show Quick actions';
      final toggle = Tooltip(
        message: label,
        child: Semantics(
          button: true,
          label: label,
          expanded: expanded,
          excludeSemantics: true,
          child: Material(
            color: expanded ? Colors.transparent : const Color(0xFFF0F1F7),
            borderRadius: const BorderRadius.only(
              topLeft: Radius.circular(12),
              bottomLeft: Radius.circular(12),
            ),
            child: InkWell(
              key: Key('$keyPrefix-actions-toggle'),
              onTap: onToggle,
              borderRadius: BorderRadius.circular(12),
              child: SizedBox(
                width: 48,
                height: expanded ? 48 : tabHeight,
                child: expanded || short
                    ? Icon(
                        expanded
                            ? Icons.chevron_right_rounded
                            : Icons.chevron_left_rounded,
                        color: MoolColors.navy,
                        size: 21,
                      )
                    : Padding(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 4,
                          vertical: 6,
                        ),
                        child: Column(
                          mainAxisAlignment: MainAxisAlignment.center,
                          children: [
                            const Icon(
                              Icons.chevron_left_rounded,
                              size: 21,
                              color: MoolColors.navy,
                            ),
                            const RotatedBox(
                              quarterTurns: 3,
                              child: Text(
                                'Quick actions',
                                style: TextStyle(
                                  fontSize: 11,
                                  fontWeight: FontWeight.w600,
                                  color: MoolColors.navy,
                                ),
                              ),
                            ),
                          ],
                        ),
                      ),
              ),
            ),
          ),
        ),
      );
      if (expanded) {
        final actionHeight = (MediaQuery.textScalerOf(context).scale(11) * 1.25 + 16)
            .clamp(48.0, double.infinity);
        return Column(
          children: [
            Expanded(child: SizedBox(
              key: Key('$keyPrefix-action-content'),
              width: double.infinity,
              child: readableContent,
            )),
            Container(
              key: Key('$keyPrefix-actions-panel'),
              height: actionHeight + 6,
              color: Colors.white,
              child: Row(
                children: [
                  Expanded(child: SingleChildScrollView(
                    key: Key('$keyPrefix-entry-controls'),
                    scrollDirection: Axis.horizontal,
                    padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 3),
                    child: Row(children: [
                      for (final action in actions)
                        Padding(
                          padding: const EdgeInsets.only(right: 4),
                          child: action,
                        ),
                    ]),
                  )),
                  toggle,
                ],
              ),
            ),
          ],
        );
      }
      return ColoredBox(
        color: const Color(0xFFF7F8FC),
        child: Stack(
          children: [
            Positioned.fill(
              child: ClipPath(
                key: Key('$keyPrefix-action-content'),
                clipper: _StockActionCutout(expanded ? 0 : tabHeight + 6),
                child: readableContent,
              ),
            ),
            Positioned(right: 0, bottom: 0, child: toggle),
          ],
        ),
      );
    },
  );
}

class _StockActionCutout extends CustomClipper<Path> {
  const _StockActionCutout(this.height);
  final double height;
  @override
  Path getClip(Size size) {
    final full = Path()..addRect(Offset.zero & size);
    if (height == 0) return full;
    final notch = Path()
      ..addRRect(
        RRect.fromRectAndCorners(
          Rect.fromLTWH(size.width - 54, size.height - height, 60, height + 6),
          topLeft: const Radius.circular(18),
          bottomLeft: const Radius.circular(18),
        ),
      );
    return Path.combine(PathOperation.difference, full, notch);
  }

  @override
  bool shouldReclip(_StockActionCutout oldClipper) =>
      oldClipper.height != height;
}

