// One horizontal viewport owns the header and all rows. Product cells are
// translated back by that same offset, keeping their identity column frozen.
class _StoreStockStatementTable extends StatefulWidget {
  const _StoreStockStatementTable({
    required this.products,
    required this.visibleCount,
    required this.vertical,
    required this.loadMore,
    required this.rowBuilder,
    this.bottomClearance = 0,
  });
  final double bottomClearance;
  final List<WorkspaceCatalogueItem> products;
  final int visibleCount;
  final ScrollController vertical;
  final VoidCallback loadMore;
  final Widget Function(
    WorkspaceCatalogueItem,
    ScrollController,
    double,
    List<double>,
    double,
  )
  rowBuilder;

  @override
  State<_StoreStockStatementTable> createState() =>
      _StoreStockStatementTableState();
}

class _StoreStockStatementTableState extends State<_StoreStockStatementTable> {
  final _horizontal = ScrollController();
  double? _productWidth;
  @override
  void dispose() {
    _horizontal.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final scale = MediaQuery.textScalerOf(context).scale(1).clamp(1.0, 2.5);
    // Ordinary grocery prices stay compact; widen only for actual larger
    // amounts instead of wasting a full mobile viewport on every price column.
    var moneyCharacters = 0;
    for (final product in widget.products) {
      for (final amount in [
        product.sellingPrice,
        product.purchasePrice,
        product.mrp ?? product.sellingPrice,
      ]) {
        final length = '₹${_formatStoreAmount(amount)}'.length;
        if (length > moneyCharacters) moneyCharacters = length;
      }
    }
    final moneyWidth = (moneyCharacters * 10.0 + 24).clamp(96.0, 260.0);
    final stockCharacters = widget.products.fold<int>(
      1,
      (length, product) => product.stock.toString().length > length
          ? product.stock.toString().length
          : length,
    );
    final widths = <double>[
      widget.products.any(
            (p) => p.stockMode == WorkspaceStockMode.availabilityOnly,
          )
          ? 112
          : (stockCharacters * 10.0 + 20).clamp(64.0, 180.0),
      moneyWidth,
      moneyWidth,
      moneyWidth,
      104,
    ].map((w) => w * scale).toList();
    return Column(
      children: [
        Expanded(
          child: LayoutBuilder(
            builder: (context, box) {
              final minimum = box.maxWidth * .30;
              final maximum = box.maxWidth * .80;
              final frozen =
                  (_productWidth ?? (box.maxWidth * .45).clamp(144.0, 240.0))
                      .clamp(minimum, maximum);
              void resize(double delta) => setState(() {
                _productWidth = (frozen + delta).clamp(minimum, maximum);
              });
              final total = frozen + widths.reduce((a, b) => a + b);
              return Stack(
                children: [
                  Scrollbar(
                    controller: _horizontal,
                    thumbVisibility: true,
                    interactive: true,
                    thickness: 2,
                    radius: const Radius.circular(1),
                    scrollbarOrientation: ScrollbarOrientation.bottom,
                    child: SingleChildScrollView(
                      key: const Key('work-stock-horizontal'),
                      controller: _horizontal,
                      scrollDirection: Axis.horizontal,
                      child: SizedBox(
                        width: total,
                        height: box.maxHeight,
                        child: Column(
                          children: [
                            _StockFrozenRow(
                              key: const Key('work-stock-statement-header'),
                              horizontal: _horizontal,
                              frozenWidth: frozen,
                              columnWidths: widths,
                              height: 36 * scale,
                              background: const Color(0xFFF1F4FF),
                              identity: const Padding(
                                padding: EdgeInsets.only(left: 10),
                                child: Align(
                                  alignment: Alignment.centerLeft,
                                  child: Text(
                                    'Product',
                                    style: TextStyle(
                                      fontSize: 11,
                                      color: MoolColors.muted,
                                      fontWeight: FontWeight.w600,
                                    ),
                                  ),
                                ),
                              ),
                              data: Row(
                                children: [
                                  for (var i = 0; i < widths.length; i++)
                                    SizedBox(
                                      width: widths[i],
                                      child: Padding(
                                        padding: const EdgeInsets.symmetric(
                                          horizontal: 8,
                                        ),
                                        child: Text(
                                          const [
                                            'Stock',
                                            'Selling price',
                                            'Purchase price',
                                            'MRP',
                                            'Reorder level',
                                          ][i],
                                          key: Key('work-stock-heading-$i'),
                                          textAlign: TextAlign.center,
                                          style: const TextStyle(
                                            fontSize: 11,
                                            color: MoolColors.muted,
                                            fontWeight: FontWeight.w600,
                                          ),
                                        ),
                                      ),
                                    ),
                                ],
                              ),
                            ),
                            Expanded(
                              child: NotificationListener<ScrollNotification>(
                                onNotification: (n) {
                                  if (n.metrics.axis == Axis.vertical &&
                                      n is ScrollUpdateNotification &&
                                      n.metrics.extentAfter < 160) {
                                    widget.loadMore();
                                  }
                                  return false;
                                },
                                child: CustomScrollView(
                                  key: const Key('work-catalogue-list'),
                                  controller: widget.vertical,
                                  keyboardDismissBehavior:
                                      ScrollViewKeyboardDismissBehavior.onDrag,
                                  slivers: [
                                    SliverList.builder(
                                      itemCount: widget.visibleCount,
                                      itemBuilder: (_, i) => widget.rowBuilder(
                                        widget.products[i],
                                        _horizontal,
                                        frozen,
                                        widths,
                                        56 * scale,
                                      ),
                                    ),
                                    if (widget.visibleCount <
                                        widget.products.length)
                                      SliverToBoxAdapter(
                                        child: Align(
                                          alignment: Alignment.centerLeft,
                                          child: SizedBox(
                                            width: frozen,
                                            child: TextButton(
                                              key: const Key(
                                                'work-catalogue-load-more',
                                              ),
                                              onPressed: widget.loadMore,
                                              child: const Text('Load more'),
                                            ),
                                          ),
                                        ),
                                      ),
                                    SliverToBoxAdapter(
                                      child: SizedBox(
                                        height: 12 + widget.bottomClearance,
                                      ),
                                    ),
                                  ],
                                ),
                              ),
                            ),
                          ],
                        ),
                      ),
                    ),
                  ),
                  Positioned(
                    left: frozen - 12,
                    top: 0,
                    bottom: 4,
                    width: 24,
                    child: Semantics(
                      label: 'Product column width',
                      value: '${(frozen / box.maxWidth * 100).round()} percent',
                      increasedValue:
                          '${((frozen + 24).clamp(minimum, maximum) / box.maxWidth * 100).round()} percent',
                      decreasedValue:
                          '${((frozen - 24).clamp(minimum, maximum) / box.maxWidth * 100).round()} percent',
                      onIncrease: () => resize(24),
                      onDecrease: () => resize(-24),
                      child: GestureDetector(
                        key: const Key('work-stock-column-resize'),
                        behavior: HitTestBehavior.opaque,
                        onHorizontalDragUpdate: (details) =>
                            resize(details.delta.dx),
                        onDoubleTap: () => setState(() => _productWidth = null),
                        child: MouseRegion(
                          cursor: SystemMouseCursors.resizeColumn,
                          child: Align(
                            alignment: Alignment.topCenter,
                            child: SizedBox(
                              height: 36 * scale,
                              child: const Icon(
                                Icons.drag_indicator,
                                size: 16,
                                color: MoolColors.muted,
                              ),
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                ],
              );
            },
          ),
        ),
      ],
    );
  }
}

const _stockStatementPrimaryStyle = TextStyle(
  fontSize: 12,
  height: 1.2,
  fontWeight: FontWeight.w600,
  color: Color(0xFF30343B),
  fontFeatures: [FontFeature.tabularFigures()],
);

class _StockFrozenRow extends StatelessWidget {
  const _StockFrozenRow({
    super.key,
    required this.horizontal,
    required this.frozenWidth,
    required this.columnWidths,
    required this.height,
    required this.identity,
    required this.data,
    this.background = Colors.white,
  });
  final ScrollController horizontal;
  final double frozenWidth;
  final List<double> columnWidths;
  final double height;
  final Widget identity;
  final Widget data;
  final Color background;
  @override
  Widget build(BuildContext context) => SizedBox(
    height: height,
    child: AnimatedBuilder(
      animation: horizontal,
      builder: (_, _) => Stack(
        children: [
          Positioned.fill(
            child: DecoratedBox(
              decoration: BoxDecoration(
                color: background,
                border: const Border(
                  bottom: BorderSide(color: Color(0xFFE6E9F1)),
                ),
              ),
              child: Padding(
                padding: EdgeInsets.only(left: frozenWidth),
                child: data,
              ),
            ),
          ),
          for (var i = 0; i < columnWidths.length - 1; i++)
            Positioned(
              left:
                  frozenWidth +
                  columnWidths.take(i + 1).fold<double>(0, (a, b) => a + b),
              top: 0,
              bottom: 0,
              width: 1,
              child: IgnorePointer(
                child: ColoredBox(
                  key: ValueKey('work-stock-column-line-$i'),
                  color: const Color(0xFFE6E9F1),
                ),
              ),
            ),
          Positioned(
            left: horizontal.hasClients ? horizontal.offset : 0,
            top: 0,
            bottom: 0,
            width: frozenWidth,
            child: Container(
              decoration: BoxDecoration(
                color: background,
                border: const Border(
                  right: BorderSide(color: Color(0xFFDCE1EF)),
                  bottom: BorderSide(color: Color(0xFFE6E9F1)),
                ),
              ),
              child: identity,
            ),
          ),
        ],
      ),
    ),
  );
}

class _WorkspaceProductRow extends StatelessWidget {
  const _WorkspaceProductRow({
    required this.product,
    required this.session,
    required this.owned,
    required this.onEdit,
    this.onChangePrice,
    this.onUpdateStock,
    this.onEditField,
    this.onTogglePublic,
    this.stockActionKey,
    this.statement = false,
    this.horizontal,
    this.frozenWidth = 144,
    this.statementWidths = const [104, 152, 152, 152, 104],
    this.statementHeight = 104,
  });

  final WorkspaceCatalogueItem product;
  final WorkSession session;
  final bool owned;
  final VoidCallback onEdit;
  final VoidCallback? onChangePrice;
  final VoidCallback? onUpdateStock;
  final ValueChanged<String>? onEditField;
  final VoidCallback? onTogglePublic;
  final Key? stockActionKey;
  final bool statement;
  final ScrollController? horizontal;
  final double frozenWidth;
  final List<double> statementWidths;
  final double statementHeight;

  @override
  Widget build(BuildContext context) {
    if (owned && statement) return _statementProduct(context);
    if (owned &&
        (MediaQuery.textScalerOf(context).scale(1) >= 1.4 ||
            product.sellingPrice.abs() >= 10000000 ||
            (product.mrp ?? product.sellingPrice).abs() >= 10000000)) {
      return _expandedProduct(context);
    }
    return KeyedSubtree(
      key: owned ? Key('work-public-sku-${product.id}') : null,
      child: WorkCard(
        keyName: 'work-catalogue-${owned ? 'owned' : 'master'}-${product.id}',
        padding: const EdgeInsets.fromLTRB(8, 7, 6, 7),
        child: Row(
          children: [
            StoreProductThumbnail(
              product: product,
              extent: 48,
              session: session,
            ),
            const SizedBox(width: MoolSpacing.xs),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    product.title,
                    maxLines: 2,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                      color: MoolColors.ink,
                      fontSize: 12,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                  Text(
                    owned
                        ? '${product.pack} · MRP ₹${product.mrp ?? product.sellingPrice} · ${product.sku}'
                        : '${product.pack} · ${product.sku}',
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                      color: MoolColors.muted,
                      fontSize: 9.5,
                    ),
                  ),
                  if (owned)
                    Wrap(
                      spacing: 5,
                      runSpacing: 4,
                      children: [
                        _ProductQuickValue(
                          keyName: 'work-catalogue-price-${product.id}',
                          icon: Icons.sell_outlined,
                          label: '₹${product.sellingPrice}',
                          onTap: onChangePrice,
                        ),
                        _ProductQuickValue(
                          key: stockActionKey,
                          keyName: 'work-catalogue-stock-${product.id}',
                          icon: Icons.inventory_2_outlined,
                          label:
                              product.stockMode ==
                                  WorkspaceStockMode.availabilityOnly
                              ? (product.available
                                    ? 'Available'
                                    : 'Unavailable')
                              : '${product.stock} in stock',
                          attention:
                              product.stockMode ==
                                  WorkspaceStockMode.exactQuantity &&
                              product.stock <= product.lowStockThreshold,
                          onTap: onUpdateStock,
                        ),
                      ],
                    )
                  else
                    Text(
                      'MRP ₹${product.mrp ?? product.sellingPrice} · Product details ready',
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        color: MoolColors.navy,
                        fontSize: 9.5,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                ],
              ),
            ),
            if (owned) ...[
              _ProductVisibilityButton(
                keyName: 'work-catalogue-visibility-${product.id}',
                isPublic: product.publicListing,
                onTap: onTogglePublic,
              ),
              IconButton(
                key: Key('work-catalogue-edit-${product.id}'),
                tooltip: 'Edit complete product details',
                visualDensity: VisualDensity.compact,
                onPressed: onEdit,
                icon: const Icon(Icons.edit_outlined, size: 20),
              ),
            ] else
              SizedBox(
                width: 68,
                child: FilledButton.tonal(
                  key: Key('work-catalogue-add-${product.id}'),
                  onPressed: onEdit,
                  style: FilledButton.styleFrom(
                    padding: const EdgeInsets.symmetric(horizontal: 7),
                  ),
                  child: const FittedBox(child: Text('Add')),
                ),
              ),
          ],
        ),
      ),
    );
  }

  Widget _statementProduct(BuildContext context) {
    final counted = product.stockMode == WorkspaceStockMode.exactQuantity;
    final quantity = counted
        ? '${product.stock}'
        : (product.available ? 'Available' : 'Unavailable');
    final low =
        counted &&
        product.stock > 0 &&
        product.stock <= product.lowStockThreshold;
    final out = counted ? product.stock <= 0 : !product.available;
    Widget cell(
      int column,
      String keyName,
      String value, {
      VoidCallback? onTap,
      Key? anchor,
      String? note,
    }) => SizedBox(
      key: anchor,
      width: statementWidths[column],
      height: statementHeight,
      child: InkWell(
        key: Key(keyName),
        onTap: onTap,
        child: Center(
          child: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 8),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Row(mainAxisSize: MainAxisSize.min, children: [
                  Flexible(child: Text(
                    value,
                    textAlign: TextAlign.center,
                    style: _stockStatementPrimaryStyle,
                  )),
                  if (onTap != null) ...[
                    const SizedBox(width: 3),
                    ExcludeSemantics(child: Icon(Icons.edit_outlined,
                        key: Key('$keyName-pencil'), size: 12,
                        color: MoolColors.navy)),
                  ],
                ]),
                if (note != null) ...[
                  const SizedBox(height: 4),
                  Text(
                    note,
                    textAlign: TextAlign.center,
                    style: const TextStyle(
                      fontSize: 10,
                      color: Color(0xFF9A4A00),
                    ),
                  ),
                ],
              ],
            ),
          ),
        ),
      ),
    );
    return KeyedSubtree(
      key: Key('work-public-sku-${product.id}'),
      child: Material(
        key: Key('work-catalogue-owned-${product.id}'),
        color: Colors.white,
        child: _StockFrozenRow(
          horizontal: horizontal!,
          frozenWidth: frozenWidth,
          columnWidths: statementWidths,
          height: statementHeight,
          identity: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 3),
            child: Row(
              children: [
                product.cataloguePhoto == null && product.privatePhoto == null
                    ? const Tooltip(
                        message: 'Photo unavailable',
                        child: SizedBox.square(
                          dimension: 32,
                          child: Icon(
                            Icons.inventory_2_outlined,
                            size: 18,
                            color: MoolColors.muted,
                          ),
                        ),
                      )
                    : StoreProductThumbnail(
                        product: product,
                        extent: 32,
                        session: session,
                      ),
                const SizedBox(width: 4),
                Expanded(
                  child: InkWell(
                    key: Key('work-catalogue-edit-${product.id}'),
                    onTap: onEdit,
                    child: Tooltip(
                      message:
                          '${product.title} · ${product.variant} · ${product.pack} · ${product.sku}',
                      child: Semantics(
                        button: true,
                        label: 'Edit ${product.title}',
                        child: SizedBox(
                          height: statementHeight,
                          child: Column(
                            mainAxisAlignment: MainAxisAlignment.center,
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Row(children: [
                                Expanded(child: Text(
                                  product.title,
                                  maxLines: 2,
                                  overflow: TextOverflow.ellipsis,
                                  style: _stockStatementPrimaryStyle,
                                )),
                                const SizedBox(width: 3),
                                ExcludeSemantics(child: Icon(Icons.edit_outlined,
                                    key: Key('work-catalogue-edit-${product.id}-pencil'),
                                    size: 12, color: MoolColors.navy)),
                              ]),
                              const SizedBox(height: 3),
                              Text(
                                '${product.pack} · ${product.sku}',
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(
                                  fontSize: 10,
                                  height: 1.2,
                                  color: MoolColors.navy,
                                ),
                              ),
                            ],
                          ),
                        ),
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
          data: Row(
            children: [
              cell(
                0,
                'work-catalogue-stock-${product.id}',
                quantity,
                onTap: onUpdateStock,
                anchor: stockActionKey,
                note: !product.counterSaleAllowed && !out
                    ? 'Counter paused'
                    : out
                    ? 'Out of stock'
                    : low
                    ? 'Low stock'
                    : null,
              ),
              cell(
                1,
                'work-catalogue-price-${product.id}',
                '₹${_formatStoreAmount(product.sellingPrice)}',
                onTap: onChangePrice,
              ),
              cell(
                2,
                'work-catalogue-purchase-${product.id}',
                '₹${_formatStoreAmount(product.purchasePrice)}',
                onTap: () => onEditField?.call('purchasePrice'),
              ),
              cell(
                3,
                'work-catalogue-mrp-${product.id}',
                product.mrp == null
                    ? 'Not set'
                    : '₹${_formatStoreAmount(product.mrp!)}',
                onTap: () => onEditField?.call('mrp'),
              ),
              cell(
                4,
                'work-catalogue-reorder-${product.id}',
                counted ? '${product.lowStockThreshold}' : 'Not applicable',
                onTap: () => onEditField?.call('lowStockThreshold'),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _expandedSurface({
    required EdgeInsets padding,
    required Widget child,
  }) {
    if (!statement) {
      return WorkCard(
        keyName: 'work-catalogue-owned-${product.id}',
        padding: padding,
        child: child,
      );
    }
    return Container(
      key: Key('work-catalogue-owned-${product.id}'),
      padding: padding,
      decoration: const BoxDecoration(
        color: Colors.white,
        border: Border(bottom: BorderSide(color: Color(0xFFE6E9F1))),
      ),
      child: child,
    );
  }

  Widget _expandedProduct(BuildContext context) {
    final compactInsets =
        MediaQuery.sizeOf(context).width < 360 &&
        MediaQuery.textScalerOf(context).scale(1) >= 2;
    final moneyStyle = Theme.of(context).textTheme.bodyMedium!.copyWith(
      fontSize: 14,
      color: MoolColors.navy,
      fontWeight: FontWeight.w800,
    );
    return KeyedSubtree(
      key: Key('work-public-sku-${product.id}'),
      child: _expandedSurface(
        padding: EdgeInsets.symmetric(
          horizontal: compactInsets ? 4 : 12,
          vertical: 12,
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                if (statement) ...[
                  StoreProductThumbnail(
                    product: product,
                    extent: 42,
                    session: session,
                  ),
                  const SizedBox(width: 6),
                ],
                Expanded(
                  child: Text(
                    product.title,
                    style: const TextStyle(
                      color: MoolColors.ink,
                      fontSize: 13,
                      fontWeight: FontWeight.w800,
                    ),
                  ),
                ),
                IconButton(
                  key: Key('work-catalogue-edit-${product.id}'),
                  tooltip: 'Edit complete product details',
                  onPressed: onEdit,
                  icon: const Icon(Icons.edit_outlined, size: 20),
                ),
              ],
            ),
            Text(
              '${product.brand} · ${product.pack}',
              style: const TextStyle(fontSize: 11, color: MoolColors.muted),
            ),
            Text(
              product.sku,
              style: const TextStyle(fontSize: 11, color: MoolColors.muted),
            ),
            const SizedBox(height: 8),
            Material(
              color: const Color(0xFFF1F4FF),
              borderRadius: BorderRadius.circular(10),
              child: InkWell(
                key: Key('work-catalogue-price-${product.id}'),
                onTap: onChangePrice,
                borderRadius: BorderRadius.circular(10),
                child: ConstrainedBox(
                  constraints: const BoxConstraints(minHeight: 48),
                  child: Padding(
                    padding: EdgeInsets.symmetric(
                      horizontal: compactInsets ? 0 : 8,
                      vertical: 8,
                    ),
                    child: _StoreMoneyLine(
                      leading: const Text(
                        'Selling price',
                        style: TextStyle(fontSize: 12),
                      ),
                      value: '₹${_formatStoreAmount(product.sellingPrice)}',
                      style: moneyStyle,
                    ),
                  ),
                ),
              ),
            ),
            Padding(
              key: Key('work-catalogue-mrp-${product.id}'),
              padding: EdgeInsets.symmetric(
                horizontal: compactInsets ? 0 : 8,
                vertical: 8,
              ),
              child: _StoreMoneyLine(
                leading: const Text('MRP', style: TextStyle(fontSize: 12)),
                value: product.mrp == null
                    ? 'Not set'
                    : '₹${_formatStoreAmount(product.mrp!)}',
                style: moneyStyle.copyWith(fontWeight: FontWeight.w500),
              ),
            ),
            Wrap(
              alignment: WrapAlignment.spaceBetween,
              spacing: 8,
              runSpacing: 4,
              crossAxisAlignment: WrapCrossAlignment.center,
              children: [
                ConstrainedBox(
                  constraints: const BoxConstraints(
                    minHeight: 48,
                    minWidth: 48,
                  ),
                  child: _ProductQuickValue(
                    key: stockActionKey,
                    keyName: 'work-catalogue-stock-${product.id}',
                    icon: Icons.inventory_2_outlined,
                    label:
                        product.stockMode == WorkspaceStockMode.availabilityOnly
                        ? (product.available ? 'Available' : 'Unavailable')
                        : '${product.stock} in stock',
                    attention:
                        product.stockMode == WorkspaceStockMode.exactQuantity &&
                        product.stock <= product.lowStockThreshold,
                    onTap: onUpdateStock,
                  ),
                ),
                _ProductVisibilityButton(
                  keyName: 'work-catalogue-visibility-${product.id}',
                  isPublic: product.publicListing,
                  onTap: onTogglePublic,
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}

class _ProductVisibilityButton extends StatelessWidget {
  const _ProductVisibilityButton({
    required this.keyName,
    required this.isPublic,
    required this.onTap,
  });

  final String keyName;
  final bool isPublic;
  final VoidCallback? onTap;

  @override
  Widget build(BuildContext context) {
    final color = isPublic ? const Color(0xFF08765D) : MoolColors.muted;
    return Tooltip(
      message: isPublic ? 'Hide from customers' : 'Show to customers',
      child: InkWell(
        key: Key(keyName),
        borderRadius: BorderRadius.circular(12),
        onTap: onTap,
        child: ConstrainedBox(
          constraints: const BoxConstraints(minWidth: 48, minHeight: 48),
          child: Padding(
            padding: const EdgeInsets.all(4),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Icon(
                  isPublic
                      ? Icons.public_rounded
                      : Icons.visibility_off_outlined,
                  color: color,
                  size: 18,
                ),
                Text(
                  isPublic ? 'Public' : 'Private',
                  style: TextStyle(
                    color: color,
                    fontSize: 9,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

