class _CatalogueProductEditor extends StatefulWidget {
  const _CatalogueProductEditor({
    super.key,
    required this.session,
    required this.product,
    this.embeddedPage = false,
    this.guardRouteExit = true,
    this.initialField,
    this.onDone,
    this.onSaved,
    this.onDraftReviewed,
    this.importRow,
    this.validateImport,
    this.onImportReviewed,
    this.purchaseScope,
    this.stockEntryMethod,
  });

  final WorkSession session;
  final WorkspaceCatalogueItem product;
  final bool embeddedPage;
  final bool guardRouteExit;
  final String? initialField;
  final VoidCallback? onDone;
  final VoidCallback? onSaved;
  final ValueChanged<WorkspaceCatalogueItem>? onDraftReviewed;
  final WorkspaceProductImportRow? importRow;
  final WorkspaceProductImportRow Function(Map<String, String>)? validateImport;
  final ValueChanged<WorkspaceProductImportRow>? onImportReviewed;
  // Only new-product setup launched by a purchase. All other editors are unchanged.
  final (String, String, bool)? purchaseScope;
  // Explicit creation route only; edits and purchase/CSV draft review do not post.
  final WorkspaceStockEntryMethod? stockEntryMethod;

  @override
  State<_CatalogueProductEditor> createState() =>
      _CatalogueProductEditorState();
}

class _CatalogueProductEditorState extends State<_CatalogueProductEditor> {
  late final String? _storeId;
  late final bool _wasOwned;
  bool _saved = false;
  bool _savingInventory = false;
  bool _pendingInventorySave = false;
  bool _choosingPhoto = false;
  bool _allowEditorExit = false;
  bool _confirmingEditorExit = false;
  late final Map<String, String> _initialEditValues;
  bool get _hasUnsavedEdits => !_saved && (
    _importControllers.entries.any(
      (entry) => entry.value.text != _initialEditValues[entry.key]) ||
    _public != widget.product.publicListing ||
    _available != widget.product.available ||
    _privatePhoto != widget.product.privatePhoto);
  late WorkspacePrivateProductPhoto? _privatePhoto =
      widget.product.privatePhoto;

  WorkspaceCatalogueItem get _photoIdentity => widget.product.copyWith(
    title: _title.text.trim(),
    brand: _brand.text.trim(),
    variant: _variant.text.trim(),
    pack: _pack.text.trim(),
    barcode: _barcode.text.trim(),
    categoryId: _category.text.trim(),
    clearPrivatePhoto: true,
  );

  WorkspacePrivateProductPhoto? get _matchingPhoto =>
      _privatePhoto?.matches(_photoIdentity) == true ? _privatePhoto : null;

  Future<void> _chooseProductPhoto() async {
    if (_choosingPhoto ||
        _savingInventory ||
        _saved ||
        widget.importRow != null) {
      return;
    }
    final product = _photoIdentity;
    if (widget.session.catalogueManagesProductPhoto(product)) return;
    final store = widget.session.privateProductPhotos;
    if (store == null) {
      _reject('Store photo storage is unavailable. Try again from your Store.');
      return;
    }
    setState(() => _choosingPhoto = true);
    try {
      String? selectedName;
      final picked = await NativeWorkProofPicker(
        documentFileName: () => selectedName,
        documentPicker: () async {
          final selected = await FilePicker.pickFile(type: FileType.image);
          selectedName = selected?.name;
          return selected?.xFile;
        },
      ).pick(WorkProofSource.upload);
      if (picked == null || !mounted || !store.isCurrent()) return;
      final photo = await store.save(product: product, picked: picked);
      final bytes = await store.read(product.copyWith(privatePhoto: photo));
      if (!mounted || !store.isCurrent()) return;
      final accepted = await showDialog<bool>(
        context: context,
        builder: (dialogContext) => AlertDialog(
          insetPadding: const EdgeInsets.symmetric(
            horizontal: 20,
            vertical: 16,
          ),
          titlePadding: const EdgeInsets.fromLTRB(16, 16, 16, 8),
          contentPadding: const EdgeInsets.symmetric(horizontal: 16),
          actionsPadding: const EdgeInsets.fromLTRB(8, 4, 8, 8),
          title: const Text(
            'Check product image',
            style: TextStyle(
              fontSize: 16,
              fontWeight: FontWeight.w700,
              color: Color(0xFF252B38),
            ),
          ),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                SizedBox.square(
                  dimension: (MediaQuery.sizeOf(dialogContext).height * .28)
                      .clamp(80.0, 180.0),
                  child: Image.memory(bytes, fit: BoxFit.contain),
                ),
                const SizedBox(height: 8),
                const Text(
                  'Use an image you have permission to use. Check that the exact product and pack are upright, clear and fully visible.',
                  style: TextStyle(
                    fontSize: 12,
                    height: 1.35,
                    color: MoolColors.muted,
                  ),
                ),
              ],
            ),
          ),
          actions: [
            TextButton(
              style: TextButton.styleFrom(
                minimumSize: const Size(48, 48),
                textStyle: const TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w600,
                ),
              ),
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('Choose another'),
            ),
            TextButton(
              key: const Key('work-product-photo-confirm'),
              style: TextButton.styleFrom(
                minimumSize: const Size(48, 48),
                textStyle: const TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w600,
                ),
              ),
              onPressed: () => Navigator.pop(dialogContext, true),
              child: const Text('Use image'),
            ),
          ],
        ),
      );
      if (!mounted || !store.isCurrent()) return;
      if (accepted == true) {
        if (!photo.matches(_photoIdentity)) {
          _reject(
            'Product details changed. Choose the image for this exact pack again.',
          );
          return;
        }
        setState(() {
          _privatePhoto = photo;
          _error = null;
        });
      }
    } on WorkGatewayException catch (error) {
      if (mounted) _reject(error.message);
    } on Object {
      if (mounted) {
        _reject(
          'The product image could not be saved. Your existing product is unchanged. Try again.',
        );
      }
    } finally {
      if (mounted) setState(() => _choosingPhoto = false);
    }
  }

  Future<void> _confirmRetirement() async {
    if (_savingInventory || _choosingPhoto) return;
    final restore = !widget.product.counterSaleAllowed;
    FocusManager.instance.primaryFocus?.unfocus();
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        scrollable: true,
        titlePadding: const EdgeInsets.fromLTRB(16, 16, 16, 0),
        contentPadding: const EdgeInsets.fromLTRB(16, 10, 16, 8),
        actionsPadding: const EdgeInsets.fromLTRB(8, 0, 8, 8),
        titleTextStyle: const TextStyle(fontSize: 18, fontWeight: FontWeight.w700,
            color: MoolColors.navy),
        contentTextStyle: const TextStyle(fontSize: 14, height: 1.35,
            color: MoolColors.navy),
        title: Text(restore ? 'Resume Counter sale?' : 'Pause Counter sale?'),
        content: Text(
          restore
              ? 'Stock, history and public visibility stay unchanged. '
                'Unsaved edits are not applied.'
              : 'Stops Counter sale only. Stock, history and public visibility '
                'stay unchanged. Unsaved edits are not applied.',
        ),
        actions: [
          Flex(
            direction: MediaQuery.textScalerOf(dialogContext).scale(14) > 22
                ? Axis.vertical : Axis.horizontal,
            mainAxisSize: MainAxisSize.min,
            children: [
          Flexible(fit: FlexFit.loose, child: TextButton(
            key: const Key('work-product-retire-cancel'),
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('Cancel'),
          )),
          Flexible(fit: FlexFit.loose, child: TextButton(
            key: const Key('work-product-retire-confirm'),
            onPressed: () => Navigator.pop(dialogContext, true),
            child: Text(restore ? 'Resume' : 'Pause'),
          )),
            ],
          ),
        ],
      ),
    );
    if (!mounted || confirmed != true) return;
    if ((widget.session.activeWorkspace?.id ?? widget.session.workspaceId) !=
        _storeId) {
      _reject('Your store changed. Open this product in the correct store.');
      return;
    }
    if (!widget.session.workspaceCatalogueItems.any(
      (product) => product.id == widget.product.id,
    )) {
      _reject('This product is no longer in your catalogue.');
      return;
    }
    final changed = restore
        ? widget.session.restoreWorkspaceProduct(widget.product.id)
        : widget.session.retireWorkspaceProduct(widget.product.id);
    if (!changed) return;
    _finish();
  }

  Future<void> _requestEditorExit({VoidCallback? afterExit}) async {
    if (_savingInventory || _choosingPhoto || _confirmingEditorExit) return;
    if (_pendingInventorySave) {
      _reject('Saving is incomplete. Tap Save changes to retry before leaving.');
      return;
    }
    if (!_hasUnsavedEdits) {
      _finish(afterExit: afterExit);
      return;
    }
    _confirmingEditorExit = true;
    FocusManager.instance.primaryFocus?.unfocus();
    try {
      final discard = await showDialog<bool>(
        context: context,
        builder: (dialogContext) => AlertDialog(
          key: const Key('work-product-unsaved-dialog'),
          scrollable: true,
          titlePadding: const EdgeInsets.fromLTRB(16, 16, 16, 0),
          contentPadding: const EdgeInsets.fromLTRB(16, 10, 16, 8),
          actionsPadding: const EdgeInsets.fromLTRB(8, 0, 8, 8),
          title: const Text('Discard changes?', style: TextStyle(
            fontSize: 18, fontWeight: FontWeight.w700, color: MoolColors.navy)),
          content: const Text('Your edits have not been saved.', style: TextStyle(
            fontSize: 14, height: 1.35, color: MoolColors.navy)),
          actions: [
            TextButton(
              key: const Key('work-product-keep-editing'),
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('Keep editing'),
            ),
            TextButton(
              key: const Key('work-product-discard-edits'),
              onPressed: () => Navigator.pop(dialogContext, true),
              child: const Text('Discard changes'),
            ),
          ],
        ),
      );
      if (mounted && discard == true) _finish(afterExit: afterExit);
    } finally {
      _confirmingEditorExit = false;
    }
  }

  void _finish({VoidCallback? afterExit}) {
    FocusManager.instance.primaryFocus?.unfocus();
    // Rebuild PopScope before the approved save/discard performs its route pop.
    setState(() => _allowEditorExit = true);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      final done = afterExit ?? widget.onDone;
      if (done != null) {
        done();
      } else {
        Navigator.pop(context);
      }
    });
  }

  @override
  void initState() {
    super.initState();
    _storeId = widget.session.activeWorkspace?.id ?? widget.session.workspaceId;
    _wasOwned =
        widget.importRow == null &&
        widget.session.workspaceCatalogueItems.any(
          (item) => item.id == widget.product.id,
        );
    if (widget.initialField case final field?) {
      _expanded[_fieldSection(field)] = true;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        _fieldFocus[field]?.requestFocus();
        _revealImportIssue(field);
      });
    }
    if (widget.importRow case final row?) {
      final fields = _importControllers;
      for (final entry in row.rawValues.entries) {
        if (fields[entry.key] case final controller?) {
          if (WorkspaceProductImport.requiredColumns.contains(entry.key) ||
              entry.value.isNotEmpty) {
            controller.text = entry.value;
          }
        }
      }
      _initialImportInputs = {
        for (final entry in fields.entries) entry.key: entry.value.text,
      };
      if ((row.rawValues['sku'] ?? '').isEmpty &&
          !widget.product.matchesMasterCatalogueIdentity) {
        _sku.clear();
        _initialImportInputs['sku'] = '';
      }
      final field = row.issueValues.keys.firstOrNull;
      _error = row.issue;
      _errorField = field;
      if (field != null) _expanded[_fieldSection(field)] = true;
      if (field != null) _revealImportIssue(field);
    }
    for (final field in [
      _title,
      _brand,
      _pack,
      _variant,
      _barcode,
      _category,
      _composition,
      _regulatory,
      ..._contentFields.values,
      ..._packFields.values,
    ]) {
      field.addListener(_refreshIdentity);
    }
    _initialEditValues = {
      for (final entry in _importControllers.entries) entry.key: entry.value.text,
    };
  }

  void _refreshIdentity() => setState(() {});

  void _revealImportIssue(String field) {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      final target = _fieldKeys[field]?.currentContext;
      if (target != null) {
        unawaited(
          Scrollable.ensureVisible(
            target,
            alignment: .15,
            duration: const Duration(milliseconds: 180),
          ),
        );
      }
    });
  }

  Map<String, String> _initialImportInputs = {};
  static const _rawImportLabels = {
    'stockMode': 'Stock tracking',
    'available': 'Available for sale',
    'publicListing': 'Visibility value (import stays private)',
    'canonicalId': 'Catalogue reference from CSV',
  };
  late final _rawImportFields = <String, TextEditingController>{
    for (final entry
        in (widget.importRow?.rawValues ?? const <String, String>{}).entries)
      if (_rawImportLabels.containsKey(entry.key))
        entry.key: TextEditingController(text: entry.value),
  };
  Map<String, TextEditingController> get _importControllers => {
    'title': _title,
    'brand': _brand,
    'variant': _variant,
    'pack': _pack,
    'categoryId': _category,
    'sku': _sku,
    'barcode': _barcode,
    'purchasePrice': _purchase,
    'sellingPrice': _selling,
    'mrp': _mrp,
    'stock': _stock,
    'lowStockThreshold': _lowStockThreshold,
    'minimumOrder': _minimumOrder,
    'deliveryPromise': _delivery,
    'unitPrice': _unitPrice,
    'origin': _origin,
    'returnPolicy': _returnPolicy,
    'composition': _composition,
    'regulatoryNote': _regulatory,
    'visualLabel': _visualLabel,
    ..._contentFields,
    ..._sellingFields,
    ..._packFields,
    ..._rawImportFields,
  };

  void _applyImportCorrection() {
    final row = widget.importRow!;
    try {
      final corrected = widget.validateImport!({
        ...row.rawValues,
        // Preserve omitted/default and catalogue-prefilled values unless edited.
        for (final entry in _importControllers.entries)
          if (entry.value.text != _initialImportInputs[entry.key])
            entry.key: entry.value.text,
      });
      if (corrected.product == null) {
        _reject(
          corrected.issue ?? 'Check this product.',
          field: corrected.issueValues.keys.firstOrNull,
        );
        return;
      }
      if (!_categories.containsKey(corrected.product!.categoryId)) {
        _reject('Choose a category from the list.', field: 'categoryId');
        return;
      }
      _saved = true;
      FocusManager.instance.primaryFocus?.unfocus();
      _finish(afterExit: () => widget.onImportReviewed!(corrected));
    } on FormatException catch (error) {
      final field = error.message.split(':').first;
      _reject(
        error.message,
        field: _importControllers.containsKey(field) ? field : null,
      );
    }
  }

  late final TextEditingController _title = TextEditingController(
    text: widget.product.title,
  );
  late final TextEditingController _brand = TextEditingController(
    text: widget.product.brand,
  );
  late final TextEditingController _variant = TextEditingController(
    text: widget.product.variant,
  );
  late final TextEditingController _pack = TextEditingController(
    text: widget.product.pack,
  );
  late final TextEditingController _category = TextEditingController(
    text: widget.product.categoryId,
  );
  late final TextEditingController _sku = TextEditingController(
    text: widget.product.sku,
  );
  late final TextEditingController _barcode = TextEditingController(
    text: widget.product.barcode,
  );
  late final TextEditingController _purchase = TextEditingController(
    text: widget.product.purchasePrice == 0
        ? ''
        : '${widget.product.purchasePrice}',
  );
  late final TextEditingController _selling = TextEditingController(
    text: '${widget.product.sellingPrice}',
  );
  late final TextEditingController _mrp = TextEditingController(
    text: widget.product.mrp == null ? '' : '${widget.product.mrp}',
  );
  late final TextEditingController _stock = TextEditingController(
    text: '${widget.product.stock}',
  );
  late final TextEditingController _lowStockThreshold = TextEditingController(
    text: '${widget.product.lowStockThreshold}',
  );
  late final TextEditingController _delivery = TextEditingController(
    text: widget.product.deliveryPromise,
  );
  late final TextEditingController _unitPrice = TextEditingController(
    text: widget.product.unitPrice,
  );
  late final TextEditingController _origin = TextEditingController(
    text: widget.product.origin,
  );
  late final TextEditingController _minimumOrder = TextEditingController(
    text: '${widget.product.minimumOrder}',
  );
  late final TextEditingController _returnPolicy = TextEditingController(
    text: widget.product.returnPolicy ?? '',
  );
  late final TextEditingController _composition = TextEditingController(
    text: widget.product.composition ?? '',
  );
  late final TextEditingController _regulatory = TextEditingController(
    text: widget.product.regulatoryNote ?? '',
  );
  late final _contentFields = {
    for (final entry in widget.product.content.inputValues.entries)
      entry.key: TextEditingController(text: entry.value),
  };
  late final TextEditingController _visualLabel = TextEditingController(
    text: widget.product.visualLabel,
  );
  late final _sellingFields = <String, TextEditingController>{
    'quantityPerPack': TextEditingController(
      text: widget.product.packMeasure?.quantityText ?? '',
    ),
    'quantityUnit': TextEditingController(
      text: widget.product.packMeasure?.unitLabel ?? '',
    ),
    'unitsPerCase': TextEditingController(
      text: '${widget.product.packMeasure?.unitsPerCase ?? 1}',
    ),
    'sellingChannels': TextEditingController(
      text: widget.product.wholesaleOffer?.enabled == true
          ? widget.product.retailEnabled
                ? 'both'
                : 'wholesale'
          : 'retail',
    ),
    'wholesaleSaleType': TextEditingController(
      text: widget.product.wholesaleOffer?.saleType?.name ?? '',
    ),
    'wholesalePrice': TextEditingController(
      text: widget.product.wholesaleOffer == null
          ? ''
          : '${widget.product.wholesaleOffer!.priceRupees}',
    ),
    'wholesaleMinimum': TextEditingController(
      text: '${widget.product.wholesaleOffer?.minimumPacks ?? 1}',
    ),
    'wholesaleIncrement': TextEditingController(
      text: '${widget.product.wholesaleOffer?.incrementPacks ?? 1}',
    ),
    'wholesaleTiers': TextEditingController(
      text:
          widget.product.wholesaleOffer?.tiers
              .map(
                (tier) => '${tier.minimumPacks}:${tier.packPriceMinor ~/ 100}',
              )
              .join('; ') ??
          '',
    ),
  };
  Map<String, String> get _sellingInputValues => {
    for (final entry in _sellingFields.entries)
      // Empty quantity may remain a private draft; default case count alone
      // must not falsely imply that a pack quantity was supplied.
      if (!(entry.key.startsWith('wholesale') &&
              _sellingFields['sellingChannels']!.text == 'retail' &&
              widget.product.wholesaleOffer == null) &&
          !(entry.key == 'unitsPerCase' &&
              _sellingFields['quantityPerPack']!.text.trim().isEmpty &&
              widget.product.packMeasure == null))
        entry.key: entry.value.text,
  };
  static const _packFieldLabels = {
    'genericName': 'Generic product name',
    'netQuantity': 'Net quantity',
    'manufacturerName': 'Manufacturer',
    'packerName': 'Packer',
    'importerName': 'Importer, if applicable',
    'countryOfOrigin': 'Country of origin',
    'fssaiLicenseNumber': 'Manufacturer FSSAI number, if applicable',
    'consumerCare': 'Product consumer care',
  };
  late final _packFields = {
    for (final key in _packFieldLabels.keys)
      key: TextEditingController(
        text: widget.product.compliance?.toJson()[key] as String? ?? '',
      ),
  };
  Widget _packField(String field) => _field(
    widget.importRow == null ? 'pack-$field' : field,
    'work-product-pack-$field',
    _packFieldLabels[field]!,
    _packFields[field]!,
    hint: 'As printed on the pack',
    lines:
        {
          'genericName',
          'manufacturerName',
          'packerName',
          'importerName',
          'consumerCare',
        }.contains(field)
        ? 0
        : 1,
  );

  Widget _packFieldsLayout() => LayoutBuilder(
    builder: (context, constraints) {
      final sideBySide =
          constraints.maxWidth >= 300 &&
          MediaQuery.textScalerOf(context).scale(16) <= 19.2;
      return Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          _packField('genericName'),
          const SizedBox(height: 8),
          if (sideBySide)
            Row(
              key: const Key('work-product-pack-compact-row'),
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Expanded(flex: 2, child: _packField('netQuantity')),
                const SizedBox(width: 8),
                Expanded(flex: 3, child: _packField('countryOfOrigin')),
              ],
            )
          else ...[
            _packField('netQuantity'),
            const SizedBox(height: 8),
            _packField('countryOfOrigin'),
          ],
          for (final field in [
            'manufacturerName',
            'packerName',
            'importerName',
            'fssaiLicenseNumber',
            'consumerCare',
          ]) ...[const SizedBox(height: 8), _packField(field)],
          const SizedBox(height: 8),
        ],
      );
    },
  );

  WorkspaceProductCompliance get _packInformation =>
      WorkspaceProductCompliance.fromJson({
        ...?widget.product.compliance?.toJson(),
        for (final entry in _packFields.entries) entry.key: entry.value.text,
      })!;
  bool get _masterFactsChanged =>
      jsonEncode(_packInformation.toJson()) !=
          jsonEncode(
            (widget.product.compliance ?? const WorkspaceProductCompliance())
                .toJson(),
          ) ||
      _composition.text.trim() != (widget.product.composition ?? '').trim() ||
      _regulatory.text.trim() != (widget.product.regulatoryNote ?? '').trim() ||
      _contentFields.entries.any(
        (e) =>
            e.value.text.trim() !=
            widget.product.content.inputValues[e.key]!.trim(),
      );
  late bool _public = widget.product.publicListing;
  bool get _factsNeedReview =>
      widget.product.catalogueFactsRequireReview || _masterFactsChanged;
  late bool _available = widget.product.available;
  late final WorkspaceStockMode _stockMode = widget.product.stockMode;
  String? _error;

  bool get _catalogueMatched => widget.product
      .copyWith(
        title: _title.text.trim(),
        brand: _brand.text.trim(),
        pack: _pack.text.trim(),
        variant: _variant.text.trim(),
        categoryId: _category.text.trim(),
        barcode: _barcode.text.trim(),
      )
      .matchesMasterCatalogueIdentity;

  @override
  void dispose() {
    _title.dispose();
    _brand.dispose();
    _variant.dispose();
    _pack.dispose();
    _category.dispose();
    _sku.dispose();
    _barcode.dispose();
    _purchase.dispose();
    _selling.dispose();
    _mrp.dispose();
    _stock.dispose();
    _lowStockThreshold.dispose();
    _delivery.dispose();
    _unitPrice.dispose();
    _origin.dispose();
    _minimumOrder.dispose();
    _returnPolicy.dispose();
    _composition.dispose();
    _regulatory.dispose();
    for (final field in _contentFields.values) {
      field.dispose();
    }
    _visualLabel.dispose();
    for (final controller in _sellingFields.values) {
      controller.dispose();
    }
    for (final controller in _packFields.values) {
      controller.dispose();
    }
    for (final controller in _rawImportFields.values) {
      controller.dispose();
    }
    for (final node in _fieldFocus.values) {
      node.dispose();
    }
    super.dispose();
  }

  Future<void> _save() async {
    if (_saved || _savingInventory || _choosingPhoto) return;
    setState(() => _savingInventory = true);
    try {
      if (widget.importRow != null) {
        _applyImportCorrection();
        return;
      }
      if ((widget.session.activeWorkspace?.id ?? widget.session.workspaceId) !=
          _storeId || (widget.purchaseScope != null &&
              widget.purchaseScope != widget.session.workspaceSupplierScope)) {
        setState(
          () => _error =
              'Your store changed. Close this product and open it in the correct store.',
        );
        return;
      }
      if (widget.session.localInventoryEnabled &&
          widget.onDraftReviewed == null) {
        final ready = await widget.session.loadWorkspaceInventory(retry: true);
        if (!mounted) return;
        if (!ready ||
            (widget.session.activeWorkspace?.id ??
                    widget.session.workspaceId) !=
                _storeId || (widget.purchaseScope != null &&
                    widget.purchaseScope != widget.session.workspaceSupplierScope)) {
          setState(
            () => _error =
                widget.session.workspaceInventoryError ??
                'Return to this product’s Store before saving.',
          );
          return;
        }
      }
      if (!_wasOwned &&
          !_pendingInventorySave &&
          widget.session.workspaceCatalogueItems.any(
            (item) =>
                item.id == widget.product.id ||
                (item.canonicalId == widget.product.canonicalId &&
                    item.pack == _pack.text.trim() &&
                    item.variant == _variant.text.trim() &&
                    item.barcode == _barcode.text.trim()),
          )) {
        setState(
          () => _error =
              'This product was already added. Open it from Store stock to edit.',
        );
        return;
      }
      final duplicate = widget.session.workspaceCatalogueItems.any(
        (item) =>
            item.id != widget.product.id &&
            item.sku.trim().toLowerCase() == _sku.text.trim().toLowerCase(),
      );
      if (duplicate) {
        _reject(
          'This store SKU is already in use. Choose a different SKU.',
          field: 'sku',
        );
        return;
      }
      final purchase = int.tryParse(_purchase.text.trim());
      final selling = int.tryParse(_selling.text.trim());
      final mrp = int.tryParse(_mrp.text.trim());
      final stock = widget.purchaseScope != null ? 0 : _stockMode == WorkspaceStockMode.availabilityOnly
          ? widget.product.stock.clamp(0, 1 << 31).toInt()
          : int.tryParse(_stock.text.trim());
      final lowStockThreshold = int.tryParse(_lowStockThreshold.text.trim());
      final minimumOrder = int.tryParse(_minimumOrder.text.trim());
      final issue = workspaceProductValuesIssue(
        title: _title.text.trim(),
        brand: _brand.text.trim(),
        pack: _pack.text.trim(),
        category: _category.text.trim(),
        sku: _sku.text.trim(),
        purchase: purchase,
        selling: selling,
        stock: stock,
        mrp: mrp,
        lowStockThreshold: lowStockThreshold,
        minimumOrder: minimumOrder,
        delivery: _delivery.text.trim(),
      );
      if (issue != null) {
        _reject(issue.message, field: issue.field);
        return;
      }
      if (_privatePhoto != null && _matchingPhoto == null) {
        _reject(
          'Product details changed. Choose the image for this exact pack again, or remove it before saving.',
        );
        return;
      }
      if (!_categories.containsKey(_category.text.trim())) {
        _reject('Choose a category from the list.', field: 'categoryId');
        return;
      }
      if (_mrp.text.trim().isNotEmpty && mrp == null) {
        _reject('Enter MRP in whole rupees, or leave it empty.', field: 'mrp');
        return;
      }
      late final WorkspaceProductContent content;
      try {
        content = WorkspaceProductContent.parse({
          for (final entry in _contentFields.entries)
            entry.key: entry.value.text,
        });
      } on FormatException catch (error) {
        _reject(
          error.message.substring(error.message.indexOf(':') + 1).trim(),
          field: error.message.split(':').first,
        );
        return;
      }
      late final WorkspaceSellingInputs sellingInputs;
      try {
        sellingInputs = WorkspaceSellingInputs.parse(
          _sellingInputValues,
          clearBlankTiers: true,
          existingMeasure: widget.product.packMeasure,
          existingWholesale: widget.product.wholesaleOffer,
          existingRetailEnabled: widget.product.retailEnabled,
        );
      } on FormatException catch (error) {
        final field = error.message.split(':').first;
        _reject(
          error.message.substring(error.message.indexOf(':') + 1).trim(),
          field: field,
        );
        return;
      }
      if (sellingInputs.wholesale?.enabled == true &&
          mrp != null &&
          sellingInputs.wholesale!.priceRupees > mrp) {
        _reject(
          'Wholesale price cannot exceed the pack MRP.',
          field: 'wholesalePrice',
        );
        return;
      }
      final measureChanged =
          jsonEncode(sellingInputs.measure?.toJson()) !=
          jsonEncode(widget.product.packMeasure?.toJson());
      final reviewedProduct = widget.product.copyWith(
        privatePhoto: _matchingPhoto,
        clearPrivatePhoto: _matchingPhoto == null,
        content: content,
        packMeasure: sellingInputs.measure,
        wholesaleOffer: sellingInputs.wholesale,
        retailEnabled: sellingInputs.retailEnabled,
        categoryId: _category.text.trim(),
        brand: _brand.text.trim(),
        title: _title.text.trim(),
        variant: _variant.text.trim(),
        pack: _pack.text.trim(),
        sku: _sku.text.trim(),
        barcode: _barcode.text.trim(),
        purchasePrice: purchase,
        sellingPrice: selling,
        mrp: mrp,
        stock: stock,
        unitPrice:
            _unitPrice.text.trim().isEmpty ||
                _unitPrice.text.trim() == widget.product.unitPrice
            ? '₹$selling/${_pack.text.trim()}'
            : _unitPrice.text.trim(),
        deliveryPromise: _delivery.text.trim(),
        origin: _origin.text.trim(),
        visualLabel: _visualLabel.text.trim().isEmpty
            ? '${_brand.text.trim()} ${_title.text.trim()} ${_pack.text.trim()}'
            : _visualLabel.text.trim(),
        minimumOrder: minimumOrder,
        returnPolicy: _returnPolicy.text.trim(),
        composition: _composition.text.trim(),
        regulatoryNote: _regulatory.text.trim(),
        compliance: _packInformation,
        catalogueFactsRequireReview: _factsNeedReview || measureChanged,
        available: widget.purchaseScope != null ? false : _stockMode == WorkspaceStockMode.availabilityOnly ||
                (_wasOwned && !widget.product.available)
            ? _available
            : stock! > 0,
        publicListing:
            widget.purchaseScope == null && _public &&
            _catalogueMatched &&
            !_factsNeedReview &&
            !measureChanged &&
            (_stockMode == WorkspaceStockMode.availabilityOnly
                ? _available
                : stock! > 0),
        stockMode: _stockMode,
        lowStockThreshold: lowStockThreshold,
      );
      if (widget.onDraftReviewed != null) {
        _saved = true;
        FocusManager.instance.primaryFocus?.unfocus();
        _finish(afterExit: () => widget.onDraftReviewed!(
          reviewedProduct.copyWith(publicListing: false)));
        return;
      }
      if (!widget.session.addOrUpdateWorkspaceProduct(
        reviewedProduct, stockEntryMethod: widget.stockEntryMethod)) {
        _reject('Goods receipt is being saved. Your changes are kept; try again when it finishes.');
        return;
      }
      if (widget.session.localInventoryEnabled) {
        final persisted = _pendingInventorySave
            ? await widget.session.retryWorkspaceInventorySave()
            : await widget.session.workspaceInventorySaved;
        if (!mounted) return;
        if (!persisted ||
            (widget.session.activeWorkspace?.id ??
                    widget.session.workspaceId) !=
                _storeId || (widget.purchaseScope != null &&
                    widget.purchaseScope != widget.session.workspaceSupplierScope)) {
          _pendingInventorySave = true;
          setState(
            () => _error =
                widget.session.workspaceInventoryError ??
                'The Store changed before saving finished. Check its stock before continuing.',
          );
          return;
        }
      }
      _saved = true;
      if (widget.onSaved != null) {
        FocusManager.instance.primaryFocus?.unfocus();
        widget.session.showNotice(widget.purchaseScope == null ? 'Saved to Store stock.'
            : 'Product saved. Goods stay in your purchase draft until receipt.');
        _finish(afterExit: widget.onSaved);
      } else {
        _finish();
      }
    } finally {
      if (mounted) setState(() => _savingInventory = false);
    }
  }

  final _sectionKeys = <String, GlobalKey>{};
  final _fieldKeys = <String, GlobalKey>{};
  final _fieldFocus = <String, FocusNode>{};
  final _expanded = <String, bool>{'summary': true};
  String? _errorField;

  Map<String, String> get _categories => {
    for (final category in [
      ...BuyV2Catalogue.shopCategories,
      ...BuyV2Catalogue.wholesaleCategories,
    ])
      if (category.id != 'all') category.id: category.label,
    for (final item in workspaceMasterCatalogue)
      item.categoryId: item.categoryId
          .split('-')
          .map(
            (part) => part.isEmpty
                ? part
                : '${part[0].toUpperCase()}${part.substring(1)}',
          )
          .join(' '),
    'other': 'Other products',
  };

  String _fieldSection(String field) => _rawImportLabels.containsKey(field)
      ? 'reference'
      : WorkspaceProductImport.packFieldLabels.containsKey(field)
      ? 'pack'
      : WorkspaceProductContent.labels.containsKey(field)
      ? 'facts'
      : WorkspaceSellingInputs.labels.containsKey(field)
      ? 'selling'
      : {
          'title',
          'purchasePrice',
          'sellingPrice',
          'mrp',
          'stock',
          'lowStockThreshold',
          'minimumOrder',
        }.contains(field)
      ? 'summary'
      : 'details';

  void _reject(String message, {String? field}) {
    final section = field == null ? null : _fieldSection(field);
    setState(() {
      _error = message;
      _errorField = field;
      if (section != null) _expanded[section] = true;
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || field == null) return;
      _fieldFocus[field]?.requestFocus();
      if (widget.importRow != null) {
        _revealImportIssue(field);
        return;
      }
      final target = _fieldKeys[field]?.currentContext;
      if (target != null) {
        unawaited(
          Scrollable.ensureVisible(
            target,
            alignment: .25,
            duration: const Duration(milliseconds: 180),
          ),
        );
      }
    });
  }

  void _clearFieldError(String field) {
    if (_errorField == field) {
      setState(() {
        _error = null;
        _errorField = null;
      });
    }
  }

  Widget _field(
    String id,
    String keyName,
    String label,
    TextEditingController controller, {
    bool numeric = false,
    bool money = false,
    int lines = 1,
    String? hint,
  }) {
    final large = MediaQuery.textScalerOf(context).scale(1) > 1.2;
    final error = _errorField == id ? _error : null;
    return Container(
      key: _fieldKeys.putIfAbsent(id, () => GlobalKey()),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          if (large)
            Padding(
              padding: const EdgeInsets.only(bottom: 4),
              child: Text(
                label,
                key: Key('$keyName-label'),
                style: Theme.of(context).textTheme.bodySmall,
              ),
            ),
          TextField(
            key: Key(keyName),
            controller: controller,
            focusNode: _fieldFocus.putIfAbsent(id, () => FocusNode()),
            // Replace the initial zero on entry without clearing valid existing
            // prices/quantities or changing the stored value merely on focus.
            selectAllOnFocus: numeric ? controller.text == '0' : null,
            onTap: numeric
                ? () {
                    // Android's tap caret placement follows focus selection.
                    if (controller.text == '0') {
                      controller.selection = const TextSelection(
                        baseOffset: 0,
                        extentOffset: 1,
                      );
                    }
                  }
                : null,
            keyboardType: numeric
                ? TextInputType.number
                : lines > 1
                ? TextInputType.multiline
                : TextInputType.text,
            textInputAction: lines > 1
                ? TextInputAction.newline
                : TextInputAction.next,
            minLines: lines == 0 ? 1 : lines,
            maxLines: lines != 1 ? null : 1,
            scrollPadding: EdgeInsets.fromLTRB(16, large ? 64 : 24, 16, 104),
            onChanged: (_) {
              _clearFieldError(id);
              setState(() {});
            },
            decoration: InputDecoration(
              constraints: const BoxConstraints(minHeight: 48),
              labelText: large ? null : label,
              floatingLabelBehavior: FloatingLabelBehavior.always,
              hintText: hint,
              prefixText: money ? '₹ ' : null,
              error: error == null
                  ? null
                  : Semantics(
                      liveRegion: true,
                      child: Text(error, key: const Key('work-product-error')),
                    ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _group(List<Widget> fields) => LayoutBuilder(
    builder: (context, constraints) {
      final paired =
          constraints.maxWidth >= 300 &&
          MediaQuery.textScalerOf(context).scale(1) <= 1.2;
      final width = paired
          ? (constraints.maxWidth - 8) / 2
          : constraints.maxWidth;
      return Wrap(
        spacing: 8,
        runSpacing: 10,
        children: [
          for (final field in fields) SizedBox(width: width, child: field),
        ],
      );
    },
  );

  Widget _section(
    String id,
    String keyName,
    String title,
    List<Widget> children, {
    Widget? leading,
    bool initiallyExpanded = false,
  }) {
    final open = _expanded[id] ?? initiallyExpanded;
    return Container(
      key: Key(keyName),
      margin: const EdgeInsets.only(bottom: 6),
      decoration: BoxDecoration(
        color: Colors.white,
        gradient: id == 'summary'
            ? const LinearGradient(
                colors: [Color(0xfff2f4ff), Colors.white],
                begin: Alignment.topLeft,
                end: Alignment.bottomRight,
              )
            : null,
        border: Border.all(color: MoolColors.line),
        borderRadius: BorderRadius.circular(12),
      ),
      child: Material(
        color: Colors.transparent,
        child: Column(
          children: [
            Material(
              color: Colors.transparent,
              child: InkWell(
                key: _sectionKeys.putIfAbsent(id, () => GlobalKey()),
                borderRadius: BorderRadius.circular(12),
                onTap: () {
                  FocusManager.instance.primaryFocus?.unfocus();
                  setState(() => _expanded[id] = !open);
                },
                child: Semantics(
                  button: true,
                  expanded: open,
                  child: ConstrainedBox(
                    constraints: const BoxConstraints(minHeight: 48),
                    child: Padding(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 10,
                        vertical: 6,
                      ),
                      child: Row(
                        children: [
                          if (leading != null) ...[
                            leading,
                            const SizedBox(width: 10),
                          ],
                          Expanded(
                            child: Text(
                              title,
                              style: Theme.of(context).textTheme.titleMedium
                                  ?.copyWith(
                                    fontSize: 14,
                                    fontWeight: FontWeight.w600,
                                    color: MoolColors.navy,
                                  ),
                            ),
                          ),
                          Icon(
                            open ? Icons.expand_less : Icons.expand_more,
                            color: MoolColors.navy,
                            size: 22,
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
              ),
            ),
            if (open)
              Padding(
                padding: const EdgeInsets.fromLTRB(10, 4, 10, 10),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: children,
                ),
              ),
          ],
        ),
      ),
    );
  }

  Widget _sellingChoice(
    String field,
    String label,
    Map<String, String> choices,
  ) => Container(
    key: _fieldKeys.putIfAbsent(field, () => GlobalKey()),
    child: DropdownButtonFormField<String>(
      key: Key('work-product-$field'),
      initialValue: choices.containsKey(_sellingFields[field]!.text)
          ? _sellingFields[field]!.text
          : null,
      isExpanded: true,
      itemHeight: null,
      focusNode: _fieldFocus.putIfAbsent(field, () => FocusNode()),
      decoration: InputDecoration(
        labelText: label,
        errorText: _errorField == field ? _error : null,
      ),
      items: [
        for (final choice in choices.entries)
          DropdownMenuItem(value: choice.key, child: Text(choice.value)),
      ],
      onChanged: (value) {
        if (value == null) return;
        setState(() => _sellingFields[field]!.text = value);
        _clearFieldError(field);
      },
    ),
  );

  Widget _categoryField() => Container(
    key: _fieldKeys.putIfAbsent('categoryId', () => GlobalKey()),
    child: InkWell(
      key: const Key('work-product-category'),
      focusNode: _fieldFocus.putIfAbsent('categoryId', () => FocusNode()),
      onTap: () async {
        FocusScope.of(context).unfocus();
        final value = await showModalBottomSheet<String>(context: context,
          isScrollControlled: true, useSafeArea: true, showDragHandle: false,
          builder: (sheetContext) => Padding(
            padding: EdgeInsets.only(bottom: MediaQuery.viewInsetsOf(sheetContext).bottom),
            child: StoreCatalogueCategories(selected: _category.text,
              counts: {for (final id in _categories.keys) id: 0},
              label: (id) => _categories[id] ?? id,
              stockOnly: false, editorSelection: true)));
        if (!mounted || value == null || !_categories.containsKey(value)) return;
        setState(() => _category.text = value);
        _clearFieldError('categoryId');
      },
      child: InputDecorator(decoration: InputDecoration(
        labelText: 'Category',
        errorText: _errorField == 'categoryId' ? _error : null,
      ), child: Row(children: [
        Expanded(child: Text(_categories[_category.text] ?? 'Choose category')),
        const Icon(Icons.expand_more, size: 20),
      ])),
    ),
  );

  Widget _referenceLine(
    String title,
    String value, {
    bool selectable = false,
  }) => Padding(
    padding: const EdgeInsets.only(bottom: 8),
    child: Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(title, style: Theme.of(context).textTheme.bodySmall),
        selectable ? SelectableText(value) : Text(value),
      ],
    ),
  );

  @override
  Widget build(BuildContext context) {
    final keyboardInset = widget.embeddedPage
        ? 0.0
        : MediaQuery.viewInsetsOf(context).bottom;
    final product = widget.product.copyWith(
      privatePhoto: _matchingPhoto,
      clearPrivatePhoto: _matchingPhoto == null,
      title: _title.text.trim(),
      brand: _brand.text.trim(),
      pack: _pack.text.trim(),
      variant: _variant.text.trim(),
      barcode: _barcode.text.trim(),
      categoryId: _category.text.trim(),
    );
    return PopScope(
      // Check live inputs even when Back arrives before the next rebuild.
      canPop: !widget.guardRouteExit || _allowEditorExit,
      onPopInvokedWithResult: (didPop, result) {
        if (!didPop && widget.guardRouteExit) unawaited(_requestEditorExit());
      },
      child: StoreSettingsStyle(
      child: Builder(
        builder: (context) => Material(
          color: const Color(0xfff7f8fc),
          child: Padding(
            padding: EdgeInsets.only(bottom: keyboardInset),
            child: Column(
              children: [
                if (!widget.embeddedPage)
                  Row(
                    children: [
                      const SizedBox(width: 12),
