                                'variant',
                                'work-product-variant',
                                'Variant',
                                _variant,
                              ),
                              _field(
                                'pack',
                                'work-product-pack',
                                'Pack or size',
                                _pack,
                              ),
                              _field(
                                'sku',
                                'work-product-sku',
                                'Store SKU',
                                _sku,
                              ),
                              _field(
                                'barcode',
                                'work-product-barcode',
                                'Barcode',
                                _barcode,
                              ),
                            ]),
                            const SizedBox(height: 10),
                            _field(
                              'deliveryPromise',
                              'work-product-delivery',
                              'Customer delivery promise',
                              _delivery,
                            ),
                            const SizedBox(height: 10),
                            _group([
                              _field(
                                'unitPrice',
                                'work-product-unit-price',
                                'Unit price',
                                _unitPrice,
                                hint: 'Optional price per unit',
                              ),
                              _field(
                                'origin',
                                'work-product-origin',
                                'Origin / source',
                                _origin,
                              ),
                            ]),
                          ],
                          initiallyExpanded: widget.product.title.isEmpty,
                        ),
                        _section(
                          'selling',
