class _OrdersDestinationSurface extends StatefulWidget {
  const _OrdersDestinationSurface({
    required this.onOpenOrder,
    required this.session,
    required this.onOpenCollection,
    required this.onOpenDelivery,
    this.orderId,
  });

  final WorkSession session;
  final VoidCallback onOpenCollection;
  final VoidCallback onOpenDelivery;
  final String? orderId;

  final ValueChanged<String> onOpenOrder;

  @override
  State<_OrdersDestinationSurface> createState() =>
      _OrdersDestinationSurfaceState();
}

class _OrdersDestinationSurfaceState extends State<_OrdersDestinationSurface> {
  late String _filter;
  final _selectedFilterKey = GlobalKey();
  final _filterScroll = ScrollController();
  bool _filterOverflow = false, _atFilterEnd = false;
  bool _filterMetricsScheduled = false;

  @override
  void initState() {
    super.initState();
    _filter = widget.session.workspaceOrderFilter;
    _filterScroll.addListener(_scheduleFilterMetrics);
    _revealSelectedFilter();
  }

  @override
  void dispose() {
    _filterScroll.dispose();
    super.dispose();
  }

  void _scheduleFilterMetrics() {
    if (_filterMetricsScheduled) return;
    _filterMetricsScheduled = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _filterMetricsScheduled = false;
      if (!mounted || !_filterScroll.hasClients) return;
      final position = _filterScroll.position;
      final overflow = position.maxScrollExtent > 1;
      final atEnd = position.extentAfter <= 1;
      final cueWidthChanged = overflow != _filterOverflow;
      if (overflow != _filterOverflow || atEnd != _atFilterEnd) {
        setState(() {
          _filterOverflow = overflow;
          _atFilterEnd = atEnd;
        });
        // The cue takes space after the first layout. Reveal again in the
        // final viewport, but never snap the strip during manual scrolling.
        if (cueWidthChanged) _revealSelectedFilter();
      }
    });
  }

  void _scrollFilters() {
    if (!_filterScroll.hasClients) return;
    final position = _filterScroll.position;
    unawaited(
      _filterScroll.animateTo(
        (position.pixels +
                position.viewportDimension * (_atFilterEnd ? -.8 : .8))
            .clamp(0.0, position.maxScrollExtent),
        duration: MediaQuery.of(context).disableAnimations
            ? Duration.zero
            : const Duration(milliseconds: 180),
        curve: Curves.easeOut,
      ),
    );
  }

  @override
  void didUpdateWidget(covariant _OrdersDestinationSurface oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (_filter != widget.session.workspaceOrderFilter ||
        (oldWidget.orderId != null && widget.orderId == null)) {
      _filter = widget.session.workspaceOrderFilter;
      _revealSelectedFilter();
    }
  }

  void _revealSelectedFilter() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      final target = _selectedFilterKey.currentContext;
      if (target != null) {
        unawaited(Scrollable.ensureVisible(target, alignment: .5));
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    final session = widget.session;
    final allOrders = session.visibleWorkspaceOrders
        .where((order) => !_isCounterSaleOrder(order));
    bool matches(WorkspaceOrderRecord order, String filter) => switch (filter) {
      'Live' => !order.isClosed,
      'Done' => order.isClosed,
      _ => _storeOrderWorkFilter(order) == filter,
    };

    const filterLabels = {
      'Live': 'All',
      'New': 'New',
      'Packing': 'Packing',
      'Ready': 'Ready',
      'Delivery': 'Delivery',
      'Attention': 'Needs review',
      'Done': 'History',
    };
    final counts = {for (final filter in filterLabels.keys) filter: 0};
    final visibleOrders = <WorkspaceOrderRecord>[];
    for (final order in allOrders) {
      for (final filter in filterLabels.keys) {
        if (!matches(order, filter)) continue;
        counts[filter] = counts[filter]! + 1;
      }
      if (widget.orderId != null
          ? order.id == widget.orderId
          : matches(order, _filter)) {
        visibleOrders.add(order);
      }
    }
    final history = widget.orderId == null && _filter == 'Done';
    if (history) {
      visibleOrders.sort((a, b) {
        final placed = b.createdAt.compareTo(a.createdAt);
        return placed != 0 ? placed : a.id.compareTo(b.id);
      });
    }
    final indices = {
      for (var index = 0; index < visibleOrders.length; index++)
        visibleOrders[index].id: index,
    };
    int countFor(String filter) => counts[filter] ?? 0;
    final storeId = session.activeWorkspace?.id ?? session.workspaceId;
    _scheduleFilterMetrics();
    return Container(
      key: const Key('work-orders-destination'),
      color: Colors.white,
      child: Column(
        children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(14, 4, 14, 2),
            child: Row(
              children: [
                Expanded(
                  flex: 3,
                  child: Text(
                    widget.orderId == null
                        ? 'Customer orders'
                        : 'Order details',
                    style: TextStyle(
                      color: MoolColors.ink,
                      fontSize: widget.orderId == null ? 16 : 14,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                ),
                if (widget.orderId != null)
                  const SizedBox.shrink()
                else
                  Flexible(
                    flex: 2,
                    child: Text(
                      '${filterLabels[_filter]} · ${countFor(_filter)}'
                          '${_filter == 'Live' ? ' active' : ''}',
                      key: const Key('work-orders-current-scope'),
                      textAlign: TextAlign.end,
                      style: const TextStyle(
                        color: MoolColors.navy,
                        fontSize: 12,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                  ),
              ],
            ),
          ),
          if (widget.orderId == null)
            Row(
              children: [
                Expanded(
                  child: NotificationListener<ScrollMetricsNotification>(
                    onNotification: (_) {
                      _scheduleFilterMetrics();
                      return false;
                    },
                    child: SingleChildScrollView(
                      key: const Key('work-orders-filter-strip'),
                      controller: _filterScroll,
                      scrollDirection: Axis.horizontal,
                      padding: const EdgeInsets.symmetric(horizontal: 14),
                      child: Row(
                        children: [
                          for (final filter in filterLabels.keys.where(
                            (value) => value != 'Attention' ||
                                countFor(value) > 0 || _filter == value,
                          )) ...[
                            KeyedSubtree(
                              key: _filter == filter ? _selectedFilterKey : null,
                              child: ChoiceChip(
                                key: Key('work-orders-filter-${filter.toLowerCase()}'),
                                showCheckmark: false,
                                backgroundColor: Colors.white,
                                selectedColor: const Color(0xFFF4F5FA),
                                surfaceTintColor: Colors.transparent,
                                labelPadding: const EdgeInsets.symmetric(horizontal: 4),
                                padding: const EdgeInsets.symmetric(horizontal: 4),
                                materialTapTargetSize: MaterialTapTargetSize.padded,
                                visualDensity: VisualDensity.standard,
                                side: BorderSide(
                                  color: _filter == filter
                                      ? MoolColors.navy : const Color(0xFFE3E6EE),
                                  width: .7,
                                ),
                                shape: RoundedRectangleBorder(
                                  borderRadius: BorderRadius.circular(7),
                                ),
                                labelStyle: TextStyle(
                                  fontSize: 12,
                                  fontWeight: _filter == filter
                                      ? FontWeight.w700 : FontWeight.w500,
                                  color: MoolColors.navy,
                                ),
                                label: Text('${filterLabels[filter]} ${countFor(filter)}'),
                                selected: _filter == filter,
                                onSelected: (_) {
                                  widget.session.setWorkspaceOrderFilter(filter);
                                  setState(() => _filter = filter);
                                  _revealSelectedFilter();
                                },
                              ),
                            ),
                            const SizedBox(width: 5),
                          ],
                        ],
                      ),
                    ),
                  ),
                ),
                if (_filterOverflow)
                  IconButton(
                    key: const Key('work-orders-filter-more'),
                    tooltip: _atFilterEnd
                        ? 'Earlier order stages' : 'More order stages',
                    constraints: const BoxConstraints(minWidth: 48, minHeight: 48),
                    onPressed: _scrollFilters,
                    icon: Icon(
                      _atFilterEnd
                          ? Icons.chevron_left_rounded : Icons.chevron_right_rounded,
                      size: 20,
                      color: MoolColors.navy,
                    ),
                  ),
              ],
            ),
          Expanded(
            child: visibleOrders.isNotEmpty
                ? ListView.builder(
                    key: PageStorageKey((
                      'work-orders-queue',
                      storeId,
                      _filter,
                      widget.orderId,
                    )),
                    padding: EdgeInsets.fromLTRB(14, widget.orderId == null ? 10 : 0, 14, 14),
                    itemCount: visibleOrders.length,
                    addAutomaticKeepAlives: false,
                    findChildIndexCallback: (key) {
                      if (key is! ValueKey<(String?, String)> ||
                          key.value.$1 != storeId) {
                        return null;
                      }
                      return indices[key.value.$2];
                    },
                    itemBuilder: (context, index) {
                      final order = visibleOrders[index];
                      return Padding(
                        key: ValueKey<(String?, String)>((storeId, order.id)),
                        padding: EdgeInsets.only(bottom: history ? 0 : 8),
                        child: history
                            ? _OrdersHistoryRow(
                                session: session,
                                order: order,
                                onOpen: () => widget.onOpenOrder(order.id),
                              )
                            : _LiveOrderTicket(
                          session: session,
                          detailed: widget.orderId != null,
                          onOpenCollection: widget.onOpenCollection,
                          order: order,
                          active:
                              session.hasActiveWorkspaceOrder &&
                              (session.currentWorkspaceOrderId == null ||
                                  order.id == session.currentWorkspaceOrderId),
                          onOpenDelivery: widget.onOpenDelivery,
                        ),
                      );
                    },
                  )
                : Align(
                    alignment: Alignment.topLeft,
                    child: SingleChildScrollView(
                      key: const Key('work-orders-empty-state'),
                      padding: const EdgeInsets.fromLTRB(14, 10, 14, 14),
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            widget.orderId != null ? 'Order unavailable' : switch (_filter) {
                              'Done' => 'No past orders yet',
                              'New' => 'No new orders',
                              'Packing' => 'No orders awaiting packing',
                              'Ready' => 'No orders ready for pickup',
                              'Delivery' => 'No orders awaiting delivery',
                              'Attention' => 'No orders need review',
                              _ => 'No active orders',
                            },
                            style: const TextStyle(
                              color: MoolColors.ink,
                              fontSize: 14,
                              fontWeight: FontWeight.w600,
                            ),
                          ),
                          const SizedBox(height: 4),
                          Text(
                            widget.orderId != null
                                ? 'Return to the order list and search again.'
                                : _filter == 'Done'
                                ? 'Completed and cancelled customer orders are saved here. Counter sales are in Sales.'
                                : 'Customer orders appear here when they reach this stage. Counter sales are in Sales.',
                            style: const TextStyle(
                              color: Color(0xFF4C5268), fontSize: 12,
                            ),
                          ),
                          if (widget.orderId == null && _filter != 'Done' && countFor('Done') > 0)
                            TextButton.icon(
                              key: const Key('work-orders-empty-history'),
                              style: TextButton.styleFrom(
                                foregroundColor: MoolColors.navy,
                                minimumSize: const Size(48, 48),
                                padding: EdgeInsets.zero,
                              ),
                              onPressed: () {
                                session.setWorkspaceOrderFilter('Done');
                                setState(() => _filter = 'Done');
                                _revealSelectedFilter();
                              },
                              icon: const Icon(Icons.history_rounded, size: 16),
                              label: Text('View past orders · ${countFor('Done')}'),
                            ),
                        ],
                      ),
                    ),
                  ),
          ),
        ],
      ),
    );
  }
}

class _ExactOrderInformation extends StatelessWidget {
  const _ExactOrderInformation({
    required this.order,
    required this.showItems,
    this.paymentLabel,
    this.showPayment = true,
    this.showFacts = true,
    this.invoiceStyle = false,
    this.stageLabel,
    this.showAmounts = true,
  });
  final WorkspaceOrderRecord order;
  final bool showItems;
  final String? paymentLabel;
  final bool showPayment;
  final bool showFacts;
  final bool invoiceStyle;
  final String? stageLabel;
  final bool showAmounts;

  static String _price(int paise) {
    final fraction = paise % 100;
    return '₹${_formatStoreAmount(paise ~/ 100)}'
        '${fraction == 0 ? '' : '.${fraction.toString().padLeft(2, '0')}'}';
  }

  @override
  Widget build(BuildContext context) {
    if (invoiceStyle) return _invoiceInformation(context);
    final localizations = MaterialLocalizations.of(context);
    final placed = order.createdAt.toLocal();
    final facts = <(String, String)>[
      (
        'Placed',
        '${localizations.formatShortDate(placed)} · '
            '${localizations.formatTimeOfDay(TimeOfDay.fromDateTime(placed))}',
      ),
      ('Ordered via', order.source == 'App' ? 'MoolSocial app' : order.source),
      if (showPayment)
        (
          'Payment',
          paymentLabel ??
              (order.payment.isEmpty
                  ? 'Awaiting payment update'
                  : order.payment),
        ),
      (
        'Receive by',
        order.isCustomerCollection
            ? 'Collect at store'
            : order.fulfilment.isEmpty
            ? 'Awaiting confirmation'
            : order.fulfilment,
      ),
      if (order.needsDelivery || order.address.trim().isNotEmpty)
        (
          'Deliver to',
          order.address.trim().isEmpty
              ? 'Address not yet available'
              : order.address,
        ),
    ];
    return Column(
      key: Key('work-exact-order-information-${order.id}'),
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        if (showFacts) const Divider(height: 20, color: Color(0xFFE5E8F1)),
        for (final fact in showFacts ? facts : const <(String, String)>[])
          Padding(
            padding: const EdgeInsets.symmetric(vertical: 4),
            child: MediaQuery.textScalerOf(context).scale(1) >= 1.8
                ? Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        fact.$1,
                        style: const TextStyle(
                          color: MoolColors.muted,
                          fontSize: 12,
                        ),
                      ),
                      Text(
                        fact.$2,
                        style: const TextStyle(
                          color: MoolColors.ink,
                          fontSize: 13,
                        ),
                      ),
                    ],
                  )
                : Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      SizedBox(
                        width: 90,
                        child: Text(
                          fact.$1,
                          style: const TextStyle(
                            color: MoolColors.muted,
                            fontSize: 12,
                          ),
                        ),
                      ),
                      Expanded(
                        child: Text(
                          fact.$2,
                          style: const TextStyle(
                            color: MoolColors.ink,
                            fontSize: 13,
                          ),
                        ),
                      ),
                    ],
                  ),
          ),
        if (showItems) ...[
          const Divider(height: 24, color: Color(0xFFE5E8F1)),
          const Text(
            'Ordered items',
            style: TextStyle(
              color: MoolColors.navy,
              fontSize: 14,
              fontWeight: FontWeight.w700,
            ),
          ),
          if (order.hasCompleteItemSnapshot)
            for (final line in order.itemSnapshots)
              Padding(
                key: Key('work-exact-order-item-${line.productId}'),
                padding: const EdgeInsets.symmetric(vertical: 10),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text(
                      line.name,
                      style: const TextStyle(
                        color: MoolColors.ink,
                        fontSize: 14,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                    if (line.pack.trim().isNotEmpty)
                      Text(
                        line.pack,
                        style: const TextStyle(
                          color: MoolColors.muted,
                          fontSize: 12,
                        ),
                      ),
                    const SizedBox(height: 5),
                    _StoreMoneyLine(
                      leading: Text(
                        '${line.quantity} × ${_price(line.unitPricePaise)}',
                        style: const TextStyle(
                          color: MoolColors.muted,
                          fontSize: 12,
                        ),
                      ),
                      value: _price(line.lineTotalPaise),
                      style: const TextStyle(
                        color: MoolColors.navy,
                        fontSize: 14,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ],
                ),
              )
          else ...[
            const SizedBox(height: 8),
            Text(
              order.items,
              style: const TextStyle(color: MoolColors.ink, fontSize: 13),
            ),
            const SizedBox(height: 6),
            const Text(
              'Item prices are not available on this order.',
              key: Key('work-exact-order-prices-unavailable'),
              style: TextStyle(color: MoolColors.muted, fontSize: 12),
            ),
          ],
        ],
      ],
    );
  }

  // Opt-in Orders details only; approved invoice/collection callers stay intact.
  Widget _invoiceInformation(BuildContext context) {
    final localizations = MaterialLocalizations.of(context);
    String date(DateTime value) {
      final local = value.toLocal();
      return '${localizations.formatShortDate(local)} · '
          '${localizations.formatTimeOfDay(TimeOfDay.fromDateTime(local))}';
    }
    final lines = order.itemSnapshots;
    final reconciled = order.hasCompleteItemSnapshot &&
        order.validBillAmounts &&
        lines.fold<int>(0, (sum, line) => sum + line.lineTotalPaise) ==
            order.payableMinor &&
        lines.fold<int>(0, (sum, line) =>
            sum + line.quantity * line.unitPricePaise) == order.subtotalMinor;
    final facts = <(String, String)>[
      ('Placed', date(order.createdAt)),
      ('Order status', order.stage == 'Confirmed'
          ? 'Awaiting acceptance' : stageLabel ?? order.stage),
      if (showPayment) ('Payment', (paymentLabel ?? order.payment).trim().isEmpty
          ? 'Payment details unavailable' : paymentLabel ?? order.payment),
      ('Fulfilment', order.isCustomerCollection ? 'Collect at store'
          : order.fulfilment.isEmpty ? 'Awaiting confirmation' : order.fulfilment),
      if (order.fulfilmentDeadline case final deadline?)
        ('Fulfil by', date(deadline)),
      if (!order.isClosed)
        if (order.actionDeadline case final deadline?)
          ('Accept by', date(deadline)),
      if (order.needsDelivery || order.address.trim().isNotEmpty)
        ('Deliver to', order.address.trim().isEmpty
            ? 'Address not yet available' : order.address),
      if (order.rejectionReason?.trim().isNotEmpty == true)
        ('Cancellation reason', order.rejectionReason!),
    ];
    return Column(
      key: Key('work-exact-order-information-${order.id}'),
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Wrap(spacing: 12, runSpacing: 2, children: [
          Text(order.source == 'Counter' ? 'Counter Sale'
              : order.source == 'App' ? 'MoolSocial order' : order.source,
              style: const TextStyle(fontSize: 11, color: MoolColors.muted)),
          for (final fact in facts.where((fact) =>
              fact.$1 == 'Order status' || fact.$1 == 'Payment'))
            Row(mainAxisSize: MainAxisSize.min, children: [
              Text('${fact.$1 == 'Order status' ? 'Order' : 'Payment'} · ',
                  style: const TextStyle(fontSize: 12, color: MoolColors.muted)),
              Flexible(child: Text(fact.$2,
                  key: fact.$1 == 'Order status'
                      ? Key('work-order-stage-label-${order.id}') : null,
                  style: const TextStyle(fontSize: 12, color: MoolColors.navy,
                      fontWeight: FontWeight.w600))),
            ]),
        ]),
        for (final fact in facts.where((fact) =>
            fact.$1 != 'Order status' && fact.$1 != 'Payment'))
          Padding(
            padding: const EdgeInsets.symmetric(vertical: 2),
            child: _StoreScaledPair(
              first: Text(fact.$1, style: const TextStyle(
                  color: MoolColors.muted, fontSize: 11)),
              second: Text(fact.$2,
                  key: fact.$1 == 'Order status'
                      ? Key('work-order-stage-label-${order.id}') : null,
                  textAlign: TextAlign.end,
                  style: const TextStyle(color: MoolColors.ink,
                      fontSize: 11, fontWeight: FontWeight.w500)),
            ),
          ),
        if (showItems) ...[
          const Divider(height: 16, color: Color(0xFFE5E8F1)),
          const Text('Ordered items', style: TextStyle(
            color: MoolColors.navy, fontSize: 13, fontWeight: FontWeight.w600)),
          if (order.hasCompleteItemSnapshot) ...[
            const Padding(
              padding: EdgeInsets.only(top: 6, bottom: 2),
              child: Row(children: [
                Expanded(child: Text('Quantity × price', style: TextStyle(
                    color: MoolColors.muted, fontSize: 11))),
                Text('Amount', style: TextStyle(
                    color: MoolColors.muted, fontSize: 11)),
              ]),
            ),
            for (final line in lines)
              Container(
                key: Key('work-exact-order-item-${line.productId}'),
                padding: const EdgeInsets.symmetric(vertical: 7),
                decoration: const BoxDecoration(border: Border(
                    bottom: BorderSide(color: Color(0xFFE8EAF0), width: .6))),
                child: Column(crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                  Text(line.name, style: const TextStyle(color: MoolColors.ink,
                      fontSize: 13, fontWeight: FontWeight.w600)),
                  if (line.pack.trim().isNotEmpty)
                    Text(line.pack, style: const TextStyle(
                        color: MoolColors.muted, fontSize: 11)),
                  _StoreMoneyLine(
                    alignAmountToEnd: true,
                    leading: Text('${line.quantity} × ${_price(line.unitPricePaise)}',
                        style: const TextStyle(color: MoolColors.ink, fontSize: 12)),
                    value: _price(reconciled
                        ? line.unitPricePaise * line.quantity : line.lineTotalPaise),
                    style: const TextStyle(color: MoolColors.ink,
                        fontSize: 13, fontWeight: FontWeight.w600),
                  ),
                ]),
              ),
          ] else ...[
            Text(order.items, style: const TextStyle(
                color: MoolColors.ink, fontSize: 13)),
            const Text('Item prices are not available on this order.',
                key: Key('work-exact-order-prices-unavailable'),
                style: TextStyle(color: MoolColors.muted, fontSize: 12)),
          ],
        ],
        if (showAmounts) ...[
        const SizedBox(height: 8),
        if (reconciled && order.discountMinor > 0) ...[
          _StoreMoneyLine(alignAmountToEnd: true,
              leading: const Text('Subtotal', style: TextStyle(
                  color: MoolColors.muted, fontSize: 12)),
              value: _price(order.subtotalMinor),
              style: const TextStyle(color: MoolColors.ink,
                  fontSize: 13, fontWeight: FontWeight.w600)),
          _StoreMoneyLine(alignAmountToEnd: true,
              leading: Text(order.discount.kind == 'percentage'
                  ? 'Bill discount (${order.discount.value / 100}%)' : 'Bill discount',
                  style: const TextStyle(color: MoolColors.muted, fontSize: 12)),
              value: '−${_price(order.discountMinor)}',
              style: const TextStyle(color: MoolColors.ink,
                  fontSize: 13, fontWeight: FontWeight.w600)),
        ],
        if (!reconciled)
          const Text('Price breakdown unavailable · saved total shown',
              key: Key('work-order-breakdown-unavailable'),
              style: TextStyle(color: MoolColors.muted, fontSize: 11)),
        _StoreMoneyLine(
          alignAmountToEnd: true,
          leading: const Text('Order total', style: TextStyle(
              color: MoolColors.navy, fontSize: 14, fontWeight: FontWeight.w700)),
          value: _price(order.payableMinor),
          style: const TextStyle(color: MoolColors.navy,
              fontSize: 14, fontWeight: FontWeight.w700),
        ),
        ],
      ],
    );
  }
}

// History presentation only: exact details and commands retain their owners.
class _OrdersHistoryRow extends StatelessWidget {
  const _OrdersHistoryRow({
    required this.session,
    required this.order,
    required this.onOpen,
    this.searchResult = false,
  });

  final WorkSession session;
  final WorkspaceOrderRecord order;
  final VoidCallback onOpen;
  final bool searchResult;

  @override
  Widget build(BuildContext context) {
    final placed = order.createdAt.toLocal();
    final localizations = MaterialLocalizations.of(context);
    final stage = session.workspaceOrderStageLabel(order);
    final payment = session.workspaceOrderPaymentLabel(order);
    final source = order.source == 'App' ? 'MoolSocial app' : order.source;
    final preview = order.hasCompleteItemSnapshot
        ? order.itemSnapshots
              .take(2)
              .map(
                (item) =>
                    '${item.name}${item.pack.isEmpty ? '' : ' · ${item.pack}'}',
              )
              .join(' · ')
        : order.items;
    final storeId = session.activeWorkspace?.id ?? session.workspaceId;
    return Material(
      color: Colors.white,
      child: InkWell(
        key: Key(searchResult ? 'work-search-order-${order.id}'
            : 'work-order-history-open-${order.id}'),
        onTap: () {
          if (storeId != (session.activeWorkspace?.id ?? session.workspaceId)) {
            return;
          }
          onOpen();
        },
        child: Container(
          constraints: const BoxConstraints(minHeight: 48),
          padding: const EdgeInsets.symmetric(vertical: 10),
          decoration: const BoxDecoration(
            border: Border(bottom: BorderSide(color: Color(0xFFE8EAF0))),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              _StoreMoneyLine(
                alignAmountToEnd: true,
                leading: Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Expanded(
                      child: Text(
                        searchResult ? _savedOrderCustomerName(session, order) : order.customer,
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: MoolColors.ink,
                          fontSize: 13,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                    ),
                    const Icon(
                      Icons.chevron_right_rounded,
                      color: MoolColors.navy,
                      size: 18,
                    ),
                  ],
                ),
                value: '₹${_formatStoreMinorAmount(order.payableMinor)}',
                style: const TextStyle(
                  color: MoolColors.navy,
                  fontSize: 14,
                  fontWeight: FontWeight.w700,
                ),
              ),
              const SizedBox(height: 3),
              if (searchResult && _savedOrderCustomerName(session, order) != order.customer)
                Text(order.customer, style: const TextStyle(
                    color: MoolColors.ink, fontSize: 11)),
              Text(
                order.id,
                key: Key('work-order-history-reference-${order.id}'),
                style: const TextStyle(color: MoolColors.ink, fontSize: 11),
              ),
              Text(
                '${localizations.formatShortDate(placed)} · ${localizations.formatTimeOfDay(TimeOfDay.fromDateTime(placed))}',
                key: Key('work-order-history-date-${order.id}'),
                style: const TextStyle(color: MoolColors.muted, fontSize: 11),
              ),
              Wrap(
                spacing: 8,
                runSpacing: 2,
                children: [
                  Text(
                    stage,
                    key: Key('work-order-stage-label-${order.id}'),
                    style: const TextStyle(
                      color: MoolColors.navy,
                      fontSize: 11,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                  Text(
                    payment,
                    style: const TextStyle(color: MoolColors.ink, fontSize: 11),
                  ),
                  if (source.isNotEmpty || order.fulfilment.isNotEmpty)
                    Text(
                      [
                        source,
                        order.isCustomerCollection
                            ? 'Collect at store'
                            : order.fulfilment,
                      ].where((part) => part.isNotEmpty).join(' · '),
                      style: const TextStyle(
                        color: MoolColors.muted,
                        fontSize: 11,
                      ),
                    ),
                ],
              ),
              if (preview.isNotEmpty) ...[
                const SizedBox(height: 3),
                Text(
                  preview,
                  key: Key('work-order-history-items-${order.id}'),
                  maxLines: 2,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(color: MoolColors.ink, fontSize: 11),
                ),
              ],
              if (order.hasCompleteItemSnapshot &&
                  order.itemSnapshots.length > 2)
                Text(
                  '+${order.itemSnapshots.length - 2} more products',
                  style: const TextStyle(color: MoolColors.muted, fontSize: 11),
                ),
            ],
          ),
        ),
      ),
    );
  }
}

class _LiveOrderTicket extends StatelessWidget {
  const _LiveOrderTicket({
    required this.session,
    required this.onOpenCollection,
    required this.order,
    required this.active,
    required this.onOpenDelivery,
    this.detailed = false,
  });

  final WorkSession session;
  final VoidCallback onOpenCollection;
  final WorkspaceOrderRecord order;
  final bool active;
  final VoidCallback onOpenDelivery;
  final bool detailed;

  @override
  Widget build(BuildContext context) {
    final stage = order.stage;
    final storeId = session.activeWorkspace?.id ?? session.workspaceId;
    final invoiceAccount = session.workspaceFinance?.accountScope;
    final linkedInvoices = detailed ? session.workspaceInvoices.where(
        (invoice) => invoice.orderId == order.id).toList() : <WorkspaceCustomerInvoice>[];
    final inlineInvoice = linkedInvoices.length == 1 ? linkedInvoices.single : null;
    String savedName(WorkspaceBillingDetails? billing) => billing == null ? ''
        : billing.business && billing.businessName.trim().isNotEmpty
        ? billing.businessName.trim() : billing.name.trim();
    final invoiceName = savedName(inlineInvoice?.billingDetails);
    final orderName = savedName(order.billingDetails);
    final exactPayments = detailed && session.workspaceFinance?.workspaceId == storeId
        ? session.workspaceFinance!.payments.where((payment) => payment.valid &&
            payment.orderId == order.id &&
            (inlineInvoice == null || payment.invoiceId == inlineInvoice.id)).toList()
        : <WorkspacePaymentRecord>[];
    final paymentName = exactPayments.length == 1
        ? exactPayments.single.customerName.trim() : '';
    final customerName = invoiceName.isNotEmpty ? invoiceName
        : orderName.isNotEmpty ? orderName
        : paymentName.isNotEmpty ? paymentName : order.customer;
    final hasCustomerName = customerName.trim().isNotEmpty &&
        !RegExp(r'^\+?[\d\s()-]+$').hasMatch(customerName.trim());
    bool sameStore() =>
        context.mounted &&
        storeId == (session.activeWorkspace?.id ?? session.workspaceId);
    bool currentActionIsValid() {
      if (!sameStore() ||
          session.busy ||
          session.workspaceOperationsSyncing ||
          session.workspaceHandoverBusy ||
          session.currentCollection?.needsReconciliation == true) {
        return false;
      }
      if (detailed && session.currentWorkspaceOrderId != order.id) {
        final current = session.visibleWorkspaceOrders
            .where((record) => record.id == order.id)
            .firstOrNull;
        if (current == null ||
            current.isClosed ||
            current.stage != stage ||
            !session.selectWorkspaceOrder(order.id)) {
          return false;
        }
      }
      return session.workspaceOrderStage == stage &&
          (session.currentWorkspaceOrderId == order.id ||
              (session.currentWorkspaceOrderId == null &&
                  session.visibleWorkspaceOrders.length == 1 &&
                  session.visibleWorkspaceOrders.single.id == order.id));
    }

    final packingLines = stage == 'Preparing' && !order.isCustomerCollection
        ? session.workspacePackingLinesForOrder(order)
        : const <WorkspacePackingLine>[];
    final itemSnapshots = order.hasCompleteItemSnapshot
        ? {for (final line in order.itemSnapshots) line.productId: line}
        : const <String, WorkspaceOrderItemSnapshot>{};
    final packedUnits = packingLines
        .where((line) => line.packed)
        .fold<int>(0, (total, line) => total + line.quantity);
    final totalUnits = packingLines.fold<int>(
      0,
      (total, line) => total + line.quantity,
    );
    final nextAction = switch (stage) {
      'Confirmed' => 'Accept',
      'Preparing' => 'Mark ready',
      'Ready for pickup' => 'Confirm pickup',
      'Ready' when order.needsDelivery => 'Arrange delivery',
      'Ready' => 'Complete pickup',
      'Delivery requested' => 'Track delivery',
      _ when order.isDeliveryInProgress => 'Track delivery',
      _ => 'Review',
    };
    return _OrderDeadlineBoundary(
      deadline: stage == 'Confirmed' ? order.actionDeadline : null,
      builder: (expired) => Material(
        key: const Key('work-live-order-ticket'),
        color: Colors.white,
        elevation: 0,
        shadowColor: const Color(0x16001B4D),
        borderRadius: BorderRadius.circular(12),
        child: Padding(
          padding: EdgeInsets.symmetric(
            horizontal:
                detailed ? 0 : MediaQuery.sizeOf(context).width < 360 &&
                    MediaQuery.textScalerOf(context).scale(1) >= 2
                ? 6
                : 13,
            vertical: detailed ? 4 : 13,
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              if (detailed) ...[
                Wrap(spacing: 10, runSpacing: 2, crossAxisAlignment: WrapCrossAlignment.center,
                    children: [Text(hasCustomerName ? customerName : order.customer,
                    key: hasCustomerName ? const Key('work-order-customer-name') : null,
                    style: const TextStyle(
                    color: MoolColors.ink, fontSize: 13, fontWeight: FontWeight.w600)),
                if (hasCustomerName && customerName != order.customer)
                  Text(order.customer, style: const TextStyle(
                      color: MoolColors.muted, fontSize: 11)),
                if (!hasCustomerName)
                  const Text('Customer name not recorded',
                      key: Key('work-order-customer-name'),
                      style: TextStyle(color: MoolColors.muted, fontSize: 11))]),
                Text(order.id, key: const Key('work-focused-order-id'),
                    style: const TextStyle(color: MoolColors.muted, fontSize: 11)),
                const SizedBox(height: 2),
              ] else if (order.isCustomerCollection)
                Text(
                  '${order.id} · ${session.workspaceOrderStageLabel(order)}',
                  key: Key('work-order-stage-label-${order.id}'),
                  style: const TextStyle(
                    fontSize: 12,
                    color: MoolColors.navy,
                    fontWeight: FontWeight.w700,
                  ),
                )
              else
                _StoreMoneyLine(
                  leading: Wrap(
                    spacing: 8,
                    runSpacing: 2,
                    crossAxisAlignment: WrapCrossAlignment.center,
                    children: [
                      Text(
                        stage == 'Confirmed'
                            ? expired
                                  ? 'Order update pending'
                                  : order.actionDeadline != null
                                  ? 'Accept within'
                                  : 'Awaiting acceptance'
                            : stage,
                        key: Key('work-order-stage-label-${order.id}'),
                        style: const TextStyle(
                          color: MoolColors.navy,
                          fontSize: 10,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      if (order.actionDeadline case final deadline?)
                        _LiveCountdownText(
                          deadline: deadline,
                          fallback: 'Review',
                          style: const TextStyle(
                            color: MoolColors.navy,
                            fontSize: 10,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                    ],
                  ),
                  value: '₹${_formatStoreMinorAmount(order.payableMinor)}',
                  style: const TextStyle(
                    color: MoolColors.navy,
                    fontSize: 19,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              if (!detailed) const SizedBox(height: 8),
              if (!detailed) Text(
                order.customer,
                style: const TextStyle(
                  color: MoolColors.ink,
                  fontSize: 16,
                  fontWeight: FontWeight.w900,
                ),
              ),
              if (!detailed)
                Text(
                  order.isCustomerCollection
                      ? '${session.workspaceOrderPaymentLabel(order)} · Collect at store'
                      : '${order.source} · ${session.workspaceOrderPaymentLabel(order)} · ${order.fulfilment}',
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                    color: MoolColors.muted,
                    fontSize: 10.5,
                  ),
                ),
              if (!detailed) const SizedBox(height: 7),
              if (detailed)
                _ExactOrderInformation(
                  order: order,
                  showItems: packingLines.isEmpty && inlineInvoice == null,
                  showAmounts: inlineInvoice == null,
                  showPayment: inlineInvoice == null,
                  paymentLabel: session.workspaceFinanceStale
                      ? 'Last saved: ${session.workspaceOrderPaymentLabel(order)}'
                      : session.workspaceOrderPaymentLabel(order),
                  invoiceStyle: true,
                  stageLabel: session.workspaceOrderStageLabel(order),
                ),
              if (detailed && inlineInvoice != null)
                _StoreInvoiceSurface(
                  key: ValueKey((storeId, invoiceAccount, inlineInvoice.id)),
                  session: session, invoice: inlineInvoice, embedded: true,
                  orderDetails: true, onClose: () {}),
              if (detailed && linkedInvoices.length > 1)
                const Text('Invoice link needs review. Return to Sales to check the original bill.',
                    key: Key('work-order-invoice-link-unavailable'),
                    style: TextStyle(color: MoolColors.muted, fontSize: 12)),
              if (detailed && inlineInvoice == null && linkedInvoices.isEmpty)
                const Text('No linked invoice in the saved records.',
                    style: TextStyle(color: MoolColors.muted, fontSize: 11)),
              _StoreIssueReviews(
                session: session,
                target: WorkspaceIssueTarget.customerOrder,
                referenceId: order.id,
              ),
              if (!detailed && packingLines.isEmpty)
                Text(
                  order.items,
                  style: const TextStyle(
                    color: MoolColors.ink,
                    fontSize: 11,
                    fontWeight: FontWeight.w700,
                  ),
                ),
              if (packingLines.isNotEmpty) ...[
                const SizedBox(height: 10),
                Row(
                  children: [
                    Expanded(
                      child: LinearProgressIndicator(
                        value: totalUnits == 0 ? 0 : packedUnits / totalUnits,
                        minHeight: 7,
                        borderRadius: BorderRadius.circular(999),
                      ),
                    ),
                    const SizedBox(width: 10),
                    Text(
                      '$packedUnits/$totalUnits packed',
                      style: const TextStyle(
                        color: MoolColors.navy,
                        fontSize: 10,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 5),
                for (final line in packingLines)
                  Material(
                    color: const Color(0xFFF4F6FF),
                    borderRadius: BorderRadius.circular(12),
                    child: CheckboxListTile(
                      key: Key(
                        active
                            ? 'work-order-pack-${line.id}'
                            : 'work-order-pack-${order.id}-${line.id}',
                      ),
                      dense: true,
                      visualDensity: VisualDensity.compact,
                      contentPadding: const EdgeInsets.symmetric(horizontal: 8),
                      controlAffinity: ListTileControlAffinity.trailing,
                      value: line.packed,
                      onChanged: (value) {
                        if (!sameStore() ||
                            (active && !currentActionIsValid())) {
                          return;
                        }
                        session.setWorkspaceOrderPackingLine(
                          storeId: storeId,
                          orderId: order.id,
                          lineId: line.id,
                          quantity: line.quantity,
                          packed: value == true,
                        );
                      },
                      title: Text(
                        detailed && itemSnapshots.containsKey(line.id)
                            ? '${itemSnapshots[line.id]!.name} · '
                                  '${itemSnapshots[line.id]!.pack} × ${line.quantity}'
                            : '${line.label} × ${line.quantity}',
                        style: const TextStyle(
                          color: MoolColors.ink,
                          fontSize: 10.5,
                          fontWeight: FontWeight.w800,
                        ),
                      ),
                      subtitle: detailed && itemSnapshots.containsKey(line.id)
                          ? Text(
                              'Each ${_ExactOrderInformation._price(itemSnapshots[line.id]!.unitPricePaise)} · '
                              'Total ${_ExactOrderInformation._price(itemSnapshots[line.id]!.lineTotalPaise)}',
                              style: const TextStyle(
                                color: MoolColors.muted,
                                fontSize: 12,
                              ),
                            )
                          : null,
                    ),
                  ),
              ],
              if (order.isCustomerCollection)
                Align(
                  alignment: Alignment.centerRight,
                  child: TextButton(
                    key: Key('work-order-collection-open-${order.id}'),
                    onPressed: () {
                      if (sameStore() &&
                          session.selectWorkspaceOrder(order.id)) {
                        onOpenCollection();
                      }
                    },
                    child: Text(
                      order.isClosed ? 'View collection' : 'Open collection',
                    ),
                  ),
                )
              else if (session.workspaceOrderOperationState(order.id) != null)
                _OrderOperationStatus(session: session, orderId: order.id)
              else if ((active && !order.isClosed) ||
                  (detailed && !order.isClosed && stage != 'Preparing')) ...[
                const SizedBox(height: 10),
                Wrap(
                  alignment: WrapAlignment.end,
                  spacing: 12,
                  crossAxisAlignment: WrapCrossAlignment.center,
                  children: [
                    if (stage == 'Confirmed')
                      TextButton(
                        onPressed:
                            expired ||
                                session.busy ||
                                session.workspaceOperationsSyncing
                            ? null
                            : () {
                                if (currentActionIsValid()) {
                                  _showRejectOrderSheet(context, session);
                                }
                              },
                        child: const Text('Reject'),
                      ),
                    FilledButton.icon(
                      onPressed:
                          expired ||
                              session.busy ||
                              session.workspaceOperationsSyncing ||
                              session.workspaceHandoverBusy ||
                              (stage == 'Preparing' &&
                                  !session.workspaceCanMarkReady)
                          ? null
                          : () {
                              if (!currentActionIsValid() ||
                                  (stage == 'Preparing' &&
                                      !session.workspaceCanMarkReady)) {
                                return;
                              }
                              if (stage == 'Ready for pickup') {
                                _showWorkspacePickupSheet(context, session);
                              } else if (order.isDeliveryInProgress &&
                                  stage != 'Ready') {
                                onOpenDelivery();
                              } else if (stage == 'Ready' &&
                                  order.needsDelivery) {
                                session.advanceWorkspaceOrder();
                                onOpenDelivery();
                              } else {
                                _advanceDeskOrder(
                                  session,
                                  expectedOrderId: order.id,
                                );
                              }
                            },
                      style: FilledButton.styleFrom(
                        minimumSize: const Size(48, 48),
                        padding: const EdgeInsets.symmetric(horizontal: 16),
                      ),
                      icon: const Icon(Icons.arrow_forward_rounded, size: 17),
                      label: Text(nextAction),
                    ),
                  ],
                ),
              ] else if (stage == 'Preparing') ...[
                Align(
                  alignment: Alignment.centerRight,
                  child: FilledButton(
                    key: Key('work-order-ready-${order.id}'),
                    onPressed:
                        session.busy ||
                            session.workspaceOperationsSyncing ||
                            session.workspaceHandoverBusy ||
                            packingLines.isEmpty ||
                            packingLines.any((line) => !line.packed)
                        ? null
                        : () {
                            final current = session.visibleWorkspaceOrders
                                .where((record) => record.id == order.id)
                                .firstOrNull;
                            final currentLines = current == null
                                ? const <WorkspacePackingLine>[]
                                : session.workspacePackingLinesForOrder(
                                    current,
                                  );
                            if (!sameStore() ||
                                current?.stage != 'Preparing' ||
                                current?.isCustomerCollection == true ||
                                currentLines.isEmpty ||
                                currentLines.any((line) => !line.packed) ||
                                !session.selectWorkspaceOrder(order.id) ||
                                !currentActionIsValid()) {
                              return;
                            }
                            _advanceDeskOrder(
                              session,
                              expectedOrderId: order.id,
                            );
                          },
                    child: const Text('Order ready'),
                  ),
                ),
              ] else if (!order.isClosed) ...[
                Align(
                  alignment: Alignment.centerRight,
                  child: TextButton(
                    key: Key('work-order-open-${order.id}'),
                    onPressed:
                        session.busy ||
                            session.workspaceOperationsSyncing ||
                            session.workspaceHandoverBusy
                        ? null
                        : () {
                            if (sameStore()) {
                              session.selectWorkspaceOrder(order.id);
                            }
                          },
                    child: const Text('Open order'),
                  ),
                ),
              ],
            ],
          ),
        ),
      ),
    );
  }
}

class _DeliveryDestinationSurface extends StatelessWidget {
  const _DeliveryDestinationSurface({
    required this.session,
    required this.onCreateOrder,
  });

  final WorkSession session;
  final VoidCallback onCreateOrder;

  @override
  Widget build(BuildContext context) {
    final hasConfirmedDelivery =
        session.workspaceOrderCustomer.isNotEmpty &&
        session.workspaceOrderNeedsDelivery;
    if (hasConfirmedDelivery) {
      return Container(
        key: const Key('work-delivery-destination'),
        decoration: const BoxDecoration(
          gradient: LinearGradient(
            colors: [Color(0xFFF9FAFF), Color(0xFFEFF3FF)],
          ),
        ),
        padding: const EdgeInsets.fromLTRB(18, 16, 18, 28),
        child: _ActivityDeckShell(
          state:
              '${session.currentWorkspaceOrderId}:${session.workspaceOrderStage}',
          child: _DeliveryActivityCard(session: session),
        ),
      );
    }
    return Container(
      key: const Key('work-delivery-destination'),
      decoration: const BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [Color(0xFFF9FAFF), Color(0xFFEEF2FF)],
        ),
      ),
      child: Padding(
        padding: const EdgeInsets.all(20),
        child: Column(
          children: [
            const Spacer(),
            Container(
              width: 112,
              height: 112,
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                color: MoolColors.navy,
                boxShadow: [
                  BoxShadow(
                    color: MoolColors.navy.withValues(alpha: .22),
                    blurRadius: 28,
                  ),
                ],
              ),
              child: const Icon(
                Icons.delivery_dining_rounded,
                color: Colors.white,
                size: 52,
              ),
            ),
            const SizedBox(height: 22),
            const Text(
              'Deliver an offline order',
              style: TextStyle(
                color: MoolColors.ink,
                fontSize: 23,
                fontWeight: FontWeight.w900,
              ),
            ),
            const SizedBox(height: 7),
            const Text(
              'Record a Phone, Counter or Chat order, confirm the customer address and request delivery.',
              textAlign: TextAlign.center,
              style: TextStyle(color: MoolColors.muted, height: 1.35),
            ),
            const SizedBox(height: 22),
            const Row(
              mainAxisAlignment: MainAxisAlignment.spaceAround,
              children: [
                _DeliverySourceIcon(
                  icon: Icons.phone_in_talk_outlined,
                  label: 'Phone',
                ),
                _DeliverySourceIcon(
                  icon: Icons.storefront_outlined,
                  label: 'Counter',
                ),
                _DeliverySourceIcon(
                  icon: Icons.chat_bubble_outline_rounded,
                  label: 'Chat',
                ),
                _DeliverySourceIcon(
                  icon: Icons.receipt_long_outlined,
                  label: 'Existing',
                ),
              ],
            ),
            const Spacer(),
            SizedBox(
              width: double.infinity,
              child: FilledButton.icon(
                key: const Key('work-delivery-start-order'),
                onPressed: onCreateOrder,
                icon: const Icon(Icons.arrow_forward_rounded),
                label: const Text('Record delivery order'),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

