/// Existing financial destinations share one scoped projection, with no local
/// money-moving capability. Summary totals are not inferred from partial rows.
class _CustomerLedgerStatement extends StatelessWidget {
  const _CustomerLedgerStatement({required this.ledger});
  final WorkspaceCustomerLedger ledger;

  @override
  Widget build(BuildContext context) {
    var running = ledger.openingBalanceMinor;
    final balances = <int?>[
      for (final entry in ledger.entries)
        running = running == null ? null : running + entry.balanceDeltaMinor,
    ];
    final closing = ledger.closingBalanceMinor;
    return ExpansionTile(
      key: PageStorageKey(
        'customer-ledger-${ledger.accountScope}-${ledger.workspaceId}-${ledger.customerId}',
      ),
      tilePadding: EdgeInsets.zero,
      title: Text(ledger.customerName),
      subtitle: Text(
        closing == null
            ? 'Customer statement · Balance unavailable'
            : 'Customer statement · ${closing < 0 ? 'Credit' : 'Due'} ${_purchaseAmount(closing.abs())}',
      ),
      children: [
        const Align(
          alignment: Alignment.centerLeft,
          child: Text('Available transaction history'),
        ),
        _MoneyDestinationLine(
          label: 'Opening balance',
          value: ledger.openingBalanceMinor == null
              ? 'Unavailable'
              : _purchaseAmount(ledger.openingBalanceMinor!),
        ),
        if (!ledger.historyComplete)
          const Text(
            'History is incomplete. A closing balance cannot be confirmed.',
          ),
        for (var i = 0; i < ledger.entries.length; i++)
          Padding(
            key: ValueKey('customer-ledger-entry-${ledger.entries[i].id}'),
            padding: const EdgeInsets.symmetric(vertical: 8),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                _MoneyDestinationLine(
                  label: switch (ledger.entries[i].kind) {
                    WorkspaceLedgerEntryKind.invoice => 'Invoice',
                    WorkspaceLedgerEntryKind.collection => 'Payment received',
                    WorkspaceLedgerEntryKind.creditNote => 'Return credit',
                    WorkspaceLedgerEntryKind.refund => 'Refund',
                    WorkspaceLedgerEntryKind.creditUsed => 'Customer credit used',
                    WorkspaceLedgerEntryKind.creditReceived => 'Customer credit applied',
                  },
                  value: _purchaseAmount(ledger.entries[i].amountMinor),
                ),
                Text(
                  '${ledger.entries[i].invoiceId} · ${ledger.entries[i].orderId}',
                ),
                if (ledger.entries[i].channel !=
                    WorkspacePaymentChannel.unknown)
                  Text(ledger.entries[i].channel.label),
                if (ledger.entries[i].paymentReference?.isNotEmpty == true)
                  Text('Reference ${ledger.entries[i].paymentReference}'),
                Text(
                  MaterialLocalizations.of(
                    context,
                  ).formatShortDate(ledger.entries[i].occurredAt.toLocal()),
                ),
                if (ledger.entries[i].state !=
                    WorkspaceLedgerPostingState.posted)
                  Text(
                    ledger.entries[i].state ==
                            WorkspaceLedgerPostingState.pending
                        ? 'Pending · Balance unchanged'
                        : 'Failed · Balance unchanged',
                  ),
                if (ledger.historyComplete && balances[i] != null)
                  _MoneyDestinationLine(
                    label: balances[i]! < 0 ? 'Customer credit' : 'Balance due',
                    value: _purchaseAmount(balances[i]!.abs()),
                  ),
              ],
            ),
          ),
      ],
    );
  }
}

// Unknown/pending credit history must not be treated as unused return capacity.
int? _remainingReturnUnits(WorkspaceOrderRecord order,
    WorkspacePaymentRecord payment, WorkspaceCustomerLedger? ledger) {
  if (!order.isCompleted || !order.hasCompleteItemSnapshot ||
      payment.invoiceId == null || ledger == null || !ledger.historyComplete ||
      ledger.customerId != payment.customerId) { return null; }
  final credits = ledger.entries.where((entry) =>
    entry.invoiceId == payment.invoiceId && entry.kind == WorkspaceLedgerEntryKind.creditNote);
  if (credits.any((entry) => entry.state == WorkspaceLedgerPostingState.pending ||
      (entry.state == WorkspaceLedgerPostingState.posted && entry.customerReturn == null))) { return null; }
  final returned = credits.where((entry) => entry.state == WorkspaceLedgerPostingState.posted)
      .expand((entry) => entry.customerReturn!.lines);
  var remaining = 0;
  for (final item in order.itemSnapshots) {
    final quantity = item.quantity - returned.where((line) => line.productId == item.productId)
        .fold<int>(0, (sum, line) => sum + line.quantity);
    if (quantity < 0) return null;
    remaining += quantity;
  }
  return remaining;
}

class _StoreFinanceSurface extends StatelessWidget {
  const _StoreFinanceSurface({
    required this.session,
    this.section = 'settlement',
    this.focus,
    this.onOpenInvoice,
    this.returnsOnly = false,
  });
  final WorkSession session;
  final String section;
  final _WorkspaceFinanceFocus? focus;
  final ValueChanged<WorkspaceCustomerInvoice>? onOpenInvoice;
  final bool returnsOnly;

  @override
  Widget build(BuildContext context) {
    final finance = session.workspaceFinance;
    final target = focus;
    final exactPayment = finance?.payments
        .where(
          (p) =>
              p.orderId == target?.orderId &&
              p.customerId == target?.customerId,
        )
        .firstOrNull;
    final exactPayout = finance?.payouts
        .where(
          (p) =>
              p.id == target?.payoutId && p.operationId == target?.operationId,
        )
        .firstOrNull;
    if (target != null &&
        (finance == null ||
            finance.accountScope != target.accountScope ||
            finance.workspaceId != target.workspaceId ||
            (exactPayment == null && exactPayout == null))) {
      return ListView(
        key: const Key('work-finance-record-unavailable'),
        padding: const EdgeInsets.all(16),
        children: const [
          Text('This payment record is unavailable.'),
          Text('Return to Alerts for the latest update.'),
        ],
      );
    }
    if (finance != null && section == 'expenses') {
      return _StoreExpensesSurface(
        key: ValueKey((finance.accountScope, finance.workspaceId)),
        session: session,
      );
    }
    if (finance == null) {
      return ListView(
        key: const Key('work-finance-unavailable'),
        padding: const EdgeInsets.all(16),
        children: [
          _DeskEmpty(
            icon: Icons.account_balance_outlined,
            title: section == 'expenses'
                ? 'Expense updates unavailable'
                : 'Payment updates unavailable',
            detail: section == 'expenses'
                ? 'Linked business expenses will appear here.'
                : 'Your confirmed payments and settlement balance will appear here when available.',
          ),
        ],
      );
    }
    final start = target == null && section == 'payments'
        ? session.workspaceMoneyPeriodStart
        : null;
    final settlementCheck = finance.settlementPaidReconciliation;
    final payments =
        target != null
              ? [?exactPayment]
              : finance.payments
                    .where(
                      (p) =>
                          (section != 'dues' || p.dueMinor > 0) &&
                          (start == null || !p.updatedAt.isBefore(start)),
                    )
                    .toList()
          ..sort((a, b) => a.orderId.compareTo(b.orderId));
    final payouts = target != null
        ? [?exactPayout]
        : section == 'settlement'
        ? finance.payouts
        : const <WorkspacePayoutRecord>[];
    final orders = {for (final o in session.visibleWorkspaceOrders) o.id: o};
    final ledgers =
        target == null && (section == 'dues' || section == 'payments')
        ? finance.customerLedgers
        : const <WorkspaceCustomerLedger>[];
    return ListView.builder(
      key: ValueKey('work-finance-$section'),
      padding: EdgeInsets.symmetric(
        horizontal:
            target != null && MediaQuery.textScalerOf(context).scale(14) > 21
            ? 8
            : 16,
        vertical: 16,
      ),
      itemCount: 1 + ledgers.length + payouts.length + payments.length,
      itemBuilder: (context, index) {
        if (index == 0) {
          return Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Text(
                target != null
                    ? (target.payoutId != null
                          ? 'Settlement details'
                          : returnsOnly ? 'Returns & refunds' : 'Payment details')
                    : section == 'settlement'
                    ? 'Settlement balance'
                    : section == 'dues'
                    ? 'Collect dues'
                    : 'Customer payments',
                style: TextStyle(
                  fontSize: target != null ? 16 : 20,
                  fontWeight: FontWeight.w800,
                  color: MoolColors.navy,
                ),
              ),
              Text(
                'Updated ${MaterialLocalizations.of(context).formatShortDate(finance.asOf.toLocal())} · '
                '${MaterialLocalizations.of(context).formatTimeOfDay(TimeOfDay.fromDateTime(finance.asOf.toLocal()))}',
                style: const TextStyle(fontSize: 11, color: MoolColors.muted),
              ),
              if (session.workspaceFinanceStale)
                const Text(
                  'Showing the last confirmed update. Current payment status is unavailable.',
                  key: Key('work-finance-stale'),
                ),
              if (session.pendingCustomerReturn != null) ...[
                Text(
                  session.customerReturnSaved
                      ? 'A return is awaiting confirmation. Its details are saved; do not enter it again.'
                      : 'Return details are not saved yet. Keep this bill open and retry.',
                ),
                TextButton(
                  onPressed: session.customerCollectionBusy
                      ? null
                      : () => session.reconcileCustomerReturn(),
                  child: Text(
                    session.customerReturnSaved
                        ? 'Check return status'
                        : 'Retry saving return',
                  ),
                ),
                const SizedBox(height: 8),
              ],
              if (session.pendingCustomerRefund != null) ...[
                Text(
                  session.customerRefundSaved
                      ? 'A refund is awaiting confirmation. Its details are saved; do not record it again.'
                      : 'Refund details are not saved yet. Keep this bill open and retry.',
                ),
                TextButton(
                  onPressed: session.customerCollectionBusy
                      ? null
                      : session.reconcileCustomerRefund,
                  child: Text(
                    session.customerRefundSaved
                        ? 'Check refund status'
                        : 'Retry saving refund',
                  ),
                ),
              ],
              if (session.pendingCustomerCollection != null) ...[
                const Text(
                  'A collection is awaiting confirmation. Do not record it again.',
                ),
                TextButton(
                  onPressed: session.customerCollectionBusy
                      ? null
                      : session.reconcileCustomerCollection,
                  child: const Text('Check collection status'),
                ),
              ],
              if (session.customerLedgerRecoveryError != null) ...[
                Text(session.customerLedgerRecoveryError!),
                TextButton(
                  onPressed: session.customerCollectionBusy
                      ? null
                      : session.recoverCustomerLedger,
                  child: const Text('Retry ledger recovery'),
                ),
              ],
              const SizedBox(height: 12),
              if (target == null && section == 'settlement') ...[
                for (final fact in <(String, int)>[
                  ('Available for settlement', finance.availableMinor),
                  ('On hold', finance.heldMinor),
                  ('Requested', finance.requestedMinor),
                  ('Paid to bank', finance.paidOutMinor),
                ])
                  _MoneyDestinationLine(
                    label: fact.$1,
                    value: _purchaseAmount(fact.$2),
                  ),
                const SizedBox(height: 8),
                const FilledButton(
                  onPressed: null,
                  child: Text('Request settlement'),
                ),
                const Text(
                  'Settlement requests are not connected yet. No money will move from this screen.',
                  style: TextStyle(fontSize: 12, color: MoolColors.muted),
                ),
                const SizedBox(height: 12),
                Text(
                  session.workspaceFinanceStale || settlementCheck == null
                      ? 'Settlement reconciliation unavailable.'
                      : settlementCheck.differenceMinor == null
                      ? 'Full payout history is needed to reconcile this total.'
                      : settlementCheck.differenceMinor == 0
                      ? 'Paid-out total matches the supplied payout records.'
                      : 'Paid-out total and payout records differ. Check the settlement update.',
                  key: const Key('work-settlement-reconciliation'),
                ),
                if (settlementCheck != null)
                  _MoneyDestinationLine(
                    label: 'Recorded paid payouts',
                    value: _purchaseAmount(settlementCheck.recordedMinor),
                  ),
                const Text(
                  'Requests and processing payouts are excluded. These records do not show your bank account balance.',
                  style: TextStyle(fontSize: 12, color: MoolColors.muted),
                ),
                const Divider(height: 24),
                const Text(
                  'Reported adjustments',
                  style: TextStyle(fontWeight: FontWeight.w700),
                ),
                for (final fact in <(String, int)>[
                  ('MoolSocial fees', finance.feesMinor),
                  ('Delivery adjustments', finance.deliveryAdjustmentsMinor),
                  ('Refunds', finance.refundsMinor),
                  ('Tax withheld', finance.taxWithheldMinor),
                ])
                  _MoneyDestinationLine(
                    label: fact.$1,
                    value: _purchaseAmount(fact.$2),
                  ),
              ],
              if (target == null && section == 'dues')
                _MoneyDestinationLine(
                  label: 'Unpaid balance',
                  value: _purchaseAmount(finance.duesMinor),
                ),
              if (target == null && !finance.historyComplete)
                const Padding(
                  padding: EdgeInsets.symmetric(vertical: 10),
                  child: Text(
                    'Showing available records. Full history is not available yet.',
                  ),
                ),
              if (payments.isEmpty &&
                  payouts.isEmpty &&
                  !((section == 'dues' || section == 'payments') &&
                      finance.customerLedgers.isNotEmpty))
                Text(
                  finance.historyComplete
                      ? 'No matching records in this view.'
                      : 'No matching updates available.',
                ),
            ],
          );
        }
        if (index <= ledgers.length) {
          return _CustomerLedgerStatement(ledger: ledgers[index - 1]);
        }
        final recordIndex = index - ledgers.length;
        if (recordIndex <= payouts.length) {
          final payout = payouts[recordIndex - 1];
          return Padding(
            key: ValueKey('work-finance-payout-${payout.id}'),
            padding: const EdgeInsets.symmetric(vertical: 12),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                const Divider(height: 16),
                _MoneyDestinationLine(
                  label: '${payout.id} · ${payout.state.label}',
                  value: _purchaseAmount(payout.amountMinor),
                ),
                if (payout.bankLabel?.isNotEmpty == true)
                  Text(payout.bankLabel!),
                if (payout.expectedBy?.isNotEmpty == true &&
                    {
                      WorkspacePayoutState.requested,
                      WorkspacePayoutState.processing,
                    }.contains(payout.state))
                  Text('Expected by ${payout.expectedBy}'),
                if (payout.message?.isNotEmpty == true) Text(payout.message!),
              ],
            ),
          );
        }
        final payment = payments[recordIndex - 1 - payouts.length];
        final order = orders[payment.orderId];
        final receiptLedger = finance.customerLedgers.where((ledger) =>
            ledger.accountScope == finance.accountScope &&
            ledger.workspaceId == finance.workspaceId &&
            ledger.customerId == payment.customerId).firstOrNull;
        final receiptChannels = receiptLedger?.recordedReceiptChannels(
            payment.invoiceId ?? '', payment.orderId) ?? <WorkspacePaymentChannel>{};
        final remainingReturnUnits = order == null ? null
            : _remainingReturnUnits(order, payment, receiptLedger);
        final mixedMethods = receiptChannels.length > 1
            ? 'Mixed payment · ${receiptChannels.map((channel) => switch (channel) {
                WorkspacePaymentChannel.cash => 'Cash',
                WorkspacePaymentChannel.directUpi => 'UPI',
                WorkspacePaymentChannel.bankTransfer => 'Bank transfer',
                _ => channel.label,
              }).join(' + ')}'
            : null;
        return Padding(
          key: ValueKey('work-finance-payment-${payment.orderId}'),
          padding: const EdgeInsets.symmetric(vertical: 12),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              const Divider(height: 16),
              _MoneyDestinationLine(
                label: '${payment.customerName} · ${payment.orderId}',
                value: _purchaseAmount(
                  section == 'dues' ? payment.dueMinor : payment.amountMinor,
                ),
              ),
              Text(
                payment.label,
                style: const TextStyle(
                  fontWeight: FontWeight.w700,
                  color: MoolColors.navy,
                ),
              ),
              if (mixedMethods != null || payment.state != WorkspacePaymentState.paid)
                Text(mixedMethods ?? payment.channel.label),
              if (order != null)
                Text(
                  'Order · ${order.stage == 'Confirmed' ? 'Awaiting acceptance' : session.workspaceOrderStageLabel(order)}',
                ),
              if (section != 'dues' && payment.dueMinor > 0)
                _MoneyDestinationLine(
                  label: 'Still due',
                  value: _purchaseAmount(payment.dueMinor),
                ),
              if (payment.paidMinor > 0 &&
                  payment.paidMinor != payment.amountMinor)
                _MoneyDestinationLine(
                  label: 'Paid so far',
                  value: _purchaseAmount(payment.paidMinor),
                ),
              if (payment.refundedMinor > 0)
                _MoneyDestinationLine(
                  label: 'Refunded',
                  value: _purchaseAmount(payment.refundedMinor),
                ),
              if (payment.invoiceId?.isNotEmpty == true)
                Text('Invoice ${payment.invoiceId}'),
              if (onOpenInvoice != null &&
                  session.workspaceInvoices.any(
                    (invoice) =>
                        invoice.id == payment.invoiceId &&
                        invoice.orderId == payment.orderId,
                  ))
                Align(
                  alignment: Alignment.centerLeft,
                  child: TextButton(
                    key: ValueKey('work-sales-invoice-${payment.invoiceId}'),
                    onPressed: () => onOpenInvoice!(
                      session.workspaceInvoices.firstWhere(
                        (invoice) =>
                            invoice.id == payment.invoiceId &&
                            invoice.orderId == payment.orderId,
                      ),
                    ),
                    child: const Text('View invoice'),
                  ),
                ),
              if (!returnsOnly && payment.dueMinor > 0 &&
                  payment.invoiceId != null &&
                  (section == 'dues' || section == 'payments'))
                Align(
                  alignment: Alignment.centerLeft,
                  child: TextButton(
                    key: ValueKey('record-collection-${payment.orderId}'),
                    onPressed:
                        session.customerCollectionAvailable &&
                            !session.customerCollectionBusy &&
                            session.pendingCustomerCollection == null &&
                            finance.customerLedgers.any(
                              (l) =>
                                  l.customerId == payment.customerId &&
                                  l.historyComplete,
                            )
                        ? () => showModalBottomSheet<void>(
                            context: context,
                            isScrollControlled: true,
                            useSafeArea: true,
                            isDismissible: false,
                            enableDrag: false,
                            builder: (_) => _CustomerCollectionSheet(
                              session: session,
                              payment: payment,
                              accountScope: finance.accountScope,
                              storeId: finance.workspaceId,
                            ),
                          )
                        : null,
                    child: const Text('Record collection'),
                  ),
                ),
              if (payment.invoiceId != null &&
                  finance.customerLedgers.any(
                    (ledger) =>
                        ledger.customerId == payment.customerId &&
                        (ledger
                                    .invoiceBalance(payment.invoiceId!)
                                    ?.refundableMinor ??
                                0) >
                            0,
                  ))
                Align(
                  alignment: Alignment.centerLeft,
                  child: TextButton(
                    key: ValueKey('record-refund-${payment.orderId}'),
                    onPressed:
                        session.customerRefundAvailable &&
                            payment.channel != WorkspacePaymentChannel.platform
                        ? () => showModalBottomSheet<void>(
                            context: context,
                            isScrollControlled: true,
                            useSafeArea: true,
                            isDismissible: false,
                            enableDrag: false,
                            builder: (_) => _CustomerCollectionSheet(
                              session: session,
                              payment: payment,
                              accountScope: finance.accountScope,
                              storeId: finance.workspaceId,
                              refund: true,
                            ),
                          )
                        : null,
                    child: const Text('Record refund'),
                  ),
                ),
              if (remainingReturnUnits != null && remainingReturnUnits > 0)
                Align(
                  alignment: Alignment.centerLeft,
                  child: TextButton(
                    key: ValueKey('record-return-${payment.orderId}'),
                    onPressed: session.customerReturnAvailable
                        ? () => showModalBottomSheet<void>(
                            context: context,
                            isScrollControlled: true,
                            useSafeArea: true,
                            isDismissible: false,
                            enableDrag: false,
                            builder: (_) => _CustomerReturnSheet(
                              session: session,
                              payment: payment,
                              order: order!,
                              account: finance.accountScope,
                              store: finance.workspaceId,
                            ),
                          )
                        : null,
                    child: const Text('Record return'),
                  ),
                ),
              if (returnsOnly && remainingReturnUnits == 0)
                const Text('All items on this invoice have already been returned.'),
              if (returnsOnly && remainingReturnUnits == null)
                const Text('Return quantities unavailable. Recover the original invoice records before recording a return.'),
              if (payment.transactionId?.isNotEmpty == true)
                Text('Transaction ${payment.transactionId}'),
              if (order != null)
                ExpansionTile(
                  key: PageStorageKey((
                    'work-finance-order-details',
                    finance.accountScope,
                    finance.workspaceId,
                    section,
                    payment.orderId,
                  )),
                  tilePadding: EdgeInsets.zero,
                  title: const Text(
                    'Order details',
                    style: TextStyle(fontSize: 13, fontWeight: FontWeight.w700),
                  ),
                  children: [
                    _ExactOrderInformation(
                      order: order,
                      showItems: true,
                      showPayment: false,
                    ),
                  ],
                ),
            ],
          ),
        );
      },
    );
  }
}

class _CustomerReturnSheet extends StatefulWidget {
  const _CustomerReturnSheet({
    required this.session,
    required this.payment,
    required this.order,
    required this.account,
    required this.store,
    this.onRecorded,
  });
  final WorkSession session;
  final WorkspacePaymentRecord payment;
  final WorkspaceOrderRecord order;
  final String account, store;
  final VoidCallback? onRecorded;
  @override
  State<_CustomerReturnSheet> createState() => _CustomerReturnSheetState();
}

class _CustomerReturnSheetState extends State<_CustomerReturnSheet> with WidgetsBindingObserver {
  final quantities = <String, TextEditingController>{};
  final sellableQuantities = <String, TextEditingController>{};
  final selectedProducts = <String>{};
  final reason = TextEditingController();
  final _reasonFocus = FocusNode();
  final _reasonAnchor = GlobalKey();
  void _revealReason() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      final target = _reasonAnchor.currentContext;
      if (mounted && target != null) {
        Scrollable.ensureVisible(target, alignment: .2);
      }
    });
  }
  @override
  void didChangeMetrics() {
    if (_reasonFocus.hasFocus) _revealReason();
  }
  String? reasonCode;
  bool listenersAttached = false;
  late final _LedgerFormAutosave draft;
  bool saving = false;
  String? error;
  int? renderedCredit, renderedRevision;
  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _reasonFocus.addListener(() {
      if (_reasonFocus.hasFocus) _revealReason();
    });
    for (final item in widget.order.itemSnapshots) {
      quantities[item.productId] = TextEditingController(text: '1');
      sellableQuantities[item.productId] = TextEditingController(text: '0');
    }
    final firstAvailable = widget.order.itemSnapshots
        .where((item) => remainingQuantity(item) > 0)
        .firstOrNull;
    if (firstAvailable != null) selectedProducts.add(firstAvailable.productId);
    draft = _LedgerFormAutosave(
      widget.session,
      widget.session.ledgerFormKey(widget.payment, 'return'),
    );
    draft.addListener(refreshDraft);
    unawaited(loadDraft());
  }

  void refreshDraft() {
    if (mounted) {
      setState(() {});
    }
  }

  Future<void> loadDraft() async {
    final fields = await draft.load();
    if (!mounted || fields == null) {
      return;
    }
    final savedItems = fields['items'];
    if (savedItems != null) {
      final items = (jsonDecode(savedItems) as Map).cast<String, dynamic>();
      if (items.keys.any((id) => !quantities.containsKey(id))) {
        draft.ready = false;
        draft.error = 'Saved return items do not match this bill. Recover the original bill before continuing.';
        setState(() {});
        return;
      }
      selectedProducts
        ..clear()
        ..addAll(items.keys);
      for (final entry in items.entries) {
        quantities[entry.key]!.text = entry.value[0] as String;
        sellableQuantities[entry.key]!.text = entry.value[1] as String;
      }
    } else {
      // Retain a draft created by the previous single-product form.
      final id = fields['product'] ?? selectedProducts.first;
      if (!quantities.containsKey(id)) {
        draft.ready = false;
        draft.error = 'Saved return item does not match this bill. Recover the original bill before continuing.';
        setState(() {});
        return;
      }
      selectedProducts..clear()..add(id);
      quantities[id]!.text = fields['quantity'] ?? '1';
      sellableQuantities[id]!.text = fields['sellable'] ?? '0';
    }
    reason.text = fields['reason'] ?? '';
    final savedReasonCode = fields['reasonCode'];
    reasonCode = WorkspaceCustomerReturn.reasonLabels.containsKey(savedReasonCode)
        ? savedReasonCode : null;
    if (!listenersAttached) {
      for (final controller in [...quantities.values, ...sellableQuantities.values, reason]) {
        controller.addListener(saveDraft);
      }
      listenersAttached = true;
    }
    setState(() {});
  }

  void saveDraft() {
    draft.save({
      'items': jsonEncode({
        for (final id in selectedProducts)
          id: [quantities[id]!.text, sellableQuantities[id]!.text],
      }),
      'reason': reason.text,
      'reasonCode': ?reasonCode,
    });
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _reasonFocus.dispose();
    draft.removeListener(refreshDraft);
    draft.dispose();
    for (final controller in [...quantities.values, ...sellableQuantities.values]) {
      controller.dispose();
    }
    reason.dispose();
    super.dispose();
  }

  WorkspaceCustomerLedger? get ledger => widget
      .session
      .workspaceFinance
      ?.customerLedgers
      .where((item) => item.customerId == widget.payment.customerId)
      .firstOrNull;
  List<WorkspaceCustomerReturnLine> get lines => [
    for (final item in widget.order.itemSnapshots)
      if (selectedProducts.contains(item.productId))
        WorkspaceCustomerReturnLine(
          productId: item.productId,
          quantity: int.tryParse(quantities[item.productId]!.text) ?? 0,
          restockQuantity: int.tryParse(sellableQuantities[item.productId]!.text) ?? -1,
        ),
  ];
  int remainingQuantity(WorkspaceOrderItemSnapshot item) => item.quantity -
      (ledger?.entries.where((entry) =>
          entry.invoiceId == widget.payment.invoiceId &&
          entry.state == WorkspaceLedgerPostingState.posted)
        .expand((entry) => entry.customerReturn?.lines ?? const <WorkspaceCustomerReturnLine>[])
        .where((line) => line.productId == item.productId)
        .fold<int>(0, (sum, line) => sum + line.quantity) ?? 0);
  int? get credit {
    final history = ledger;
    if (history == null) return null;
    final credits = history.entries.where(
      (item) =>
          item.invoiceId == widget.payment.invoiceId &&
          item.kind == WorkspaceLedgerEntryKind.creditNote,
    );
    if (credits.any(
      (item) =>
          item.customerReturn == null ||
          item.state == WorkspaceLedgerPostingState.pending,
    )) {
      return null;
    }
    return WorkspaceCustomerReturn(
      accountScope: widget.account,
      workspaceId: widget.store,
      customerId: widget.payment.customerId,
      invoiceId: widget.payment.invoiceId!,
      orderId: widget.order.id,
      operationId: 'preview',
      expectedRevision: history.revision,
      reason: 'Return preview',
      lines: lines,
    ).creditMinorFor(
      widget.order,
      priorReturns: [
        for (final item in credits)
          if (item.state == WorkspaceLedgerPostingState.posted)
            item.customerReturn!,
      ],
    );
  }

  Future<void> submit() async {
    if (!await draft.flush() || !mounted) {
      return;
    }
    final amount = renderedCredit;
    final revision = renderedRevision;
    if (amount == null ||
        amount <= 0 ||
        reason.text.trim().isEmpty ||
        widget.session.workspaceFinance?.accountScope != widget.account ||
        widget.session.workspaceFinance?.workspaceId != widget.store) {
      setState(
        () =>
            error = 'Check the quantities, reason and original Store invoice.',
      );
      return;
    }
    setState(() {
      saving = true;
      error = null;
    });
    final success = await widget.session.recordCustomerReturn(
      invoiceId: widget.payment.invoiceId!,
      lines: lines,
      reason: reason.text,
      reasonCode: reasonCode,
      expectedCreditMinor: amount,
      expectedLedgerRevision: revision,
    );
    if (!mounted) return;
    if (success) {
      widget.onRecorded?.call();
      Navigator.pop(context);
      return;
    }
    setState(() {
      saving = false;
      error = widget.session.pendingCustomerReturn != null
          ? 'Return is not confirmed. Use Check return status or Retry saving in the invoice view.'
          : 'Invoice changed or return unavailable. Review the current bill before retrying.';
    });
  }

  @override
  Widget build(BuildContext context) {
    renderedCredit = credit;
    renderedRevision = ledger?.revision;
    return PopScope(
      canPop: !saving && !draft.busy && (!draft.ready || draft.error == null),
      onPopInvokedWithResult: (didPop, result) async {
        if (!didPop && !saving && await draft.flush() && context.mounted) {
          Navigator.pop(context);
        }
      },
      child: SafeArea(
        top: false,
        child: Padding(padding: EdgeInsets.only(bottom: MediaQuery.viewInsetsOf(context).bottom),
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          Padding(padding: const EdgeInsets.fromLTRB(16, 8, 8, 4), child: Row(children: [
            Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text('Record return', style: Theme.of(context).textTheme.titleMedium),
              Text('Invoice ${widget.payment.invoiceId}', style: const TextStyle(fontSize: 12)),
            ])),
            TextButton(key: const Key('return-jump-reason'),
              onPressed: saving ? null : _revealReason, child: const Text('Reason')),
          ])),
        Flexible(child: SingleChildScrollView(
          padding: const EdgeInsets.fromLTRB(16, 4, 16, 16),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              if (widget.onRecorded != null)
                const Text('Exchange · Step 1: record returned items. Choose replacements after saving.',
                  style: TextStyle(fontSize: 12, color: MoolColors.ink)),
              const SizedBox(height: 12),
              if (widget.order.itemSnapshots.length > 1)
                Text('Select items to return · ${selectedProducts.length} selected'),
              for (final item in widget.order.itemSnapshots) ...[
                if (widget.order.itemSnapshots.length > 1)
                  CheckboxListTile(
                    key: Key('return-select-${item.productId}'),
                    contentPadding: EdgeInsets.zero,
                    controlAffinity: ListTileControlAffinity.leading,
                    value: selectedProducts.contains(item.productId),
                    title: Text('${item.name} · ${item.pack}'),
                    subtitle: Text('Billed: ${item.quantity} · Available to return: ${remainingQuantity(item)}'),
                    onChanged: saving || !draft.ready ? null : (value) {
                      setState(() {
                        if (value == true) {
                          selectedProducts.add(item.productId);
                        } else {
                          selectedProducts.remove(item.productId);
                        }
                      });
                      saveDraft();
                    },
                  )
                else ...[
                  Text('${item.name} · ${item.pack}', key: const Key('return-original-item')),
                  Text('Billed quantity: ${item.quantity} · Available to return: ${remainingQuantity(item)}'),
                  const SizedBox(height: 12),
                ],
                if (selectedProducts.contains(item.productId)) ...[
                  LayoutBuilder(builder: (context, constraints) {
                    final twoColumns = constraints.maxWidth >= 280 &&
                        MediaQuery.textScalerOf(context).scale(14) <= 18.2;
                    final fieldWidth = twoColumns
                        ? ((constraints.maxWidth - 12) / 2).clamp(0.0, 180.0)
                        : constraints.maxWidth.clamp(0.0, 240.0);
                    return Wrap(spacing: 12, runSpacing: 12, children: [
                  SizedBox(width: fieldWidth, child: TextField(
                    key: item == widget.order.itemSnapshots.first
                        ? const Key('return-quantity') : Key('return-quantity-${item.productId}'),
                    controller: quantities[item.productId],
                    enabled: !saving && draft.ready,
                    keyboardType: TextInputType.number,
                    decoration: const InputDecoration(labelText: 'Units returned',
                      isDense: true, contentPadding: EdgeInsets.symmetric(horizontal: 12, vertical: 14)),
                    onChanged: (_) => setState(() {}),
                  )),
                  SizedBox(width: fieldWidth, child: TextField(
                    key: item == widget.order.itemSnapshots.first
                        ? const Key('return-sellable') : Key('return-sellable-${item.productId}'),
                    controller: sellableQuantities[item.productId],
                    enabled: !saving && draft.ready,
                    keyboardType: TextInputType.number,
                    decoration: const InputDecoration(
                      labelText: 'Fit for resale',
                      isDense: true, contentPadding: EdgeInsets.symmetric(horizontal: 12, vertical: 14),
                    ),
                    onChanged: (_) => setState(() {}),
                  )),
                    ]);
                  }),
                  const SizedBox(height: 4),
                  const Text('Damaged units must not go back into sellable stock.',
                    style: TextStyle(fontSize: 12)),
                  const SizedBox(height: 12),
                ],
              ],
              const SizedBox(height: 12),
              SingleChildScrollView(
                key: const Key('return-reason-choices'),
                scrollDirection: Axis.horizontal,
                child: Row(children: [
                  for (final entry in WorkspaceCustomerReturn.reasonLabels.entries)
                    Padding(
                      padding: const EdgeInsets.only(right: 12),
                      child: Semantics(
                        checked: reasonCode == entry.key,
                        inMutuallyExclusiveGroup: true,
                        child: InkWell(
                          key: Key('return-reason-${entry.key}'),
                          onTap: saving || !draft.ready ? null : () {
                            if (reasonCode == entry.key) return;
                            setState(() {
                              reasonCode = entry.key;
                              reason.text = entry.key == 'other' ? '' : entry.value;
                            });
                            saveDraft();
                          },
                          child: ConstrainedBox(
                            constraints: const BoxConstraints(minHeight: 48),
                            child: Row(mainAxisSize: MainAxisSize.min, children: [
                              Icon(reasonCode == entry.key
                                ? Icons.radio_button_checked : Icons.radio_button_unchecked,
                                size: 18, color: MoolColors.navy),
                              const SizedBox(width: 5),
                              Text(entry.value, style: const TextStyle(fontSize: 13)),
                            ]),
                          ),
                        ),
                      ),
                    ),
                ]),
              ),
              Container(key: _reasonAnchor, child: TextField(
                key: const Key('return-reason'),
                controller: reason,
                focusNode: _reasonFocus,
                scrollPadding: const EdgeInsets.only(bottom: 100, top: 20),
                enabled: !saving && draft.ready,
                maxLength: 160,
                decoration: InputDecoration(
                  labelText: reasonCode == 'other' ? 'Describe the reason' : 'Reason for return',
                ),
                onChanged: (_) {
                  if (reasonCode == null) setState(() => reasonCode = 'other');
                  saveDraft();
                },
              )),
              Text(
                credit == null
                    ? 'Enter valid quantities within the original bill.'
                    : 'Return credit: ${_purchaseAmount(credit!)}',
              ),
              const Text(
                'Credit reduces this invoice’s dues first. Any amount owed back remains pending until a refund is confirmed.',
              ),
              if (draft.error != null) ...[
                Text(draft.error!),
                TextButton(
                  onPressed: draft.busy
                      ? null
                      : () {
                          if (draft.ready) {
                            saveDraft();
                          } else {
                            unawaited(loadDraft());
                          }
                        },
                  child: const Text('Retry saving input'),
                ),
              ],
              if (error != null)
                Padding(
                  padding: const EdgeInsets.only(top: 8),
                  child: Text(error!),
                ),
              const SizedBox(height: 12),
              FilledButton(
                onPressed:
                    !draft.ready ||
                        draft.busy ||
                        draft.error != null ||
                        saving ||
                        widget.session.pendingCustomerReturn != null
                    ? null
                    : submit,
                child: Text(saving ? 'Recording…' : 'Confirm return'),
              ),
            ],
          ),
        )),
        ])),
      ),
    );
  }
}

class _LedgerFormAutosave extends ChangeNotifier {
  _LedgerFormAutosave(this.session, this.key);
  final WorkSession session;
  final WorkspaceLedgerFormKey? key;
  int? revision;
  bool ready = false, busy = false, closed = false;
  String? error;
  WorkspaceLedgerFormDraft? pending;
  Future<void> writes = Future<void>.value();
  void changed() {
    if (!closed) {
      notifyListeners();
    }
  }

  Future<Map<String, String>?> load() async {
    try {
      if (key == null) {
        throw StateError('Invoice unavailable');
      }
      final saved = await session.readLedgerForm(key!);
      revision = saved?.revision;
      ready = true;
      error = null;
      changed();
      return saved?.fields ?? const {};
    } catch (_) {
      error = 'Saved input could not be opened. Retry before editing.';
      changed();
      return null;
    }
  }

  void save(Map<String, String> fields) {
    if (!ready || key == null) {
      return;
    }
    final snapshot = Map<String, String>.of(fields);
    busy = true;
    changed();
    writes = writes.then((_) async {
      try {
        if (pending != null) {
          await session.saveLedgerForm(pending!, expectedRevision: revision);
          revision = pending!.revision;
          pending = null;
        }
        pending = WorkspaceLedgerFormDraft(
          key: key!,
          revision: (revision ?? 0) + 1,
          fields: snapshot,
        );
        await session.saveLedgerForm(pending!, expectedRevision: revision);
        revision = pending!.revision;
        pending = null;
        error = null;
      } catch (_) {
        error = 'Input is not saved yet. Retry saving before leaving.';
      }
    });
    final current = writes;
    unawaited(
      current.then((_) {
        if (identical(current, writes)) {
          busy = false;
          changed();
        }
      }),
    );
  }

  Future<bool> flush() async {
    await writes;
    return ready && pending == null && error == null;
  }

  @override
  void dispose() {
    closed = true;
    super.dispose();
  }
}

class _StoreExpensesSurface extends StatefulWidget {
  const _StoreExpensesSurface({
    super.key,
    required this.session,
    this.statement = false,
    this.register = false,
  });
  final WorkSession session;
  final bool statement;
  final bool register;
  @override
  State<_StoreExpensesSurface> createState() => _StoreExpensesSurfaceState();
}

class _StoreExpensesSurfaceState extends State<_StoreExpensesSurface> {
  bool loading = true, recovered = false;
  String? _registerId;

  Widget _moneyBook(BuildContext context) {
    final session = widget.session;
    if (loading || !recovered) {
      return ListView(
        children: [
          Text(
            loading
                ? 'Opening saved money records…'
                : 'Money records are unavailable.',
          ),
          if (!loading)
            TextButton(
              onPressed: recover,
              child: const Text('Retry opening records'),
            ),
        ],
      );
    }
    final registers = session.workspaceMoneyRegisters;
    final selected = _registerId == ''
        ? null
        : registers
              .where((r) => _registerId == null || r.registerId == _registerId)
              .firstOrNull;
    final rows = <List<String>>[];
    final keys = <Key>[];
    var debit = 0, credit = 0;
    String balanceText(int? minor) => minor == null
        ? 'Unavailable'
        : '${_formatStoreMinorAmount(minor.abs())}${minor == 0
              ? ''
              : minor > 0
              ? ' Dr'
              : ' Cr'}';
    int? closing;
    var unavailable = false;
    if (selected != null) {
      final now = DateTime.now();
      final end = selected.asOf.isBefore(now) ? selected.asOf : now;
      final start = session.workspaceMoneyPeriodStart ?? selected.openingAt;
      final balances = session.workspaceFinanceStale
          ? null
          : selected.balances(start, end);
      int? running = balances?.openingMinor;
      unavailable = balances == null;
      rows.add(['', 'Opening Balance', '', '', '', '', balanceText(running)]);
      keys.add(const ValueKey('money-book-opening'));
      for (final entry in selected.entries.where(
        (e) => !e.occurredAt.isBefore(start) && e.occurredAt.isBefore(end),
      )) {
        if (entry.deltaMinor > 0) {
          debit += entry.deltaMinor;
        } else {
          credit -= entry.deltaMinor;
        }
        if (running != null) running += entry.deltaMinor;
        rows.add([
          _registerDate(entry.occurredAt),
          entry.reference,
          'Movement',
          entry.id,
          entry.deltaMinor > 0 ? _formatStoreMinorAmount(entry.deltaMinor) : '',
          entry.deltaMinor < 0
              ? _formatStoreMinorAmount(-entry.deltaMinor)
              : '',
          balanceText(running),
        ]);
        keys.add(ValueKey('money-book-entry-${entry.id}'));
      }
      closing = balances?.closingMinor;
      rows.add(['', 'Closing Balance', '', '', '', '', balanceText(closing)]);
      keys.add(const ValueKey('money-book-closing'));
    } else {
      unavailable = true;
      final statement = session.workspaceMoneyStatement;
      for (final entry
          in statement?.entries ?? <WorkspaceMoneyStatementEntry>[]) {
        if (entry.posted && !entry.transfer) {
          if (entry.incoming) {
            debit += entry.amountMinor;
          } else {
            credit += entry.amountMinor;
          }
        }
        rows.add([
          _registerDate(entry.occurredAt),
          entry.party,
          entry.label,
          entry.reference,
          entry.incoming ? _formatStoreMinorAmount(entry.amountMinor) : '',
          !entry.incoming ? _formatStoreMinorAmount(entry.amountMinor) : '',
          entry.status,
        ]);
        keys.add(ValueKey('work-money-entry-${entry.id}'));
      }
    }
    return Column(
      key: const Key('work-money-statement'),
      children: [
        Align(
          alignment: Alignment.centerLeft,
          child: PopupMenuButton<String>(
            key: const Key('work-money-book-selector'),
            onSelected: (id) => setState(() => _registerId = id),
            itemBuilder: (_) => [
              for (final r in registers)
                PopupMenuItem(value: r.registerId, child: Text(r.label)),
              const PopupMenuItem(value: '', child: Text('Recorded movements')),
            ],
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
              child: Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Flexible(
                    child: Text(
                      selected?.label ?? 'Recorded movements',
                      style: const TextStyle(
                        fontSize: 13,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                  ),
                  const SizedBox(width: 4),
                  const Icon(Icons.expand_more, size: 18),
                ],
              ),
            ),
          ),
        ),
        if (unavailable)
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 16),
            child: Text(
              selected == null
                  ? 'Select a supplied cash/bank account for balances.'
                  : 'Opening balance or complete history unavailable.',
              style: const TextStyle(fontSize: 11),
            ),
          ),
        Expanded(
          child: _StoreVoucherRegister(
            identity: (
              'money',
              session.workspaceStockHistoryScope()?.key,
              selected?.registerId,
              session.workspaceMoneyPeriod,
            ),
            headers: selected == null
                ? const [
                    'Date',
                    'Particulars',
                    'Entry Type',
                    'Reference',
                    'Money in (₹)',
                    'Money out (₹)',
                    'Status',
                  ]
                : const [
                    'Date',
                    'Particulars',
                    'Entry Type',
                    'Reference ID',
                    'Debit (₹)',
                    'Credit (₹)',
                    'Balance (₹)',
                  ],
            rows: rows,
            rowKeys: keys,
            amountColumns: const {4, 5, 6},
            total: '',
            footer: [
              '',
              'Recorded total',
              '',
              '',
              _formatStoreMinorAmount(debit),
              _formatStoreMinorAmount(credit),
              selected == null ? '' : balanceText(closing),
            ],
            notice: selected == null
                ? 'Posted movements only in totals; pending entries and transfers excluded.'
                : 'Book balance, not a verified bank balance. Movement type is supplied without an inferred voucher classification.',
            empty: 'No records in this period.',
          ),
        ),
      ],
    );
  }

  @override
  void initState() {
    super.initState();
    unawaited(recover());
  }

  Future<void> recover() async {
    final result = await widget.session.recoverCustomerLedger();
    if (mounted) {
      setState(() {
        loading = false;
        recovered = result;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    if (widget.statement) return _moneyBook(context);
    final start = widget.session.workspaceMoneyPeriodStart;
    final expenses = widget.session.workspaceExpenses
        .where(
          (expense) => start == null || !expense.occurredAt.isBefore(start),
        )
        .toList();
    if (recovered && widget.register) {
      return _StoreVoucherRegister(
        identity: (
          'expenses',
          widget.session.workspaceStockHistoryScope()?.key,
          widget.session.workspaceMoneyPeriod,
        ),
        headers: const [
          'Date',
          'Particulars',
          'Voucher Type',
          'Reference',
          'Amount (₹)',
        ],
        rows: [
          for (final expense in expenses)
            [
              _registerDate(expense.occurredAt),
              expense.category,
              'Expense',
              expense.reference,
              _formatStoreMinorAmount(expense.amountMinor),
            ],
        ],
        rowKeys: [
          for (final expense in expenses)
            ValueKey('work-expense-${expense.operationId}'),
        ],
        amountColumns: const {4},
        total: _formatStoreMinorAmount(
          expenses.fold<int>(0, (sum, expense) => sum + expense.amountMinor),
        ),
        notice: 'Recorded expenses · not a cash or bank balance',
        empty: 'No expense entries recorded for this period.',
      );
    }
    return ListView(
      key: const Key('work-finance-expenses'),
      padding: const EdgeInsets.all(16),
      children: [
        Text(
          'Business expenses',
          style: Theme.of(context).textTheme.titleLarge,
        ),
        if (loading)
          const Text('Opening saved expenses…')
        else if (!recovered) ...[
          const Text('Saved expenses could not be opened.'),
          TextButton(
            onPressed: recover,
            child: const Text('Retry opening expenses'),
          ),
        ] else ...[
          Text(
            'Recorded expenses ${_purchaseAmount(expenses.fold<int>(0, (sum, expense) => sum + expense.amountMinor))}',
            key: const Key('work-expense-period-total'),
          ),
          if (widget.session.canRecordStoreReviewExpense)
            TextButton.icon(
              key: const Key('store-expense-open'),
              icon: const Icon(Icons.add),
              label: const Text('Record test expense'),
              onPressed: () => showModalBottomSheet<void>(
                context: context,
                isScrollControlled: true,
                useSafeArea: true,
                builder: (_) => _StoreMoneyEntrySheet(session: widget.session),
              ),
            ),
          const Text(
            'Recorded entries for this Store and period. Purchases and settlements stay in their own records.',
          ),
          if (expenses.isEmpty)
            const Text('No expense entries recorded for this period.'),
          for (final expense in expenses)
            Padding(
              key: ValueKey('work-expense-${expense.operationId}'),
              padding: const EdgeInsets.symmetric(vertical: 12),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    expense.category,
                    style: const TextStyle(fontWeight: FontWeight.w700),
                  ),
                  Text(_purchaseAmount(expense.amountMinor)),
                  Text('${expense.method} · ${expense.reference}'),
                  Text(
                    '${expense.occurredAt.day}/${expense.occurredAt.month}/${expense.occurredAt.year}',
                  ),
                  if (expense.note.isNotEmpty) Text(expense.note),
                  const Divider(),
                ],
              ),
            ),
        ],
      ],
    );
  }
}

class _StoreSupplierRefundTarget {
  const _StoreSupplierRefundTarget({required this.supplierId, required this.sourceKind,
    required this.sourceId, required this.label, required this.opening, this.copy});
  final String supplierId, sourceId, label;
  final WorkspaceSupplierRefundSourceKind sourceKind;
  final WorkspaceSupplierOpeningRecord opening;
  final WorkspacePurchaseSavedCopy? copy;
  WorkspaceLedgerFormKey? key(WorkSession session) => session.supplierRefundRecoveryFormKey(
    supplierId: supplierId, sourceKind: sourceKind, sourceId: sourceId,
    openingRevision: opening.revision, copyId: copy?.id, copyRevision: copy?.revision);
}

Future<void> _chooseSupplierRefund(BuildContext context, WorkSession session, String supplierId) async {
  final opening = session.workspaceSupplierOpeningRecord(supplierId);
  if (opening == null) return;
  final ledger = session.workspaceSupplierLedger(supplierId);
  final sources = <_StoreSupplierRefundTarget>[
    if (opening.supplierCredit) _StoreSupplierRefundTarget(supplierId: supplierId,
      sourceKind: WorkspaceSupplierRefundSourceKind.openingAdvance, sourceId: opening.id,
      label: 'Starting advance · ${opening.asOfDate}', opening: opening),
    for (final entry in ledger?.entries ?? <WorkspaceSupplierLedgerEntry>[])
      if (entry.origin == WorkspaceSupplierEntryOrigin.supplierAccount && entry.kind == WorkspaceSupplierEntryKind.advance)
        _StoreSupplierRefundTarget(supplierId: supplierId,
          sourceKind: WorkspaceSupplierRefundSourceKind.accountAdvance, sourceId: entry.operationId,
          label: 'Advance · ${entry.reference} · ${entry.moneyReview?.occurredOn ?? ''}', opening: opening),
    for (final copy in session.workspaceLatestPurchaseCopies.where((c) => c.supplier.id == supplierId))
      _StoreSupplierRefundTarget(supplierId: supplierId, sourceKind: WorkspaceSupplierRefundSourceKind.manualBillSurplus,
        sourceId: copy.draft.id, label: 'Bill ${copy.draft.invoiceReference} · ${copy.draft.invoiceDate}',
        opening: opening, copy: copy),
  ];
  final target = await showModalBottomSheet<_StoreSupplierRefundTarget>(context: context, useSafeArea: true,
    isScrollControlled: true, builder: (sheet) => SafeArea(top: false, child: ListView(shrinkWrap: true,
      padding: const EdgeInsets.all(16), children: [
        const Text('Refund received from supplier', style: TextStyle(fontSize: 16, fontWeight: FontWeight.w700)),
        const Text('Choose the bill or advance. Saved requests remain available even when no credit remains.'),
        if (sources.isEmpty) const Text('No saved bill or advance. Recover the supplier account or record the supporting bill first.'),
        for (var i = 0; i < sources.length; i++) ListTile(contentPadding: EdgeInsets.zero,
          key: ValueKey('supplier-refund-source-$i'), title: Text(sources[i].label),
          trailing: const Icon(Icons.chevron_right), onTap: () => Navigator.pop(sheet, sources[i])),
        TextButton(onPressed: () => Navigator.pop(sheet), child: const Text('Close')),
      ])));
  if (target != null && context.mounted) await _showSupplierRefund(context, session, target);
}

Future<void> _showSupplierRefund(BuildContext context, WorkSession session,
    _StoreSupplierRefundTarget target) => showModalBottomSheet<void>(context: context,
      isScrollControlled: true, useSafeArea: true, isDismissible: false, enableDrag: false,
      builder: (_) => _StoreSupplierRefundSheet(session: session, target: target));

class _StoreSupplierRefundSheet extends StatefulWidget {
  const _StoreSupplierRefundSheet({required this.session, required this.target});
  final WorkSession session;
  final _StoreSupplierRefundTarget target;
  @override
  State<_StoreSupplierRefundSheet> createState() => _StoreSupplierRefundSheetState();
}

class _StoreSupplierRefundSheetState extends State<_StoreSupplierRefundSheet> {
  late final _LedgerFormAutosave draft;
  final amount = TextEditingController(), reference = TextEditingController(), date = TextEditingController();
  String channel = 'Cash';
  WorkspaceSupplierRefundIntent? frozen;
  WorkspaceLedgerFormDraft? resetAttempt;
  bool busy = false, closing = false, recovered = false, statusVerified = false;
  String? confirmedAttempt;
  bool get confirmed => current && frozen != null &&
    confirmedAttempt == jsonEncode(frozen!.toJson());
  String? error;
  WorkspaceSupplierLedger? get ledger => widget.session.workspaceSupplierLedger(widget.target.supplierId);
  bool get current => draft.key != null && widget.target.key(widget.session) == draft.key;
  String printedDate(String day) => '${day.substring(8)}/${day.substring(5, 7)}/${day.substring(0, 4)}';
  String? get occurredOn {
    final m = RegExp(r'^(\d{2})/(\d{2})/(\d{4})$').firstMatch(date.text.trim());
    if (m == null) return null;
    final parsed = DateTime(int.parse(m[3]!), int.parse(m[2]!), int.parse(m[1]!));
    if (parsed.year != int.parse(m[3]!) || parsed.month != int.parse(m[2]!) || parsed.day != int.parse(m[1]!)) return null;
    return '${m[3]}-${m[2]}-${m[1]}';
  }
  WorkspaceSupplierRefundIntent intent({required String id, required int minor}) => WorkspaceSupplierRefundIntent(
    operationId: id, accountScope: draft.key!.account, workspaceId: draft.key!.store,
    supplierId: widget.target.supplierId, qa: widget.target.opening.qa,
    openingId: widget.target.opening.id, openingRevision: widget.target.opening.revision,
    sourceKind: widget.target.sourceKind, sourceId: widget.target.sourceId,
    copyId: widget.target.copy?.id, copyRevision: widget.target.copy?.revision,
    amountMinor: minor, reference: reference.text.trim(), occurredOn: occurredOn ?? '',
    paymentMethod: channel, requestedAt: DateTime.now().toUtc());
  int? get capacity {
    if (!recovered || !current) return null;
    final probe = WorkspaceSupplierRefundIntent(operationId: 'refund-capacity-review',
      accountScope: draft.key!.account, workspaceId: draft.key!.store, supplierId: widget.target.supplierId,
      qa: widget.target.opening.qa, openingId: widget.target.opening.id,
      openingRevision: widget.target.opening.revision, sourceKind: widget.target.sourceKind,
      sourceId: widget.target.sourceId, copyId: widget.target.copy?.id, copyRevision: widget.target.copy?.revision,
      amountMinor: 1, reference: 'Capacity review', occurredOn: DateTime.now().toUtc().toIso8601String().substring(0, 10),
      paymentMethod: 'Cash', requestedAt: DateTime.now().toUtc());
    return ledger?.reviewedRefundCapacity(probe);
  }
  Map<String, String> get fields => {'amount': amount.text, 'reference': reference.text,
    'channel': channel, 'occurredOn': frozen?.occurredOn ?? date.text,
    'sourceKind': widget.target.sourceKind.name, 'sourceId': widget.target.sourceId,
    if (frozen != null) 'attempt': jsonEncode(frozen!.toJson())};
  @override
  void initState() {
    super.initState();
    draft = _LedgerFormAutosave(widget.session, widget.target.key(widget.session));
    draft.addListener(refresh); unawaited(load());
  }
  void refresh() { if (mounted) setState(() {}); }
  Future<void> verify() async {
    statusVerified = false;
    if (!current || frozen == null) return;
    final reviewed = frozen!;
    final proof = await widget.session.readWorkspaceSupplierRefundStatus(draft.key!, reviewed);
    if (!mounted || !current || frozen == null ||
        jsonEncode(frozen!.toJson()) != jsonEncode(reviewed.toJson())) {
      throw StateError('Store or saved request changed');
    }
    confirmedAttempt = proof != null ? jsonEncode(reviewed.toJson()) : null;
    statusVerified = true;
  }
  Future<void> load() async {
    if (busy || draft.busy) return;
    setState(() { busy = true; error = null; });
    try {
      if (!await flushPending() || !mounted || !current) return;
      final saved = await draft.load();
      if (!mounted || saved == null || !current) throw StateError('Saved request unavailable');
      frozen = saved['attempt']?.isNotEmpty == true
        ? WorkspaceSupplierRefundIntent.fromJson(jsonDecode(saved['attempt']!)) : null;
      amount.text = saved['amount'] ?? ''; reference.text = saved['reference'] ?? '';
      channel = saved['channel']?.isNotEmpty == true ? saved['channel']! : 'Cash';
      date.text = frozen == null ? saved['occurredOn'] ?? printedDate(DateTime.now().toUtc().toIso8601String().substring(0, 10))
        : printedDate(frozen!.occurredOn);
      if (frozen != null) await verify();
      recovered = await widget.session.recoverCustomerLedger();
      if (!current) throw StateError('Store changed');
      if (!recovered) error = confirmed ? 'Refund recorded; account refresh pending.' : 'Account unavailable. Keep the saved request and retry recovery.';
    } on Object {
      recovered = false;
      error = confirmed ? 'Refund recorded; account refresh pending.' : 'Saved refund status is unverified. Keep these details and retry.';
    } finally { if (mounted) setState(() => busy = false); }
  }
  Future<bool> flushPending() async {
    if (!draft.ready) return true;
    if (draft.pending != null) draft.save(fields);
    return await draft.flush();
  }
  Future<void> close() async {
    if (busy || closing || draft.busy) return;
    final route = ModalRoute.of(context);
    setState(() { closing = true; busy = true; });
    try {
      if (await flushPending() && mounted && route?.isCurrent == true) {
        Navigator.pop(context);
      }
    } finally {
      if (mounted) setState(() { closing = false; busy = false; });
    }
  }
  Future<void> submit() async {
    if (busy || !current || !draft.ready || draft.busy) return;
    setState(() { busy = true; error = null; });
    try {
      if (!await draft.flush() || !mounted || !current) return;
      if (confirmed) {
        if (!recovered) { error = 'Refresh the account before recording another refund.'; return; }
        resetAttempt ??= WorkspaceLedgerFormDraft(key: draft.key!, revision: draft.revision! + 1, fields: const {});
        if (!await widget.session.resetConfirmedWorkspaceSupplierRefundDraft(resetAttempt!, expectedRevision: draft.revision!)) {
          error = 'Recorded refund is kept. Retry recovery before starting another.'; return;
        }
        if (!mounted || !current) return;
        draft.revision = resetAttempt!.revision; draft.pending = null; draft.error = null;
        frozen = null; resetAttempt = null; confirmedAttempt = null; statusVerified = false;
        amount.clear(); reference.clear(); channel = 'Cash';
        date.text = printedDate(DateTime.now().toUtc().toIso8601String().substring(0, 10));
        return;
      }
      if (frozen == null) {
        if (!recovered) { error = 'Recover the supplier account before recording money received.'; return; }
        final minor = WorkspacePurchaseEntryDraft.printedPaise(amount.text);
        if (minor == null || minor <= 0 || occurredOn == null) {
          error = 'Enter the amount received and a valid date (DD/MM/YYYY).'; return;
        }
        final review = intent(id: widget.session.newWorkspaceSupplierRefundId(), minor: minor);
        final available = ledger?.reviewedRefundCapacity(review);
        if (!review.valid || available == null || minor > available) {
          error = 'Check the reference, date and available credit. No refund was recorded.'; return;
        }
        reference.text = review.reference; amount.text = (minor / 100).toStringAsFixed(2);
        frozen = review; draft.save(fields);
        if (!await draft.flush() || !mounted || !current) return;
      }
      final posted = await widget.session.recordWorkspaceSupplierRefundDraft(draft.key!, frozen!);
      if (!mounted || !current) return;
      await verify();
      recovered = await widget.session.recoverCustomerLedger();
      if (!current) return;
      error = confirmed ? recovered ? null : 'Refund recorded; account refresh pending.'
        : posted ? 'Saved status needs verification. Retry recovery; do not enter this refund again.'
        : 'Refund not confirmed. Keep and retry this same saved request.';
    } on Object {
      error = confirmed ? 'Refund recorded; account refresh pending.' : 'Refund status unverified. Keep and recover this saved request.';
    } finally { if (mounted) setState(() => busy = false); }
  }
  @override
  void dispose() {
    draft.removeListener(refresh); draft.dispose(); amount.dispose(); reference.dispose(); date.dispose(); super.dispose();
  }
  @override
  Widget build(BuildContext context) {
    final editable = draft.ready && recovered && current && !busy && frozen == null;
    final retained = current && frozen != null;
    final available = capacity;
    return PopScope(canPop: !busy && !draft.busy && draft.pending == null && draft.error == null,
      onPopInvokedWithResult: (didPop, result) async { if (!didPop) await close(); },
      child: SafeArea(top: false, child: Padding(padding: EdgeInsets.only(bottom: MediaQuery.viewInsetsOf(context).bottom),
        child: SingleChildScrollView(padding: const EdgeInsets.fromLTRB(16, 12, 16, 16),
          child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            Wrap(alignment: WrapAlignment.spaceBetween, crossAxisAlignment: WrapCrossAlignment.center, children: [
              Text('Supplier refund received', style: Theme.of(context).textTheme.titleMedium),
              TextButton(key: const Key('supplier-refund-close'), onPressed: busy || draft.busy ? null : close, child: const Text('Close'))]),
            Text('${widget.session.workspaceSuppliers.where((s) => s.id == widget.target.supplierId).firstOrNull?.name ?? 'Supplier'} · ${widget.target.label}'),
            const Text('Records money received; no transfer or Stock change.'),
            Text(available == null ? 'Available credit needs verification' : 'Available to receive ${_purchaseAmount(available)}',
              key: const Key('supplier-refund-available')),
            Wrap(spacing: 12, runSpacing: 8, children: [
              _purchaseCompactLabeledField('Amount received (₹)', width: 145, field: TextField(
                key: const Key('supplier-refund-amount'), controller: amount, enabled: editable || retained,
                readOnly: retained,
                keyboardType: const TextInputType.numberWithOptions(decimal: true),
                onChanged: editable ? (_) => draft.save(fields) : null)),
              _purchaseCompactLabeledField('Received date', width: 145, field: TextField(
                key: const Key('supplier-refund-date'), controller: date, enabled: editable || retained,
                readOnly: retained,
                decoration: InputDecoration(helperText: retained ? null : 'DD/MM/YYYY'), keyboardType: TextInputType.datetime,
                onChanged: editable ? (_) => draft.save(fields) : null)),
            ]),
            const SizedBox(height: 8),
            if (retained) Padding(padding: const EdgeInsets.symmetric(vertical: 8),
              child: Text('Received by · $channel', key: const Key('supplier-refund-saved-method'),
                style: Theme.of(context).textTheme.bodyLarge))
            else DropdownButtonFormField<String>(key: ValueKey('supplier-refund-method-$channel'), initialValue: channel,
              isExpanded: true, decoration: const InputDecoration(labelText: 'Received by'),
              items: [for (final method in ['Cash', 'UPI', 'Bank transfer']) DropdownMenuItem(value: method, child: Text(method))],
              onChanged: editable ? (value) { setState(() => channel = value!); draft.save(fields); } : null),
            TextField(key: const Key('supplier-refund-reference'), controller: reference, enabled: editable || retained,
              readOnly: retained,
              decoration: InputDecoration(labelText: 'Refund reference',
                helperText: retained ? null : 'Receipt No. / UPI reference / bank reference'),
              onChanged: editable ? (_) => draft.save(fields) : null),
            if (frozen != null) Text(confirmed ? 'Refund recorded · ${_purchaseAmount(frozen!.amountMinor)}'
              : statusVerified ? 'Saved request · not recorded' : 'Saved refund status unverified', key: const Key('supplier-refund-status')),
            if (confirmed && recovered && ledger?.creditMinor != null) Text('Credit remaining with supplier ${_purchaseAmount(ledger!.creditMinor!)}'),
            if (error != null || draft.error != null) Text(error ?? draft.error!),
            if (frozen != null || error != null || draft.error != null || !recovered)
              TextButton(key: const Key('supplier-refund-recover'), onPressed: busy || draft.busy ? null : load,
              child: const Text('Recover saved refund')),
            FilledButton(key: const Key('supplier-refund-submit'), onPressed: !busy && !draft.busy && draft.ready && current && draft.error == null &&
              (frozen != null || recovered && (available ?? 0) > 0) ? submit : null,
              child: Text(busy ? 'Recording…' : confirmed ? 'Record another refund'
                : frozen == null ? 'Record refund received' : 'Retry same refund')),
          ])))));
  }
}

class _StoreSupplierMoneyTarget {
  const _StoreSupplierMoneyTarget({required this.supplierId, this.copy, this.advance = false})
    : assert(copy == null || !advance);
  final String supplierId;
  final WorkspacePurchaseSavedCopy? copy;
  final bool advance;
}

Future<void> _showSupplierMoneyEntry(BuildContext context, WorkSession session,
    _StoreSupplierMoneyTarget target) => showModalBottomSheet<void>(context: context,
      isScrollControlled: true, useSafeArea: true, isDismissible: false, enableDrag: false,
      builder: (_) => _StoreMoneyEntrySheet(session: session, supplierMoney: target));

Future<void> _showSupplierGoodsReturn(BuildContext context, WorkSession session,
    String supplierId, WorkspaceSupplierGoodsReceipt receipt) => showModalBottomSheet<void>(
      context: context, isScrollControlled: true, useSafeArea: true, isDismissible: false, enableDrag: false,
      builder: (_) => _StoreSupplierGoodsReturnSheet(session: session, supplierId: supplierId, receipt: receipt));

class _StoreSupplierGoodsReturnSheet extends StatefulWidget {
  const _StoreSupplierGoodsReturnSheet({required this.session, required this.supplierId, required this.receipt});
  final WorkSession session;
  final String supplierId;
  final WorkspaceSupplierGoodsReceipt receipt;
  @override
  State<_StoreSupplierGoodsReturnSheet> createState() => _StoreSupplierGoodsReturnSheetState();
}

class _StoreSupplierGoodsReturnSheetState extends State<_StoreSupplierGoodsReturnSheet> {
  late final _LedgerFormAutosave draft;
  final reference = TextEditingController(), reason = TextEditingController(), day = TextEditingController();
  final accepted = <String, TextEditingController>{}, damaged = <String, TextEditingController>{};
  WorkspaceSupplierGoodsReturnIntent? frozen;
  WorkspaceLedgerFormDraft? resetAttempt;
  WorkspaceLedgerFormDraft? correctionAttempt;
  DateTime? cancelledAt;
  bool busy = true, confirmed = false, complete = false, conflict = false, statusUnverified = false;
  String? error;
  WorkspaceSupplierLedger? get ledger => widget.session.workspaceSupplierLedger(widget.supplierId);
  Map<String, String> get fields => {'reference': reference.text, 'reason': reason.text, 'returnedOn': day.text,
    'items': frozen == null ? jsonEncode({for (final line in widget.receipt.lines)
      line.sourceLineId: [accepted[line.sourceLineId]!.text, damaged[line.sourceLineId]!.text]})
      : jsonEncode(frozen!.lines.map((line) => line.toJson()).toList()),
    if (frozen != null) 'attempt': jsonEncode(frozen!.toJson())};
  @override
  void initState() {
    super.initState();
    day.text = DateTime.now().toIso8601String().substring(0, 10);
    for (final line in widget.receipt.lines) {
      accepted[line.sourceLineId] = TextEditingController(text: '0');
      damaged[line.sourceLineId] = TextEditingController(text: '0');
    }
    draft = _LedgerFormAutosave(widget.session,
      widget.session.supplierGoodsReturnFormKey(widget.supplierId, widget.receipt.id));
    draft.addListener(refresh);
    unawaited(load(initial: true));
  }
  void refresh() { if (mounted) setState(() {}); }
  Future<void> load({bool initial = false}) async {
    if (!initial && (busy || draft.busy)) return;
    setState(() => busy = true);
    try {
      if (draft.pending != null) { draft.save(fields); await draft.flush(); }
      final retained = draft.pending;
      final saved = await draft.load();
      if (!mounted || saved == null) return;
      if (retained != null && jsonEncode(retained.fields) != jsonEncode(saved)) {
        conflict = true; error = 'Saved return differs from this input. Both are kept; do not replace either.';
        return;
      }
      draft.pending = null; conflict = false; error = null; complete = false; resetAttempt = null; statusUnverified = false;
      correctionAttempt = null; cancelledAt = null;
      reference.text = saved['reference'] ?? ''; reason.text = saved['reason'] ?? '';
      day.text = saved['returnedOn']?.isNotEmpty == true ? saved['returnedOn']! : DateTime.now().toIso8601String().substring(0, 10);
      final attempt = saved['attempt'];
      frozen = attempt == null || attempt.isEmpty ? null : WorkspaceSupplierGoodsReturnIntent.fromJson(jsonDecode(attempt));
      for (final line in widget.receipt.lines) {
        accepted[line.sourceLineId]!.text = '0'; damaged[line.sourceLineId]!.text = '0';
      }
      if (frozen != null) {
        for (final line in frozen!.lines) {
          if (!accepted.containsKey(line.receiptLineId)) throw const FormatException('Receipt item changed');
          accepted[line.receiptLineId]!.text = _ReceivingLineInput._quantity(line.acceptedMilli);
          damaged[line.receiptLineId]!.text = _ReceivingLineInput._quantity(line.damagedMilli);
        }
        confirmed = await widget.session.readWorkspaceSupplierGoodsReturnStatus(draft.key!, frozen!) != null;
      } else {
        confirmed = false;
        final items = saved['items'];
        if (items != null && items.isNotEmpty) {
          final values = jsonDecode(items);
          if (values is! Map || values.keys.any((id) => !accepted.containsKey(id))) throw const FormatException('Invalid saved items');
          for (final entry in values.entries) {
            if (entry.value is! List || (entry.value as List).length != 2 ||
                !(entry.value as List).every((value) => value is String)) {
              throw const FormatException('Invalid saved quantities');
            }
            accepted[entry.key]!.text = entry.value[0] as String; damaged[entry.key]!.text = entry.value[1] as String;
          }
        }
      }
    } on Object { conflict = true; statusUnverified = true;
      error = 'Saved goods return could not be verified. Keep the request and retry recovery.'; }
    finally { if (mounted) setState(() => busy = false); }
  }
  Future<void> submit() async {
    if (busy || conflict || !draft.ready || draft.key == null) return;
    setState(() { busy = true; error = null; });
    try {
      if (!await draft.flush() || !mounted) return;
      if (confirmed && complete) {
        resetAttempt ??= WorkspaceLedgerFormDraft(key: draft.key!, revision: draft.revision! + 1, fields: const {});
        if (await widget.session.resetConfirmedWorkspaceSupplierGoodsReturnDraft(resetAttempt!, expectedRevision: draft.revision!)) {
          draft.revision = resetAttempt!.revision; draft.pending = null; draft.error = null;
          frozen = null; confirmed = false; complete = false; resetAttempt = null;
          reference.clear(); reason.clear();
          for (final controller in [...accepted.values, ...damaged.values]) { controller.text = '0'; }
        } else { error = 'Recorded return is kept. Verify its saved status before starting another.'; }
        return;
      }
      if (frozen == null) {
        final lines = <WorkspaceSupplierGoodsReturnLine>[];
        for (final line in widget.receipt.lines) {
          final good = _ReceivingLineInput.milli(accepted[line.sourceLineId]!.text);
          final damage = _ReceivingLineInput.milli(damaged[line.sourceLineId]!.text);
          if (good == null || damage == null || good < 0 || damage < 0) {
            error = 'Enter a valid return quantity for each item.'; return;
          }
          if (good + damage == 0) continue;
          final returned = ledger?.goodsReturns.values.where((record) => record.receiptId == widget.receipt.id)
            .expand((record) => record.lines).where((item) => item.receiptLineId == line.sourceLineId).toList() ?? const [];
          if (good > line.acceptedMilli - returned.fold<int>(0, (sum, item) => sum + item.acceptedMilli) ||
              damage > line.damagedMilli - returned.fold<int>(0, (sum, item) => sum + item.damagedMilli)) {
            error = 'Return quantity exceeds the remaining received goods.'; return;
          }
          lines.add(WorkspaceSupplierGoodsReturnLine(receiptLineId: line.sourceLineId, productId: line.productId,
            productLabel: line.productLabel, purchaseUnit: line.purchaseUnit, stockUnit: line.stockUnit,
            unitsPerPack: line.unitsPerPack, acceptedMilli: good, damagedMilli: damage));
        }
        final key = draft.key!;
        final intent = WorkspaceSupplierGoodsReturnIntent(operationId: widget.session.newWorkspaceSupplierGoodsReturnId(),
          accountScope: key.account, workspaceId: key.store, supplierId: key.customer, receiptId: key.invoice,
          reference: reference.text.trim(), reason: reason.text.trim(), returnedOn: day.text.trim(),
          requestedAt: DateTime.now().toUtc(), lines: lines);
        if (!intent.valid) { error = 'Enter return reference, date, reason and at least one item quantity.'; return; }
        reference.text = intent.reference; reason.text = intent.reason; day.text = intent.returnedOn;
        frozen = intent; draft.save(fields);
        if (!await draft.flush()) error = 'Return is not submitted. Retry saving this same review.';
        return;
      }
      statusUnverified = true;
      complete = await widget.session.recordWorkspaceSupplierGoodsReturnDraft(draft.key!, frozen!);
      confirmed = await widget.session.readWorkspaceSupplierGoodsReturnStatus(draft.key!, frozen!) != null;
      statusUnverified = false;
      if (!complete) {
        error = confirmed ? 'Return recorded; Stock recovery is pending. Retry this same return.'
          : 'Return status needs checking. Keep and retry this saved request.';
      }
    } on Object { statusUnverified = true; error = 'Return status is unverified. Keep this request and retry recovery.'; }
    finally { if (mounted) setState(() => busy = false); }
  }
  Future<void> correctReview() async {
    if (busy || conflict || draft.busy || draft.pending != null || draft.error != null ||
        !draft.ready || draft.key == null || draft.revision == null || frozen == null || confirmed) {
      return;
    }
    setState(() => busy = true);
    try {
      correctionAttempt ??= WorkspaceLedgerFormDraft(key: draft.key!, revision: draft.revision! + 1,
        fields: {'reference': reference.text, 'reason': reason.text, 'returnedOn': day.text,
          'items': jsonEncode({for (final line in widget.receipt.lines)
            line.sourceLineId: [accepted[line.sourceLineId]!.text, damaged[line.sourceLineId]!.text]})});
      cancelledAt ??= DateTime.now().toUtc();
      if (!await widget.session.cancelUnpostedWorkspaceSupplierGoodsReturnDraft(correctionAttempt!,
          expectedRevision: draft.revision!, intent: frozen!, cancelledAt: cancelledAt!)) {
        statusUnverified = true;
        error = 'Correction status needs checking. Keep this review and retry correction or recover its saved status.';
        return;
      }
      if (!mounted) return;
      if (widget.session.supplierGoodsReturnFormKey(widget.supplierId, widget.receipt.id) != draft.key) return;
      draft.revision = correctionAttempt!.revision;
      draft.pending = null; draft.error = null;
      frozen = null; confirmed = false; complete = false; statusUnverified = false; error = null;
      correctionAttempt = null; cancelledAt = null;
    } finally { if (mounted) setState(() => busy = false); }
  }
  @override
  void dispose() {
    draft.removeListener(refresh); draft.dispose(); reference.dispose(); reason.dispose(); day.dispose();
    for (final controller in [...accepted.values, ...damaged.values]) { controller.dispose(); }
    super.dispose();
  }
  @override
  Widget build(BuildContext context) {
    final newReturnBlocked = frozen == null && widget.session.workspaceGoodsReceiptRecoveryPending;
    final editable = draft.ready && !busy && !conflict && frozen == null && !newReturnBlocked;
    final impacts = <(String, String), int>{};
    for (final line in frozen?.lines ?? <WorkspaceSupplierGoodsReturnLine>[]) {
      impacts.update((line.productId, line.stockUnit), (units) => units + line.stockUnits,
        ifAbsent: () => line.stockUnits);
    }
    String remaining(WorkspaceSupplierGoodsReceiptLine line) {
      final returns = ledger?.goodsReturns.values.where((record) => record.receiptId == widget.receipt.id)
        .expand((record) => record.lines).where((item) => item.receiptLineId == line.sourceLineId).toList() ?? const [];
      return 'Remaining: ${_ReceivingLineInput._quantity(line.acceptedMilli - returns.fold<int>(0, (sum, item) => sum + item.acceptedMilli))} from Stock · '
        '${_ReceivingLineInput._quantity(line.damagedMilli - returns.fold<int>(0, (sum, item) => sum + item.damagedMilli))} arrival damage ${line.purchaseUnit}';
    }
    Widget input(String label, TextEditingController controller, Key key,
        {bool quantity = false, String? hint, String? semantics}) =>
      SizedBox(width: quantity ? 108 : 220, child: Semantics(label: semantics,
        child: TextField(key: key, controller: controller, enabled: editable,
        keyboardType: quantity ? const TextInputType.numberWithOptions(decimal: true) : TextInputType.text,
        decoration: InputDecoration(labelText: label, hintText: hint,
          floatingLabelBehavior: FloatingLabelBehavior.always),
        onChanged: (_) => draft.save(fields))));
    return PopScope(canPop: !busy && !draft.busy && draft.pending == null && draft.error == null && !conflict,
      child: SafeArea(top: false, child: SingleChildScrollView(
        padding: EdgeInsets.fromLTRB(16, 12, 16, 16 + MediaQuery.viewInsetsOf(context).bottom),
        child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          Wrap(alignment: WrapAlignment.spaceBetween, crossAxisAlignment: WrapCrossAlignment.center, children: [
            Text('Return goods to supplier', style: Theme.of(context).textTheme.titleMedium),
            TextButton(key: const Key('supplier-return-close'), onPressed: busy || conflict || draft.busy ? null : () async {
              setState(() => busy = true);
              if (await draft.flush() && context.mounted) { Navigator.pop(context); }
              else if (mounted) { setState(() => busy = false); }
            }, child: const Text('Close'))]),
          Text('${ledger?.supplierName ?? ''} · ${widget.receipt.reference}'),
          const Text('Record goods handed back. Supplier credit and money received are recorded separately.'),
          if (newReturnBlocked) const Text('Recover the saved return before recording another goods return.'),
          Wrap(spacing: 12, runSpacing: 8, children: [input('Return reference', reference, const Key('supplier-return-reference')),
            input('Date', day, const Key('supplier-return-date'), hint: 'YYYY-MM-DD',
              semantics: 'Return date, YYYY-MM-DD')]),
          input('Reason for return', reason, const Key('supplier-return-reason')),
          for (final line in widget.receipt.lines) Padding(padding: const EdgeInsets.symmetric(vertical: 8),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text(line.productLabel, style: const TextStyle(fontSize: 14, color: MoolColors.navy, fontWeight: FontWeight.w600)),
              Text('Accepted into Stock ${_ReceivingLineInput._quantity(line.acceptedMilli)} · Arrival damage (not stocked) ${_ReceivingLineInput._quantity(line.damagedMilli)} ${line.purchaseUnit}',
                style: const TextStyle(fontSize: 12, color: MoolColors.ink)),
              Text(remaining(line), style: const TextStyle(fontSize: 12, color: MoolColors.ink)),
              Wrap(spacing: 12, runSpacing: 8, children: [
                input('Stock', accepted[line.sourceLineId]!, ValueKey(('supplier-return-accepted', line.sourceLineId)),
                  quantity: true, semantics: 'Return quantity from Stock'),
                if (line.damagedMilli > 0) input('Damage', damaged[line.sourceLineId]!,
                  ValueKey(('supplier-return-damaged', line.sourceLineId)), quantity: true,
                  semantics: 'Return quantity from arrival damage')]),
            ])),
          if (frozen != null) Text(statusUnverified ? 'Return status unverified' : complete ? 'Goods returned · Stock updated' : confirmed ? 'Return recorded · verify Stock'
            : draft.pending != null || draft.error != null ? 'Review save status unverified' : 'Review saved · confirm return',
            key: const Key('supplier-return-status'), style: const TextStyle(color: MoolColors.navy, fontWeight: FontWeight.w600)),
          for (final impact in impacts.entries) Text('${frozen!.lines.firstWhere((line) => line.productId == impact.key.$1 && line.stockUnit == impact.key.$2).productLabel} · '
            'Stock to remove: ${impact.value} ${impact.key.$2}', key: ValueKey(('supplier-return-stock-impact', impact.key))),
          if (error != null || draft.error != null) Text(error ?? draft.error!,
            style: const TextStyle(color: Color(0xffa52a2a), fontSize: 12)),
          Wrap(spacing: 8, children: [
            if (frozen != null && !confirmed) TextButton(key: const Key('supplier-return-correct'),
              onPressed: busy || conflict || draft.busy || draft.pending != null || draft.error != null ? null : correctReview,
              child: const Text('Cancel review to correct')),
            TextButton(key: const Key('supplier-return-confirm'), onPressed: busy || conflict || !draft.ready || newReturnBlocked ? null : submit,
              child: Text(confirmed && complete ? 'Start another return' : frozen == null ? 'Review & save return'
                : confirmed ? 'Verify returned Stock' : 'Confirm goods returned')),
            TextButton(key: const Key('supplier-return-recover'), onPressed: busy || draft.busy ? null : load,
              child: const Text('Recover saved return'))]),
        ]))));
  }
}

Future<void> _showSupplierShortage(BuildContext context, WorkSession session,
    WorkspacePurchaseSavedCopy copy) => showModalBottomSheet<void>(context: context,
      isScrollControlled: true, isDismissible: false, enableDrag: false,
      builder: (_) => _StoreSupplierShortageSheet(session: session, copy: copy));

class _StoreSupplierShortageSheet extends StatefulWidget {
  const _StoreSupplierShortageSheet({required this.session, required this.copy});
  final WorkSession session;
  final WorkspacePurchaseSavedCopy copy;
  @override
  State<_StoreSupplierShortageSheet> createState() => _StoreSupplierShortageSheetState();
}

class _StoreSupplierShortageSheetState extends State<_StoreSupplierShortageSheet> {
  late final _LedgerFormAutosave draft;
  final quantity = TextEditingController();
  int? billLine;
  String? deliveryId, sourceLine;
  bool reviewed = false, busy = false, recovered = false, confirmed = false;
  WorkspaceSupplierShortageIntent? frozen;
  WorkspaceLedgerFormDraft? resetAttempt;
  String? error;
  bool get current => draft.key != null &&
    widget.session.supplierShortageRecoveryFormKey(widget.copy) == draft.key;
  WorkspaceSupplierLedger? get ledger => widget.session.workspaceSupplierLedger(widget.copy.supplier.id);
  Map<String, String> get fields => {
    'billLineIndex': billLine == null ? '' : '$billLine',
    'deliveryId': deliveryId ?? '', 'lineId': sourceLine ?? '',
    // Unfrozen text is retained verbatim, including an incomplete decimal.
    'quantityMilli': frozen == null ? 'input:${quantity.text}' : '${frozen!.quantityMilli}',
    'attributionReviewed': '$reviewed',
    if (frozen != null) 'attempt': jsonEncode(frozen!.toJson()),
  };
  void refresh() { if (mounted) setState(() {}); }
  void changed() { setState(() {}); draft.save(fields); }
  @override
  void initState() {
    super.initState();
    draft = _LedgerFormAutosave(widget.session, widget.session.supplierShortageRecoveryFormKey(widget.copy))
      ..addListener(refresh);
    unawaited(load());
  }
  void restore(Map<String, String> saved) {
    final attempt = saved['attempt'];
    frozen = attempt == null || attempt.isEmpty ? null : WorkspaceSupplierShortageIntent.fromJson(jsonDecode(attempt));
    billLine = frozen?.billLineIndex ?? int.tryParse(saved['billLineIndex'] ?? '');
    deliveryId = frozen?.expectedDeliveryId ?? saved['deliveryId'];
    sourceLine = frozen?.receiptLineId ?? saved['lineId'];
    reviewed = frozen != null || saved['attributionReviewed'] == 'true';
    final text = saved['quantityMilli'] ?? '';
    quantity.text = frozen != null ? _ReceivingLineInput._quantity(frozen!.quantityMilli)
      : text.startsWith('input:') ? text.substring(6)
      : int.tryParse(text) == null ? text : _ReceivingLineInput._quantity(int.parse(text));
  }
  Future<void> verify() async {
    confirmed = false;
    if (frozen == null) return;
    final proof = await widget.session.readWorkspaceSupplierShortageStatus(draft.key!, frozen!);
    if (!mounted || !current) throw StateError('Original Store is unavailable');
    confirmed = proof != null;
  }
  Future<void> load() async {
    if (busy || draft.busy) return;
    setState(() { busy = true; error = null; });
    try {
      if (!current) throw StateError('Original Store is unavailable');
      if (draft.pending != null) {
        draft.save(fields);
        if (!await draft.flush()) throw StateError('Input save is pending');
      }
      // Recover the persisted attempt before requiring account cache hydration.
      final saved = await draft.load();
      if (saved == null || !mounted || !current) throw StateError('Saved review is unavailable');
      restore(saved);
      await verify();
      recovered = await widget.session.recoverCustomerLedger();
      if (!mounted || !current) throw StateError('Original Store is unavailable');
      if (!recovered) {
        error = confirmed ? 'Shortage recorded. Supplier account refresh is pending.'
          : 'Supplier account is unavailable. Your saved review is kept; retry before recording.';
      }
    } on Object {
      recovered = false;
      error = 'Status is unverified. Keep this review and retry; do not record another shortage.';
    } finally { if (mounted) setState(() => busy = false); }
  }
  List<(int, WorkspaceSupplierGoodsReceipt, WorkspaceSupplierGoodsReceiptLine)> get options {
    final account = ledger;
    if (!recovered || !current || account == null ||
        widget.session.supplierShortageFormKey(widget.copy) != draft.key) { return const []; }
    return _supplierShortageOptions(widget.copy, account);
  }
  String optionId(int index, String delivery, String line) => jsonEncode([index, delivery, line]);
  Future<void> submit() async {
    if (busy || draft.busy || !current || !draft.ready) return;
    setState(() { busy = true; error = null; });
    try {
      if (!await draft.flush()) throw StateError('Input is not saved');
      if (!mounted || !current) throw StateError('Original Store is unavailable');
      if (confirmed) {
        resetAttempt ??= WorkspaceLedgerFormDraft(key: draft.key!, revision: draft.revision! + 1, fields: const {});
        if (!await widget.session.resetConfirmedWorkspaceSupplierShortageDraft(resetAttempt!,
            expectedRevision: draft.revision!)) { throw StateError('Verified reset failed'); }
        if (!mounted || !current) throw StateError('Original Store is unavailable');
        draft.revision = resetAttempt!.revision;
        restore(const {}); resetAttempt = null; confirmed = false;
        recovered = await widget.session.recoverCustomerLedger();
        return;
      }
      if (frozen == null) {
        final amount = _ReceivingLineInput.milli(quantity.text.trim());
        final account = ledger;
        if (!recovered || widget.session.supplierShortageFormKey(widget.copy) != draft.key || account == null) {
          throw StateError('Supplier account needs recovery');
        }
        final intent = amount == null || billLine == null || deliveryId == null || sourceLine == null ? null
          : account.reviewShortageIntent(operationId: widget.session.newWorkspaceSupplierShortageId(),
              billId: widget.copy.draft.id, billLineIndex: billLine!, deliveryId: deliveryId!, lineId: sourceLine!,
              quantityMilli: amount, attributionReviewed: reviewed, requestedAt: DateTime.now().toUtc());
        if (intent == null) {
          error = 'Choose the matching bill item and delivery, confirm the match, and enter a valid missing quantity.';
          return;
        }
        frozen = intent;
        draft.save(fields);
        if (!await draft.flush()) throw StateError('Review is not saved yet');
        if (!mounted || !current) throw StateError('Original Store is unavailable');
      }
      await widget.session.recordWorkspaceSupplierShortageDraft(draft.key!, frozen!);
      await verify();
      recovered = await widget.session.recoverCustomerLedger();
      if (!mounted || !current) throw StateError('Original Store is unavailable');
      if (!confirmed) {
        error = 'Not confirmed. The exact saved review is kept. Retry verification before recording again.';
      } else if (!recovered) {
        error = 'Shortage recorded. Supplier account refresh is pending.';
      }
    } on Object {
      error = 'Status is unverified. Your review is kept. Retry to verify the same shortage.';
    } finally { if (mounted) setState(() => busy = false); }
  }
  Future<void> close() async {
    if (busy || draft.busy) return;
    if (await draft.flush() && mounted) Navigator.of(context).pop();
  }
  @override
  void dispose() {
    draft.removeListener(refresh); draft.dispose(); quantity.dispose(); super.dispose();
  }
  @override
  Widget build(BuildContext context) {
    final accountReady = recovered && current && widget.session.supplierShortageFormKey(widget.copy) == draft.key;
    final editable = draft.ready && accountReady && !busy && frozen == null;
    final choices = options;
    final history = accountReady ? ledger!.shortageClaims.values.where((claim) =>
      claim.copyId == widget.copy.id && claim.copyRevision == widget.copy.revision).toList()
      : const <WorkspaceSupplierShortageClaim>[];
    final historyOnly = frozen == null && accountReady && choices.isEmpty && history.isNotEmpty;
    final selected = billLine == null || deliveryId == null || sourceLine == null ? null
      : optionId(billLine!, deliveryId!, sourceLine!);
    final visibleSelection = choices.any((o) => optionId(o.$1, o.$2.expectedDeliveryId, o.$3.sourceLineId) == selected);
    return PopScope(canPop: !busy && !draft.busy && draft.ready && draft.pending == null && draft.error == null,
      child: SafeArea(child: SingleChildScrollView(
        padding: EdgeInsets.fromLTRB(16, 12, 16, MediaQuery.viewInsetsOf(context).bottom + 16),
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
          Wrap(spacing: 12, crossAxisAlignment: WrapCrossAlignment.center, children: [
            Text(historyOnly ? 'Shortage history' : 'Review short delivery', style: Theme.of(context).textTheme.titleMedium),
            TextButton(onPressed: busy || draft.busy ? null : close, child: const Text('Close')),
          ]),
          Text('${widget.copy.supplier.name} · Bill ${widget.copy.draft.invoiceReference}'),
          Text(historyOnly
            ? 'Missing quantities already recorded for this bill. Viewing them does not change Stock, dues or refunds.'
            : 'Record goods still missing from this bill. This does not change Stock, reduce dues or issue a refund.'),
          const SizedBox(height: 8),
          if (frozen == null) ...[
            if (choices.isNotEmpty) DropdownButtonFormField<String>(
              key: ValueKey('supplier-shortage-source-$visibleSelection-$selected'), initialValue: visibleSelection ? selected : null,
              isExpanded: true, decoration: const InputDecoration(labelText: 'Bill item · delivery'),
              items: [for (final option in choices) DropdownMenuItem(
                value: optionId(option.$1, option.$2.expectedDeliveryId, option.$3.sourceLineId),
                child: Text('${option.$1 + 1}. ${widget.copy.draft.goods[option.$1]['name'] ?? option.$3.productLabel} · '
                  '${option.$2.reference}', maxLines: 2, overflow: TextOverflow.ellipsis))],
              onChanged: !editable ? null : (value) {
                final choice = choices.firstWhere((o) => optionId(o.$1, o.$2.expectedDeliveryId, o.$3.sourceLineId) == value);
                billLine = choice.$1; deliveryId = choice.$2.expectedDeliveryId; sourceLine = choice.$3.sourceLineId;
                reviewed = false; changed();
              }),
            if (choices.isEmpty && accountReady) Text(history.isEmpty
              ? 'No missing quantity is available to review. Check the saved delivery and its expected quantity.'
              : 'No further missing quantity is available to record for this bill.'),
            if (choices.isEmpty && quantity.text.isNotEmpty) ...[
              Text('Saved missing qty: ${quantity.text}', key: const Key('supplier-shortage-retained-quantity')),
              const Text('Your input is kept. Verify the saved bill and delivery before recording.'),
            ],
            if (history.isNotEmpty) ...[
              const Text('Recorded shortages', style: TextStyle(fontWeight: FontWeight.w600)),
              for (final claim in history) Text(
                '${widget.copy.draft.goods[claim.billLineIndex]['name'] ?? 'Bill item ${claim.billLineIndex + 1}'} · '
                'Missing qty ${_ReceivingLineInput._quantity(claim.quantityMilli)} · Unit ${claim.purchaseUnit} · '
                'Recorded ${_registerDate(claim.recordedAt)}', key: ValueKey(('supplier-shortage-history', claim.operationId))),
              const Text('These are missing-goods records, not credit notes or refunds.'),
            ],
            if (!accountReady && !busy) Text(recovered
              ? 'Confirm the supplier’s starting balance and this bill in Purchases before reviewing missing goods.'
              : 'Supplier account is unavailable. Your saved input is kept. Retry verification.'),
            if (accountReady && choices.isNotEmpty) ...[
              SizedBox(width: 140, child: TextField(key: const Key('supplier-shortage-quantity'), controller: quantity,
              enabled: editable, keyboardType: const TextInputType.numberWithOptions(decimal: true),
              decoration: const InputDecoration(labelText: 'Missing qty'), onChanged: (_) => changed())),
            CheckboxListTile(key: const Key('supplier-shortage-match'), contentPadding: EdgeInsets.zero,
              controlAffinity: ListTileControlAffinity.leading, value: reviewed,
              title: const Text('This bill item and delivery refer to the same goods'),
                onChanged: editable ? (value) { reviewed = value == true; changed(); } : null),
            ],
          ] else ...[
            Text('${widget.copy.draft.goods[frozen!.billLineIndex]['name'] ?? 'Bill item ${frozen!.billLineIndex + 1}'} · '
              'Missing ${_ReceivingLineInput._quantity(frozen!.quantityMilli)} ${frozen!.purchaseUnit}'),
            Text(!current ? 'Return to the original Store to verify this review'
              : confirmed ? 'Shortage recorded · no credit or refund applied'
              : 'Saved review · recording not yet confirmed', key: const Key('supplier-shortage-status')),
          ],
          if (draft.error != null) Text(draft.error!),
          if (error != null) Text(error!),
          Wrap(spacing: 8, children: [
            TextButton(key: const Key('supplier-shortage-retry'), onPressed: busy || draft.busy ? null : load,
              child: const Text('Retry verification')),
            if (frozen != null || (accountReady && choices.isNotEmpty)) FilledButton(key: const Key('supplier-shortage-submit'),
              onPressed: busy || draft.busy || !draft.ready || !current ||
                (!confirmed && frozen == null && !editable) ? null : submit,
              child: Text(confirmed ? 'Review another shortage' : frozen == null ? 'Record shortage' : 'Retry saved shortage')),
          ]),
        ]))));
  }
}

Future<void> _showSupplierCredit(BuildContext context, WorkSession session,
    WorkspacePurchaseSavedCopy copy) => showModalBottomSheet<void>(context: context,
      isScrollControlled: true, useSafeArea: true, isDismissible: false, enableDrag: false,
      builder: (_) => _StoreSupplierCreditSheet(session: session, copy: copy));

class _StoreSupplierCreditSheet extends StatefulWidget {
  const _StoreSupplierCreditSheet({required this.session, required this.copy});
  final WorkSession session;
  final WorkspacePurchaseSavedCopy copy;
  @override
  State<_StoreSupplierCreditSheet> createState() => _StoreSupplierCreditSheetState();
}

class _StoreSupplierCreditSheetState extends State<_StoreSupplierCreditSheet> {
  late final _LedgerFormAutosave draft;
  final reference = TextEditingController(), amount = TextEditingController(),
    reason = TextEditingController(), date = TextEditingController();
  final selected = <String, (WorkspaceSupplierCreditSupport, TextEditingController)>{};
  WorkspaceSupplierCreditIntent? frozen;
  WorkspaceLedgerFormDraft? resetAttempt;
  bool busy = false, recovered = false, confirmed = false, conflict = false;
  String? error;
  WorkspaceSupplierLedger? get ledger => widget.session.workspaceSupplierLedger(widget.copy.supplier.id);
  bool get current => draft.key != null &&
    widget.session.supplierCreditFormKey(widget.copy) == draft.key;
  String identity(WorkspaceSupplierCreditSupport support) => jsonEncode([
    support.kind.name, support.receiptId, support.receiptLineId, support.billLineIndex,
    support.returnOperationId, support.shortageClaimId]);
  String printedDate(String day) => day.length == 10
    ? '${day.substring(8)}/${day.substring(5, 7)}/${day.substring(0, 4)}' : day;
  String? get occurredOn {
    final match = RegExp(r'^(\d{2})/(\d{2})/(\d{4})$').firstMatch(date.text.trim());
    if (match == null) return null;
    final day = int.parse(match[1]!), month = int.parse(match[2]!), year = int.parse(match[3]!);
    final value = DateTime(year, month, day);
    if (value.year != year || value.month != month || value.day != day) return null;
    return '${match[3]}-${match[2]}-${match[1]}';
  }
  Map<String, String> get fields => {
    'reference': reference.text, 'amount': amount.text, 'reason': reason.text,
    'occurredOn': frozen?.occurredOn ?? date.text,
    'supports': frozen == null ? jsonEncode([for (final value in selected.values)
      {'support': value.$1.toJson(), 'quantity': value.$2.text}])
      : jsonEncode(frozen!.supports.map((s) => s.toJson()).toList()),
    if (frozen != null) 'attempt': jsonEncode(frozen!.toJson()),
  };
  @override
  void initState() {
    super.initState();
    draft = _LedgerFormAutosave(widget.session, widget.session.supplierCreditFormKey(widget.copy));
    draft.addListener(refresh);
    unawaited(load());
  }
  void refresh() { if (mounted) setState(() {}); }
  void clearSelections() {
    for (final value in selected.values) { value.$2.dispose(); }
    selected.clear();
  }
  void restore(Map<String, String> saved) {
    final text = saved['attempt'];
    final intent = text == null || text.isEmpty ? null : WorkspaceSupplierCreditIntent.fromJson(jsonDecode(text));
    final restored = <String, (WorkspaceSupplierCreditSupport, TextEditingController)>{};
    try {
      if (intent != null) {
        for (final support in intent.supports) {
          restored[identity(support)] = (support, TextEditingController(text: _ReceivingLineInput._quantity(support.quantityMilli)));
        }
      } else {
        final raw = jsonDecode(saved['supports']?.isNotEmpty == true ? saved['supports']! : '[]');
        if (raw is! List || raw.length > 200) { throw const FormatException('Invalid saved credit selection'); }
        for (final item in raw) {
          if (item is! Map || item['quantity'] is! String) { throw const FormatException('Invalid saved credit quantity'); }
          final support = WorkspaceSupplierCreditSupport.fromJson(item['support']);
          if (support.billLineIndex >= widget.copy.draft.goods.length) { throw const FormatException('Saved credit item unavailable'); }
          if (restored.containsKey(identity(support))) { throw const FormatException('Duplicate saved credit selection'); }
          restored[identity(support)] = (support, TextEditingController(text: item['quantity'] as String));
        }
      }
    } on Object {
      for (final value in restored.values) { value.$2.dispose(); }
      rethrow;
    }
    clearSelections(); selected.addAll(restored);
    reference.text = saved['reference'] ?? '';
    amount.text = saved['amount'] ?? '';
    reason.text = saved['reason'] ?? '';
    date.text = intent == null ? saved['occurredOn'] ?? '' : printedDate(intent.occurredOn);
    frozen = intent;
  }
  Future<void> verifyStatus() async {
    confirmed = false;
    if (!current || !recovered) { throw StateError('Original supplier bill unavailable'); }
    if (frozen != null) {
      final proof = await widget.session.readWorkspaceSupplierCreditStatus(draft.key!, frozen!);
      if (!current) { throw StateError('Store changed'); }
      confirmed = proof != null;
    }
  }
  Future<void> load() async {
    if (busy || draft.busy) return;
    setState(() { busy = true; recovered = false; confirmed = false; });
    try {
      if (draft.pending != null) {
        draft.save(fields);
        if (!await draft.flush()) {
          error = 'Credit-note input is not saved yet. Retry saving; your entries are kept here.';
          return;
        }
      }
      if (!mounted || !current) { throw StateError('Original supplier bill unavailable'); }
      recovered = await widget.session.recoverCustomerLedger();
      if (!mounted || !current || !recovered) { throw StateError('Saved supplier account unavailable'); }
      final saved = await draft.load();
      if (!mounted || saved == null) { throw StateError('Saved input unavailable'); }
      restore(saved);
      conflict = false; error = null; resetAttempt = null;
      await verifyStatus();
    } on Object {
      recovered = false; conflict = true;
      error = 'Credit-note status could not be verified. Keep these details and retry recovery.';
    } finally { if (mounted) setState(() => busy = false); }
  }
  Future<void> submit() async {
    if (busy || conflict || !recovered || !draft.ready || !current) return;
    setState(() { busy = true; error = null; });
    try {
      if (!await draft.flush() || !mounted || !current) return;
      if (confirmed) {
        resetAttempt ??= WorkspaceLedgerFormDraft(key: draft.key!, revision: draft.revision! + 1,
          fields: const {'reference': '', 'amount': '', 'reason': '', 'occurredOn': '', 'supports': '[]'});
        if (await widget.session.resetConfirmedWorkspaceSupplierCreditDraft(resetAttempt!, expectedRevision: draft.revision!)) {
          draft.revision = resetAttempt!.revision; draft.pending = null; draft.error = null;
          reference.clear(); amount.clear(); reason.clear(); date.clear(); clearSelections();
          frozen = null; confirmed = false; resetAttempt = null;
        } else { error = 'Recorded credit note is kept. Retry recovery before starting another.'; }
        return;
      }
      if (frozen == null) {
        final minor = WorkspacePurchaseEntryDraft.printedPaise(amount.text), day = occurredOn;
        final opening = ledger?.openingRecord;
        final options = ledger?.availableCreditSupports(widget.copy.draft.id) ?? const [];
        final supports = <WorkspaceSupplierCreditSupport>[];
        for (final value in selected.values) {
          final quantity = _ReceivingLineInput.milli(value.$2.text);
          final option = options.where((o) => identity(o.$1) == identity(value.$1)).firstOrNull;
          if (quantity == null || quantity <= 0 || option == null || quantity > option.$1.quantityMilli) {
            error = 'Enter a credited quantity within the available goods shown for each selected item.';
            return;
          }
          supports.add(WorkspaceSupplierCreditSupport.fromJson({...value.$1.toJson(), 'quantityMilli': quantity}));
        }
        if (minor == null || minor <= 0 || day == null || opening == null || supports.isEmpty) {
          error = 'Enter the credit-note amount and date, and select the goods credited by your supplier.';
          return;
        }
        final key = draft.key!;
        final intent = WorkspaceSupplierCreditIntent(operationId: widget.session.newWorkspaceSupplierCreditId(),
          accountScope: key.account, workspaceId: key.store, supplierId: key.customer,
          billId: widget.copy.draft.id, copyId: widget.copy.id, copyRevision: widget.copy.revision,
          openingId: opening.id, openingRevision: opening.revision, reference: reference.text.trim(),
          occurredOn: day, reason: reason.text.trim(), amountMinor: minor, requestedAt: DateTime.now().toUtc(), supports: supports);
        if (!intent.valid) {
          error = 'Check the credit-note number, date and reason. Select each goods source only once.';
          return;
        }
        final reviewedLedger = ledger;
        if (reviewedLedger == null || !reviewedLedger.valid || !reviewedLedger.historyComplete ||
            reviewedLedger.accountScope != key.account || reviewedLedger.workspaceId != key.store ||
            reviewedLedger.supplierId != key.customer || reviewedLedger.asOf.isAfter(intent.requestedAt)) {
          recovered = false;
          error = 'Recover the saved supplier account before confirming this credit note. Your entries are kept.';
          return;
        }
        // Pure admission only: never adopt or persist this tentative ledger.
        // Native posting still verifies a fresh predecessor after draft saving.
        if (reviewedLedger.recordSupplierCredit(intent.commit(revision: reviewedLedger.revision + 1,
              at: intent.requestedAt), expectedRevision: reviewedLedger.revision) == null) {
          error = 'Check the credit-note amount and selected goods against this bill. No credit note was recorded.';
          return;
        }
        // Frozen fields must exactly match the immutable request after trimming.
        reference.text = intent.reference; reason.text = intent.reason;
        amount.text = (minor / 100).toStringAsFixed(2);
        frozen = intent;
        draft.save(fields);
        if (!await draft.flush() || !mounted || !current) {
          error = 'Credit note is not submitted. Save and retry these same details.';
          return;
        }
      }
      final posted = await widget.session.recordWorkspaceSupplierCreditDraft(draft.key!, frozen!);
      if (!mounted || !current) return;
      recovered = await widget.session.recoverCustomerLedger();
      await verifyStatus();
      error = posted && confirmed ? null : confirmed ? null
        : 'Credit note is not confirmed. Recover and retry this same request; do not enter it again.';
    } on Object {
      recovered = false;
      error = 'Credit-note status is unverified. Keep the request and retry recovery.';
    } finally { if (mounted) setState(() => busy = false); }
  }
  @override
  void dispose() {
    draft.removeListener(refresh); draft.dispose(); clearSelections();
    reference.dispose(); amount.dispose(); reason.dispose(); date.dispose(); super.dispose();
  }
  @override
  Widget build(BuildContext context) {
    final options = ledger?.availableCreditSupports(widget.copy.draft.id) ?? const [];
    final rows = <String, (WorkspaceSupplierCreditSupport, String, String)>{
      for (final option in options) identity(option.$1): option,
    };
    for (final value in selected.values) {
      rows.putIfAbsent(identity(value.$1), () => (value.$1,
        value.$1.billLineIndex < widget.copy.draft.goods.length
          ? widget.copy.draft.goods[value.$1.billLineIndex]['name'] ?? 'Credited item' : 'Credited item unavailable',
        value.$1.billLineIndex < widget.copy.draft.goods.length
          ? widget.copy.draft.goods[value.$1.billLineIndex]['pack'] ?? '' : ''));
    }
    final editable = draft.ready && recovered && current && !busy && !conflict && frozen == null;
    final savedVerified = draft.pending == null && draft.error == null && draft.revision != null && !draft.busy;
    Future<void> close() async {
      if (!busy && !conflict && await draft.flush() && context.mounted) Navigator.pop(context);
    }
    return PopScope(canPop: !busy && !draft.busy && draft.pending == null && draft.error == null && !conflict,
      onPopInvokedWithResult: (didPop, result) async { if (!didPop) await close(); },
      child: SafeArea(top: false, child: Padding(
        padding: EdgeInsets.only(bottom: MediaQuery.viewInsetsOf(context).bottom),
        child: SingleChildScrollView(
        padding: const EdgeInsets.fromLTRB(16, 12, 16, 16),
        child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          Wrap(alignment: WrapAlignment.spaceBetween, crossAxisAlignment: WrapCrossAlignment.center, children: [
            Text('Supplier credit note', style: Theme.of(context).textTheme.titleMedium),
            TextButton(key: const Key('supplier-credit-close'), onPressed: busy || conflict ? null : close,
              child: const Text('Close'))]),
          Text('${widget.copy.supplier.name} · ${widget.copy.draft.invoiceReference}'),
          const Text('Enter the credit note received from your supplier. Reduces dues; no Stock change or refund.'),
          TextField(key: const Key('supplier-credit-reference'), controller: reference, enabled: editable,
            decoration: const InputDecoration(labelText: 'Credit note No.'), onChanged: (_) => draft.save(fields)),
          Wrap(spacing: 12, runSpacing: 8, children: [
            _purchaseCompactLabeledField('Credit note date', width: 170, field: TextField(key: const Key('supplier-credit-date'), controller: date,
              enabled: editable, keyboardType: TextInputType.datetime,
              decoration: const InputDecoration(helperText: 'DD/MM/YYYY'),
              onChanged: (_) => draft.save(fields))),
            _purchaseCompactLabeledField('Amount credited (₹)', width: 170, field: TextField(key: const Key('supplier-credit-amount'), controller: amount,
              enabled: editable, keyboardType: const TextInputType.numberWithOptions(decimal: true),
              decoration: const InputDecoration(), onChanged: (_) => draft.save(fields))),
          ]),
          TextField(key: const Key('supplier-credit-reason'), controller: reason, enabled: editable,
            decoration: const InputDecoration(labelText: 'Reason on credit note'), onChanged: (_) => draft.save(fields)),
          const SizedBox(height: 12),
          Text('Goods credited', style: Theme.of(context).textTheme.titleSmall),
          if (rows.isEmpty) const Text('First link this bill to received goods or record goods returned. Short-delivery credit needs a reviewed shortage record.'),
          for (final entry in rows.entries) ...[
            CheckboxListTile(key: ValueKey('supplier-credit-select-${entry.key}'), contentPadding: EdgeInsets.zero,
              controlAffinity: ListTileControlAffinity.leading, value: selected.containsKey(entry.key),
              title: Text(entry.value.$2), subtitle: frozen == null
                ? Text('Available ${_ReceivingLineInput._quantity(entry.value.$1.quantityMilli)} ${entry.value.$3}') : null,
              onChanged: editable ? (checked) {
                setState(() {
                  if (checked == true) {
                    selected[entry.key] = (entry.value.$1, TextEditingController(text: _ReceivingLineInput._quantity(entry.value.$1.quantityMilli)));
                  } else { selected.remove(entry.key)?.$2.dispose(); }
                });
                draft.save(fields);
              } : null),
            if (selected[entry.key] case final value?) Align(alignment: Alignment.centerLeft,
              child: _purchaseCompactLabeledField('Credited qty', width: 112, field: TextField(key: ValueKey('supplier-credit-qty-${entry.key}'),
                controller: value.$2, enabled: editable, keyboardType: const TextInputType.numberWithOptions(decimal: true),
                decoration: const InputDecoration(), onChanged: (_) => draft.save(fields)))),
          ],
          if (frozen != null) Text(confirmed ? 'Credit note recorded · ${_purchaseAmount(frozen!.amountMinor)}'
            : savedVerified ? 'Saved credit-note request · not confirmed. Recover before retrying.'
            : 'Saved status unverified · keep this request and retry saving.', key: const Key('supplier-credit-status')),
          if (error != null || draft.error != null) Text(error ?? draft.error!),
          TextButton(key: const Key('supplier-credit-recover'), onPressed: busy || draft.busy ? null : load,
            child: const Text('Recover saved credit note')),
          FilledButton(key: const Key('supplier-credit-submit'),
            onPressed: draft.ready && recovered && current && !busy && !conflict && !draft.busy && draft.error == null
              && (frozen != null || rows.isNotEmpty) ? submit : null,
            child: Text(busy ? 'Recording…' : confirmed ? 'Record another credit note'
              : frozen == null ? 'Save supplier credit note' : 'Retry same credit note')),
        ])))));
  }
}

Future<void> _showSupplierAllocation(BuildContext context, WorkSession session,
    WorkspacePurchaseSavedCopy copy) => showModalBottomSheet<void>(context: context,
      isScrollControlled: true, isDismissible: false, enableDrag: false,
      builder: (_) => _StoreSupplierAllocationSheet(session: session, copy: copy));

class _StoreSupplierAllocationSheet extends StatefulWidget {
  const _StoreSupplierAllocationSheet({required this.session, required this.copy});
  final WorkSession session;
  final WorkspacePurchaseSavedCopy copy;
  @override
  State<_StoreSupplierAllocationSheet> createState() => _StoreSupplierAllocationSheetState();
}

class _StoreSupplierAllocationSheetState extends State<_StoreSupplierAllocationSheet> {
  late final _LedgerFormAutosave draft;
  final amount = TextEditingController();
  WorkspaceSupplierMoneySourceKind? sourceKind;
  String sourceId = '';
  WorkspaceSupplierMoneyAllocationIntent? frozen;
  WorkspaceLedgerFormDraft? resetAttempt;
  bool busy = false, recovered = false, confirmed = false, conflict = false;
  String? error;
  WorkspaceSupplierLedger? get ledger => widget.session.workspaceSupplierLedger(widget.copy.supplier.id);
  List<(WorkspaceSupplierMoneySourceKind, String, String, int)> get sources {
    final current = ledger;
    if (current == null || !current.valid) return const [];
    final list = <(WorkspaceSupplierMoneySourceKind, String, String, int)>[];
    void add(WorkspaceSupplierMoneySourceKind kind, String id, String label) {
      final remaining = current.unallocatedMoneyMinor(kind, id);
      if (remaining != null && (remaining > 0 || frozen != null)) {
        list.add((kind, id, label, remaining));
      }
    }
    final opening = current.openingRecord;
    if (opening?.supplierCredit == true) {
      add(WorkspaceSupplierMoneySourceKind.openingAdvance, opening!.id, 'Starting advance / credit');
    }
    for (final entry in current.entries.where((e) => e.origin == WorkspaceSupplierEntryOrigin.supplierAccount &&
      e.moneyReview != null && (e.kind == WorkspaceSupplierEntryKind.advance || e.kind == WorkspaceSupplierEntryKind.payment))) {
      add(entry.kind == WorkspaceSupplierEntryKind.advance ? WorkspaceSupplierMoneySourceKind.accountAdvance
        : WorkspaceSupplierMoneySourceKind.accountPayment, entry.operationId,
        '${entry.kind == WorkspaceSupplierEntryKind.advance ? 'Advance' : 'Account payment'} · ${entry.reference}'
        ' · ${entry.moneyReview!.occurredOn} · ${entry.paymentMethod ?? 'Method not recorded'}');
    }
    for (final bill in current.purchaseBills.values.where((b) => b.billId != widget.copy.draft.id)) {
      add(WorkspaceSupplierMoneySourceKind.manualBillSurplus, bill.billId,
        'Bill credit · ${bill.copy.draft.invoiceReference} · ${bill.copy.draft.invoiceDate}');
    }
    return [for (var index = 0; index < list.length; index++)
      (list[index].$1, list[index].$2,
        list.where((source) => source.$3 == list[index].$3).length > 1
          ? '${list[index].$3} · Record ${index + 1}' : list[index].$3,
        list[index].$4)];
  }
  String sourceValue(WorkspaceSupplierMoneySourceKind kind, String id) => jsonEncode([kind.name, id]);
  Map<String, String> get fields => {'amount': amount.text, 'sourceKind': sourceKind?.name ?? '',
    'sourceId': sourceId, if (frozen != null) 'attempt': jsonEncode(frozen!.intentToJson())};

  @override
  void initState() {
    super.initState();
    draft = _LedgerFormAutosave(widget.session, widget.session.supplierAllocationFormKey(widget.copy));
    draft.addListener(refresh);
    unawaited(load());
  }
  void refresh() { if (mounted) setState(() {}); }
  void inspect() {
    confirmed = false;
    if (frozen == null || !recovered) return;
    final saved = ledger?.billMoneyAllocations[frozen!.operationId];
    if (saved != null) {
      confirmed = jsonEncode(saved.intentToJson()) == jsonEncode(frozen!.intentToJson());
      if (!confirmed) { conflict = true; error = 'Recorded allocation differs. Keep this request for review.'; }
    }
  }
  Future<void> recordMoney(bool advance) async {
    final session = widget.session;
    if (busy || conflict || frozen != null || !draft.ready || !recovered ||
        session.supplierAllocationFormKey(widget.copy) != draft.key) { return; }
    setState(() => busy = true);
    try {
      if (!await draft.flush() || !mounted ||
          session.supplierAllocationFormKey(widget.copy) != draft.key) { return; }
      await _showSupplierMoneyEntry(context, session,
        _StoreSupplierMoneyTarget(supplierId: widget.copy.supplier.id, advance: advance));
    } finally { if (mounted) setState(() => busy = false); }
    if (mounted && session.supplierAllocationFormKey(widget.copy) == draft.key) {
      await load();
    } else if (mounted) {
      setState(() { conflict = true; error = 'Return to the original Store to recover this allocation.'; });
    }
  }
  Future<void> load() async {
    if (busy || draft.busy) return;
    setState(() => busy = true);
    try {
      var pendingConflict = false;
      if (draft.pending != null) { draft.save(fields); pendingConflict = !await draft.flush(); }
      if (!mounted || draft.key == null) return;
      recovered = await widget.session.recoverWorkspaceSupplierAllocationStatus(draft.key!);
      final saved = await draft.load();
      if (!mounted || saved == null) return;
      amount.text = saved['amount'] ?? '';
      sourceKind = WorkspaceSupplierMoneySourceKind.values.where((k) => k.name == saved['sourceKind']).firstOrNull;
      sourceId = saved['sourceId'] ?? '';
      final text = saved['attempt'];
      frozen = text == null || text.isEmpty ? null : WorkspaceSupplierMoneyAllocationIntent.fromJson(jsonDecode(text));
      conflict = false; error = null; resetAttempt = null;
      if (pendingConflict && draft.pending != null) {
        if (jsonEncode(draft.pending!.fields) == jsonEncode(saved)) {
          draft.pending = null;
        } else {
          conflict = true;
          draft.error = 'Saved allocation differs from this unsaved input. The unsaved input remains on this screen; do not replace either record.';
          error = draft.error;
        }
      }
      inspect();
    } on Object {
      if (mounted) setState(() { conflict = true; error = 'Saved allocation could not be read. Keep the request and retry recovery.'; });
    } finally { if (mounted) setState(() => busy = false); }
  }
  Future<void> submit() async {
    if (busy || conflict || !recovered || !draft.ready || draft.key == null) return;
    setState(() { busy = true; error = null; });
    try {
      if (!await draft.flush() || !mounted) return;
      if (confirmed) {
        resetAttempt ??= WorkspaceLedgerFormDraft(key: draft.key!, revision: draft.revision! + 1,
          fields: const {'amount': '', 'sourceKind': '', 'sourceId': ''});
        if (await widget.session.resetConfirmedWorkspaceSupplierAllocationDraft(resetAttempt!, expectedRevision: draft.revision!)) {
          draft.revision = resetAttempt!.revision; draft.pending = null; draft.error = null;
          amount.clear(); sourceKind = null; sourceId = ''; frozen = null; confirmed = false; resetAttempt = null;
        } else { error = 'Recorded allocation is kept. Retry before starting another.'; }
        return;
      }
      final current = ledger;
      if (frozen == null) {
        final minor = WorkspacePurchaseEntryDraft.printedPaise(amount.text);
        final available = sourceKind == null ? null : current?.unallocatedMoneyMinor(sourceKind!, sourceId);
        final billDue = current?.manualBillRemainingMinor(widget.copy.draft.id);
        if (minor == null || minor <= 0 || available == null || billDue == null ||
            minor > available || minor > billDue || current?.openingRecord == null) {
          error = 'Choose an advance, payment or bill credit and an amount within its available balance and this bill’s due.';
          return;
        }
        final key = draft.key!;
        frozen = WorkspaceSupplierMoneyAllocationIntent(operationId: widget.session.newWorkspaceSupplierMoneyAllocationId(),
          accountScope: key.account, workspaceId: key.store, supplierId: key.customer,
          sourceKind: sourceKind!, sourceId: sourceId, openingId: current!.openingRecord!.id,
          openingRevision: current.openingRecord!.revision, billId: widget.copy.draft.id,
          copyId: widget.copy.id, copyRevision: widget.copy.revision, amountMinor: minor,
          requestedAt: DateTime.now().toUtc(),
          sourceCopyId: sourceKind == WorkspaceSupplierMoneySourceKind.manualBillSurplus
            ? current.purchaseBills[sourceId]?.copy.id : null,
          sourceCopyRevision: sourceKind == WorkspaceSupplierMoneySourceKind.manualBillSurplus
            ? current.purchaseBills[sourceId]?.copy.revision : null);
        draft.save(fields);
        if (!await draft.flush() || !mounted) { error = 'Request is not submitted. Save and retry this same request.'; return; }
      }
      final saved = await widget.session.recordWorkspaceSupplierAllocationDraft(draft.key!, frozen!);
      if (!mounted) return;
      recovered = await widget.session.recoverWorkspaceSupplierAllocationStatus(draft.key!);
      inspect();
      final remainingSource = ledger?.unallocatedMoneyMinor(frozen!.sourceKind, frozen!.sourceId);
      final remainingBill = ledger?.manualBillRemainingMinor(widget.copy.draft.id);
      final capacityChanged = recovered && !confirmed && remainingSource != null && remainingBill != null &&
        (remainingSource < frozen!.amountMinor || remainingBill < frozen!.amountMinor);
      error = saved && confirmed ? null : capacityChanged
        ? 'This request cannot be linked: the available money or bill due has changed. The request is retained for review.'
        : 'Allocation status needs recovery. Keep and retry this request, not a new one.';
    } finally { if (mounted) setState(() => busy = false); }
  }
  @override
  void dispose() { draft.removeListener(refresh); draft.dispose(); amount.dispose(); super.dispose(); }
  @override
  Widget build(BuildContext context) {
    final list = sources;
    final accountReady = recovered && widget.session.supplierAllocationFormKey(widget.copy) == draft.key;
    final billDue = accountReady ? ledger?.manualBillRemainingMinor(widget.copy.draft.id) : null;
    final settled = accountReady && billDue != null && billDue <= 0 && frozen == null;
    final selected = sourceKind == null ? null : sourceValue(sourceKind!, sourceId);
    final selectionKnown = list.any((s) => sourceValue(s.$1, s.$2) == selected);
    final selectedSource = list.where((s) => sourceValue(s.$1, s.$2) == selected).firstOrNull;
    final savedVerified = draft.pending == null && draft.error == null && draft.revision != null && !draft.busy;
    final editable = draft.ready && accountReady && !busy && !conflict && frozen == null;
    return PopScope(canPop: !busy && !draft.busy && draft.pending == null && draft.error == null && !conflict,
      onPopInvokedWithResult: (didPop, result) async {
        if (!didPop && !busy && !conflict && await draft.flush() && context.mounted) Navigator.pop(context);
      }, child: SafeArea(top: false, child: SingleChildScrollView(
        padding: EdgeInsets.fromLTRB(16, 12, 16, 16 + MediaQuery.viewInsetsOf(context).bottom),
        child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          Wrap(alignment: WrapAlignment.spaceBetween, crossAxisAlignment: WrapCrossAlignment.center, children: [
            Text('Apply payment or credit to bill', style: Theme.of(context).textTheme.titleMedium),
            TextButton(key: const Key('supplier-allocation-close'), onPressed: busy || conflict ? null : () async {
              if (await draft.flush() && context.mounted) Navigator.pop(context);
            }, child: const Text('Close'))]),
          Text('${widget.copy.supplier.name} · ${widget.copy.draft.invoiceReference}'),
          const Text('Uses an existing advance, payment or bill credit. No new payment or Stock change.'),
          Text(billDue == null ? 'Bill due unavailable' : billDue < 0
            ? 'Credit with supplier ${_purchaseAmount(-billDue)}' : 'Bill due ${_purchaseAmount(billDue)}'),
          if (settled) const Text('No amount remains to link to this bill. Your recorded payments and allocations are kept.',
            key: Key('supplier-allocation-settled')),
          if (!settled && list.isEmpty && accountReady && frozen == null) ...[
            const Text('No available advance, payment or bill credit. If you have already paid this supplier, record that payment or advance first.'),
            if (billDue != null && billDue > 0) Wrap(spacing: 8, children: [
              TextButton(key: const Key('supplier-allocation-record-payment'),
                onPressed: editable ? () => recordMoney(false) : null, child: const Text('Record supplier payment')),
              TextButton(key: const Key('supplier-allocation-record-advance'),
                onPressed: editable ? () => recordMoney(true) : null, child: const Text('Record supplier advance')),
            ]),
          ],
          if (!settled) ...[
          DropdownButtonFormField<String>(key: ValueKey(('supplier-allocation-source', selected)),
            initialValue: selectionKnown ? selected : null, isExpanded: true,
            decoration: const InputDecoration(labelText: 'Advance, payment or bill credit'),
            items: [for (final s in list) DropdownMenuItem(value: sourceValue(s.$1, s.$2),
              child: Text('${s.$3} · Unassigned ${_purchaseAmount(s.$4)}', overflow: TextOverflow.ellipsis))],
            onChanged: editable ? (value) {
              if (value == null) return;
              final source = list.singleWhere((s) => sourceValue(s.$1, s.$2) == value);
              setState(() { sourceKind = source.$1; sourceId = source.$2; }); draft.save(fields);
            } : null),
          if (selectedSource != null) Text('${selectedSource.$3} · Unassigned ${_purchaseAmount(selectedSource.$4)}',
            key: const Key('supplier-allocation-selected-source')),
          Align(alignment: Alignment.centerLeft, child: SizedBox(width: 180, child: TextField(
            key: const Key('supplier-allocation-amount'), controller: amount, enabled: editable,
            keyboardType: const TextInputType.numberWithOptions(decimal: true),
            decoration: const InputDecoration(labelText: 'Amount (₹)'), onChanged: (_) => draft.save(fields)))),
          ],
          if (frozen != null) Text(confirmed ? 'Allocation recorded · ${_purchaseAmount(frozen!.amountMinor)}'
            : savedVerified ? 'Saved allocation request · recover and retry the same details.'
            : 'Saved status unverified · keep this request and retry saving.', key: const Key('supplier-allocation-status')),
          if (error != null || draft.error != null) Text(error ?? draft.error!),
          TextButton(key: const Key('supplier-allocation-recover'), onPressed: busy || draft.busy ? null : load,
            child: const Text('Recover saved allocation')),
          if (!settled) FilledButton(key: const Key('supplier-allocation-submit'),
            onPressed: draft.ready && accountReady && !busy && !conflict && !draft.busy && draft.error == null ? submit : null,
            child: Text(busy ? 'Recording…' : confirmed ? 'Link another amount'
              : frozen == null ? 'Apply selected amount' : 'Retry same allocation')),
        ]))));
  }
}

class _StoreMoneyEntrySheet extends StatefulWidget {
  const _StoreMoneyEntrySheet({required this.session, this.purchase, this.supplierMoney})
    : assert(purchase == null || supplierMoney == null);
  final WorkSession session;
  final WorkspacePurchaseRecord? purchase;
  final _StoreSupplierMoneyTarget? supplierMoney;
  @override
  State<_StoreMoneyEntrySheet> createState() => _StoreMoneyEntrySheetState();
}

class _StoreMoneyEntrySheetState extends State<_StoreMoneyEntrySheet> {
  bool get expense => widget.purchase == null && widget.supplierMoney == null;
  bool get manualMoney => widget.supplierMoney != null;
  WorkspaceSupplierLedger? get moneyLedger => widget.session.workspaceSupplierLedger(widget.supplierMoney?.supplierId ?? '');
  bool get _settledBillInput => manualMoney && widget.supplierMoney!.copy != null &&
    moneyRecovered && draft.ready && !draft.busy && draft.error == null &&
    frozen == null && billBalance != null && billBalance! <= 0;
  // Absence must be recovered, not inferred from initially empty controllers.
  // Every editable method/date/checkbox change uses the same autosave owner.
  bool get _compactSettled => _settledBillInput && !saving && !conflict && error == null &&
    draft.revision == null && draft.pending == null && amount.text.isEmpty && reference.text.isEmpty;
  String get title => _settledBillInput ? 'Bill payment details' : manualMoney ? widget.supplierMoney!.advance
      ? 'Record supplier advance' : 'Record supplier payment'
      : expense ? 'Record test expense' : 'Record test payment';
  int? get billBalance {
    if (manualMoney) {
      final copy = widget.supplierMoney!.copy;
      return copy == null ? moneyLedger?.payableMinor : moneyLedger?.manualBillRemainingMinor(copy.draft.id);
    }
    final ledger = widget.session.workspaceSupplierLedger(
      widget.purchase?.supplierId ?? '',
    );
    if (ledger == null || !ledger.historyComplete) {
      return null;
    }
    return ledger.entries
        .where((entry) => entry.orderId == widget.purchase?.orderId)
        .fold<int>(0, (sum, entry) => sum + entry.payableDeltaMinor);
  }

  final amount = TextEditingController(), reference = TextEditingController();
  final note = TextEditingController();
  String category = 'Shop expense';
  String method = 'Bank transfer';
  bool saving = false;
  bool moneyRecovered = false, excludedFromOpening = false, confirmed = false, conflict = false;
  String occurredOn = DateTime.now().toIso8601String().substring(0, 10);
  WorkspaceSupplierMoneyAttempt? frozen;
  WorkspaceLedgerFormDraft? resetAttempt;
  String? error;
  late final _LedgerFormAutosave draft;
  Map<String, String> get fields => {
    'amount': amount.text,
    'reference': reference.text,
    'channel': method,
    if (expense) 'category': category,
    if (expense) 'note': note.text,
    if (manualMoney) 'occurredOn': occurredOn,
    if (manualMoney) 'notIncludedInOpening': '$excludedFromOpening',
    if (manualMoney && frozen != null) 'attempt': jsonEncode(frozen!.toJson()),
  };
  @override
  void initState() {
    super.initState();
    draft = _LedgerFormAutosave(
      widget.session,
      manualMoney ? widget.session.supplierMoneyFormKey(widget.supplierMoney!.supplierId,
        copy: widget.supplierMoney!.copy, advance: widget.supplierMoney!.advance)
      : expense
          ? widget.session.expenseFormKey()
          : widget.session.supplierPaymentFormKey(widget.purchase!),
    );
    draft.addListener(refresh);
    unawaited(load());
  }

  void refresh() {
    if (mounted) {
      setState(() {});
    }
  }

  Future<void> load() async {
    if (saving || draft.busy) return;
    setState(() => saving = true);
    try {
      await _loadMoneyInputLocked();
    } finally {
      if (mounted) setState(() => saving = false);
    }
  }

  Future<void> _loadMoneyInputLocked() async {
    var pendingConflict = false;
    if (manualMoney && draft.pending != null) {
      draft.save(fields);
      pendingConflict = !await draft.flush();
      if (!mounted) return;
    }
    if (manualMoney) moneyRecovered = await widget.session.recoverCustomerLedger();
    final saved = await draft.load();
    if (!mounted || saved == null) {
      return;
    }
    amount.text = saved['amount'] ?? '';
    reference.text = saved['reference'] ?? '';
    method = saved['channel'] ?? (expense ? 'Cash' : 'Bank transfer');
    category = saved['category'] ?? 'Shop expense';
    note.text = saved['note'] ?? '';
    if (manualMoney) {
      occurredOn = saved['occurredOn'] ?? occurredOn;
      excludedFromOpening = saved['notIncludedInOpening'] == 'true';
      final text = saved['attempt'];
      try {
        frozen = text == null || text.isEmpty ? null
          : WorkspaceSupplierMoneyAttempt.fromJson(jsonDecode(text));
      } on FormatException {
        setState(() { conflict = true; error = 'Saved payment attempt could not be read. Its data is kept; do not replace it.'; });
        return;
      }
      resetAttempt = null;
      _inspectSavedMoney();
      if (pendingConflict) {
        // Preserve the losing local payload; authoritative recovery must not
        // be blocked forever by retrying a stale write before every read.
        final pending = draft.pending;
        if (pending != null && jsonEncode(pending.fields) == jsonEncode(saved)) {
          draft.pending = null;
        } else {
          conflict = true;
          draft.error = 'Saved payment details differ from this unsaved input. The unsaved input remains on this screen; do not submit or replace either record.';
          error = draft.error;
        }
      }
    }
    setState(() {});
  }

  void _inspectSavedMoney() {
    confirmed = false;
    conflict = false;
    if (frozen == null || !moneyRecovered) return;
    final found = moneyLedger?.entries.where((entry) => entry.operationId == frozen!.entry.operationId).toList();
    if (found?.length == 1) {
      confirmed = jsonEncode(found!.single.toJson()) == jsonEncode(frozen!.entry.toJson());
      conflict = !confirmed;
      if (conflict) error = 'Saved payment details conflict. Keep this attempt and recover the supplier account.';
    }
  }

  Future<void> submitManualMoney() async {
    if (saving || confirmed || conflict || !moneyRecovered) return;
    setState(() => saving = true);
    try {
      await _submitManualMoneyLocked();
    } finally {
      if (mounted) setState(() => saving = false);
    }
  }

  Future<void> _submitManualMoneyLocked() async {
    if (!await draft.flush() || !mounted) return;
    final ledger = moneyLedger;
    final opening = ledger?.openingRecord;
    final minor = WorkspacePurchaseEntryDraft.printedPaise(amount.text);
    if (frozen == null) {
      if (ledger == null || opening == null || minor == null || minor <= 0 ||
          reference.text.trim().isEmpty || !excludedFromOpening) {
        setState(() => error = 'Enter the amount, payment reference and date. Confirm it is not already included in the starting balance.');
        return;
      }
      final target = widget.supplierMoney!;
      final payable = ledger.payableMinor;
      if (!target.advance && (billBalance == null || payable == null || minor > billBalance! || minor > payable)) {
        setState(() => error = 'Amount exceeds the verified dues. Record extra money separately as an advance.');
        return;
      }
      final review = WorkspaceSupplierMoneyReview(occurredOn: occurredOn,
        openingId: opening.id, openingRevision: opening.revision, notIncludedInOpening: true);
      final entry = WorkspaceSupplierLedgerEntry(operationId: widget.session.newWorkspaceSupplierMoneyOperationId(),
        reference: reference.text.trim(), origin: target.copy == null
          ? WorkspaceSupplierEntryOrigin.supplierAccount : WorkspaceSupplierEntryOrigin.manualPurchase,
        purchaseId: target.copy?.id, billId: target.copy?.draft.id,
        kind: target.advance ? WorkspaceSupplierEntryKind.advance : WorkspaceSupplierEntryKind.payment,
        amountMinor: minor, paymentMethod: method, postedAt: DateTime.now().toUtc(), moneyReview: review);
      final attempt = WorkspaceSupplierMoneyAttempt(entry: entry, expectedRevision: ledger.revision);
      if (!attempt.valid) { setState(() => error = 'Check the payment date and details.'); return; }
      setState(() { frozen = attempt; saving = true; error = null; });
      // Earlier editable snapshots have been flushed. Persist the immutable
      // attempt first; a failed/lost draft reply cannot create another payment.
      draft.save(fields);
      if (!await draft.flush() || !mounted) {
        if (mounted) setState(() { saving = false; error = 'Payment has not been submitted. Retry saving this same attempt first.'; });
        return;
      }
    } else {
      setState(() { saving = true; error = null; });
    }
    final saved = await widget.session.recordWorkspaceSupplierMoneyDraft(draft.key!, frozen!);
    if (!mounted) return;
    moneyRecovered = await widget.session.recoverCustomerLedger();
    if (!mounted) return;
    _inspectSavedMoney();
    setState(() {
      saving = false;
      error = saved && confirmed ? null : 'Payment status needs checking. This saved attempt is retained; recover and retry it, not a new payment.';
    });
  }

  Future<void> recordAnother() async {
    if (saving || !confirmed || draft.revision == null) return;
    setState(() => saving = true);
    try {
      await _recordAnotherLocked();
    } finally {
      if (mounted) setState(() => saving = false);
    }
  }

  Future<void> _recordAnotherLocked() async {
    if (!await draft.flush() || !mounted) return;
    resetAttempt ??= WorkspaceLedgerFormDraft(key: draft.key!, revision: draft.revision! + 1,
      fields: {'amount': '', 'reference': '', 'channel': method,
        'occurredOn': DateTime.now().toIso8601String().substring(0, 10), 'notIncludedInOpening': 'false'});
    setState(() { saving = true; error = null; });
    final reset = await widget.session.resetConfirmedWorkspaceSupplierMoneyDraft(resetAttempt!, expectedRevision: draft.revision!);
    if (!mounted) return;
    if (reset) {
      draft.revision = resetAttempt!.revision;
      draft.pending = null;
      draft.error = null;
      amount.clear(); reference.clear();
      occurredOn = resetAttempt!.fields['occurredOn']!;
      excludedFromOpening = false; frozen = null; confirmed = false; conflict = false; resetAttempt = null;
    }
    setState(() { saving = false; error = reset ? null : 'The recorded payment is kept. Retry starting another payment.'; });
  }

  Future<void> choosePaymentDate() async {
    if (saving || conflict || frozen != null || !draft.ready) return;
    final now = DateTime.now();
    final parsed = DateTime.tryParse(occurredOn);
    final initial = parsed == null || parsed.isAfter(now) || parsed.isBefore(DateTime(2000)) ? now : parsed;
    final chosen = await showDatePicker(context: context,
      initialDate: initial,
      firstDate: DateTime(2000), lastDate: now);
    if (!mounted || chosen == null || frozen != null) return;
    setState(() => occurredOn = chosen.toIso8601String().substring(0, 10));
    draft.save(fields);
  }

  Future<void> submit() async {
    if (manualMoney) { await submitManualMoney(); return; }
    if (saving || !await draft.flush() || !mounted) {
      return;
    }
    final text = amount.text.trim();
    if (!RegExp(r'^\d{1,10}(\.\d{1,2})?$').hasMatch(text) ||
        reference.text.trim().isEmpty) {
      setState(
        () => error = 'Enter the amount paid and its payment reference.',
      );
      return;
    }
    final parts = text.split('.');
    final minor =
        int.parse(parts.first) * 100 +
        (parts.length == 1 ? 0 : int.parse(parts.last.padRight(2, '0')));
    final key = draft.key!;
    setState(() {
      saving = true;
      error = null;
    });
    final saved = expense
        ? await widget.session.recordStoreReviewExpense(
            key: key,
            amountMinor: minor,
            category: category,
            method: method,
            reference: reference.text.trim(),
            note: note.text.trim(),
          )
        : await widget.session.recordStoreReviewSupplierPayment(
            widget.purchase!,
            operationId: jsonEncode([
              'supplier-payment',
              key.account,
              key.store,
              key.customer,
              key.invoice,
              key.order,
              key.ledgerRevision,
            ]),
            reference: reference.text.trim(),
            paymentMethod: method,
            amountMinor: minor,
            expectedRevision: key.ledgerRevision,
          );
    if (!mounted) {
      return;
    }
    if (saved) {
      Navigator.pop(context);
      return;
    }
    setState(() {
      saving = false;
      error = expense
          ? 'Expense not confirmed. Recover saved status before retrying.'
          : 'Payment not confirmed. Check the bill balance and saved status before retrying.';
    });
  }

  @override
  void dispose() {
    draft.removeListener(refresh);
    draft.dispose();
    amount.dispose();
    reference.dispose();
    note.dispose();
    super.dispose();
  }

  Widget _paidAmountField() => TextField(
    key: Key(expense ? 'store-expense-amount' : 'supplier-payment-amount'),
    controller: amount,
    enabled: draft.ready && !saving && !_settledBillInput && (!manualMoney || (frozen == null && !conflict)),
    keyboardType: const TextInputType.numberWithOptions(decimal: true),
    decoration: const InputDecoration(labelText: 'Paid (₹)'),
    onChanged: (_) => draft.save(fields));

  Widget _moneyViewport(BuildContext context, Widget fields) {
    if (!manualMoney) return fields;
    return LayoutBuilder(builder: (context, constraints) => ConstrainedBox(
      constraints: BoxConstraints(maxHeight: constraints.maxHeight),
      child: Column(mainAxisSize: MainAxisSize.min, children: [
        Padding(padding: const EdgeInsets.fromLTRB(16, 8, 8, 0),
          child: Row(children: [
            Expanded(child: Text(title,
              style: Theme.of(context).textTheme.titleMedium)),
            IconButton(key: const Key('supplier-money-hide-keyboard'),
              tooltip: 'Hide keyboard',
              onPressed: () => FocusScope.of(context).unfocus(),
              icon: const Icon(Icons.keyboard_hide_outlined)),
            TextButton(key: const Key('supplier-money-close'),
              onPressed: saving ? null : () async {
                if (await draft.flush() && context.mounted) Navigator.pop(context);
              }, child: const Text('Close')),
          ])),
        Flexible(child: NotificationListener<ScrollNotification>(
          onNotification: (notification) {
            if (notification.depth == 0 &&
                (notification is ScrollStartNotification ||
                 notification is ScrollUpdateNotification)) {
              // Selection handles follow their field outside the scrolling
              // viewport; hide them before they can cover the fixed controls.
              final editor = FocusManager.instance.primaryFocus?.context
                  ?.findAncestorStateOfType<EditableTextState>();
              if (editor?.context.findAncestorStateOfType<_StoreMoneyEntrySheetState>() == this) {
                editor?.hideToolbar();
              }
            }
            return false;
          }, child: fields)),
      ]),
    ));
  }

  @override
  Widget build(BuildContext context) => PopScope(
    canPop: !saving && !draft.busy && draft.error == null,
    onPopInvokedWithResult: (didPop, result) async {
      if (!didPop && !saving && await draft.flush() && context.mounted) {
        Navigator.pop(context);
      }
    },
    child: SafeArea(
      top: false,
      child: Padding(
        padding: EdgeInsets.only(bottom: manualMoney ? MediaQuery.viewInsetsOf(context).bottom : 0),
      child: _moneyViewport(context, SingleChildScrollView(
        padding: EdgeInsets.fromLTRB(
          16,
          16,
          16,
          16 + (manualMoney ? 0 : MediaQuery.viewInsetsOf(context).bottom),
        ),
        child: Column(
          key: _compactSettled ? const Key('supplier-money-compact-settled') : null,
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            if (!manualMoney) Text(title, style: Theme.of(context).textTheme.titleLarge),
            Text(
              manualMoney ? '${moneyLedger?.supplierName ?? 'Supplier'}${widget.supplierMoney!.copy == null ? '' : ' · ${widget.supplierMoney!.copy!.draft.invoiceReference}'}'
              : expense
                  ? 'Business expense not already recorded elsewhere.'
                  : '${widget.purchase!.supplierName} · ${draft.key?.invoice ?? 'Bill unavailable'}',
            ),
            if (_compactSettled) Text('Bill balance ${_purchaseAmount(billBalance!)}',
              key: const Key('supplier-money-compact-balance'),
              style: Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight: FontWeight.w600)),
            Text(manualMoney ? 'Evaluation record · no money is transferred.' : 'Test record only. No money is transferred.'),
            if (_settledBillInput) const Text(
              'No amount is due on this bill. To record extra money already paid to the supplier, close and choose Record advance paid.',
              key: Key('supplier-money-no-bill-due')),
            if (manualMoney && widget.supplierMoney!.advance) const Text(
              'Record money already paid to the supplier as an advance. Link it to a bill separately.'),
            if (!expense && !_compactSettled)
              Text(
                manualMoney && widget.supplierMoney!.advance
                    ? 'Advance paid before or after delivery. Stock stays unchanged.'
                : billBalance == null
                    ? 'Bill balance unavailable'
                    : '${manualMoney && widget.supplierMoney!.copy == null ? 'Supplier dues' : 'Bill balance'} ${_purchaseAmount(billBalance!)}',
              ),
            if (!_compactSettled) if (manualMoney) Align(alignment: Alignment.centerLeft,
              child: SizedBox(width: 180, child: _paidAmountField())) else _paidAmountField(),
            if (!_compactSettled) DropdownButtonFormField<String>(
              key: ValueKey('supplier-payment-method-$method'),
              initialValue: method,
              isExpanded: true,
              decoration: const InputDecoration(labelText: 'Method used'),
              items: [
                for (final value in {
                  'UPI',
                  'Cheque',
                  'Bank transfer',
                  'NEFT',
                  'RTGS',
                  'Cash',
                  method,
                })
                  DropdownMenuItem(value: value, child: Text(value)),
              ],
              onChanged: !draft.ready || saving || _settledBillInput || (manualMoney && (frozen != null || conflict))
                  ? null
                  : (value) {
                      if (value != null) {
                        setState(() => method = value);
                        draft.save(fields);
                      }
                    },
            ),
            if (!_compactSettled) TextField(
              key: Key(
                expense
                    ? 'store-expense-reference'
                    : 'supplier-payment-reference',
              ),
              controller: reference,
              enabled: draft.ready && !saving && !_settledBillInput && (!manualMoney || (frozen == null && !conflict)),
              decoration: InputDecoration(labelText: 'Payment reference',
                hintText: manualMoney ? 'UPI/bank reference or cash note' : null),
              onChanged: (_) => draft.save(fields),
            ),
            if (manualMoney) ...[
              if (!_compactSettled) TextButton.icon(key: const Key('supplier-money-date'),
                onPressed: !draft.ready || saving || _settledBillInput || conflict || frozen != null ? null : choosePaymentDate,
                icon: const Icon(Icons.calendar_today_outlined, size: 16),
                label: Text('Payment date · ${occurredOn.split('-').reversed.join('/')}')),
              if (!_compactSettled) CheckboxListTile(key: const Key('supplier-money-opening-excluded'),
                contentPadding: EdgeInsets.zero, dense: true, value: excludedFromOpening,
                title: const Text('Not already included in the starting balance'),
                onChanged: !draft.ready || saving || _settledBillInput || conflict || frozen != null ? null : (value) {
                  setState(() => excludedFromOpening = value == true); draft.save(fields);
                }),
              if (frozen != null) Text(confirmed ? '${widget.supplierMoney!.advance ? 'Advance' : 'Payment'} recorded · ${_purchaseAmount(frozen!.entry.amountMinor)} · ${frozen!.entry.paymentMethod}'
                  : draft.pending == null && draft.error == null && draft.revision != null && !draft.busy
                    ? 'Saved payment attempt · recover and retry these same details.'
                    : 'Saved status unverified · keep this payment request and retry saving.',
                key: const Key('supplier-money-attempt-status')),
              if (!moneyRecovered || (frozen != null && !confirmed))
                TextButton(key: const Key('supplier-money-recover'),
                  onPressed: saving || draft.busy ? null : load, child: const Text('Recover saved payment')),
            ],
            if (expense) ...[
              DropdownButtonFormField<String>(
                key: ValueKey('store-expense-category-$category'),
                initialValue: category,
                isExpanded: true,
                decoration: const InputDecoration(labelText: 'Category'),
                items: [
                  for (final value in {
                    'Shop expense',
                    'Delivery',
                    'Electricity',
                    'Salary',
                    'Repair',
                    'Other',
                    category,
                  })
                    DropdownMenuItem(value: value, child: Text(value)),
                ],
                onChanged: !draft.ready || saving
                    ? null
                    : (value) {
                        if (value != null) {
                          setState(() => category = value);
                          draft.save(fields);
                        }
                      },
              ),
              TextField(
                key: const Key('store-expense-note'),
                controller: note,
                maxLength: 512,
                enabled: draft.ready && !saving,
                decoration: const InputDecoration(labelText: 'Expense note'),
                onChanged: (_) => draft.save(fields),
              ),
            ],
            if (error != null || draft.error != null)
              Text(error ?? draft.error!),
            if (!draft.ready)
              TextButton(
                onPressed: load,
                child: const Text('Retry opening saved input'),
              ),
            if (draft.error != null && draft.ready)
              TextButton(
                onPressed: saving || (manualMoney && conflict) ? null : () => draft.save(fields),
                child: const Text('Retry saving input'),
              ),
            if (!_compactSettled) FilledButton(
              key: manualMoney ? const Key('supplier-money-submit') : null,
              onPressed:
                  draft.ready && !saving && !draft.busy && draft.error == null &&
                    !_settledBillInput && (!manualMoney || (moneyRecovered && !conflict))
                  ? manualMoney && confirmed ? recordAnother : submit
                  : null,
              child: Text(
                saving
                    ? 'Recording…'
                    : _settledBillInput ? 'No bill amount due'
                    : manualMoney ? confirmed ? widget.supplierMoney!.advance ? 'Record another advance' : 'Record another payment'
                        : frozen != null ? 'Retry same payment' : widget.supplierMoney!.advance ? 'Record advance paid' : 'Record payment'
                    : expense
                    ? 'Record test expense'
                    : 'Record test payment',
              ),
            ),
          ],
        ),
      )),
      ),
    ),
  );
}

class _CustomerCollectionSheet extends StatefulWidget {
  const _CustomerCollectionSheet({
    super.key,
    required this.session,
    required this.payment,
    required this.accountScope,
    required this.storeId,
    this.refund = false,
    this.counterSaleReceipt = false,
    this.onClose,
  });
  final bool refund;
  final bool counterSaleReceipt;
  final VoidCallback? onClose;
  final WorkSession session;
  final WorkspacePaymentRecord payment;
  final String accountScope, storeId;
  @override
  State<_CustomerCollectionSheet> createState() =>
      _CustomerCollectionSheetState();
}

class _CustomerCollectionSheetState extends State<_CustomerCollectionSheet>
    with WidgetsBindingObserver {
  Future<bool> flushForNavigation() async =>
      !saving && !confirming && await draft.flush();
  final amount = TextEditingController();
  final reference = TextEditingController();
  final amountFocus = FocusNode();
  final referenceFocus = FocusNode();
  final _receiptContentKey = GlobalKey();
  bool _receiptRevealScheduled = false;
  bool get _inlineCounterReceipt =>
      widget.counterSaleReceipt && widget.onClose != null;
  late WorkspacePaymentChannel channel;
  String? sourceCollectionId;
  WorkspaceCustomerLedger? get refundLedger {
    final finance = widget.session.workspaceFinance;
    if (finance?.accountScope != widget.accountScope ||
        finance?.workspaceId != widget.storeId ||
        widget.session.activeWorkspace?.id != widget.storeId) {
      return null;
    }
    return finance?.customerLedgers.where((l) =>
        l.customerId == widget.payment.customerId && l.valid && l.historyComplete).firstOrNull;
  }
  List<WorkspaceCustomerLedgerEntry> get refundReceipts =>
      refundLedger?.entries.where((e) => e.valid &&
          e.invoiceId == widget.payment.invoiceId &&
          e.orderId == widget.payment.orderId &&
          e.kind == WorkspaceLedgerEntryKind.collection &&
          e.state == WorkspaceLedgerPostingState.posted).toList() ?? [];
  WorkspaceCustomerLedgerEntry? get sourceReceipt => refundReceipts
      .where((e) => e.id == sourceCollectionId).firstOrNull;
  String receiptRemainingLabel(WorkspaceCustomerLedgerEntry receipt) {
    final remaining = refundLedger?.receiptRemainingMinor(widget.payment.invoiceId!, receipt.id);
    return remaining == null ? 'Unavailable' : _purchaseAmount(remaining);
  }
  bool get sourceRefundSupported => sourceReceipt != null &&
      const [WorkspacePaymentChannel.cash, WorkspacePaymentChannel.directUpi,
        WorkspacePaymentChannel.bankTransfer].contains(sourceReceipt!.channel) &&
      refundLedger?.receiptRemainingMinor(widget.payment.invoiceId!, sourceCollectionId!) != null;
  bool get _bankTransfer => channel == WorkspacePaymentChannel.bankTransfer;
  bool get _needsReference =>
      _bankTransfer || channel == WorkspacePaymentChannel.directUpi;
  String get _referenceLabel => widget.refund ? 'Refund transaction reference' : _bankTransfer
      ? 'Bank transaction reference'
      : 'UPI transaction reference';
  bool saving = false;
  bool confirming = false;
  String? error;
  String? amountError, referenceError;
  late final _LedgerFormAutosave draft;
  Map<String, String> get draftFields => {
    'amount': amount.text,
    'reference': reference.text,
    'channel': channel.name,
    if (widget.refund && sourceCollectionId != null) 'sourceCollectionId': sourceCollectionId!,
  };
  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    amountFocus.addListener(_scheduleReceiptReveal);
    referenceFocus.addListener(_scheduleReceiptReveal);
    final invoice = widget.session.workspaceInvoices
        .where(
          (invoice) =>
              invoice.id == widget.payment.invoiceId &&
              invoice.orderId == widget.payment.orderId,
        )
        .firstOrNull;
    // An unpaid ledger correctly has no recorded tender yet. Use the saved
    // invoice's intended method without changing that financial fact.
    channel =
        (!widget.refund && invoice?.payment == 'UPI') ||
            widget.payment.channel == WorkspacePaymentChannel.directUpi
        ? WorkspacePaymentChannel.directUpi
        : WorkspacePaymentChannel.cash;
    if (widget.counterSaleReceipt) {
      channel = switch (invoice?.payment) {
        'UPI' => WorkspacePaymentChannel.directUpi,
        'Bank Transfer' => WorkspacePaymentChannel.bankTransfer,
        _ => WorkspacePaymentChannel.cash,
      };
      amount.text = _formatStoreMinorAmount(
        widget.payment.dueMinor,
      ).replaceAll(',', '');
    }
    if (widget.refund) {
      final receipts = refundReceipts;
      if (receipts.length == 1) {
        sourceCollectionId = receipts.single.id;
        channel = receipts.single.channel;
      } else {
        channel = WorkspacePaymentChannel.unknown;
      }
    }
    draft = _LedgerFormAutosave(
      widget.session,
      widget.session.ledgerFormKey(
        widget.payment,
        widget.refund ? 'refund' : 'collection',
      ),
    );
    draft.addListener(refreshDraft);
    unawaited(loadDraft());
  }

  @override
  void didChangeMetrics() => _scheduleReceiptReveal();

  void _scheduleReceiptReveal() {
    if (!_inlineCounterReceipt ||
        _receiptRevealScheduled ||
        (!amountFocus.hasFocus && !referenceFocus.hasFocus)) {
      return;
    }
    _receiptRevealScheduled = true;
    // Run after EditableText's post-frame caret scrolling, which otherwise
    // overrides the form reveal during successive keyboard-inset changes.
    unawaited(
      WidgetsBinding.instance.endOfFrame.then((_) {
        _receiptRevealScheduled = false;
        if (!mounted ||
            !_inlineCounterReceipt ||
            (!amountFocus.hasFocus && !referenceFocus.hasFocus)) {
          return;
        }
        final target = _receiptContentKey.currentContext;
        if (target == null || !target.mounted) return;
        final box = target.findRenderObject();
        final scroll = Scrollable.maybeOf(target);
        if (box is! RenderBox || !box.hasSize || scroll == null) return;
        // Reveal the complete editor/action after IME and validation layout, not
        // only the text caret. On very short screens prioritise the active field
        // and retain ordinary scrolling rather than hide it to expose the button.
        final fits = box.size.height <= scroll.position.viewportDimension;
        final focused = referenceFocus.hasFocus ? referenceFocus : amountFocus;
        final reveal = fits ? target : focused.context;
        if (reveal == null || !reveal.mounted) return;
        unawaited(
          Scrollable.ensureVisible(
            reveal,
            alignment: fits ? 1 : .5,
            duration: const Duration(milliseconds: 180),
          ),
        );
      }),
    );
  }

  void refreshDraft() {
    if (mounted) {
      setState(() {});
    }
  }

  Future<void> loadDraft() async {
    final fields = await draft.load();
    if (!mounted || fields == null) {
      return;
    }
    amount.text = fields['amount'] ?? amount.text;
    reference.text = fields['reference'] ?? '';
    if (!widget.counterSaleReceipt) {
      channel = switch (fields['channel']) {
        'directUpi' => WorkspacePaymentChannel.directUpi,
        'cash' => WorkspacePaymentChannel.cash,
        _ => channel,
      };
    }
    if (widget.refund) {
      final savedSource = fields['sourceCollectionId'];
      if (refundReceipts.any((e) => e.id == savedSource)) sourceCollectionId = savedSource;
      channel = sourceReceipt?.channel ?? WorkspacePaymentChannel.unknown;
    }
    amount.addListener(saveDraft);
    reference.addListener(saveDraft);
    setState(() {});
  }

  void saveDraft() {
    draft.save(draftFields);
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    amountFocus.removeListener(_scheduleReceiptReveal);
    referenceFocus.removeListener(_scheduleReceiptReveal);
    draft.removeListener(refreshDraft);
    draft.dispose();
    amount.dispose();
    reference.dispose();
    amountFocus.dispose();
    referenceFocus.dispose();
    super.dispose();
  }

  int get limitMinor {
    if (!widget.refund) return widget.payment.dueMinor;
    final ledger = refundLedger;
    final credit = ledger?.invoiceBalance(widget.payment.invoiceId!)?.refundableMinor ?? 0;
    final remaining = sourceCollectionId == null ? 0 :
        ledger?.receiptRemainingMinor(widget.payment.invoiceId!, sourceCollectionId!) ?? 0;
    return remaining < credit ? remaining : credit;
  }

  Future<void> submit() async {
    if (saving || confirming || !draft.ready || draft.error != null) return;
    setState(() => confirming = true);
    try {
      await _submitCollection();
    } finally {
      if (mounted) {
        setState(() => confirming = false);
        _scheduleReceiptReveal();
      }
    }
  }

  Future<void> _submitCollection() async {
    if (!await draft.flush() || !mounted) {
      return;
    }
    setState(() {
      amountError = null;
      referenceError = null;
      error = null;
    });
    if (widget.refund && !sourceRefundSupported) {
      setState(() => error = 'Select a verified original receipt. Refund allocation is unavailable for incomplete records.');
      return;
    }
    final text = amount.text.trim();
    if (!RegExp(r'^\d{1,10}(\.\d{1,2})?$').hasMatch(text)) {
      setState(
        () =>
            amountError = 'Enter a valid amount with up to two decimal places.',
      );
      amountFocus.requestFocus();
      return;
    }
    final parts = text.split('.');
    final minor =
        int.parse(parts[0]) * 100 +
        (parts.length == 1 ? 0 : int.parse(parts[1].padRight(2, '0')));
    if (minor <= 0) {
      setState(() => amountError = 'Enter an amount greater than zero.');
      amountFocus.requestFocus();
      return;
    }
    if (minor > limitMinor) {
      setState(
        () => amountError = 'Enter ${_purchaseAmount(limitMinor)} or less.',
      );
      amountFocus.requestFocus();
      return;
    }
    if (_needsReference && reference.text.trim().isEmpty) {
      setState(
        () => referenceError = 'Enter the ${_referenceLabel.toLowerCase()}.',
      );
      referenceFocus.requestFocus();
      return;
    }
    if (widget.session.workspaceFinance?.accountScope != widget.accountScope ||
        widget.session.workspaceFinance?.workspaceId != widget.storeId) {
      setState(() => error = 'Store changed. Return to the correct invoice.');
      return;
    }
    setState(() {
      saving = true;
      error = null;
    });
    final recorded = widget.refund
        ? await widget.session.recordCustomerRefund(
            customerId: widget.payment.customerId,
            invoiceId: widget.payment.invoiceId!,
            amountMinor: minor,
            channel: channel,
            reference: reference.text,
            sourceCollectionId: sourceCollectionId,
          )
        : await widget.session.recordCustomerCollection(
      customerId: widget.payment.customerId,
      invoiceId: widget.payment.invoiceId!,
      amountMinor: minor,
      channel: channel,
      reference: reference.text,
    );
    if (!mounted) return;
    if (recorded) {
      if (widget.onClose != null) {
        widget.onClose!();
      } else {
        Navigator.pop(context);
      }
      return;
    }
    setState(() {
      saving = false;
      error = widget.refund
          ? 'Refund not confirmed. Close this sheet and check its status.'
          : 'Collection not confirmed. Close this sheet and check its status.';
    });
  }

  Widget _inlineReceipt() => Container(
    key: const Key('work-counter-inline-receipt'),
    margin: const EdgeInsets.only(top: 10, bottom: 8),
    padding: const EdgeInsets.symmetric(vertical: 4),
    decoration: const BoxDecoration(
      color: Colors.white,
      border: Border(top: BorderSide(color: _counterSaleLine)),
    ),
    child: Column(
      key: _receiptContentKey,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      mainAxisSize: MainAxisSize.min,
      children: [
        Row(
          children: [
            Expanded(
              child: Text(
                _bankTransfer ? 'Bank transfer receipt' : 'Cash receipt',
                style: const TextStyle(fontWeight: FontWeight.w600),
              ),
            ),
            IconButton(
              tooltip: 'Close receipt entry',
              onPressed: saving || confirming
                  ? null
                  : () async {
                      if (await draft.flush() && mounted) widget.onClose!();
                    },
              icon: const Icon(Icons.close, size: 18),
            ),
          ],
        ),
        LayoutBuilder(
          builder: (context, constraints) {
            final input = TextField(
              key: const Key('collection-amount'),
              controller: amount,
              focusNode: amountFocus,
              enabled: !saving && !confirming && draft.ready,
              keyboardType: const TextInputType.numberWithOptions(
                decimal: true,
              ),
              textInputAction: _needsReference
                  ? TextInputAction.next
                  : TextInputAction.done,
              onSubmitted: (_) => _needsReference
                  ? referenceFocus.requestFocus()
                  : amountFocus.unfocus(),
              onChanged: (_) {
                if (amountError != null) {
                  setState(() => amountError = null);
                  _scheduleReceiptReveal();
                }
              },
              decoration: InputDecoration(
                labelText: 'Amount received',
                prefixText: '₹ ',
                errorText: amountError,
                errorMaxLines: 3,
                isDense: true,
                filled: false,
                border: InputBorder.none,
                enabledBorder: InputBorder.none,
                focusedBorder: InputBorder.none,
              ),
            );
            final action = TextButton(
              key: const Key('collection-confirm'),
              onPressed:
                  !draft.ready ||
                      draft.busy ||
                      draft.error != null ||
                      saving ||
                      confirming
                  ? null
                  : submit,
              child: Text(saving ? 'Checking…' : 'Record receipt'),
            );
            if (!_needsReference &&
                amountError == null &&
                constraints.maxWidth >= 300 &&
                MediaQuery.textScalerOf(context).scale(14) <= 16.8) {
              return Row(
                children: [
                  Expanded(child: input),
                  const SizedBox(width: 8),
                  action,
                ],
              );
            }
            return Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                input,
                if (!_needsReference)
                  Align(alignment: Alignment.centerRight, child: action),
              ],
            );
          },
        ),
        if (_needsReference) ...[
          const SizedBox(height: 12),
          TextField(
            key: const Key('collection-reference'),
            controller: reference,
            focusNode: referenceFocus,
            enabled: !saving && !confirming && draft.ready,
            textInputAction: TextInputAction.done,
            onSubmitted: (_) => referenceFocus.unfocus(),
            onChanged: (_) {
              if (referenceError != null) {
                setState(() => referenceError = null);
                _scheduleReceiptReveal();
              }
            },
            decoration: InputDecoration(
              labelText: _referenceLabel,
              errorText: referenceError,
              errorMaxLines: 3,
            ),
          ),
        ],
        if (_needsReference)
          TextButton(
            key: const Key('collection-confirm'),
            onPressed:
                !draft.ready ||
                    draft.busy ||
                    draft.error != null ||
                    saving ||
                    confirming
                ? null
                : submit,
            child: Text(saving ? 'Checking…' : 'Record receipt'),
          ),
        Text(
          _bankTransfer
              ? 'Confirm only after checking the credit in your bank account.'
              : 'Confirm only after receiving the cash.',
          style: const TextStyle(fontSize: 12, color: MoolColors.muted),
        ),
        if (draft.error != null) ...[
          Text(draft.error!),
          TextButton(
            onPressed: draft.busy
                ? null
                : () {
                    if (draft.ready) {
                      saveDraft();
                    } else {
                      unawaited(loadDraft());
                    }
                  },
            child: const Text('Retry saving input'),
          ),
        ],
        if (error != null) Text(error!),
      ],
    ),
  );

  @override
  Widget build(BuildContext context) =>
      widget.counterSaleReceipt && widget.onClose != null
      ? _inlineReceipt()
      : PopScope(
          canPop:
              !saving &&
              !confirming &&
              !draft.busy &&
              (!draft.ready || draft.error == null),
          onPopInvokedWithResult: (didPop, result) async {
            if (!didPop &&
                !saving &&
                !confirming &&
                await draft.flush() &&
                context.mounted) {
              if (widget.onClose != null) {
                widget.onClose!();
              } else {
                Navigator.pop(context);
              }
            }
          },
          child: SafeArea(
            top: false,
            child: Padding(
              padding: EdgeInsets.only(
                bottom: widget.onClose == null
                    ? MediaQuery.viewInsetsOf(context).bottom
                    : 0,
              ),
              child: _StoreFormLayout(
                compact: true,
                action: ListenableBuilder(
                  listenable: Listenable.merge([amountFocus, referenceFocus]),
                  builder: (context, action) => Row(
                    children: [
                      if (amountFocus.hasFocus || referenceFocus.hasFocus)
                        IconButton(
                          key: const Key('ledger-hide-keyboard'),
                          tooltip: 'Hide keyboard',
                          onPressed: () {
                            amountFocus.unfocus();
                            referenceFocus.unfocus();
                          },
                          icon: const Icon(Icons.keyboard_hide_outlined),
                        ),
                      Expanded(child: action!),
                    ],
                  ),
                  child: FilledButton(
                  key: Key(
                    widget.refund ? 'refund-confirm' : 'collection-confirm',
                  ),
                  style: widget.counterSaleReceipt
                      ? FilledButton.styleFrom(
                          backgroundColor: const Color(0xFFF0F1F7),
                          foregroundColor: MoolColors.navy,
                          minimumSize: const Size(48, 48),
                        )
                      : null,
                  onPressed:
                      !draft.ready ||
                          draft.busy ||
                          draft.error != null ||
                          saving ||
                          confirming ||
                          (widget.refund &&
                              (widget.session.pendingCustomerRefund != null || !sourceRefundSupported))
                      ? null
                      : submit,
                  child: Text(
                    saving
                        ? 'Checking…'
                        : widget.refund
                        ? 'Confirm refund'
                        : widget.counterSaleReceipt
                        ? 'Record receipt'
                        : 'Confirm collection',
                  ),
                ),
                ),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Row(
                      children: [
                        Expanded(
                          child: Text(
                            widget.refund
                                ? 'Record refund'
                                : widget.counterSaleReceipt
                                ? 'Payment receipt'
                                : 'Record collection',
                            style: widget.counterSaleReceipt
                                ? const TextStyle(
                                    fontSize: 18,
                                    fontWeight: FontWeight.w700,
                                    color: MoolColors.ink,
                                  )
                                : Theme.of(context).textTheme.titleLarge,
                          ),
                        ),
                        IconButton(
                          key: Key(widget.refund ? 'refund-close' : 'collection-close'),
                          tooltip: 'Close',
                          onPressed: saving || confirming
                              ? null
                              : () => Navigator.maybePop(context),
                          icon: const Icon(Icons.close, size: 20),
                        ),
                      ],
                    ),
                    if (widget.counterSaleReceipt) const SizedBox(height: 6),
                    Text(
                      '${widget.payment.customerName} · ${widget.payment.invoiceId}',
                      style: widget.counterSaleReceipt
                          ? const TextStyle(
                              fontSize: 12,
                              color: MoolColors.muted,
                            )
                          : null,
                    ),
                    if (widget.counterSaleReceipt) const SizedBox(height: 14),
                    if (!widget.counterSaleReceipt)
                      Text(
                        widget.refund && !sourceRefundSupported
                            ? 'Select an original payment with verified refund availability.'
                            : '${widget.refund ? 'Maximum refund now' : 'Due'} ${_purchaseAmount(limitMinor)}',
                      ),
                    if (widget.refund) ...[
                      if (sourceRefundSupported &&
                          refundLedger?.invoiceBalance(widget.payment.invoiceId!) != null)
                        Text(
                          'Limited to the lower of invoice refund credit '
                          '${_purchaseAmount(refundLedger!.invoiceBalance(widget.payment.invoiceId!)!.refundableMinor)} '
                          'and the selected payment’s remaining refundable amount.',
                          key: const Key('refund-limit-explanation'),
                          style: const TextStyle(fontSize: 12, color: MoolColors.muted),
                        ),
                      const Text('Original payment', style: TextStyle(fontWeight: FontWeight.w600)),
                      if (refundReceipts.isEmpty)
                        const Text('Original payment details unavailable.')
                      else
                        for (final receipt in refundReceipts)
                          TextButton.icon(
                            key: ValueKey('refund-source-${receipt.id}'),
                            onPressed: saving || confirming ? null : () {
                              setState(() {
                                sourceCollectionId = receipt.id;
                                channel = receipt.channel;
                                reference.clear();
                                amountError = null;
                              });
                              saveDraft();
                            },
                            icon: Icon(sourceCollectionId == receipt.id ? Icons.radio_button_checked : Icons.radio_button_unchecked, size: 18),
                            label: Text('${receipt.channel.label} · ${_purchaseAmount(receipt.amountMinor)} · '
                                '${MaterialLocalizations.of(context).formatShortDate(receipt.occurredAt.toLocal())}\n'
                                'Payment refundable balance: ${receiptRemainingLabel(receipt)}'),
                          ),
                      if (sourceReceipt?.paymentReference?.isNotEmpty == true)
                        Text('Original transaction: ${sourceReceipt!.paymentReference}', key: const Key('refund-original-reference')),
                      if (sourceReceipt != null && channel != WorkspacePaymentChannel.cash)
                        const Text('Original payer account details unavailable. Confirm the customer’s destination before returning money. Original-payment refunds require a connected payment provider.', key: Key('refund-account-guidance')),
                      const SizedBox(height: 16),
                    ],
                    _StoreAmountWidth(
                      controller: amount,
                      child: TextField(
                      key: Key(
                        widget.refund ? 'refund-amount' : 'collection-amount',
                      ),
                      controller: amount,
                      focusNode: amountFocus,
                      onChanged: (_) {
                        if (amountError != null) {
                          setState(() => amountError = null);
                        }
                      },
                      textInputAction: _needsReference
                          ? TextInputAction.next
                          : TextInputAction.done,
                      onSubmitted: (_) => _needsReference
                          ? referenceFocus.requestFocus()
                          : amountFocus.unfocus(),
                      enabled: !saving && !confirming && draft.ready,
                      keyboardType: const TextInputType.numberWithOptions(
                        decimal: true,
                      ),
                      decoration: InputDecoration(
                        errorText: amountError,
                        errorMaxLines: 3,
                        labelText: widget.refund
                            ? 'Amount refunded (₹)'
                            : widget.counterSaleReceipt
                            ? 'Amount received'
                            : 'Amount received (₹)',
                        prefixText: widget.counterSaleReceipt ? '₹ ' : null,
                      ),
                      ),
                    ),
                    if (widget.counterSaleReceipt)
                      Padding(
                        padding: const EdgeInsets.symmetric(vertical: 8),
                        child: Text(
                          'Payment method: ${_bankTransfer
                              ? 'Bank Transfer'
                              : channel == WorkspacePaymentChannel.cash
                              ? 'Cash'
                              : 'UPI'}',
                          key: const Key('work-counter-receipt-method'),
                        ),
                      )
                    else if (!widget.refund)
                      Wrap(
                        spacing: 8,
                        children: [
                          for (final mode in [
                            WorkspacePaymentChannel.cash,
                            WorkspacePaymentChannel.directUpi,
                          ])
                            ChoiceChip(
                              label: Text(
                                mode == WorkspacePaymentChannel.cash
                                    ? 'Cash'
                                    : 'UPI',
                              ),
                              selected: channel == mode,
                              onSelected: saving || confirming || !draft.ready
                                  ? null
                                  : (_) {
                                      setState(() => channel = mode);
                                      saveDraft();
                                    },
                            ),
                        ],
                      ),
                    if (widget.refund && _needsReference)
                      const SizedBox(height: 16),
                    if (_needsReference)
                      TextField(
                        key: Key(
                          widget.refund
                              ? 'refund-reference'
                              : 'collection-reference',
                        ),
                        controller: reference,
                        focusNode: referenceFocus,
                        enabled: !saving && !confirming && draft.ready,
                        textInputAction: TextInputAction.done,
                        onSubmitted: (_) => referenceFocus.unfocus(),
                        onChanged: (_) {
                          if (referenceError != null) {
                            setState(() => referenceError = null);
                          }
                        },
                        decoration: InputDecoration(
                          labelText: _referenceLabel,
                          errorText: referenceError,
                          errorMaxLines: 3,
                        ),
                      ),
                    Text(
                      widget.refund
                          ? 'Record money already returned to this customer. This does not transfer money.'
                          : 'Record a payment already received. This does not request or transfer money.',
                    ),
                    if (draft.error != null) ...[
                      Text(draft.error!),
                      TextButton(
                        onPressed: draft.busy
                            ? null
                            : () {
                                if (draft.ready) {
                                  saveDraft();
                                } else {
                                  unawaited(loadDraft());
                                }
                              },
                        child: const Text('Retry saving input'),
                      ),
                    ],
                    if (error != null) Text(error!),
                  ],
                ),
              ),
            ),
          ),
        );
}

class _MoneyDestinationSurface extends StatelessWidget {
