int _availableCustomerCredit(WorkspaceCustomerLedger ledger) => !ledger.valid || !ledger.historyComplete ? 0
    : ledger.entries.map((e) => e.invoiceId).toSet().fold<int>(0,
        (sum, id) => sum + (ledger.invoiceBalance(id)?.availableCreditMinor ?? 0));

class _CustomerCreditApplication extends StatefulWidget {
  const _CustomerCreditApplication({required this.session, required this.ledger, required this.payment});
  final WorkSession session;
  final WorkspaceCustomerLedger ledger;
  final WorkspacePaymentRecord payment;
  @override
  State<_CustomerCreditApplication> createState() => _CustomerCreditApplicationState();
}

class _CustomerCreditApplicationState extends State<_CustomerCreditApplication> {
  final amount = TextEditingController();
  String? source;
  String? error;
  bool saving = false;
  bool needsReview = false;
  bool get _sameStore => widget.session.activeWorkspace?.id == widget.ledger.workspaceId &&
      widget.session.workspaceFinance?.accountScope == widget.ledger.accountScope;
  Future<void> _reviewSavedInvoice() async {
    if (!_sameStore) {
      setState(() => error = 'Store changed. Close and return to the original invoice.');
      return;
    }
    setState(() { saving = true; error = null; });
    final recovered = await widget.session.recoverCustomerLedger();
    if (!mounted) return;
    if (recovered && _sameStore) {
      Navigator.pop(context);
      return;
    }
    setState(() {
      saving = false;
      error = _sameStore
          ? 'Saved records could not be loaded. Try reviewing again before applying credit.'
          : 'Store changed. Close and return to the original invoice.';
    });
  }
  String _sourceContext(String id) {
    final original = widget.ledger.entries.where((entry) => entry.invoiceId == id &&
        entry.valid && entry.kind == WorkspaceLedgerEntryKind.invoice &&
        entry.state == WorkspaceLedgerPostingState.posted).firstOrNull;
    if (original == null) return 'Original invoice details unavailable';
    final date = original.occurredAt.toLocal();
    final label = '${date.day.toString().padLeft(2, '0')}/'
        '${date.month.toString().padLeft(2, '0')}/${date.year}';
    return '$label · Original invoice ${_purchaseAmount(original.amountMinor)}';
  }
  @override
  void dispose() { amount.dispose(); super.dispose(); }
  @override
  Widget build(BuildContext context) {
    final candidates = widget.ledger.entries.map((e) => e.invoiceId).toSet().where((id) =>
      id != widget.payment.invoiceId && (widget.ledger.invoiceBalance(id)?.availableCreditMinor ?? 0) > 0);
    return PopScope(canPop: !saving, child: SafeArea(top: false, child: Padding(
      padding: EdgeInsets.fromLTRB(16, 12, 16, MediaQuery.viewInsetsOf(context).bottom + 16),
      child: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          Row(children: [const Expanded(child: Text('Use customer credit', style: TextStyle(fontSize: 18, fontWeight: FontWeight.w700))),
            IconButton(tooltip: 'Close', onPressed: saving ? null : () => Navigator.pop(context), icon: const Icon(Icons.close))]),
          Text('Invoice due ${_purchaseAmount(widget.payment.dueMinor)}'),
          for (final id in candidates)
            ListTile(dense: true, contentPadding: EdgeInsets.zero,
              leading: Icon(source == id ? Icons.radio_button_checked : Icons.radio_button_unchecked),
              selected: source == id,
              title: Text(id), subtitle: Text('${_sourceContext(id)}\n'
                  'Available credit ${_purchaseAmount(widget.ledger.invoiceBalance(id)!.availableCreditMinor)}',
                  key: ValueKey('customer-credit-source-context-$id')),
              onTap: saving || needsReview ? null : () => setState(() {
                source = id;
                final credit = widget.ledger.invoiceBalance(id)!.availableCreditMinor;
                amount.text = _formatStoreMinorAmount(credit < widget.payment.dueMinor ? credit : widget.payment.dueMinor);
                error = null;
              })),
          Align(alignment: Alignment.centerLeft, child: SizedBox(width: 180, child: TextField(
            key: const Key('customer-credit-amount'), controller: amount, enabled: !saving && !needsReview,
            keyboardType: const TextInputType.numberWithOptions(decimal: true),
            decoration: const InputDecoration(labelText: 'Credit to use', prefixText: '₹ ')))),
          const SizedBox(height: 12),
          const Text('This reduces the invoice due. No money is collected or refunded.'),
          if (error != null) Text(error!, style: TextStyle(color: Theme.of(context).colorScheme.error)),
          if (needsReview) Align(alignment: Alignment.centerLeft, child: TextButton.icon(
            key: const Key('customer-credit-review-saved'),
            onPressed: saving ? null : _reviewSavedInvoice,
            icon: const Icon(Icons.refresh, size: 18),
            label: Text(saving ? 'Checking saved records…' : 'Review saved invoice'))),
          Align(alignment: Alignment.centerLeft, child: TextButton.icon(
            key: const Key('customer-credit-confirm'), icon: const Icon(Icons.check, size: 18),
            label: Text(saving && !needsReview ? 'Applying…' : 'Apply credit'), onPressed: saving || needsReview ? null : () async {
              final text = amount.text.trim();
              if (source == null || !RegExp(r'^\d{1,12}(\.\d{1,2})?$').hasMatch(text)) {
                setState(() => error = 'Select a credit and enter a valid amount.'); return;
              }
              final parts = text.split('.');
              final minor = int.parse(parts.first) * 100 + (parts.length == 1 ? 0 : int.parse(parts.last.padRight(2, '0')));
              if (minor <= 0 || minor > widget.payment.dueMinor || minor > widget.ledger.invoiceBalance(source!)!.availableCreditMinor) {
                setState(() => error = 'Amount exceeds available credit or invoice due.'); return;
              }
              if (widget.session.workspaceFinance?.accountScope != widget.ledger.accountScope ||
                  widget.session.activeWorkspace?.id != widget.ledger.workspaceId) {
                setState(() => error = 'Store changed. Reopen the invoice.'); return;
              }
              setState(() { saving = true; error = null; });
              final done = await widget.session.applyCustomerCredit(customerId: widget.ledger.customerId,
                sourceInvoiceId: source!, targetInvoiceId: widget.payment.invoiceId!, amountMinor: minor,
                expectedRevision: widget.ledger.revision);
              if (!mounted || !context.mounted) return;
              if (done) { Navigator.pop(context); } else {
                setState(() { saving = false; needsReview = true;
                  error = 'Credit update not confirmed. Review the saved invoice before trying again.'; });
              }
            })),
        ])))));
  }
}

// Presentation only: amounts remain owned by the original payment/ledger.
// Long values and larger text reduce columns rather than clip or shrink digits.
class _OrderPaymentFigures extends StatelessWidget {
  const _OrderPaymentFigures({required this.figures});

  final List<(String, int)> figures;

  @override
  Widget build(BuildContext context) => LayoutBuilder(builder: (context, constraints) {
    const labelStyle = TextStyle(fontSize: 11, color: MoolColors.muted);
    const valueStyle = TextStyle(fontSize: 12, color: MoolColors.ink,
        fontWeight: FontWeight.w600);
    var minimumWidth = 96.0;
    for (final figure in figures) {
      for (final text in [(figure.$1, labelStyle), (_purchaseAmount(figure.$2), valueStyle)]) {
        final painter = TextPainter(text: TextSpan(text: text.$1, style: text.$2),
            textDirection: Directionality.of(context), textScaler: MediaQuery.textScalerOf(context))..layout();
        if (painter.width + 16 > minimumWidth) minimumWidth = painter.width + 16;
        painter.dispose();
      }
    }
    final columns = (constraints.maxWidth / minimumWidth).floor()
        .clamp(1, figures.length == 4 ? 2 : 3);
    return Wrap(runSpacing: 4, children: [
      for (var index = 0; index < figures.length; index++)
        SizedBox(width: constraints.maxWidth / columns,
          child: Container(
            padding: EdgeInsets.only(left: index % columns == 0 ? 0 : 8, right: 8),
            decoration: BoxDecoration(border: index % columns == 0 ? null
                : const Border(left: BorderSide(color: MoolColors.line))),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text(figures[index].$1, style: labelStyle),
              Text(_purchaseAmount(figures[index].$2),
                  key: Key('work-order-${figures[index].$1.toLowerCase().replaceAll(' ', '-')}-amount'),
                  style: valueStyle),
            ]),
          ),
        ),
    ]);
  });
}

class _InvoiceCollectionSummary extends StatelessWidget {
  const _InvoiceCollectionSummary({
    required this.session,
    required this.invoice,
    required this.accountScope,
    required this.storeId,
    this.onRecord,
    this.receiptEditor,
    this.orderDetails = false,
  });

  final WorkSession session;
  final ValueChanged<WorkspacePaymentRecord>? onRecord;
  final Widget? receiptEditor;
  final bool orderDetails;
  final WorkspaceCustomerInvoice invoice;
  final String? accountScope, storeId;

  @override
  Widget build(BuildContext context) => AnimatedBuilder(
    animation: session,
    builder: (context, _) {
      final finance = session.workspaceFinance;
      final sameScope =
          finance != null &&
          accountScope != null &&
          storeId != null &&
          finance.accountScope == accountScope &&
          finance.workspaceId == storeId &&
          session.activeWorkspace?.id == storeId;
      final payment = sameScope
          ? finance.payments
                .where(
                  (record) =>
                      record.invoiceId == invoice.id &&
                      record.orderId == invoice.orderId,
                )
                .firstOrNull
          : null;
      if (payment == null || !payment.valid) {
        return const Text(
          'Payment status unavailable. Creating an invoice does not confirm payment.',
          key: Key('work-invoice-payment-unavailable'),
          style: TextStyle(color: MoolColors.muted),
        );
      }
      final canRecord =
          (!orderDetails || !session.workspaceFinanceStale) &&
          session.customerCollectionAvailable &&
          payment.dueMinor > 0 &&
          finance!.customerLedgers.any(
            (ledger) =>
                ledger.customerId == payment.customerId &&
                ledger.historyComplete,
          );
      final creditLedger = finance?.customerLedgers.where((l) => l.customerId == payment.customerId).firstOrNull;
      final balance = creditLedger?.invoiceBalance(invoice.id);
      return DefaultTextStyle.merge(
        style: orderDetails ? const TextStyle(fontSize: 12, color: MoolColors.ink) : const TextStyle(),
        child: Column(
        key: const Key('work-invoice-payment-totals'),
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          if (orderDetails) ...[
            Wrap(spacing: 12, runSpacing: 2, children: [
              Text('${session.workspaceFinanceStale ? 'Last saved payment' : 'Payment'} · ${payment.label}',
                key: const Key('work-order-payment-state'),
                style: const TextStyle(color: MoolColors.navy, fontWeight: FontWeight.w600)),
              Text(storeInvoicePaymentMethod(invoice.payment, payment,
                  creditLedger?.historyComplete == true ? creditLedger!.entries : const [],
                  preferRecordedMethods: true), style: const TextStyle(
                      fontSize: 11, color: MoolColors.muted)),
            ]),
            Text('Recorded ${MaterialLocalizations.of(context).formatShortDate(payment.updatedAt.toLocal())} · '
                '${MaterialLocalizations.of(context).formatTimeOfDay(TimeOfDay.fromDateTime(payment.updatedAt.toLocal()))}',
                style: const TextStyle(fontSize: 11, color: MoolColors.muted)),
            if (session.workspaceFinanceStale)
              const Text('Payment records need refresh. Return to Orders and reopen after records load.',
                  key: Key('work-order-payment-stale'),
                  style: TextStyle(fontSize: 11, color: MoolColors.muted)),
            const SizedBox(height: 4),
            _OrderPaymentFigures(figures: [
              ('Received', payment.paidMinor),
              ('Due', payment.dueMinor),
              if (payment.refundedMinor > 0) ('Refunded', payment.refundedMinor),
              if (balance != null && balance.creditedMinor > 0)
                ('Return credit', balance.creditedMinor),
              if (balance != null && balance.refundableMinor > 0)
                ('Available to refund', balance.refundableMinor),
            ]),
          ],
          if (!orderDetails) Text(
            'Received ${_purchaseAmount(payment.paidMinor)} · Due ${_purchaseAmount(payment.dueMinor)}',
          ),
          if (orderDetails && payment.state == WorkspacePaymentState.refundPending && balance == null)
            const Text('Refund pending · amount not confirmed in these records.'),
          if (creditLedger != null && creditLedger.entries.any((e) => e.invoiceId == invoice.id &&
              e.kind == WorkspaceLedgerEntryKind.creditReceived))
            Text('Customer credit applied ${_purchaseAmount(creditLedger.entries.where((e) =>
              e.invoiceId == invoice.id && e.kind == WorkspaceLedgerEntryKind.creditReceived &&
              e.state == WorkspaceLedgerPostingState.posted).fold<int>(0, (sum, e) => sum + e.amountMinor))}'),
          if (creditLedger != null && payment.dueMinor > 0 && _availableCustomerCredit(creditLedger) > 0)
            Align(alignment: Alignment.centerLeft, child: TextButton.icon(
              key: const Key('work-invoice-use-credit'), icon: const Icon(Icons.account_balance_wallet_outlined, size: 18),
              style: orderDetails ? TextButton.styleFrom(
                  textStyle: const TextStyle(fontSize: 12, fontWeight: FontWeight.w600)) : null,
              label: Text('Use customer credit · ${_purchaseAmount(_availableCustomerCredit(creditLedger))} available'),
              onPressed: !session.customerCreditAvailable ? null : () => showModalBottomSheet<void>(
                context: context, isScrollControlled: true, useSafeArea: true, isDismissible: false, enableDrag: false,
                builder: (_) => _CustomerCreditApplication(session: session, ledger: creditLedger, payment: payment)))),
          if (receiptEditor != null)
            receiptEditor!
          else if (payment.dueMinor > 0 &&
              (invoice.payment == 'Cash' || invoice.payment == 'Bank Transfer'))
            Align(
              alignment: Alignment.centerLeft,
              child: TextButton.icon(
                key: Key(
                  invoice.payment == 'Cash'
                      ? 'work-invoice-record-payment'
                      : 'work-invoice-record-bank-transfer',
                ),
                onPressed: !canRecord
                    ? null
                    : () async {
                        if (onRecord != null) {
                          onRecord!(payment);
                          return;
                        }
                        // The existing collection sheet rechecks Store, account and
                        // invoice revision; reopening it never creates another sale.
                        await showModalBottomSheet<void>(
                          context: context,
                          isScrollControlled: true,
                          useSafeArea: true,
                          isDismissible: false,
                          enableDrag: false,
                          builder: (_) => _CustomerCollectionSheet(
                            session: session,
                            payment: payment,
                            accountScope: accountScope!,
                            storeId: storeId!,
                            counterSaleReceipt: true,
                          ),
                        );
                      },
                style: orderDetails ? TextButton.styleFrom(
                    textStyle: const TextStyle(fontSize: 12, fontWeight: FontWeight.w600)) : null,
                icon: Icon(Icons.payments_outlined, size: orderDetails ? 18 : null),
                label: Text(
                  invoice.payment == 'Cash'
                      ? orderDetails ? 'Record payment receipt' : 'Record Payment Receipt'
                      : 'Confirm bank transfer',
                ),
              ),
            ),
        ],
      ));
    },
  );
}

