// Older customer history may contain a display name followed by a mobile.
// Only history/draft display values use this; typed input is validated whole.
String? _storedCounterCustomerMobile(String customer) {
  return workspaceCustomerMobile(customer);
}

class _CounterOrderSurfaceState extends State<_CounterOrderSurface> {
  final _collectionKey = GlobalKey<_CustomerCollectionSheetState>();
  bool get hasCompletedInvoice =>
      _invoice != null && (_stage == 'invoice' || _stage == 'payment');
  Future<bool> flushForNavigation() async {
    if (_saving) return false;
    return await (_collectionKey.currentState?.flushForNavigation() ??
        Future.value(true));
  }

  Future<bool> backWithinSale() async {
    if (_stage == 'invoice') return false;
    if (_stage == 'items') {
      await _editCustomer(returnToItems: false);
      return true;
    }
    if (_stage == 'customer' && !_customerReturnToItems) return false;
    if (!await flushForNavigation() || !mounted) return true;
    setState(() {
      _stage = _stage == 'payment' ? 'invoice' : 'items';
      _error = null;
    });
    return true;
  }

  late final TextEditingController _customer = TextEditingController(
    text: widget.session.workspaceOrderCustomer,
  );
  late final TextEditingController _productSearch = TextEditingController(
    text: widget.query,
  );
  final _productSearchFocus = FocusNode(debugLabel: 'counter-product-search');
  bool _usbScanMode = false;
  String _barcodeBuffer = '';
  bool _barcodeOverflow = false;
  DateTime? _lastScannerKeyAt;
  final _barcodeFocus = FocusNode();
  late final TextEditingController _address = TextEditingController(
    text: widget.session.workspaceOrderAddress,
  );
  late String _source = widget.session.workspaceOrderSource;
  late String _fulfilment = widget.session.workspaceOrderFulfilment;
  late String _payment = widget.session.workspaceOrderPayment;
  String? _error;
  String _stage = 'customer';
  bool _customerReturnToItems = false;
  WorkspaceCustomerInvoice? _invoice;
  WorkspacePaymentRecord? _collection;
  String? _invoiceAccount, _invoiceStore;
  String? _reviewedBill;
  String? _reviewedOrderId;
  final Set<String> _expandedCartCategories = {};
  bool _saving = false, _restoring = false, _openingDraft = false;
  bool _editingDiscount = false;
  String? _customerInput;
  Object? _draftIdentity;
  Object get _currentDraftIdentity =>
      (widget.session.counterDraftIdentity, widget.session.activeWorkspace?.id);

  @override
  void initState() {
    super.initState();
    _draftIdentity = _currentDraftIdentity;
    _openingDraft = widget.session.counterDraftIdentity != null;
    _address.addListener(_rememberDetails);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) unawaited(_openDraft());
    });
  }

  @override
  void didUpdateWidget(covariant _CounterOrderSurface oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.query != widget.query) _productSearch.text = widget.query;
    if (_draftIdentity != _currentDraftIdentity) {
      _draftIdentity = _currentDraftIdentity;
      _openingDraft = true;
      _stage = 'customer';
      _productSearch.clear();
      _usbScanMode = false;
      _clearScannerBuffer();
      _invoice = null;
      _collection = null;
      _expandedCartCategories.clear();
      _saving = false;
      _editingDiscount = false;
      _error = null;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) unawaited(_openDraft());
      });
    }
  }

  Future<void> _openDraft({bool retry = false}) async {
    final identity = _currentDraftIdentity;
    var recovered = false;
    if (retry) {
      recovered = await widget.session.retryWorkspaceCounterDraft(
        shouldRestore: () => mounted && identity == _currentDraftIdentity,
      );
    } else {
      await widget.session.loadWorkspaceCounterDraft(
        retry: true,
        shouldRestore: () => mounted && identity == _currentDraftIdentity,
      );
    }
    if (!mounted || identity != _currentDraftIdentity) return;
    _restoring = true;
    setState(() {
      _customer.text = widget.session.workspaceOrderCustomer;
      _customerInput = widget.session.counterCustomerInput;
      _address.text = widget.session.workspaceOrderAddress;
      _source = widget.session.workspaceOrderSource;
      _fulfilment = widget.session.workspaceOrderFulfilment;
      _payment = widget.session.workspaceOrderPayment;
      _stage = _storedCounterCustomerMobile(_customer.text) == null
          ? 'customer'
          : 'items';
      _openingDraft = false;
    });
    _restoring = false;
    final completed = widget.session.recoveredCounterSubmission;
    if (recovered && completed != null) {
      _finishSavedBill(completed, identity);
    }
  }

  void _rememberDetails() {
    if (_restoring || _saving || _openingDraft || !mounted) return;
    widget.session.updateWorkspaceCounterDetails(
      customer: _customerInput == null ? _customer.text : null,
      source: _source,
      fulfilment: _fulfilment,
      payment: _payment,
      address: _address.text,
    );
  }

  @override
  void dispose() {
    _address.removeListener(_rememberDetails);
    _customer.dispose();
    _productSearch.dispose();
    _productSearchFocus.dispose();
    _barcodeFocus.dispose();
    _address.dispose();
    super.dispose();
  }

  List<_RecentCounterCustomer> get _recentCustomers {
    final seen = <String>{};
    final invoices = [...widget.session.workspaceInvoices]
      ..sort((a, b) => b.issuedAt.compareTo(a.issuedAt));
    return [
          for (final invoice in invoices)
            _RecentCounterCustomer(invoice.customer, invoice.billingDetails),
          for (final order in widget.session.visibleWorkspaceOrders)
            _RecentCounterCustomer(order.customer, order.billingDetails),
        ]
        .where(
          (customer) => customer.mobile != null && seen.add(customer.mobile!),
        )
        .take(4)
        .toList(growable: false);
  }

  int get _selectedUnits => widget.session.workspaceOrderQuantities.values
      .fold<int>(0, (total, quantity) => total + quantity);

  Future<void> _save({String? expectedReview}) async {
    if (_saving || _openingDraft || widget.session.counterDraftEditingBlocked) {
      return;
    }
    final error = _storedCounterCustomerMobile(_customer.text) == null
        ? 'Enter a valid 10-digit customer mobile number.'
        : widget.session.workspaceOrderItemCount == 0
        ? 'Add at least one product from your store catalogue.'
        : _fulfilment != 'At the shop' && _address.text.trim().isEmpty
        ? 'Add the confirmed customer delivery address.'
        : null;
    if (error != null) {
      setState(() => _error = error);
      return;
    }
    _rememberDetails();
    setState(() => _saving = true);
    final identity = _currentDraftIdentity;
    final submitted = await widget.session.submitWorkspaceCounterBill(
      expectedReview: expectedReview,
    );
    if (!mounted || identity != _currentDraftIdentity) return;
    setState(() => _saving = false);
    if (submitted == null) {
      setState(
        () => _error =
            widget.session.counterDraftError ??
            widget.session.errorMessage ??
            widget.session.noticeMessage ??
            'This bill could not be saved.',
      );
      // Keep recovery next to this bill; do not repeat it in the shared banner.
      widget.session.clearMessages();
      return;
    }
    _finishSavedBill(submitted, identity);
  }

  void _finishSavedBill(
    ({String orderId, WorkspaceCustomerInvoice? invoice}) submitted,
    Object identity,
  ) {
    setState(() => _error = null);
    // The central invoice is the confirmation; a duplicate global banner can
    // crowd its payment controls out of a compact, enlarged-text viewport.
    widget.session.clearMessages();
    FocusManager.instance.primaryFocus?.unfocus();
    if (_fulfilment == 'At the shop') {
      final invoice = submitted.invoice;
      if (invoice != null) {
        setState(() {
          _invoice = invoice;
          _collection = null;
          _invoiceAccount = widget.session.workspaceFinance?.accountScope;
          _invoiceStore = widget.session.activeWorkspace?.id;
          _stage = 'invoice';
        });
      }
    } else {
      widget.session.showNotice(
        _source == 'Phone'
            ? 'Delivery order saved. Confirm the order with the customer before dispatch.'
            : 'Delivery order saved. Pack the items before requesting a rider.',
      );
      widget.onArrangeDelivery();
    }
  }

  void _nextSale() {
    if (!widget.session.startNewWorkspaceOrder()) return;
    _restoring = true;
    setState(() {
      _invoice = null;
      _collection = null;
      _stage = 'customer';
      _customerReturnToItems = false;
      _customer.clear();
      _productSearch.clear();
      _usbScanMode = false;
      _clearScannerBuffer();
      _barcodeFocus.unfocus();
      _customerInput = null;
      _address.clear();
      _source = widget.session.workspaceOrderSource;
      _fulfilment = widget.session.workspaceOrderFulfilment;
      _payment = widget.session.workspaceOrderPayment;
    });
    _restoring = false;
  }

  Future<void> _review() async {
    if (_saving || _openingDraft || widget.session.counterDraftEditingBlocked) {
      return;
    }
    final pendingCustomer =
        _customerInput ?? widget.session.counterCustomerInput;
    if (pendingCustomer != null && pendingCustomer != _customer.text) {
      await _editCustomer();
      return;
    }
    _rememberDetails();
    setState(() {
      _reviewedBill = widget.session.counterBillReviewSignature;
      _reviewedOrderId = widget.session.currentWorkspaceOrderId;
      _stage = 'review';
      _editingDiscount = false;
    });
  }

  void _applyDiscount(WorkspaceBillDiscount discount) {
    if (_saving ||
        _stage != 'review' ||
        widget.session.counterDraftEditingBlocked ||
        _reviewedOrderId != widget.session.currentWorkspaceOrderId) {
      return;
    }
    if (widget.session.updateWorkspaceCounterDiscount(discount)) {
      setState(() {
        _reviewedBill = widget.session.counterBillReviewSignature;
        _error = null;
        _editingDiscount = false;
      });
    }
  }

  Widget _reviewPanel() {
    void editItems() {
      FocusManager.instance.primaryFocus?.unfocus();
      setState(() => _stage = 'items');
    }

    final compactHeader =
        MediaQuery.sizeOf(context).width < 360 &&
        MediaQuery.textScalerOf(context).scale(14) > 20;
    final products = widget.session.workspaceCatalogueItems
        .where(
          (product) =>
              (widget.session.workspaceOrderQuantities[product.id] ?? 0) > 0,
        )
        .toList(growable: false);
    final groups = <String, List<WorkspaceCatalogueItem>>{};
    for (final product in products) {
      (groups[product.categoryId] ??= []).add(product);
    }
    final grouped = products.length > 6;
    final rows = <({String? category, WorkspaceCatalogueItem? product})>[
      if (!grouped)
        for (final product in products) (category: null, product: product)
      else
        for (final group in groups.entries) ...[
          (category: group.key, product: null),
          if (_expandedCartCategories.contains(group.key))
            for (final product in group.value)
              (category: null, product: product),
        ],
    ];
    final categoryLabels = {
      for (final category in [
        ...BuyV2Catalogue.shopCategories,
        ...BuyV2Catalogue.wholesaleCategories,
      ])
        category.id: category.label,
    };
    final amountWidth = products.fold<double>(48, (width, product) {
      final painter = TextPainter(
        text: TextSpan(
          text:
              '₹${_formatStoreAmount(product.sellingPrice * widget.session.workspaceOrderQuantities[product.id]!)}',
          style: DefaultTextStyle.of(
            context,
          ).style.copyWith(fontSize: 12, fontWeight: FontWeight.w700),
        ),
        textDirection: Directionality.of(context),
        textScaler: MediaQuery.textScalerOf(context),
      )..layout();
      final measured = painter.width + 8;
      painter.dispose();
      return measured > width ? measured : width;
    });
    Widget cart({List<Widget> trailing = const []}) => Material(
      key: const Key('work-order-review-summary'),
      color: Colors.white,
      child: CustomScrollView(
        key: const Key('work-review-items-list'),
        keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
        slivers: [
          SliverToBoxAdapter(
            child: Padding(
              padding: const EdgeInsets.fromLTRB(16, 8, 16, 8),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Row(
                    children: [
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            if (widget.session.workspaceOrderBillingDetails.name
                                .trim()
                                .isNotEmpty)
                              Text(
                                widget.session.workspaceOrderBillingDetails.name
                                    .trim(),
                                style: const TextStyle(
                                  fontWeight: FontWeight.w700,
                                ),
                              ),
                            Text(
                              '+91 ${_storedCounterCustomerMobile(_customer.text) ?? _customer.text.trim()}',
                              style: const TextStyle(
                                fontSize: 12,
                                color: MoolColors.muted,
                              ),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                  Row(
                    children: [
                      Expanded(
                        child: Text(
                          'Review bill · ${products.length} ${products.length == 1 ? 'item' : 'items'}',
                          key: const Key('work-review-item-count'),
                          style: const TextStyle(
                            fontSize: 12,
                            color: MoolColors.muted,
                          ),
                        ),
                      ),
                      if (compactHeader)
                        IconButton(
                          key: const Key('work-review-edit-items'),
                          tooltip: 'Edit items',
                          onPressed: _saving ? null : editItems,
                          icon: const Icon(Icons.edit_outlined),
                        )
                      else
                        TextButton(
                          key: const Key('work-review-edit-items'),
                          onPressed: _saving ? null : editItems,
                          child: const Text('Edit items'),
                        ),
                    ],
                  ),
                ],
              ),
            ),
          ),
          SliverPadding(
            padding: const EdgeInsets.symmetric(horizontal: 16),
            sliver: SliverList(
              delegate: SliverChildBuilderDelegate((context, index) {
                final row = rows[index];
                if (row.category case final String categoryId) {
                  final items = groups[categoryId]!;
                  final expanded = _expandedCartCategories.contains(categoryId);
                  final subtotal = items.fold<int>(
                    0,
                    (sum, item) =>
                        sum +
                        item.sellingPrice *
                            widget.session.workspaceOrderQuantities[item.id]!,
                  );
                  final label =
                      categoryLabels[categoryId] ??
                      (categoryId.trim().isEmpty
                          ? 'Other products'
                          : categoryId
                                .split('-')
                                .map(
                                  (part) => part.isEmpty
                                      ? part
                                      : '${part[0].toUpperCase()}${part.substring(1)}',
                                )
                                .join(' '));
                  return Semantics(
                    expanded: expanded,
                    child: TextButton(
                      key: ValueKey('work-review-category-$categoryId'),
                      style: TextButton.styleFrom(
                        foregroundColor: MoolColors.muted,
                        padding: const EdgeInsets.symmetric(vertical: 8),
                        minimumSize: const Size(0, 48),
                        alignment: Alignment.centerLeft,
                      ),
                      onPressed: () => setState(() {
                        if (expanded) {
                          _expandedCartCategories.remove(categoryId);
                        } else {
                          _expandedCartCategories.add(categoryId);
                        }
                      }),
                      child: Row(
                        children: [
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text(
                                  label,
                                  style: const TextStyle(
                                    fontWeight: FontWeight.w600,
                                  ),
                                ),
                                Text(
                                  '${items.length} ${items.length == 1 ? 'item' : 'items'} · ₹${_formatStoreAmount(subtotal)}',
                                  style: const TextStyle(
                                    fontSize: 12,
                                    color: MoolColors.muted,
                                  ),
                                ),
                              ],
                            ),
                          ),
                          Icon(
                            expanded ? Icons.expand_less : Icons.expand_more,
                            size: 20,
                          ),
                        ],
                      ),
                    ),
                  );
                }
                final product = row.product!;
                final quantity =
                    widget.session.workspaceOrderQuantities[product.id]!;
                return Container(
                  key: ValueKey('work-review-item-${product.id}'),
                  padding: const EdgeInsets.symmetric(vertical: 6),
                  decoration: const BoxDecoration(
                    border: Border(top: BorderSide(color: Color(0xFFE9EDF5))),
                  ),
                  child: LayoutBuilder(
                    builder: (context, constraints) {
                      final rate =
                          '$quantity × ₹${_formatStoreAmount(product.sellingPrice)}';
                      final separateRate =
                          constraints.maxWidth - amountWidth >= 260 &&
                          MediaQuery.textScalerOf(context).scale(12) <= 16;
                      if (constraints.maxWidth - amountWidth < 140) {
                        return Column(
                          crossAxisAlignment: CrossAxisAlignment.stretch,
                          children: [
                            Row(
                              children: [
                                StoreProductThumbnail(
                                  product: product,
                                  session: widget.session,
                                  extent: 36,
                                ),
                                const SizedBox(width: 8),
                                Expanded(
                                  child: Text(
                                    '${product.title} · ${product.pack}',
                                  ),
                                ),
                              ],
                            ),
                            Text(rate, style: const TextStyle(fontSize: 12)),
                            Align(
                              alignment: Alignment.centerRight,
                              child: Text(
                                '₹${_formatStoreAmount(product.sellingPrice * quantity)}',
                                style: const TextStyle(
                                  fontSize: 12,
                                  fontWeight: FontWeight.w700,
                                ),
                              ),
                            ),
                          ],
                        );
                      }
                      return Row(
                        children: [
                          StoreProductThumbnail(
                            product: product,
                            extent: 36,
                            session: widget.session,
                          ),
                          const SizedBox(width: 8),
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.stretch,
                              children: [
                                Text(
                                  product.title,
                                  style: const TextStyle(
                                    fontWeight: FontWeight.w600,
                                  ),
                                ),
                                const SizedBox(height: 2),
                                Text(
                                  separateRate
                                      ? product.pack
                                      : '${product.pack} · $rate',
                                  style: const TextStyle(
                                    fontSize: 12,
                                    color: MoolColors.muted,
                                  ),
                                ),
                              ],
                            ),
                          ),
                          if (separateRate)
                            SizedBox(
                              width: 82,
                              child: Text(
                                rate,
                                textAlign: TextAlign.right,
                                style: const TextStyle(fontSize: 12),
                              ),
                            ),
                          SizedBox(
                            width: amountWidth,
                            child: Text(
                              '₹${_formatStoreAmount(product.sellingPrice * quantity)}',
                              textAlign: TextAlign.right,
                              style: const TextStyle(
                                fontSize: 12,
                                fontWeight: FontWeight.w700,
                              ),
                            ),
                          ),
                        ],
                      );
                    },
                  ),
                );
              }, childCount: rows.length),
            ),
          ),
          ...trailing,
        ],
      ),
    );
    Widget checkout(double paymentViewportHeight) => Container(
      key: const Key('work-counter-review-totals-card'),
      padding: const EdgeInsets.fromLTRB(16, 8, 16, 0),
      decoration: const BoxDecoration(
        color: Colors.white,
        border: Border(top: BorderSide(color: _counterSaleLine)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          _StoreMoneyLine(
            alignAmountToEnd: true,
            leading: Text(
              'Subtotal · $_selectedUnits ${_selectedUnits == 1 ? 'unit' : 'units'}',
              style: const TextStyle(fontSize: 12),
            ),
            value: _purchaseAmount(
              widget.session.workspaceCounterSubtotalMinor,
            ),
          ),
          const SizedBox(height: 4),
          _CounterBillDiscountEditor(
            key: const Key('work-counter-discount-editor'),
            subtotalMinor: widget.session.workspaceCounterSubtotalMinor,
            initial: widget.session.workspaceCounterDiscount,
            onApply: _applyDiscount,
            onInvalid: () => setState(() => _editingDiscount = true),
            enabled: !_saving && !widget.session.counterDraftEditingBlocked,
          ),
          const Divider(height: 12),
          _StoreMoneyLine(
            key: const Key('work-counter-review-total'),
            alignAmountToEnd: true,
            leading: const Text('Amount due'),
            value:
                !_editingDiscount &&
                    widget.session.workspaceCounterDiscountError == null
                ? '₹${_formatStoreMinorAmount(widget.session.workspaceCounterPayableMinor)}'
                : '—',
            style: const TextStyle(
              fontSize: 16,
              fontWeight: FontWeight.w700,
              color: Color(0xff252b38),
            ),
          ),
          const SizedBox(height: 4),
          if (_editingDiscount)
            const Text(
              'Apply your discount to update the total.',
              style: TextStyle(fontSize: 11, color: MoolColors.muted),
            ),
          if (widget.session.workspaceCounterDiscountError case final error?)
            Text(
              error,
              key: const Key('work-counter-discount-error'),
              style: const TextStyle(color: Color(0xFFB42318)),
            ),
          const SizedBox(height: 4),
          _OrderCompletionChoices(
            fulfilment: _fulfilment,
            payment: _payment,
            counterOnly: true,
            compact: true,
            addressController: _address,
            onFulfilmentChanged: (value) {
              setState(() => _fulfilment = value);
              _rememberDetails();
            },
            onPaymentChanged: (value) {
              setState(() {
                _payment = value;
                _error = null;
              });
              _rememberDetails();
            },
          ),
          if (_payment == 'UPI' &&
              !_editingDiscount &&
              widget.session.workspaceCounterDiscountError == null)
            _CounterUpiPanel(
              key: ValueKey(widget.session.storeUpiScope),
              session: widget.session,
              amountPaise: widget.session.workspaceCounterPayableMinor,
              reference: widget.session.retainedCounterDraft?.id,
              viewportHeight: paymentViewportHeight,
            ),
          if (_error != null)
            Semantics(
              key: const Key('work-bill-review-update'),
              liveRegion: true,
              child: Text(
                _error!,
                style: const TextStyle(color: Color(0xFFB42318)),
              ),
            ),
        ],
      ),
    );
    final action = ColoredBox(
      color: Colors.white,
      child: Padding(
        padding: const EdgeInsets.fromLTRB(12, 6, 12, 8),
        child: SizedBox(
          width: double.infinity,
          child: FilledButton.icon(
            key: const Key('work-order-save'),
            onPressed:
                _saving ||
                    _editingDiscount ||
                    widget.session.workspaceCounterDiscountError != null
                ? null
                : () {
                    final current = widget.session.counterBillReviewSignature;
                    if (_reviewedOrderId !=
                            widget.session.currentWorkspaceOrderId ||
                        current != _reviewedBill) {
                      setState(() {
                        _reviewedOrderId =
                            widget.session.currentWorkspaceOrderId;
                        _reviewedBill = current;
                        _error = 'Bill updated. Review the items and total.';
                      });
                      return;
                    }
                    _save(expectedReview: _reviewedBill);
                  },
            icon: const Icon(Icons.check_circle_outline),
            label: Text(_saving ? 'Saving…' : 'Create invoice'),
          ),
        ),
      ),
    );
    final continuousReview =
        products.length <= 3 ||
        MediaQuery.sizeOf(context).height < 500 ||
        (MediaQuery.sizeOf(context).width < 600 &&
            MediaQuery.textScalerOf(context).scale(14) > 18.2);
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Expanded(
          child: LayoutBuilder(
            builder: (context, constraints) => continuousReview
                ? KeyedSubtree(
                    key: const Key('work-sale-central-review'),
                    child: cart(
                      trailing: [
                        SliverToBoxAdapter(
                          child: checkout(constraints.maxHeight),
                        ),
                      ],
                    ),
                  )
                : Column(
                    children: [
                      Expanded(child: cart()),
                      // Allocate after measuring the action at its natural height.
                      // Payment/recovery controls scroll without covering the footer;
                      // stable subtrees retain discount focus when the IME resizes us.
                      ConstrainedBox(
                        constraints: BoxConstraints(
                          maxHeight: constraints.maxHeight * .65,
                        ),
                        child: SingleChildScrollView(
                          key: const Key('work-sale-central-review'),
                          keyboardDismissBehavior:
                              ScrollViewKeyboardDismissBehavior.onDrag,
                          child: checkout(constraints.maxHeight * .65),
                        ),
                      ),
                    ],
                  ),
          ),
        ),
        action,
      ],
    );
  }

  Future<void> _openProduct(WorkspaceCatalogueItem product) async {
    if (_saving || _openingDraft || widget.session.counterDraftEditingBlocked) {
      return;
    }
    final identity = _currentDraftIdentity;
    final saleGeneration = widget.session.counterSaleGeneration;
    _productSearchFocus.unfocus();
    await Navigator.of(context).push<void>(
      MaterialPageRoute(
        builder: (_) => Theme(
          data: _counterSaleTheme(Theme.of(context)),
          child: _CounterStoreProductPage(
            session: widget.session,
            productId: product.id,
            isCurrent: () =>
                mounted &&
                identity == _currentDraftIdentity &&
                saleGeneration == widget.session.counterSaleGeneration &&
                !widget.session.counterDraftEditingBlocked,
          ),
        ),
      ),
    );
  }

  Future<void> _scanProduct() async {
    if (_saving || _openingDraft || widget.session.counterDraftEditingBlocked) {
      return;
    }
    final identity = _currentDraftIdentity;
    final saleGeneration = widget.session.counterSaleGeneration;
    final code = await showStoreProductScanner(context);
    if (!mounted || code == null || code.trim().isEmpty) return;
    if (identity != _currentDraftIdentity ||
        saleGeneration != widget.session.counterSaleGeneration) {
      return;
    }
    _addScannedProduct(code);
  }

  void _toggleUsbScanner() {
    _clearScannerBuffer();
    final enable = !_usbScanMode || !_barcodeFocus.hasPrimaryFocus;
    setState(() => _usbScanMode = enable);
    if (_usbScanMode) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted && _usbScanMode) _barcodeFocus.requestFocus();
      });
    } else {
      _barcodeFocus.unfocus();
      _clearScannerBuffer();
    }
  }

  void _clearScannerBuffer() {
    _barcodeBuffer = '';
    _barcodeOverflow = false;
    _lastScannerKeyAt = null;
  }

  KeyEventResult _handleScannerKey(FocusNode node, KeyEvent event) {
    if (!_usbScanMode || !node.hasPrimaryFocus || _stage != 'items') {
      return KeyEventResult.ignored;
    }
    if (event is KeyRepeatEvent) return KeyEventResult.handled;
    if (event is! KeyDownEvent) return KeyEventResult.ignored;
    if (event.logicalKey == LogicalKeyboardKey.escape) {
      _toggleUsbScanner();
      return KeyEventResult.handled;
    }
    final now = DateTime.now();
    if (_lastScannerKeyAt != null &&
        now.difference(_lastScannerKeyAt!) > const Duration(seconds: 2)) {
      _clearScannerBuffer();
    }
    _lastScannerKeyAt = now;
    if (event.logicalKey == LogicalKeyboardKey.enter ||
        event.logicalKey == LogicalKeyboardKey.numpadEnter) {
      final code = _barcodeBuffer;
      final overflow = _barcodeOverflow;
      _clearScannerBuffer();
      if (overflow) {
        widget.session.showError('Scan the product again.');
      } else {
        _addScannedProduct(code);
      }
      return KeyEventResult.handled;
    }
    final character = event.character;
    if (character == null || character.runes.any((rune) => rune < 32)) {
      return KeyEventResult.ignored;
    }
    if (_barcodeBuffer.length + character.length > 128) {
      _barcodeOverflow = true;
    } else {
      _barcodeBuffer += character;
    }
    return KeyEventResult.handled;
  }

  void _addScannedProduct(String code) {
    if (_saving ||
        _openingDraft ||
        widget.session.counterDraftEditingBlocked ||
        _stage != 'items' ||
        code.trim().isEmpty) {
      return;
    }
    widget.session.clearMessages();
    final normalized = code.trim().toLowerCase();
    final matches = widget.session.workspaceCatalogueItems
        .where(
          (item) =>
              item.barcode.toLowerCase() == normalized ||
              item.sku.toLowerCase() == normalized ||
              item.canonicalId.toLowerCase() == normalized,
        )
        .toList(growable: false);
    if (matches.length > 1) {
      widget.session.showError(
        'More than one product matches this code. Search and choose the correct pack.',
      );
      return;
    }
    final product = matches.firstOrNull;
    if (product == null || !product.canSellAtCounter) {
      widget.session.showError(
        'This product is not available in your store inventory.',
      );
      return;
    }
    widget.session.adjustWorkspaceOrderQuantity(product.id, 1);
  }

  Future<void> _editCustomer({bool returnToItems = true}) async {
    if (_openingDraft || _saving || widget.session.counterDraftEditingBlocked) {
      return;
    }
    FocusManager.instance.primaryFocus?.unfocus();
    setState(() {
      _customerReturnToItems = returnToItems;
      _stage = 'customer';
    });
  }

  Widget _customerPanel() => _StoreSaleCustomerSheet(
    key: ValueKey(_currentDraftIdentity),
    initialValue:
        _customerInput ?? widget.session.counterCustomerInput ?? _customer.text,
    recentCustomers: _recentCustomers,
    billingDetails: widget.session.workspaceOrderBillingDetails,
    billingCustomer: widget.session.workspaceOrderBillingCustomer,
    onBillingChanged: (details, mobile) =>
        widget.session.updateWorkspaceCounterDetails(
          billingDetails: details,
          billingCustomer: mobile ?? '',
        ),
    onClose: () {
      if (_storedCounterCustomerMobile(_customer.text) == null) {
        widget.onExit();
      } else {
        setState(() => _stage = 'items');
      }
    },
    onConfirmed: (selected) {
      setState(() {
        _customer.text = selected;
        _customerInput = null;
        _error = null;
        _stage = 'items';
      });
      _rememberDetails();
    },
    onDraftChanged: (value) {
      _customerInput = value;
      widget.session.retainWorkspaceCounterCustomerInput(value);
    },
  );

  @override
  Widget build(BuildContext context) {
    final validPhone = _storedCounterCustomerMobile(_customer.text) != null;
    if (_openingDraft || widget.session.counterDraftLoading) {
      return const Center(
        child: CircularProgressIndicator(
          semanticsLabel: 'Opening your saved bill',
        ),
      );
    }
    if (widget.session.counterDraftEditingBlocked && !_saving) {
      final draft = widget.session.retainedCounterDraft;
      return ListView(
        key: const Key('work-counter-draft-recovery'),
        padding: const EdgeInsets.all(16),
        children: [
          Text(
            widget.session.counterDraftError ?? 'Checking your saved bill…',
            style: const TextStyle(
              color: MoolColors.navy,
              fontWeight: FontWeight.w600,
            ),
          ),
          const SizedBox(height: 8),
          Align(
            alignment: Alignment.centerRight,
            child: FilledButton(
              key: const Key('work-counter-draft-retry'),
              style: FilledButton.styleFrom(minimumSize: const Size(48, 48)),
              onPressed: widget.session.counterDraftSubmitting
                  ? null
                  : () => _openDraft(retry: true),
              child: const Text('Try again'),
            ),
          ),
          if (draft != null) ...[
            const SizedBox(height: 12),
            Text(draft.customer),
            if (draft.submissionOrderId != null) Text(draft.submissionOrderId!),
            for (final line in draft.lines)
              ListTile(
                contentPadding: EdgeInsets.zero,
                title: Text('${line.name} · ${line.pack} × ${line.quantity}'),
                subtitle: Text(
                  '₹${_formatStoreAmount(line.lineTotalPaise ~/ 100)}.${(line.lineTotalPaise % 100).toString().padLeft(2, '0')}',
                ),
              ),
          ],
          if (widget.session.counterDraftCatalogueChanged)
            TextButton(
              key: const Key('work-counter-draft-discard'),
              onPressed: () async {
                final discard = await showDialog<bool>(
                  context: context,
                  builder: (context) => AlertDialog(
                    title: const Text('Discard saved bill?'),
                    content: const Text(
                      'No order will be cancelled. This removes only the unfinished bill.',
                    ),
                    actions: [
                      TextButton(
                        onPressed: () => Navigator.pop(context, false),
                        child: const Text('Keep bill'),
                      ),
                      FilledButton(
                        onPressed: () => Navigator.pop(context, true),
                        child: const Text('Discard'),
                      ),
                    ],
                  ),
                );
                if (discard == true &&
                    mounted &&
                    await widget.session.discardWorkspaceCounterDraft() &&
                    mounted) {
                  widget.session.startNewWorkspaceOrder();
                  await _openDraft();
                }
              },
              child: const Text('Discard bill'),
            ),
        ],
      );
    }
    if (_invoice != null && (_stage == 'invoice' || _stage == 'payment')) {
      return Column(
        children: [
          Expanded(
            child: _StoreInvoiceSurface(
              key: ValueKey(_invoice!.id),
              embedded: true,
              counterAppearance: true,
              session: widget.session,
              invoice: _invoice!,
              onClose: _nextSale,
              receiptEditor:
                  _stage == 'payment' &&
                      _collection != null &&
                      _invoiceAccount != null &&
                      _invoiceStore != null
                  ? _CustomerCollectionSheet(
                      key: _collectionKey,
                      session: widget.session,
                      payment: _collection!,
                      accountScope: _invoiceAccount!,
                      storeId: _invoiceStore!,
                      counterSaleReceipt: true,
                      onClose: () => setState(() {
                        widget.session.clearMessages();
                        _collection = null;
                        _stage = 'invoice';
                      }),
                    )
                  : null,
              onRecord: (payment) {
                setState(() {
                  _collection = payment;
                  _stage = 'payment';
                });
                WidgetsBinding.instance.addPostFrameCallback((_) {
                  final target = _collectionKey.currentContext;
                  if (!mounted ||
                      _stage != 'payment' ||
                      _collection != payment ||
                      target == null) {
                    return;
                  }
                  unawaited(
                    Scrollable.ensureVisible(
                      target,
                      alignment: 1,
                      duration: const Duration(milliseconds: 180),
                    ),
                  );
                });
              },
            ),
          ),
          if (_stage == 'invoice')
            Padding(
              padding: const EdgeInsets.fromLTRB(12, 8, 12, 12),
              child: SizedBox(
                width: double.infinity,
                child: FilledButton.icon(
                  key: const Key('work-sale-next'),
                  style: FilledButton.styleFrom(
                    minimumSize: const Size(0, 48),
                    padding: const EdgeInsets.symmetric(
                      horizontal: 16,
                      vertical: 12,
                    ),
                  ),
                  onPressed: _nextSale,
                  icon: const Icon(Icons.add),
                  label: const Text('New sale'),
                ),
              ),
            ),
        ],
      );
    }
    if (_stage == 'customer') {
      return Material(color: Colors.white, child: _customerPanel());
    }
    if (_stage == 'review') return _reviewPanel();
    final query = _productSearch.text.trim().toLowerCase();
    final searchTerms = query
        .split(RegExp(r'\s+'))
        .where((term) => term.isNotEmpty);
    final products = widget.session.workspaceCatalogueItems
        .where(
          (product) => searchTerms.every(
            (term) =>
                '${product.title} ${product.brand} ${product.variant} ${product.pack} ${product.sku} ${product.barcode}'
                    .toLowerCase()
                    .contains(term),
          ),
        )
        .toList(growable: false);
    final enteredName = widget.session.workspaceOrderBillingDetails.name.trim();
    final selectedCustomer = enteredName.isNotEmpty
        ? enteredName
        : _RecentCounterCustomer(
            _customer.text.trim(),
            widget.session.workspaceOrderBillingDetails,
          ).label;
    final mobile = _storedCounterCustomerMobile(_customer.text.trim());
    final customerName =
        selectedCustomer.replaceAll(RegExp(r'\D'), '') == mobile
        ? 'Customer'
        : selectedCustomer.split('·').first.trim();
    final customerControls = Container(
      key: const Key('work-sale-compact-controls'),
      padding: const EdgeInsets.symmetric(horizontal: 12),
      decoration: const BoxDecoration(
        border: Border(bottom: BorderSide(color: Color(0xFFE9EDF5))),
      ),
      child: SizedBox(
        width: double.infinity,
        child: TextButton(
          key: const Key('work-sale-customer'),
          onPressed: _editCustomer,
          style: TextButton.styleFrom(
            minimumSize: const Size(48, 48),
            padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 6),
            alignment: Alignment.centerLeft,
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                customerName.isEmpty ? 'Customer' : customerName,
                key: const Key('work-sale-customer-label'),
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                semanticsLabel: selectedCustomer,
                style: const TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w600,
                ),
              ),
              if (mobile != null)
                Text(
                  '+91 $mobile',
                  key: const Key('work-sale-customer-mobile'),
                  style: const TextStyle(fontSize: 12, color: MoolColors.muted),
                ),
            ],
          ),
        ),
      ),
    );
    final controls = Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
          child: Semantics(
            textField: true,
            label: 'Search store products',
            onTap: _productSearchFocus.requestFocus,
            child: StoreRecentSearches(
              controller: _productSearch,
              focusNode: _productSearchFocus,
              history: widget.session.workspaceRecentSearches(
                'counter-products',
              ),
              onChanged: (_) => setState(() {}),
              child: TextField(
                key: const Key('work-counter-product-search'),
                controller: _productSearch,
                focusNode: _productSearchFocus,
                onChanged: (_) => setState(() {}),
                onSubmitted: (_) => _productSearchFocus.unfocus(),
                textInputAction: TextInputAction.search,
                style: const TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w600,
                ),
                decoration: InputDecoration(
                  hintText: MediaQuery.textScalerOf(context).scale(13) > 17
                      ? 'Search'
                      : 'Search Store stock',
                  isDense: true,
                  filled: false,
                  prefixIcon: const Icon(Icons.search_rounded, size: 21),
                  border: InputBorder.none,
                  enabledBorder: InputBorder.none,
                  focusedBorder: InputBorder.none,
                  contentPadding: const EdgeInsets.symmetric(vertical: 12),
                  suffixIcon: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      if (query.isNotEmpty)
                        IconButton(
                          key: const Key('work-counter-search-clear'),
                          tooltip: 'Clear search',
                          icon: const Icon(Icons.clear),
                          onPressed: () {
                            setState(_productSearch.clear);
                            _productSearchFocus.requestFocus();
                          },
                        ),
                      IconButton(
                        key: const Key('work-counter-camera-scan'),
                        tooltip: 'Scan product',
                        onPressed: () {
                          _productSearchFocus.unfocus();
                          _scanProduct();
                        },
                        icon: const Icon(Icons.qr_code_scanner, size: 20),
                      ),
                      IconButton(
                        key: const Key('work-counter-usb-scan'),
                        tooltip: _usbScanMode
                            ? 'Stop attached scanner'
                            : 'Use attached scanner',
                        onPressed: _toggleUsbScanner,
                        isSelected: _usbScanMode,
                        icon: const Icon(Icons.barcode_reader, size: 20),
                      ),
                    ],
                  ),
                ),
              ),
            ),
          ),
        ),
        customerControls,
      ],
    );
    final hasStoreStock = widget.session.workspaceCatalogueItems.isNotEmpty;
    final emptyProducts = Center(
      child: SingleChildScrollView(
        padding: const EdgeInsets.all(12),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            if (!hasStoreStock) ...[
              const Icon(
                Icons.shopping_cart_outlined,
                size: 32,
                color: MoolColors.navy,
              ),
              const SizedBox(height: 8),
              const Text(
                'No stock yet',
                style: TextStyle(fontSize: 16, fontWeight: FontWeight.w700),
              ),
              const SizedBox(height: 4),
              const Text(
                'Add products to your Store to start billing.',
                textAlign: TextAlign.center,
                style: TextStyle(color: MoolColors.muted, fontSize: 13),
              ),
              const SizedBox(height: 8),
              OutlinedButton.icon(
                onPressed: widget.onOpenCatalogue,
                icon: const Icon(Icons.add_rounded),
                label: const Text('Add products'),
              ),
              const SizedBox(height: 8),
            ],
            if (hasStoreStock)
              Text(
                query.isNotEmpty
                    ? 'No products match your search'
                    : 'Add products to Store stock to start billing.',
                style: const TextStyle(color: MoolColors.muted, fontSize: 13),
                textAlign: TextAlign.center,
              ),
          ],
        ),
      ),
    );
    final errorText =
        widget.session.counterDraftError ??
        _error ??
        (widget.fullScreen ? widget.session.errorMessage : null);
    final error = errorText == null
        ? null
        : Padding(
            padding: const EdgeInsets.fromLTRB(16, 4, 16, 8),
            child: Semantics(
              liveRegion: true,
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    errorText,
                    key: const Key('work-order-error'),
                    style: const TextStyle(color: Color(0xFFB42318)),
                  ),
                  if (widget.session.counterDraftError != null)
                    TextButton(
                      key: const Key('work-counter-draft-save-retry'),
                      onPressed: _saving ? null : () => _openDraft(retry: true),
                      child: const Text('Try again'),
                    ),
                ],
              ),
            ),
          );
    final total = Container(
      key: const Key('work-sale-total-bar'),
      padding: const EdgeInsets.fromLTRB(16, 10, 16, 12),
      decoration: const BoxDecoration(
        gradient: _counterSalePaperGradient,
        border: Border(top: BorderSide(color: _counterSaleLine)),
      ),
      child: _StoreScaledPair(
        forceStack: widget.session.workspaceOrderTotal >= 10000000,
        first: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              '$_selectedUnits ${_selectedUnits == 1 ? 'unit' : 'units'}',
              style: const TextStyle(color: MoolColors.muted, fontSize: 12),
            ),
            _StoreMoneyText(
              widget.session.workspaceCounterDiscountError == null
                  ? '₹${_formatStoreMinorAmount(widget.session.workspaceCounterPayableMinor)}'
                  : 'Review discount',
              style: const TextStyle(
                color: MoolColors.navy,
                fontSize: 23,
                fontWeight: FontWeight.w800,
              ),
            ),
          ],
        ),
        second: FilledButton(
          key: const Key('work-order-review'),
          onPressed:
              _saving ||
                  widget.session.counterDraftSubmitting ||
                  _selectedUnits == 0
              ? null
              : validPhone
              ? _review
              : _editCustomer,
          style: FilledButton.styleFrom(
            minimumSize: const Size(48, 48),
            padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 12),
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(12),
            ),
          ),
          child: Text(
            _selectedUnits == 0
                ? 'Review bill'
                : validPhone
                ? 'Review bill'
                : 'Add customer',
            textAlign: TextAlign.center,
          ),
        ),
      ),
    );
    return Material(
      key: const Key('work-dashboard-counter-order-screen'),
      color: Colors.white,
      child: Focus(
        key: const Key('work-counter-scanner-listener'),
        focusNode: _barcodeFocus,
        skipTraversal: true,
        canRequestFocus: _usbScanMode,
        onFocusChange: (focused) {
          if (!focused) _clearScannerBuffer();
        },
        onKeyEvent: _handleScannerKey,
        child: LayoutBuilder(
          builder: (context, constraints) {
            // Keep the same editable/scroll subtree when the keyboard resizes
            // this surface. Replacing it detaches Search's native IME connection.
            final scaledLine = MediaQuery.textScalerOf(context).scale(14);
            final pinBillAction =
                hasStoreStock && constraints.maxHeight >= scaledLine * 5 + 100;
            final scroll = CustomScrollView(
              key: const Key('work-sale-short-scroll'),
              keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
              slivers: [
                SliverToBoxAdapter(child: controls),
                if (products.isEmpty)
                  SliverToBoxAdapter(child: emptyProducts)
                else
                  SliverPadding(
                    padding: const EdgeInsets.fromLTRB(16, 4, 16, 12),
                    sliver: SliverList(
                      key: const Key('work-sale-products'),
                      delegate: SliverChildBuilderDelegate(
                        (context, index) => index.isOdd
                            ? const Divider(height: 1, color: Color(0xFFE9EDF5))
                            : _SaleProductTile(
                                product: products[index ~/ 2],
                                session: widget.session,
                                onOpen: () =>
                                    _openProduct(products[index ~/ 2]),
                              ),
                        childCount: products.length * 2 - 1,
                      ),
                    ),
                  ),
                if (error != null) SliverToBoxAdapter(child: error),
                if (hasStoreStock && !pinBillAction)
                  SliverToBoxAdapter(child: total),
              ],
            );
            return Column(
              children: [
                Expanded(child: scroll),
                if (pinBillAction) total,
              ],
            );
          },
        ),
      ),
    );
  }
}

/// Keeps the next step visible while the form scrolls above the keyboard.
/// Very short windows retain one scroll surface instead of overflowing a footer.
class _StoreAmountWidth extends StatelessWidget {
  const _StoreAmountWidth({required this.controller, required this.child});
  final TextEditingController controller;
  final Widget child;

  @override
  Widget build(BuildContext context) => LayoutBuilder(
    builder: (context, constraints) => ValueListenableBuilder<TextEditingValue>(
      valueListenable: controller,
      child: child,
      builder: (context, value, field) {
        final scaler = MediaQuery.textScalerOf(context);
        final measure = TextPainter(
          text: TextSpan(text: '₹ ${value.text}',
              style: Theme.of(context).textTheme.bodyLarge),
          textDirection: Directionality.of(context), textScaler: scaler,
        )..layout();
        final preferred = measure.width + 56;
        final minimum = scaler.scale(220);
        final width = (preferred > minimum ? preferred : minimum)
            .clamp(0.0, constraints.maxWidth).toDouble();
        measure.dispose();
        return Align(alignment: Alignment.centerLeft,
            child: SizedBox(width: width, child: field));
      },
    ),
  );
}

class _StoreFormLayout extends StatelessWidget {
  const _StoreFormLayout({
    required this.child,
    required this.action,
    this.scrollKey,
    this.compact = false,
    this.padding = const EdgeInsets.all(16),
  });

  final Widget child, action;
  final Key? scrollKey;
  final bool compact;
  final EdgeInsets padding;

  @override
  Widget build(BuildContext context) => LayoutBuilder(
    builder: (context, constraints) {
      final footer = Padding(
        padding: const EdgeInsets.fromLTRB(16, 8, 16, 12),
        child: SizedBox(width: double.infinity, child: action),
      );
      if (!constraints.hasBoundedHeight || constraints.maxHeight < 180) {
        return SingleChildScrollView(
          key: scrollKey,
          keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Padding(padding: padding, child: child),
              footer,
            ],
          ),
        );
      }
      return Column(
        mainAxisSize: compact ? MainAxisSize.min : MainAxisSize.max,
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Flexible(
            fit: compact ? FlexFit.loose : FlexFit.tight,
            child: SingleChildScrollView(
              key: scrollKey,
              keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
              padding: padding,
              child: child,
            ),
          ),
          footer,
        ],
      );
    },
  );
}

class _RecentCounterCustomer {
  const _RecentCounterCustomer(this.customer, this.billingDetails);
  final String customer;
  final WorkspaceBillingDetails billingDetails;
  String? get mobile => _storedCounterCustomerMobile(customer);
  String get label =>
      billingDetails.business && billingDetails.businessName.trim().isNotEmpty
      ? billingDetails.businessName.trim()
      : billingDetails.name.trim().isNotEmpty
      ? billingDetails.name.trim()
      : customer;
}

class _StoreSaleCustomerSheet extends StatefulWidget {
  const _StoreSaleCustomerSheet({
    super.key,
    required this.initialValue,
    required this.recentCustomers,
    this.onDraftChanged,
    this.onConfirmed,
    this.onClose,
    this.billingDetails = const WorkspaceBillingDetails(),
    this.billingCustomer = '',
    this.onBillingChanged,
  });
  final ValueChanged<String>? onConfirmed;
  final VoidCallback? onClose;
  final WorkspaceBillingDetails billingDetails;
  final String billingCustomer;
  final void Function(WorkspaceBillingDetails, String?)? onBillingChanged;
  final String initialValue;
  final List<_RecentCounterCustomer> recentCustomers;
  final ValueChanged<String>? onDraftChanged;

  @override
  State<_StoreSaleCustomerSheet> createState() =>
      _StoreSaleCustomerSheetState();
}

class _StoreSaleCustomerSheetState extends State<_StoreSaleCustomerSheet> {
  late final _controller = TextEditingController(text: widget.initialValue);
  bool get _enteredCountryPrefix {
    final value = _controller.text.trimLeft();
    return value.startsWith('+') ||
        (normalizeWorkspaceMobile(value) != null &&
            value.replaceAll(RegExp(r'[ +\-]'), '').length == 12);
  }

  late bool _showMobilePrefix = !_enteredCountryPrefix;
  String? _error;
  late bool _business = widget.billingDetails.business;
  late bool _businessExpanded = widget.billingDetails.business;
  late final _name = TextEditingController(text: widget.billingDetails.name);
  late final _businessName = TextEditingController(
    text: widget.billingDetails.businessName,
  );
  late final _gst = TextEditingController(text: widget.billingDetails.gst);
  late final _billingAddress = TextEditingController(
    text: widget.billingDetails.address,
  );
  bool _applyingRecent = false;
  late String? _billingMobile =
      normalizeWorkspaceMobile(widget.billingCustomer) ??
      _storedCounterCustomerMobile(widget.initialValue);
  final _customerDrafts = <String, (WorkspaceBillingDetails, bool)>{};

  WorkspaceBillingDetails get _currentBilling => WorkspaceBillingDetails(
    business: _business,
    name: _name.text,
    businessName: _businessName.text,
    gst: _gst.text,
    address: _billingAddress.text,
  );

  void _cacheBilling() {
    if (_billingMobile case final mobile?) {
      _customerDrafts[mobile] = (_currentBilling, _businessExpanded);
    }
  }

  void _applyBilling(WorkspaceBillingDetails details, bool expanded) {
    _applyingRecent = true;
    _name.text = details.name;
    _businessName.text = details.businessName;
    _gst.text = details.gst;
    _billingAddress.text = details.address;
    _business = details.business;
    _businessExpanded = expanded;
    _applyingRecent = false;
  }

  void _switchBillingTo(String next) {
    if (next == _billingMobile) return;
    _cacheBilling();
    final hadOwner = _billingMobile != null;
    _billingMobile = next;
    final saved = _customerDrafts[next];
    if (hadOwner || saved != null) {
      setState(
        () => _applyBilling(
          saved?.$1 ?? const WorkspaceBillingDetails(),
          saved?.$2 ?? false,
        ),
      );
    }
    _rememberBilling();
  }

  void _rememberBilling() {
    if (_applyingRecent) return;
    _cacheBilling();
    widget.onBillingChanged?.call(_currentBilling, _billingMobile);
  }

  void _selectRecent(_RecentCounterCustomer customer) {
    final mobile = customer.mobile;
    if (mobile == null) return;
    final details = customer.billingDetails;
    _cacheBilling();
    _billingMobile = mobile;
    _applyingRecent = true;
    _controller.text = mobile;
    _name.text = details.name;
    _businessName.text = details.businessName;
    _gst.text = details.gst;
    _billingAddress.text = details.address;
    _business = details.business;
    _businessExpanded = details.business;
    _lastDraft = mobile;
    _applyingRecent = false;
    widget.onDraftChanged?.call(mobile);
    _rememberBilling();
    _confirm();
  }

  void _complete(String value) {
    if (widget.onConfirmed != null) {
      widget.onConfirmed!(value);
    } else {
      Navigator.pop(context, value);
    }
  }

  late String _lastDraft = widget.initialValue;

  @override
  void initState() {
    super.initState();
    for (final controller in [_name, _businessName, _gst, _billingAddress]) {
      controller.addListener(_rememberBilling);
    }
    _controller.addListener(() {
      final showPrefix = !_enteredCountryPrefix;
      if (_showMobilePrefix != showPrefix) {
        // Keep the actual editing value, selection and IME connection intact.
        setState(() => _showMobilePrefix = showPrefix);
      }
      if (_applyingRecent) return;
      if (_error != null &&
          normalizeWorkspaceMobile(_controller.text) != null) {
        setState(() => _error = null);
      }
      if (_lastDraft != _controller.text) {
        final next = normalizeWorkspaceMobile(_controller.text);
        if (next != null && next != _billingMobile) {
          // A partially typed number is not a customer switch. A different
          // complete number must never inherit another customer's billing facts.
          _switchBillingTo(next);
        } else if (next == null && _billingMobile != null) {
          // Bind legacy valid drafts before saving their first partial edit.
          _rememberBilling();
        }
        _lastDraft = _controller.text;
        widget.onDraftChanged?.call(_lastDraft);
      }
    });
  }

  @override
  void dispose() {
    _controller.dispose();
    for (final controller in [_name, _businessName, _gst, _billingAddress]) {
      controller.dispose();
    }
    super.dispose();
  }

  void _confirm() {
    final value = normalizeWorkspaceMobile(_controller.text);
    if (value == null) {
      setState(() => _error = 'Enter a valid 10-digit customer mobile number.');
      return;
    }
    _switchBillingTo(value);
    FocusManager.instance.primaryFocus?.unfocus();
    _complete(value);
  }

  @override
  Widget build(BuildContext context) {
    final media = MediaQuery.of(context);
    return Padding(
      padding: EdgeInsets.only(
        bottom: widget.onConfirmed == null ? media.viewInsets.bottom : 0,
      ),
      child: SafeArea(
        top: false,
        child: ConstrainedBox(
          constraints: BoxConstraints(
            maxHeight: widget.onConfirmed == null
                ? (media.size.height - media.viewInsets.bottom) * .8
                : double.infinity,
          ),
          child: _StoreFormLayout(
            scrollKey: const Key('work-sale-customer-sheet'),
            padding: const EdgeInsets.fromLTRB(16, 4, 16, 12),
            action: FilledButton(
              key: const Key('work-sale-customer-confirm'),
              onPressed: _confirm,
              style: FilledButton.styleFrom(
                minimumSize: const Size(48, 48),
                padding: const EdgeInsets.symmetric(
                  horizontal: 16,
                  vertical: 12,
                ),
              ),
              child: Text(
                widget.onConfirmed == null
                    ? 'Use customer'
                    : 'Add items to bill',
              ),
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Row(
                  children: [
                    const Expanded(
                      child: Text(
                        'Customer details',
                        key: Key('work-sale-customer-title'),
                        style: TextStyle(
                          color: MoolColors.navy,
                          fontSize: 18,
                          fontWeight: FontWeight.w800,
                        ),
                      ),
                    ),
                    if (widget.onConfirmed == null)
                      IconButton(
                        key: const Key('work-sale-customer-close'),
                        tooltip: 'Close',
                        onPressed:
                            widget.onClose ?? () => Navigator.pop(context),
                        icon: const Icon(Icons.close_rounded, size: 20),
                      ),
                  ],
                ),
                const SizedBox(height: 12),
                _AccessibleWorkTextField(
                  keyName: 'work-sale-customer-name',
                  compact: true,
                  controller: _name,
                  label: 'Customer name',
                  textInputAction: TextInputAction.next,
                ),
                const SizedBox(height: 12),
                _AccessibleWorkTextField(
                  keyName: 'work-order-customer',
                  compact: true,
                  controller: _controller,
                  label: 'Mobile number',
                  stackedLabel: media.textScaler.scale(14) > 21,
                  keyboardType: TextInputType.phone,
                  textInputAction: TextInputAction.done,
                  prefixIcon: _showMobilePrefix
                      ? const Padding(
                          padding: EdgeInsets.symmetric(horizontal: 12),
                          child: Center(widthFactor: 1, child: Text('+91')),
                        )
                      : null,
                ),
                if (_error != null)
                  Semantics(
                    liveRegion: true,
                    child: Text(
                      _error!,
                      key: const Key('work-sale-customer-error'),
                      style: const TextStyle(color: Color(0xFFB42318)),
                    ),
                  ),
                Align(
                  alignment: Alignment.centerLeft,
                  child: TextButton.icon(
                    key: const Key('work-sale-business-details'),
                    style: TextButton.styleFrom(
                      foregroundColor: MoolColors.navy,
                      padding: EdgeInsets.zero,
                      minimumSize: const Size(48, 48),
                    ),
                    label: const Text('Business details (optional)'),
                    onPressed: () {
                      setState(() {
                        _businessExpanded = !_businessExpanded;
                        if (_businessExpanded) _business = true;
                      });
                      _rememberBilling();
                    },
                    icon: Icon(_businessExpanded ? Icons.remove : Icons.add),
                  ),
                ),
                if (_businessExpanded) ...[
                  _AccessibleWorkTextField(
                    keyName: 'work-sale-business-name',
                    compact: true,
                    controller: _businessName,
                    label: 'Business name',
                  ),
                  const SizedBox(height: 8),
                  _AccessibleWorkTextField(
                    keyName: 'work-sale-business-gst',
                    compact: true,
                    controller: _gst,
                    label: 'GST',
                  ),
                  const SizedBox(height: 8),
                  _AccessibleWorkTextField(
                    keyName: 'work-sale-billing-address',
                    compact: true,
                    controller: _billingAddress,
                    label: 'Billing address',
                  ),
                  const SizedBox(height: 8),
                ],
                const Text(
                  'Home delivery? Share your Store link through WhatsApp or MoolSocial Chat.',
                  style: TextStyle(color: MoolColors.muted, fontSize: 12),
                ),
                if (widget.recentCustomers.isNotEmpty) ...[
                  const SizedBox(height: 14),
                  const Text(
                    'Recent customers',
                    style: TextStyle(color: MoolColors.muted, fontSize: 12),
                  ),
                  for (final customer in widget.recentCustomers)
                    ListTile(
                      contentPadding: EdgeInsets.zero,
                      leading: const Icon(Icons.history_rounded, size: 20),
                      title: Text(
                        customer.label,
                        style: const TextStyle(fontSize: 14),
                      ),
                      subtitle:
                          customer.mobile == null ||
                              customer.label
                                  .replaceAll(RegExp(r'\D'), '')
                                  .endsWith(customer.mobile!)
                          ? null
                          : Text(customer.mobile!),
                      onTap: () => _selectRecent(customer),
                    ),
                ],
              ],
            ),
          ),
        ),
      ),
    );
  }
}

class _SaleProductTile extends StatelessWidget {
  const _SaleProductTile({
    required this.product,
    required this.session,
    required this.onOpen,
  });
  final WorkspaceCatalogueItem product;
  final WorkSession session;
  final VoidCallback onOpen;

  void _adjustQuantity(int change) {
    final before = session.workspaceOrderQuantities[product.id] ?? 0;
    session.adjustWorkspaceOrderQuantity(product.id, change);
    final after = session.workspaceOrderQuantities[product.id] ?? 0;
    // Confirm a real selection change, never a rejected or disabled action.
    if (after != before) unawaited(HapticFeedback.selectionClick());
  }

  @override
  Widget build(BuildContext context) {
    final quantity = session.workspaceOrderQuantities[product.id] ?? 0;
    final facts = Text(
      '${product.pack} · ${!product.available
          ? 'Unavailable'
          : product.stockMode == WorkspaceStockMode.availabilityOnly
          ? 'Available'
          : '${product.stock} in stock'}',
      style: const TextStyle(
        color: MoolColors.muted,
        fontSize: 12,
        height: 1.3,
      ),
    );
    final price = '₹${_formatStoreAmount(product.sellingPrice)}';
    const priceStyle = TextStyle(
      color: MoolColors.navy,
      fontSize: 15,
      fontWeight: FontWeight.w800,
    );
    Widget identity({bool includePrice = false}) => InkWell(
      key: Key('work-sale-product-open-${product.id}'),
      onTap: onOpen,
      child: ConstrainedBox(
        constraints: const BoxConstraints(minHeight: 48),
        child: Row(
          children: [
            StoreProductThumbnail(
              product: product,
              extent: 36,
              session: session,
            ),
            const SizedBox(width: 6),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(
                    product.title,
                    style: const TextStyle(
                      color: MoolColors.ink,
                      fontSize: 14,
                      height: 1.25,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                  facts,
                  if (includePrice) _StoreMoneyText(price, style: priceStyle),
                ],
              ),
            ),
          ],
        ),
      ),
    );
    final quantityControls = Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        IconButton(
          key: Key('work-order-reduce-${product.id}'),
          tooltip: 'Reduce ${product.title}',
          constraints: const BoxConstraints(minWidth: 48, minHeight: 48),
          onPressed: quantity == 0 ? null : () => _adjustQuantity(-1),
          icon: const Icon(Icons.remove_rounded, size: 20),
        ),
        ConstrainedBox(
          constraints: const BoxConstraints(minWidth: 26),
          child: Semantics(
            liveRegion: false,
            label: '${product.title}, $quantity selected',
            child: Text(
              '$quantity',
              softWrap: false,
              textAlign: TextAlign.center,
              style: const TextStyle(
                color: MoolColors.navy,
                fontWeight: FontWeight.w800,
              ),
            ),
          ),
        ),
        IconButton(
          key: Key('work-order-add-${product.id}'),
          tooltip: 'Add ${product.title} to bill',
          constraints: const BoxConstraints(minWidth: 48, minHeight: 48),
          onPressed:
              product.canSellAtCounter &&
                  (product.stockMode == WorkspaceStockMode.availabilityOnly
                      ? quantity < 99
                      : product.stock > quantity)
              ? () => _adjustQuantity(1)
              : null,
          style: IconButton.styleFrom(
            disabledForegroundColor: const Color(0xFF68758A),
            disabledBackgroundColor: const Color(0xFFE6EAF1),
            foregroundColor: _counterSalePrimary,
            backgroundColor: _counterSaleTint,
          ),
          icon: const Icon(Icons.add_rounded, size: 20),
        ),
      ],
    );
    return Container(
      key: Key('work-sale-product-${product.id}'),
      padding: const EdgeInsets.symmetric(vertical: 4),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(10),
      ),
      child: LayoutBuilder(
        builder: (context, constraints) {
          // Keep full names and amounts readable rather than shrinking text.
          // Enlarged text and unusually wide amounts use the full row width.
          final stacked =
              MediaQuery.textScalerOf(context).scale(14) > 18.2 ||
              constraints.maxWidth < 300 ||
              price.length > 11;
          if (stacked) {
            return Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                _StoreMoneyLine(
                  leading: identity(),
                  value: price,
                  style: priceStyle,
                ),
                Align(
                  alignment: Alignment.centerRight,
                  child: quantityControls,
                ),
              ],
            );
          }
          return Row(
            children: [
              Expanded(child: identity(includePrice: true)),
              const SizedBox(width: 6),
              quantityControls,
            ],
          );
        },
      ),
    );
  }
}

class _CounterStoreProductPage extends StatefulWidget {
  const _CounterStoreProductPage({
    required this.session,
    required this.productId,
    required this.isCurrent,
  });
  final WorkSession session;
  final String productId;
  final bool Function() isCurrent;
  @override
  State<_CounterStoreProductPage> createState() =>
      _CounterStoreProductPageState();
}

class _CounterStoreProductPageState extends State<_CounterStoreProductPage> {
  String? error;
  @override
  Widget build(BuildContext context) => AnimatedBuilder(
    animation: widget.session,
    builder: (context, _) {
      final product = widget.session.workspaceCatalogueItems
          .where((p) => p.id == widget.productId)
          .firstOrNull;
      final current = widget.isCurrent();
      final quantity =
          widget.session.workspaceOrderQuantities[widget.productId] ?? 0;
      final canAdd =
          current &&
          product != null &&
          product.canSellAtCounter &&
          (product.stockMode == WorkspaceStockMode.availabilityOnly
              ? quantity < 99
              : quantity < product.stock);
      return Scaffold(
        key: const Key('work-counter-store-product-page'),
        backgroundColor: Colors.white,
        appBar: AppBar(
          title: const Text('Product details', style: TextStyle(fontSize: 18)),
          flexibleSpace: const SizedBox.expand(
            child: DecoratedBox(
              decoration: BoxDecoration(gradient: _counterSaleHeaderGradient),
            ),
          ),
        ),
        body: SafeArea(
          child: ListView(
            padding: const EdgeInsets.all(16),
            children: [
              if (!current)
                const Text(
                  'This sale has changed. Return to Counter Sale to continue.',
                )
              else if (product == null)
                const Text('This product is no longer in your store catalogue.')
              else ...[
                Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  StoreProductThumbnail(key: const Key('work-counter-details-photo'),
                    product: product, session: widget.session, extent: 64),
                  const SizedBox(width: 12),
                  Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                    if (product.brand.trim().isNotEmpty)
                      Text(product.brand, style: const TextStyle(fontSize: 12, color: MoolColors.muted)),
                    Text(product.title, style: const TextStyle(fontSize: 18,
                      fontWeight: FontWeight.w700, color: MoolColors.navy)),
                    Text([product.variant, product.pack].where((value) => value.trim().isNotEmpty).join(' · '),
                      style: const TextStyle(fontSize: 13, color: MoolColors.muted)),
                  ])),
                ]),
                const SizedBox(height: 12),
                Text(
                  '₹${_formatStoreAmount(product.sellingPrice)}',
                  style: const TextStyle(
                    color: MoolColors.navy,
                    fontSize: 20,
                    fontWeight: FontWeight.w800,
                  ),
                ),
                if (product.unitPrice.trim().isNotEmpty) Text(product.unitPrice),
                if (product.mrp != null)
                  Text('MRP ₹${_formatStoreAmount(product.mrp!)}'),
                const Divider(height: 20),
                _ProductPreviewLine(label: 'In this bill', value: '$quantity'),
                _ProductPreviewLine(
                  label: 'Availability',
                  value: !product.canSellAtCounter
                      ? 'Unavailable'
                      : product.stockMode == WorkspaceStockMode.availabilityOnly
                      ? 'Available'
                      : '${product.stock} in stock',
                ),
                if (product.sku.trim().isNotEmpty)
                  _ProductPreviewLine(label: 'Product code', value: product.sku),
                if (product.barcode.trim().isNotEmpty) ...[
                const SizedBox(height: 8),
                const Text(
                  'Barcode',
                  style: TextStyle(color: MoolColors.muted, fontSize: 14),
                ),
                Text(
                  product.barcode,
                  key: const Key('work-counter-product-barcode'),
                  style: const TextStyle(
                    color: MoolColors.navy,
                    fontSize: 14,
                    fontWeight: FontWeight.w700,
                  ),
                ),
                ],
                if (product.origin.trim().isNotEmpty) ...[
                const SizedBox(height: 8),
                _ProductPreviewLine(
                  label: 'Country of origin',
                  value: product.origin,
                ),
                ],
                if (product.composition?.isNotEmpty == true) ...[
                  const SizedBox(height: 16),
                  Text(product.composition!),
                ],
                if (product.returnPolicy?.isNotEmpty == true) ...[
                  const SizedBox(height: 16),
                  Text(product.returnPolicy!),
                ],
              ],
              if (error != null)
                Text(error!, style: const TextStyle(color: Color(0xFFB42318))),
            ],
          ),
        ),
        bottomNavigationBar: SafeArea(
          minimum: const EdgeInsets.all(16),
          child: FilledButton.icon(
            key: const Key('work-counter-product-add-confirm'),
            icon: const Icon(Icons.add_shopping_cart),
            label: const Text('Add to bill'),
            onPressed: !canAdd
                ? null
                : () {
                    if (!widget.isCurrent()) return;
                    widget.session.adjustWorkspaceOrderQuantity(
                      widget.productId,
                      1,
                    );
                    if ((widget.session.workspaceOrderQuantities[widget
                                .productId] ??
                            0) ==
                        quantity + 1) {
                      Navigator.of(context).pop();
                    } else {
                      setState(
                        () => error =
                            widget.session.errorMessage ??
                            'Could not add this product. Check availability and try again.',
                      );
                    }
                  },
          ),
        ),
      );
    },
  );
}

