class _CounterBillDiscountEditor extends StatefulWidget {
  const _CounterBillDiscountEditor({
    super.key,
    required this.subtotalMinor,
    required this.initial,
    required this.onApply,
    required this.onInvalid,
    required this.enabled,
  });
  final int subtotalMinor;
  final WorkspaceBillDiscount initial;
  final ValueChanged<WorkspaceBillDiscount> onApply;
  final VoidCallback onInvalid;
  final bool enabled;
  @override
  State<_CounterBillDiscountEditor> createState() =>
      _CounterBillDiscountEditorState();
}

class _CounterBillDiscountEditorState
    extends State<_CounterBillDiscountEditor> {
  final _errorAnchor = GlobalKey();
  late String kind = widget.initial.isEmpty
      ? 'percentage'
      : widget.initial.kind;
  late final input = TextEditingController(
    text: widget.initial.isEmpty
        ? ''
        : '${widget.initial.value ~/ 100}.${(widget.initial.value % 100).toString().padLeft(2, '0')}',
  );
  String? error;
  void _revealError() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      final target = _errorAnchor.currentContext;
      if (!mounted || error == null || target == null) return;
      Scrollable.ensureVisible(target, alignment: 1);
    });
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    // Repeat after a keyboard/text-scale resize without replacing the input.
    if (error != null) _revealError();
  }

  @override
  void dispose() {
    input.dispose();
    super.dispose();
  }

  void applyInput() {
    if (!widget.enabled) return;
    WorkspaceBillDiscount? discount;
    try {
      final text = input.text.trim();
      discount = text.isEmpty || RegExp(r'^0+(\.0{1,2})?$').hasMatch(text)
          ? const WorkspaceBillDiscount.none()
          : WorkspaceBillDiscount.parse(kind, text);
      if (!discount.isEmpty && !discount.validFor(widget.subtotalMinor)) {
        discount = null;
      }
    } on FormatException {
      discount = null;
    }
    setState(
      () => error = discount == null
          ? kind == 'percentage'
                ? 'Enter a percentage from 0 to less than 100.'
                : 'Enter an amount from 0 to less than the subtotal.'
          : null,
    );
    if (discount == null) {
      widget.onInvalid();
      _revealError();
    } else {
      widget.onApply(discount);
    }
  }

  Widget _applyButton() => TextButton(
    key: const Key('work-counter-discount-apply'),
    style: TextButton.styleFrom(
      minimumSize: const Size(48, 48),
      padding: const EdgeInsets.symmetric(horizontal: 8),
    ),
    onPressed: !widget.enabled
        ? null
        : () {
            applyInput();
            if (error == null) FocusScope.of(context).unfocus();
          },
    child: const Text('Apply'),
  );

  @override
  Widget build(BuildContext context) => Column(
    key: const Key('work-counter-discount-inline'),
    crossAxisAlignment: CrossAxisAlignment.stretch,
    mainAxisSize: MainAxisSize.min,
    children: [
      const Text(
        'Bill discount',
        key: Key('work-counter-discount-label'),
        style: TextStyle(fontSize: 12, fontWeight: FontWeight.w600),
      ),
      LayoutBuilder(
        builder: (context, constraints) {
          // Subscribe to keyboard changes as well as text scale. Otherwise the
          // error anchor is not revealed again when the viewport shrinks.
          MediaQuery.viewInsetsOf(context);
          if (error != null) _revealError();
          final field = TextField(
            key: const Key('work-counter-discount-value'),
            controller: input,
            enabled: widget.enabled,
            scrollPadding: EdgeInsets.fromLTRB(
              20,
              24,
              20,
              MediaQuery.textScalerOf(context).scale(12) * 3 + 24,
            ),
            keyboardType: const TextInputType.numberWithOptions(decimal: true),
            textInputAction: TextInputAction.done,
            onSubmitted: (_) {
              applyInput();
              if (error == null) FocusScope.of(context).unfocus();
            },
            onChanged: (_) {
              setState(() => error = null);
              widget.onInvalid();
            },
            decoration: InputDecoration(
              hintText: '0.00',
              prefixText: kind == 'fixed' ? '₹ ' : null,
              suffixText: kind == 'percentage' ? '%' : null,
              border: InputBorder.none,
              enabledBorder: InputBorder.none,
              focusedBorder: InputBorder.none,
              disabledBorder: InputBorder.none,
              errorBorder: InputBorder.none,
              focusedErrorBorder: InputBorder.none,
              error: error == null
                  ? null
                  : Semantics(
                      key: _errorAnchor,
                      liveRegion: true,
                      child: Text(
                        error!,
                        key: const Key('work-counter-discount-input-error'),
                        style: const TextStyle(
                          color: Color(0xFFB42318),
                          fontSize: 12,
                        ),
                      ),
                    ),
              filled: false,
              isDense: true,
              contentPadding: const EdgeInsets.symmetric(
                horizontal: 4,
                vertical: 10,
              ),
            ),
          );
          final modes = Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              for (final mode in ['percentage', 'fixed'])
                Padding(
                  padding: const EdgeInsets.only(left: 2),
                  child: ChoiceChip(
                    key: Key('work-counter-discount-$mode'),
                    label: Text(mode == 'percentage' ? '%' : 'Amt'),
                    labelPadding: const EdgeInsets.symmetric(horizontal: 2),
                    padding: EdgeInsets.zero,
                    showCheckmark: false,
                    selectedColor: const Color(0xffedf0f4),
                    backgroundColor: Colors.white,
                    side: BorderSide.none,
                    labelStyle: TextStyle(
                      color: MoolColors.navy,
                      fontWeight: kind == mode
                          ? FontWeight.w700
                          : FontWeight.w400,
                    ),
                    tooltip: mode == 'percentage'
                        ? 'Percentage discount'
                        : 'Amount discount',
                    selected: kind == mode,
                    onSelected: !widget.enabled
                        ? null
                        : (_) {
                            setState(() {
                              kind = mode;
                              error = null;
                            });
                            widget.onInvalid();
                          },
                  ),
                ),
            ],
          );
          final textScale = MediaQuery.textScalerOf(context).scale(14) / 14;
          // Large text needs stacking on narrow phones, not on a wide counter.
          // Reserve scaled space for both modes, a readable value and Apply.
          final expandedInput =
              error != null ||
              (textScale > 20 / 14 && constraints.maxWidth < 360 * textScale);
          if (!expandedInput && constraints.maxWidth >= 260) {
            return Row(
              children: [
                modes,
                const SizedBox(width: 6),
                Expanded(
                  child: Semantics(label: 'Discount value', child: field),
                ),
                _applyButton(),
              ],
            );
          }
          return Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Align(alignment: Alignment.centerLeft, child: modes),
              Row(
                children: [
                  Expanded(
                    child: Semantics(label: 'Discount value', child: field),
                  ),
                  if (MediaQuery.textScalerOf(context).scale(14) <= 20) ...[
                    const SizedBox(width: 12),
                    _applyButton(),
                  ],
                ],
              ),
              if (MediaQuery.textScalerOf(context).scale(14) > 20)
                Align(alignment: Alignment.centerRight, child: _applyButton()),
            ],
          );
        },
      ),
      const SizedBox(height: 6),
    ],
  );
}

class _CounterUpiPanel extends StatefulWidget {
  const _CounterUpiPanel({
    super.key,
    required this.session,
    required this.amountPaise,
    required this.reference,
    required this.viewportHeight,
  });
  final WorkSession session;
  final int amountPaise;
  final String? reference;
  final double viewportHeight;

  @override
  State<_CounterUpiPanel> createState() => _CounterUpiPanelState();
}

class _CounterUpiPanelState extends State<_CounterUpiPanel> {
  final _paymentDetailsKey = GlobalKey();
  static const _verificationMessage =
      'Payment unverified. Automatic check unavailable.';
  static const _amountStyle = TextStyle(
    fontSize: 24,
    fontWeight: FontWeight.w800,
  );
  late final _scope = widget.session.storeUpiScope;
  WorkspaceUpiDestination? _destination;
  bool _loading = true;
  String? _error;

  bool get _current =>
      mounted && _scope != null && _scope == widget.session.storeUpiScope;

  @override
  void initState() {
    super.initState();
    unawaited(_load());
  }

  @override
  void didUpdateWidget(covariant _CounterUpiPanel oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.amountPaise != widget.amountPaise ||
        oldWidget.viewportHeight != widget.viewportHeight) {
      _revealPayment();
    }
  }

  void _revealPayment() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      final target = _paymentDetailsKey.currentContext;
      if (!_current || _loading || target == null) return;
      unawaited(
        Scrollable.ensureVisible(
          target,
          alignment: 0,
          duration: const Duration(milliseconds: 180),
        ),
      );
    });
  }

  String get _amountLabel =>
      '₹${_formatStoreAmount(widget.amountPaise ~/ 100)}.${(widget.amountPaise % 100).toString().padLeft(2, '0')}';

  double _qrSize(BuildContext context, double width) {
    final baseStyle = DefaultTextStyle.of(context).style;
    double height(String text, [TextStyle? style]) {
      final painter = TextPainter(
        text: TextSpan(text: text, style: baseStyle.merge(style)),
        textDirection: Directionality.of(context),
        textScaler: MediaQuery.textScalerOf(context),
      )..layout(maxWidth: width);
      final value = painter.height;
      painter.dispose();
      return value;
    }

    final textHeight =
        height(
          _destination!.payeeName,
          const TextStyle(fontWeight: FontWeight.w700),
        ) +
        height(_destination!.address) +
        height(_amountLabel, _amountStyle) +
        height(_verificationMessage);
    // Keep the cart-first allocation. Never shrink text or clip truthful status;
    // exceptionally small/enlarged-text viewports retain scrolling as fallback.
    return (widget.viewportHeight - textHeight - 10).clamp(112.0, 224.0);
  }

  Future<void> _load() async {
    if (!_current) {
      if (mounted) setState(() => _loading = false);
      return;
    }
    setState(() {
      _loading = true;
      _error = null;
      _destination = null;
    });
    try {
      final destination = await widget.session.loadStoreUpiDestination(_scope!);
      if (!_current) return;
      setState(() {
        _destination = destination;
      });
    } on Object {
      if (_current) {
        setState(() => _error = 'Could not load Store UPI details. Try again.');
      }
    } finally {
      if (mounted) setState(() => _loading = false);
      _revealPayment();
    }
  }

  @override
  Widget build(BuildContext context) {
    if (!_current) {
      return const Text(
        'Return to your Store to view its registered UPI ID.',
        key: Key('work-sale-payment-request-unavailable'),
      );
    }
    if (_loading) {
      return const Padding(
        padding: EdgeInsets.all(12),
        child: Text('Loading Store UPI details…'),
      );
    }
    Uri? uri;
    if (_destination != null && widget.reference != null) {
      try {
        uri = _destination!.paymentUri(
          expectedAccount: _scope!.account,
          expectedStore: _scope!.store,
          amountPaise: widget.amountPaise,
          reference: widget.reference!,
        );
      } on FormatException {
        // No fallback payee, amount, or invented transaction reference.
      }
    }
    return Padding(
      padding: const EdgeInsets.only(top: 12),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          if (_error != null) ...[
            Semantics(
              liveRegion: true,
              child: Text(_error!, key: const Key('work-sale-upi-error')),
            ),
          ],
          if (_destination == null) ...[
            const Text(
              'No registered Store UPI ID is available. Choose Cash or Bank Transfer.',
              key: Key('work-sale-payment-request-unavailable'),
            ),
          ] else
            LayoutBuilder(
              builder: (context, constraints) {
                final qrSize = _qrSize(context, constraints.maxWidth);
                return Column(
                  key: _paymentDetailsKey,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text(
                      _destination!.payeeName,
                      style: const TextStyle(fontWeight: FontWeight.w700),
                    ),
                    SelectableText(
                      _destination!.address,
                      key: const Key('work-sale-upi-registered-address'),
                    ),
                    if (uri != null) ...[
                      const SizedBox(height: 4),
                      Center(
                        child: _StoreMoneyText(
                          _amountLabel,
                          key: const Key('work-sale-upi-amount'),
                          style: _amountStyle,
                        ),
                      ),
                      const SizedBox(height: 4),
                      Center(
                        child: Semantics(
                          label: 'Scan to pay this Store by UPI',
                          image: true,
                          child: CustomPaint(
                            key: const Key('work-sale-upi-qr'),
                            size: Size(qrSize, qrSize),
                            painter: _StoreUpiQrPainter(uri.toString()),
                          ),
                        ),
                      ),
                      const Text(
                        _verificationMessage,
                        key: Key('work-sale-upi-verification-unavailable'),
                      ),
                    ] else
                      const Text(
                        'Save the bill details before showing its payment QR.',
                        key: Key('work-sale-payment-request-unavailable'),
                      ),
                  ],
                );
              },
            ),
          Align(
            alignment: Alignment.centerLeft,
            child: TextButton.icon(
              key: const Key('work-sale-upi-refresh'),
              onPressed: _load,
              icon: const Icon(Icons.refresh, size: 18),
              label: const Text('Refresh Store UPI'),
            ),
          ),
        ],
      ),
    );
  }
}

class _StoreUpiQrPainter extends CustomPainter {
  _StoreUpiQrPainter(this.data);
  final String data;

  @override
  void paint(Canvas canvas, Size size) {
    canvas.drawRect(Offset.zero & size, Paint()..color = Colors.white);
    // Generous white quiet zone; never stretch or decorate the encoded modules.
    final side = (size.shortestSide - 40).clamp(1.0, double.infinity);
    final offset = Offset((size.width - side) / 2, (size.height - side) / 2);
    final ink = Paint()
      ..color = Colors.black
      ..isAntiAlias = false;
    for (final element in store_qr.Barcode.qrCode().make(
      data,
      width: side,
      height: side,
    )) {
      if (element is store_qr.BarcodeBar && element.black) {
        canvas.drawRect(
          Rect.fromLTWH(
            offset.dx + element.left,
            offset.dy + element.top,
            element.width,
            element.height,
          ),
          ink,
        );
      }
    }
  }

  @override
  bool shouldRepaint(_StoreUpiQrPainter oldDelegate) =>
      oldDelegate.data != data;
}

class _OrderCompletionChoices extends StatelessWidget {
